pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose residual exactly matches.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but penalize leftover slack after that hypothetical placement.
            let after_next = post_residual - next_item_size;
            score -= 200.0 - after_next as f64;
        } else {
            // Next item cannot follow here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Dead-space penalty: small unusable residuals are wasteful unless item is huge.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare residual against mean residual across open bins.
    let residual_f = bin_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += mean_gap * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / residual_f.max(1.0) as f64;
    score -= fill_ratio * 50.0;

    // New-bin candidate: empty bin gets a moderate default so it is chosen only
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // Late-stream adjustment: slightly prefer consolidating into fewer bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress) - 0.5 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits with smooth polynomial term
    let fit = 1.0 - norm_pr;
    score -= 0.6 * fit * fit * fit;

    // Penalize near-full bins late in stream only if next item doesn't fit
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let next_fits = pr >= ni;
        if !next_fits {
            let urgency = 0.3 + 0.7 * progress;
            score += urgency * (ni - pr) / cap * 10.0;
        } else {
            // reward bins that can also fit the next item (chained fit)
            let chain = 1.0 - (pr - ni) / cap;
            score -= 0.4 * chain * chain * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64).ln() * norm_pr;

    // Smooth coupling with mean residual: prefer bins below mean residual (tighter)
    let mr = mean_residual / cap;
    score += 0.3 * (norm_pr - mr) * (1.0 - progress);

    // New-bin candidate baseline: keep it slightly unattractive unless post_residual is huge
    if bin_residual == bin_capacity {
        score += 1.5 - 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps that few items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Moderate penalty for medium gaps that only tiny items can use.
    else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the gap: penalize creating dead space.
        score += post_residual as f64 * 1.5;
    }

    // New-bin candidate calibration: empty bin gets baseline tied to mean residual;
    // prefer opening a new bin only when all open bins have small residuals.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 120.0; // never open new bin when it's the only fitting one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: bin exactly fits item + next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Penalize dead space: post_residual that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Small unusable slivers are wasteful; scale by how close it is to fitting.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 2.0;
    }
    // Reward leaving space close to next item (near-perfect fit softness).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (10.0_f64.min(slack)) * 3.0;
    }

    // Last-chance bonus: if this is the only bin that can fit, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when current bin leaves a terrible fit for the next item.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 1.5; // default moderately bad
        if next_item_size > 0 {
            // New bin fits item + next item comfortably: acceptable when no open bin does.
            if item_size + next_item_size <= bin_capacity && (post_residual as f64) >= mean_residual {
                score -= 150.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // forced new bin anyway
        }
    }

    // Mild coupling with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that no item can ever use (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward if the next item fits into post_residual,
    // penalize otherwise (chained placement keeps bins dense).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 + 60.0 * tightness;
        } else {
            // Next item won't chain here; penalize more if leftover is small (wasted).
            if post_residual > 0 && post_residual < 20 {
                score += 25.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit style), but only mildly.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress;

    // New-bin candidate (residual == capacity): penalize unless the item
    // leaves a large, usable residual AND open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is more attractive when few bins exist or
        // the item is large (would leave big residual elsewhere anyway).
        score -= (item_size as f64 / 10.0) * 6.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins with small post_residual (tight fit).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>=1, but
    // practically >=10) can use are pure waste. Penalize tiny unusable gaps hard.
    let pr = post_residual;
    if pr > 0 {
        if pr < 10 {
            // Dead space: nothing in [10,80] can ever fill it.
            score += 40.0 + (10 - pr) as f64 * 8.0;
        } else if pr < 20 {
            // Marginal zone: only very small items could use it.
            score += 12.0 + (20 - pr) as f64 * 2.0;
        } else if pr < 30 {
            score += 4.0;
        }
    }

    // Perfect fill is ideal.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // next item creates another near-perfect fit here
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: residual becomes a waiting gap.
        if post_residual < 30 {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 10 {
            // Dead space anyway; a new bin may be better — soften the penalty.
            score += 0.0;
        } else {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin should win only when the fit in
    // existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slight preference for keeping bins tight.
        score = 55.0 + (bin_capacity - item_size) as f64 * 0.2;
        // If next item also fits well in the fresh bin, mildly encourage opening.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Few open bins -> less pressure to consolidate; opening is cheaper.
        score -= open_bins_count as f64 * 0.5;
    } else {
        // Open-bin count pressure: with many open bins, favor consolidating
        // into existing bins (subtract to prefer them over new bins).
        score -= open_bins_count as f64 * 0.3;
        // If mean residual is high, bins are loose; prefer the tightest fit more.
        score += (mean_residual - post_residual as f64).max(0.0) * 0.05;
    }

    // Late in the stream, avoid opening new bins (fewer future items to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0 + (10 - post_residual) as f64 * 2.0;
    } else {
        // Penalize residuals that are too small to ever fit typical items.
        if post_residual < 25 {
            score += (25 - post_residual) as f64 * 1.5;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next == 0 {
                score -= 45.0;
            } else if leftover_after_next <= 15 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's remainder; slight penalty for
            // locking space that would have helped the next item.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; only attractive when existing
        // bins fit poorly (high mean residual fragmentation) or the item
        // is large and would leave awkward space elsewhere.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 35.0;
        score -= fragmentation * 0.4;
        score -= (open_bins_count as f64) * 1.2;
        // Late in the stream, prefer reusing open bins.
        score += progress * 12.0;
        // Large items start fresh bins more willingly.
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild preference for filling bins that are already partially used,
    // keeping the pool of open bins small.
    score -= (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are effectively wasted -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fit, ideal
    } else if post_residual < 10 {
        // unusable sliver: penalize far beyond its face value
        score += (10 - post_residual) as f64 * 12.0;
    } else {
        // usable gap: mild quadratic penalty to prefer tighter fits
        score += (post_residual as f64) * (post_residual as f64) / 400.0;
    }

    // Reward exact / near-exact packing relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few are open, slightly tolerate new-bin usage.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.8 * (0.5 + progress);

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would NOT fit here but would fit elsewhere, mild penalty
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual
    // (i.e., fuller bins) to consolidate packing.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: only attractive when existing bins are tight
    // or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score = 60.0 + 40.0 * pressure - 20.0 * fill_ratio;
        // Late in the stream, opening new bins is cheaper than dead space
        score -= 30.0 * progress;
        if fitting_bins_count == 1 {
            score += 120.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // "harmonic" steps (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 5.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        score -= bonus;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Next-item lookahead: reward residuals that still fit the next item
    // (keeps bins useful), penalize residuals that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it is
    // chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 30.0
            + 0.15 * mean_residual
            - (open_bins_count as f64).ln() * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big next item: fresh bin is attractive
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative anyway
        }
    }

    // Fractional capacity coupling: prefer post-residuals that are small
    // fractions of capacity.
    let frac = post_residual as f64 / cap;
    score += frac * frac * 20.0;

    // Slight stream-progress bias toward consolidating into fewer bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (fitting_bins_count.max(1) as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 150.0; // perfect fit reward
    }

    // Reward tight fits relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Pressure from number of open bins: discourage spreading when many bins open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size && next_item_size <= post_residual {
        score -= 30.0;
    }
    // Penalize leaving a gap just under the next item size (near-miss dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // New bin candidate handling: keep it neutral-ish unless fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Late-stream: prefer consolidating into fewer bins
