        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Fractional fill reward: how much of the bin is consumed.
    let fill = (bin_residual as f64 - pr) / cap;
    score -= fill * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let large = item_size as f64 > 0.6 * cap;
        let poor_fit = pr > 0.45 * cap || fitting_bins_count == 0;
        if large || poor_fit {
            score -= 70.0; // opening a new bin is fine for big items / no alternatives
        } else {
            score += 80.0 + 0.5 * open_bins_count as f64; // discourage bin proliferation
        }
    }

    // Lookahead coupling: if next item fits the post-residual nicely, reward.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr && pr - ns < 10.0 {
            score -= 20.0; // chain fit
        } else if ns > pr && ns <= bin_residual {
            score += 10.0;
        }
        // Harmonic divisibility: next item divides residual cleanly.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Stream progression: early on, be conservative with open bins;
    // late in stream, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 10.0 * fill;
    } else if progress < 0.2 {
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual context: if mean residual is low, preserve high-residual bins.
    if (mean_residual - pr).abs() < 5.0 {
        score -= 6.0;
    }

    score
}

