    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or this bin's residual would be truly unusable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_gap = (mean_residual - item_size as f64).max(0.0);
