        score -= 25.0; // perfect or near-perfect fill is excellent
    } else if post_residual <= 20 {
        score -= 8.0; // still fairly tight
    } else if post_residual <= 35 {
        score += 6.0; // moderately wasteful
    } else {
        score += 14.0; // large dead space penalty
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - fit_quality);
    }

    // New-bin candidate: make it attractive only when the item is large
    // relative to typical residuals and no good tight fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 20.0 + 30.0 * (1.0 - progress);
        // If the item would leave a huge gap in any existing bin, a fresh
        // bin is competitive; if a tight fit exists elsewhere, discourage.
        if post_residual < 15 {
            score += 10.0; // item fits well in a fresh bin, but only choose if others are worse
        }
        if mean_residual < item_size as f64 + 5.0 {
            score -= 5.0; // existing bins are nearly full anyway -> new bin reasonable
        }
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += 0.35 * open_bins_count as f64;

    // Lookahead: if the next item can use the leftover gap, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0; // gap likely wasted for the immediate future
    }

    // Mild preference for bins already below-average residual (keeps fuller bins tighter).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins that end up tight (small post residual).
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // ---- Aggressive 2-step lookahead ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Post residual exactly matches the next item: chain placement.
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item can still go here afterwards: mildly good.
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Post residual is dead space relative to the next item.
            // Penalize proportionally to how unusable it is, but only if
            // the dead space is small (otherwise it's just a big residual).
            let dead = next_item_size - post_residual;
            if dead <= 10 {
                score += 40.0 + dead as f64 * 3.0;
            }
        }
    } else {
        // Last item: closing bins tightly is all that matters.
        score -= 100.0;
    }

    // ---- Compare against mean residual of open bins ----
    // Bins with residual far above the mean are "wasted" bins; using them
    // for a small item keeps them alive, which can be good or bad.
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual + 25.0 {
        // This bin is much emptier than average: deprioritize using it
        // unless it gives a great fit (the earlier bonuses handle that).
        score += 15.0;
    } else if resid_f < mean_residual - 15.0 {
        // Bin is tighter than average: filling it further is efficient.
        score -= 10.0;
    }

    // ---- Last-chance bonus: only one open bin fits this item ----
    if fitting_bins_count == 1 {
        // Avoid opening a new bin if at all possible.
        score -= 60.0;
        // Extra bonus if the fit here is decent (post residual small).
        score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.2;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new empty bin: it should only win when open bins are bad.
        // Give it a moderate penalty so only truly poor alternatives lose.
        score += 120.0;
        // But if this is the last item, an empty new bin is terrible.
        if next_item_size == 0 {
            score += 500.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count >= 1 {
            score += 30.0 * fitting_bins_count as f64;
        }
    }

    // ---- Late-stream tightening: as the stream ends, prefer closing bins ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for using fewer open bins overall.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Core: prefer minimal post residual (tight fit)
    let mut score = post;

    // Exact fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item (1..100 range):
    // small post residuals are fine, but mid-range residuals (e.g. 1..=9)
    // are unusable dead space unless exact fit already handled.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < f64::EPSILON || next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly good, scaled by how well it fills
            score -= 6.0 * (nxt / post.max(1.0));
        } else {
            // next item won't fit here: slight penalty proportional to leftover waste
            score += 3.0 * (1.0 - nxt / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins (penalize opening new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / 10.0;
    let mean_res_norm = mean_residual / cap;

    // New-bin candidate handling: empty bin gets base score near capacity,
    // adjusted by global conditions. Opening a new bin is favored when
    // mean residuals are low (existing bins are full) or few bins are open.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 30.0 * (1.0 - mean_res_norm) - 20.0 * (1.0 - progress) * crowding.min(3.0);
        score = cap - new_bin_bonus;
        // If this is the only fitting option anyway, make new bin attractive
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        return score;
    }

    // Encourage packing into bins whose residual is close to the item (best fit)
    let fit_ratio = item / residual.max(1.0);
    score -= 10.0 * fit_ratio;

    // Mild pressure to fill bins more fully as the stream progresses
    score += 5.0 * (1.0 - residual / cap) * progress;

    // Slight penalty when many bins are open and this bin's residual is far
    // above mean (outlier bin that will linger)
    if residual > mean_residual * 1.5 && open_bins_count > 3 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward small post-residual (tight fit) with non-linear emphasis.
    let mut score = post * (1.0 + 0.5 * post / cap) - 20.0 * (post / cap).powi(2);

    // Dead-space penalty: residuals too small to fit any plausible item (min size 1..100 unknown,
    // so penalize mid-range waste smoothly).
    let waste = (post / cap).powi(3);
    score += 15.0 * waste;

    // Stream progress coupling: late in the stream, tighten placements harder.
    score -= 10.0 * progress * (1.0 - post / cap);

    // Lookahead coupling: reward if next item fits the post-residual (smooth term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0) / cap;
        score -= 12.0 * (1.0 - fits_next) * (post / nxt.max(1.0)).min(1.0);
        // Penalize leaving residual that neither closes the bin nor fits next item.
        let awkward = (post - nxt).max(0.0) / cap;
        score += 8.0 * awkward * (1.0 - awkward);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: residual == capacity. Make it unattractive unless all fits are bad.
    if bin_residual == bin_capacity {
        let desperation = (post / cap) * (1.0 + progress);
        score += 30.0 - 20.0 * desperation;
        // More open bins => prefer filling existing ones.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild tie-break toward bins below mean residual (balance packing pressure).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but dampen the linear term
    // so residual-class effects can dominate.
    score = (post_residual as f64).powf(1.25);

    // Harmonic residual classes: classify post_residual by capacity fractions.
    // Residuals near 0 are great; residuals in "dead zones" (small but unusable)
    // are penalized, especially when the next item cannot use them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap * 0.25;
    let half = cap * 0.50;
    let three_quarter = cap * 0.75;

    // Class bonus/penalty via integer-division-style thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: huge reward
    } else if post_residual <= 10 {
        // Tiny dead space: usable only by items <=10; mildly penalize.
        score += 8.0;
    } else if (post_residual as u64) < (quarter as u64) {
        // Quarter-class dead zone: penalize proportionally to how far from
        // common item-size harmonics (multiples of 10).
        let harmonic_dist = (post_residual % 10) as f64;
        score += 12.0 + harmonic_dist * 1.5;
    } else if (post_residual as u64) < (half as u64) {
        score += 4.0 - ((post_residual % 10) as f64) * 0.5;
    } else if (post_residual as u64) < (three_quarter as u64) {
        score -= 6.0; // comfortable residual, still useful
    } else {
        score -= 10.0; // large residual: keep bin flexible
    }

    // Lookahead coupling: reward residuals that exactly/nearly fit next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // chains perfectly with the next item
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack.min(40) as f64) * 0.3;
        } else {
            // Next item cannot fit here: if residual is in a dead zone, penalize.
            if post_residual < next_item_size && post_residual < 30 {
                score += 15.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes all current residual.
    // Only attractive when open bins fit poorly (high post_residual) or the
    // stream is early and we expect many future items needing fresh space.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: it starts with max flexibility, so score
        // slightly better than a badly-filled existing bin but worse than a
        // good fit.
        score = cap * 0.85;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0; // late in the stream, reuse is cheaper
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // big next item: fresh bin may help
        }
    }

    // Slight preference to fill bins with larger residual when many bins open
    // (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap) * 5.0;

    // Tie-break toward bins below mean residual (use the "emptier" bins less).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // perfect fill, strongly reward
        score -= 80.0;
    }

    // Tight-fit reward: item occupies most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize creating gaps that cannot fit the known next item
    // (dead space relative to lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes less attractive.
    if bin_residual == bin_capacity {
        // candidate new bin: base penalty plus pressure from open bins.
        score = bin_capacity as f64 + 10.0 + 4.0 * open_bins_count as f64;
        // late in the stream, new bins are even less desirable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if next item is huge, a fresh bin may be worth keeping empty-ish
        if next_item_size > 70 {
            score -= 15.0;
        }
    } else {
        // mild bonus for using bins that are already below-average residual
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: fill bins as tightly as possible.
    score -= 0.5 * (item_size as f64);

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        // Perfect match: post_residual equals next item's size -> strong reward.
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 20.0 - 2.0 * diff;
        } else {
            // Penalize residuals that neither fit the next item nor stay useful.
            score += 0.3 * diff;
        }
        // If post_residual cannot fit the next item at all, penalize dead space.
        if pr < nxt && pr > 0 {
            score += 0.4 * (nxt - pr);
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.2 * post_residual as f64;
    }

    // --- Relative-to-mean coupling ---
    // Bins with residual far above the mean are "fresh" bins; discourage
    // wasting them on mediocre fits, encourage using crowded bins.
    let res_f = bin_residual as f64;
    if res_f > mean_residual * 1.5 {
        score += 6.0;
    } else if res_f < mean_residual * 0.5 {
        score -= 4.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // Only this bin can fit the item: strongly prefer it over opening a new bin.
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // existing bins would leave badly fragmented space.
        let fragmentation = (mean_residual - item_size as f64).abs();
        score = 60.0 + fragmentation;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin can host both this and the next item.
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to fill ratio.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys ability to host the next item
            score += 6.0;
        }
        // If next item is large, prefer conserving big-residual bins
        if next_item_size >= 60 && post_residual < next_item_size && bin_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer filling existing bins rather than fragmenting.
    if open_bins_count > 0 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * spread;
        score -= 0.5 * mean_residual.min(bin_residual as f64) / open_bins_count as f64;
    }

    // Time horizon: late in the stream, be more aggressive about filling bins
    // (less chance to consolidate later), favor low post-residual even more.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well; make the empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if the item is large and would leave a usable residual, ease the penalty
        if item_size >= 70 {
            score -= 25.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits, with smooth non-linear (quartic) shaping.
    let mut score = x * x * (3.0 - 2.0 * x) * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream -> punish wasted residual more aggressively.
    let coupling = 12.0 * x.powi(3) + 8.0 * x * x * progress - 6.0 * x * progress * (1.0 - progress);
    score += coupling * cap * 0.5;

    // Penalize bins whose residual is much below the mean (fragmented bins),
    // with a smooth quadratic term in the deviation.
    let dev = (mean_residual - pr) / cap;
    score += 4.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only bin that fits, reward using it
    // smoothly, stronger as the stream progresses.
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let g = gap / cap;
        score += 6.0 * g * g * cap;
    }

    // Mild penalty for spreading across many open bins, growing with progress.
    score += (open_bins_count as f64) * (1.0 + 4.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // sizes (small multiples / near-zero waste classes).
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect fit: overwhelming reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are more likely
    // reusable by future items (items 1..100, common sizes cluster on 10s).
    let class = pr % 10;
    score -= match class {
        0 => 20.0,
        5 => 8.0,
        _ => 0.0,
    };

    // Integer-division thresholds: residual <= 10 is nearly dead space.
    if pr <= 10 && pr > 0 {
        score += 25.0;
    } else if pr <= 20 {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if pr >= next_item_size {
            // next item fits; residual class after that placement matters
            let pr2 = pr - next_item_size;
            score -= (pr2 % 10 == 0) as i32 as f64 * 15.0;
            if pr2 == 0 { score -= 100.0; }
        } else {
            // next item won't fit here regardless; penalize tight residuals less
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty so new bins only win when open-bin scores are poor.
        score += 40.0;
        // Early in stream, new bins are cheaper; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If many bins open with slack, discourage another.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Large items start fresh bins more willingly.
        if item_size >= 50 {
            score -= 25.0;
        }
        // If next item is large and this item leaves bad residual, new bin ok.
        if next_item_size > 60 && post_residual < 40 {
            score -= 20.0;
        }
    } else {
        // Prefer fuller bins: tie-break toward bins with less original slack.
        score += (bin_residual as f64 - item_size as f64 - post_residual as f64) * 0.0;
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Small global preference for bins already below mean residual (filler bins).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: tiny gaps that no item (min size 1..100 unknown)
    // can plausibly fill. Gaps in (0, 10) are near-wasted; scale penalty sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Gaps just above small-item range are also risky
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward exact / near-exact fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to the item (tight fit overall)
    score += 0.15 * ((bin_residual as f64 - item_size as f64).abs());

    // Open-bin pressure: when many bins are open, discourage spreading; when few are open,
    // filling existing bins is cheap.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 40 {
        score -= 25.0;
    }

    // New-bin candidate: allow opening a fresh bin only when the fit into existing bins
    // would leave large dead space, or when the next item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = 100.0 + 0.5 * open_bins_count as f64;
        // if next item is large and current item is large, a fresh bin can host the pair
        if next_item_size > 0 {
            if item_size + next_item_size as u32 <= bin_capacity {
                // pairing potential: current bin can take both -> mild bonus
                new_bin_score -= 10.0;
            }
            if item_size >= 50 && next_item_size >= 50 {
                new_bin_score -= 30.0;
            }
        }
        // if mean residual across open bins is small, existing bins are tight -> new bin OK
        if mean_residual < item_size as f64 {
            new_bin_score -= 20.0;
        }
        score = new_bin_score;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size as u32;
        if slack < 10 {
            score -= 20.0;
        }
    }

    // Slight stream-progression tie-breaker: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits comfortably with little waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // reward tight fits (slack small), penalize leaving medium dead space
        score -= 30.0 * (-slack / 15.0).exp();
    }
    // Next item cannot follow into this bin: penalize proportionally to dead space
    else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize very small post residuals (unusable dead space), but not when zero waste
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, slightly prefer filling existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus a bias that grows late in the stream
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize large dead space quadratically: residuals that can never
    // fit typical items (>=10) are wasted.
    if post_residual < 10 {
        score -= 15.0; // perfect fill bonus
    } else if post_residual < 20 {
        score -= 8.0;
    } else {
        score += 0.05 * (post_residual as f64 - 20.0).powi(2) / bin_capacity as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward heavily; if post residual can't hold the next item but is
    // large, mildly penalize (fragmentation risk).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are badly fragmented (high mean residual relative to item) or many
    // bins are already open with poor fit options.
    if bin_residual == bin_capacity {
        let mut nb = 20.0;
        if mean_residual > item_size as f64 * 1.5 {
            nb -= 10.0; // open bins are too full anyway; new bin fine
        }
        if fitting_bins_count == 0 {
            nb -= 30.0;
        }
        if post_residual as f64 > mean_residual {
            nb += 5.0;
        }
        score += nb;
    }

    // Time horizon: early in the stream, be more conservative about
    // fragmentation (long future benefits from tight packing); late in
    // the stream, just close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Mild diversity pressure: with many open bins, prefer filling
    // existing ones rather than spreading.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight packing)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in stream: tolerate larger residuals (bins can absorb future items).
    // Late in stream: heavily penalize leftover space (few chances to fill it).
    let norm_post = post / cap; // in [0, 1)
    let w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * w * norm_post * norm_post * (1.0 - norm_post + 0.5);

    // Dead-space penalty: residuals too small for any plausible item (1..100 range)
    let dead_threshold = 10.0;
    if post < dead_threshold {
        score += 25.0 * (dead_threshold - post) / dead_threshold;
    }

    // Coupling with next item: reward bins whose post residual fits the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack); // exact-ish fit bonus
        } else {
            // post residual cannot host next item: mild penalty scaled by closeness
            score += 6.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    if (bin_residual as f64 - cap).abs() < f64::EPSILON {
        // Penalize opening a new bin; scale penalty with how well the item
        // would fill it and how many alternatives exist.
        let fill = item / cap;
        score += 60.0 * (1.0 - fill * fill);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Late in the stream, opening new bins is more costly (fewer items left to fill them)
        score += 30.0 * w;
    } else {
        // Reward using existing bins, especially when they are scarce options
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Slight preference for bins with residuals close to the item (best-fit flavor)
        let residual = bin_residual as f64;
        let fit_gap = (residual - item) / cap;
        score += 5.0 * fit_gap * fit_gap;
    }

    // Mild global balance: avoid drifting far from mean residual of open bins
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space < 10 is nearly unusable)
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 20.0;
    }

    // Harmonic class of post_residual: residues mod 10 / mod 20 determine
    // how "reusable" the leftover space is for typical small items.
    let pr = post_residual;
    let class_mod20 = pr % 20;
    // Residues near 0 mod 20 are highly reusable (fit 20, 40, 60, 80 items later)
    let reusability = match class_mod20 {
        0 => 12.0,
        10 => 8.0,
        5 | 15 => 4.0,
        _ => 0.0,
    };
    score -= reusability;

    // Integer-division threshold: post_residual in a "large chunk" class
    // (pr / 20 >= 2) keeps flexibility; tiny chunks (pr/20 == 0) are dead space.
    let chunk_class = pr / 20;
    if chunk_class == 0 && pr > 0 {
        score += 8.0; // penalize awkward slivers like 1..9 already partially covered
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            let next_post = pr - next_item_size;
            if next_post < 10 {
                score -= 25.0;
            }
        } else {
            // next item cannot fit here: mild penalty for wasting a good slot
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when it is genuinely better,
    // i.e. when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer filling existing bins by default
        score += 55.0;
        // But if the item would fit terribly anywhere (min possible post_residual
        // across open bins would be small), opening fresh is fine. We approximate:
        // if mean residual is much larger than item, existing bins fit well.
        let slack = mean_residual - item_size as f64;
        if slack < 10.0 {
            score -= 70.0; // existing bins are tight; new bin is attractive
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // Many open bins: discourage adding more
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Slight preference for bins below mean residual (concentrate fullness)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Exact-fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to hold even the smallest item (1)
    // are pure waste; penalize gaps below the minimum plausible item size harshly.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // impossible, shouldn't happen but guard
    }

    // Non-linear dead-space penalty: gaps in [1, 15] are "unusable slivers".
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 12.0;
    }

    // Reward tight fits strongly (post_residual near zero but not in sliver zone).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins;
    // discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above typical good fits.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 8.0;
        // If next item is large and this bin would be fresh, a new bin can be attractive
        // when no existing bin fits well.
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
    } else {
        // Slight preference for bins whose residual is close to what's needed (tightness).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 25.0;
    }

    // Mean-residual coupling: when mean residual is high, prefer bins below mean
    // (use up the loosest space first).
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.3;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 35.0;
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: heavily penalize unless it's a great 2-step fit.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 1000.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let gap = (bin_capacity - item_size) as f64 - next_item_size as f64;
            if gap >= 0.0 {
                // Perfect 2-step chain: new bin fits item then next item exactly.
                new_bin_score = 5.0 + gap;
            }
        }
        if next_item_size == 0 {
            new_bin_score = 500.0; // last item: never open a new bin if any fits
        }
        return new_bin_score;
    }

    // Strong reward for exact 2-step lookahead match.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap == 0.0 {
            score -= 250.0; // perfect chain: item + next item fill bin exactly
        } else if gap > 0.0 && gap <= 10.0 {
            score -= 120.0 - 8.0 * gap; // near-perfect chain
        } else if gap < 0.0 && post_residual > 0 {
            // next item won't fit here: dead space penalty scaled to dead space
            score += 0.6 * gap.abs();
        }
    } else {
        // Last item: just prefer tightest fit (post_residual minimal is default).
    }

    // Reward filling the bin nearly completely (small post_residual is good).
    if post_residual > 0 && post_residual <= 10 {
        score -= 30.0; // creates near-unusable residual that is "spent" well
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Relative to mean residual: prefer bins with residual below mean
    // (compact bins), i.e., bins that are already well filled.
    let rel = mean_residual - bin_residual as f64;
    score += 0.35 * rel;

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post residual (tight fit).
    let mut score = post;

    // Strong penalty for unusable dead space: if post residual cannot fit the
    // smallest plausible item, the leftover is wasted.
    if post_residual < 1 {
        score += 50.0;
    }
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 60.0; // perfect pairing
        } else if post_residual >= next_item_size {
            score -= 15.0; // next item still fits here
        } else {
            score += 8.0; // next item forces a new bin anyway; less pressure
        }
        // Penalize if post residual is just barely below next item (near-miss waste)
        if post_residual < next_item_size && post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
        let _ = nxt;
    }

    // Fragmentation pressure: penalize bins whose residual is far above the item
    // (loose fit) when many bins are open — consolidate instead.
    let looseness = (bin_residual - item_size) as f64;
    if open_bins_count > 2 {
        score += looseness * 0.15 * ((open_bins_count as f64).ln() + 1.0);
    }

    // Mean-residual coupling: bins below mean residual are "denser"; prefer them.
    score += (mean_residual - residual) * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins
    // (more future items to benefit from flexibility); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so later in stream
        // and when decent fitting bins exist.
        let mut new_bin_penalty = 30.0 + 40.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Exception: item is large; a fresh bin gives maximal future flexibility.
        if item > 0.6 * cap {
            new_bin_penalty -= 20.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: small reward for using it, growing with progress.
        score -= 5.0 + 5.0 * progress;
    }

    // Slight preference for filling larger items into tighter bins overall.
    score -= (item / cap) * 10.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = post;

    // Smooth non-linear coupling: quadratic growth of penalty for larger leftover space,
    // modulated by stream progress (later in stream -> tighter packing desired)
    let progress_coupling = 1.0 + 3.0 * progress * progress;
    score += progress_coupling * post_norm * post_norm * cap;

    // Reward near-perfect fits smoothly (small residual gets extra discount)
    let fit_bonus = (1.0 - post_norm).powi(8);
    score -= 25.0 * fit_bonus * (1.0 + progress);

    // Dead-space penalty: residuals too small for typical future items
    let min_future = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    if post < min_future && post > 0.0 {
        let waste_ratio = (min_future - post) / min_future;
        score += 15.0 * waste_ratio * waste_ratio * (0.5 + progress);
    }

    // Lookahead synergy: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = 1.0 - (post - next_item_size as f64) / cap;
        score -= 12.0 * next_fit_quality * next_fit_quality;
    }

    // Last-chance bonus: only one bin fits -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening new bins smoothly,
    // stronger when many bins fit and mean residual is large
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let mean_res_norm = mean_residual / cap;
        let openness = open_bins_count as f64;
        score += 10.0
            + 4.0 * fit_pressure.sqrt()
            + 20.0 * mean_res_norm * (1.0 - progress)
            + 2.0 * openness.sqrt();
    }

    // Mild preference for bins with residual close to item (best-fit flavor)
    let residual_norm = bin_residual as f64 / cap;
    score += 5.0 * (residual_norm - (item_size as f64 / cap)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space ---
    // Class A: post_residual == 0 -> perfect closure, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        // Class B: tiny unusable dead space (below min item size 10)
        score -= 60.0 - (post_residual as f64) * 2.0;
    } else {
        // Class C: usable leftover; classify by integer division bands of 10
        let band = post_residual / 10; // 1..=9
        // Deeper bands (smaller leftovers) are generally better; reward quadratically
        score -= (band as f64) * (band as f64) * 0.9;

        // Harmonic modulo classes on post_residual: multiples of 10 align
        // with the common item-size grid -> easier future packing.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 5.0;
        }
    }

    // --- Lookahead coupling: does the next item fit into the leftover? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.3;
        } else if next_item_size <= bin_residual {
            // Next item would have fit before this placement but not after:
            // penalize destroying future opportunity
            score += 25.0;
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that can take the item; avoid opening a new bin
        score -= 80.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: chosen only when all open bins are bad fits.
        // Cost of a fresh bin ~ mean waste of open bins + fixed overhead.
        score = 100.0 + mean_residual * 0.5 + (open_bins_count as f64) * 0.2;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // --- Mild stream-phase adaptation: late in the stream, prefer closing bins ---
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 8.0 * (post_residual.min(20) as f64) / 20.0;

    // --- Crowding: with many open bins, prefer reusing (lower score for tight reuse) ---
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect packing: very small post residual is excellent.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 80.0; // perfect chaining: this item + next item fill bin
        } else if gap <= 3.0 {
            score -= 40.0;
        } else if gap <= 8.0 {
            score -= 18.0;
        } else {
            // Residual too large relative to next item: dead space risk
            score += gap * 0.6;
        }
        // If next item cannot even fit anywhere after placement, penalize heavily
        if next_item_size > post_residual && post_residual > 0 {
            score += 12.0;
        }
    }

    // Compare against mean residual: leaving this bin far below mean residual
    // concentrates fragmentation; prefer balanced residuals.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes the residual of
    // all open bins; only attractive if this placement would leave a big hole.
    if bin_residual == bin_capacity {
        // Base penalty for spawning a new bin
        score += 45.0;
        // Scale penalty with how many bins already fit the item
        score += 20.0 * (fitting_bins_count as f64).min(5.0);
        // If the leftover would be a large unusable gap, opening a new bin
        // becomes relatively more attractive: reduce the penalty.
        let hole = post_residual as f64;
        if hole > 30.0 && hole < 60.0 {
            score -= 50.0;
        }
        // Late in the stream, avoid opening new bins for small leftovers
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Slight preference for tighter bins (small residual before placement)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 12.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 6.0 * fit_ratio;
    }

    // Dead-space penalty: leaving tiny unusable slivers is bad unless next item uses them.
    if post_residual > 0 && post_residual < 10 {
        let next_fits_sliver = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits_sliver {
            score += 15.0;
        } else {
            score -= 10.0; // perfect chain: next item fills the sliver exactly
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_tightness = next_item_size as f64 / post_residual as f64;
        score -= 5.0 + 6.0 * next_tightness;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to gap.
        score += 2.0;
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if fit_ratio > 0.5 {
            score -= 20.0;
        } else {
            score -= 4.0;
        }
    }

    // Fragmentation guard: penalize bins whose residual deviates badly from the mean
    // when open bin count is high (fragmented state).
    if open_bins_count > 3 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early stream: keep bins flexible (favor mid-size residuals) to preserve options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        // prefer leaving room for medium items
        if post_residual >= 20 && post_residual <= 60 {
            score -= 3.0;
        }
    } else if progress > 0.8 {
        // late stream: consolidate aggressively, prefer tightest fits
        score += 0.03 * post_residual as f64;
    }

    // New-bin candidate handling: opening a fresh bin should only win when no
    // existing bin gives an acceptable fit. Give it a moderate baseline plus a
    // penalty scaled by how many bins could fit the item.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64; // waste potential of fresh bin
        score += 8.0 * fitting_bins_count as f64;  // discourage when alternatives exist
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * cap
        + 20.0 * norm_pr * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in the stream, tighter packing matters more.
    score *= 1.0 + 0.6 * progress * norm_pr;

    // Reward near-perfect fits smoothly via interaction term.
    let fit_quality = 1.0 - norm_pr;
    score -= 30.0 * fit_quality * fit_quality * fit_quality * (item_size as f64 / 100.0);

    // Penalize waste relative to mean residual (smooth coupling).
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving post_residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += (open_bins_count as f64) * (1.0 + 2.0 * progress) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues near multiples of
    // common item sizes (10,20,25,50) are "reusable" and get rewarded.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 {
        -30.0
    } else if pr % 10 == 0 {
        -18.0
    } else if pr >= 10 && pr <= 9 {
        0.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize dead space below the minimum item size (unusable waste).
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Fractional capacity class of the fit: tight fits are excellent.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let tightness = (fill_frac - (fill_frac * 4.0).round() / 4.0).abs(); // distance to quarter-class
    score += tightness * 25.0;

    // Integer-division threshold on post_residual: classify leftover into
    // quartiles of capacity; middling leftovers are least attractive.
    let quart = pr / (bin_capacity / 4);
    score += match quart {
        0 => -5.0,   // nearly full bin
        1 => 6.0,    // awkward small leftover
        2 => 10.0,   // half-empty: worst harmonic class
        3 => 2.0,    // large leftover still reusable
        _ => 0.0,
    };

    // Lookahead coupling: if the next item fits the post residual exactly
    // or harmonically, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 20.0;
        } else if pr < next_item_size && pr > 0 {
            score += 12.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the stream is
    // early or current open bins are nearly saturated on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let saturation = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).sqrt() * 4.0;
        score += 55.0 + pressure - saturation * 30.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    // Mild preference to keep mean residual balanced (avoid fragmentation).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but treat tiny unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        // Dead space: gap too small for any item (min size 1..100, but small gaps waste).
        score += 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward keeping it usable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Post-residual too small for next item: penalize proportionally to wasted space.
            score += 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current
    // fit is poor (large post_residual creating fragmentation).
    if bin_residual == bin_capacity {
        // New bin baseline: neutral residual (100). Only win if open bins are fragmented
        // and the fit would waste a lot.
        let fit_quality = post_residual as f64; // == bin_capacity - item_size
        let open_pressure = open_bins_count as f64;
        // Penalize opening new bins when few bins are open (consolidation phase).
        score = fit_quality + 25.0 + 3.0 * open_pressure;
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If a new bin leaves a large residual (small item), that's fine early, bad late.
        score += 0.2 * fit_quality * progress;
    } else {
        // Existing bin: mild penalty for spreading across many open bins is wrong direction;
        // instead reward using existing bins to keep open_bins_count low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: if open bins are already fragmented (high mean residual),
    // avoid adding more fragmentation to an existing bin.
    if bin_residual != bin_capacity {
        score += 0.15 * mean_residual;
    }

    // Open bins pressure: with many open bins, strongly prefer filling existing ones.
    score += 2.0 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual == next_item_size {
            // Perfect 2-step match: fill exactly on next item. Huge reward.
            score -= 45.0 + 10.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            // Next item still fits; reward proportional to how close the
            // remaining space after that hypothetical placement is to zero.
            let after_next = post - nxt;
            // Prefer post_residual just slightly above next_item_size.
            score -= 20.0 * (1.0 - after_next / bin_capacity as f64);
            // Extra bonus if after the next item the residual is small (tight packing).
            if after_next < 10.0 {
                score -= 8.0;
            }
        } else {
            // Next item would NOT fit: dead space risk. Penalize small
            // unusable gaps (below min item size ~10) more strongly.
            let gap = post;
            if gap < 10.0 {
                score += 12.0 + 0.5 * gap; // tiny unusable sliver
            } else {
                score += 4.0;
            }
        }
    } else {
        // Last item: simply prefer the tightest fit (smallest post_residual).
        score -= 5.0;
    }

    // --- Mean-residual coupling ---
    // Bins whose residual is far below the mean are "loose"; placing here
    // when the bin is nearly full is good, but dumping into a very full bin
    // leaving a large gap is bad. Nudge score toward mean_residual context.
    let mean_r = mean_residual;
    if (post_residual as f64) < mean_r - 15.0 {
        // This bin ends much tighter than average: good consolidation.
        score -= 3.0;
    } else if (post_residual as f64) > mean_r + 15.0 {
        // This bin stays much looser than average: mild penalty.
        score += 2.0;
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin can take the item; avoid opening a new bin.
        score -= 6.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: base cost of opening a new bin.
        score = bin_capacity as f64;
        // Open a new bin only when the item is large and would leave a
        // badly fragmented fit elsewhere, or when no existing bin fits well.
        // Large items pack cleanly in fresh bins.
        if item_size >= 70 {
            score -= 30.0;
        } else if item_size >= 50 {
            score -= 10.0;
        }
        // If many bins are open and mean residual is large, spreading is cheap.
        if mean_r > 40.0 {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 * progress;
        // If several bins already fit, discourage opening yet another bin.
        if fitting_bins_count >= 2 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = pr;

    // Reward tight fits: exponentially favor bins whose post-residual is small (dead-space killer).
    if pr > 0.0 {
        score -= 40.0 * (-pr / 15.0).exp();
    } else {
        score -= 45.0; // perfect fill
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Lookahead (k=2): if the next item can still use this residual, reward; otherwise
    // penalize the unusable gap proportionally (encourages new bin when gap is wasteful).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - nx / pr.max(1.0));
        } else {
            score += (nx - pr).min(25.0);
        }
    }

    // New-bin candidate: penalize slightly so open bins are preferred, but relax the
    // penalty for large items (which leave small residuals anyway).
    if is_new_bin {
        score += 8.0 - 6.0 * (item_size as f64 / cap);
    }

    // Late in the stream, tighten packing more aggressively (less room for slack).
    score -= 4.0 * progress * (1.0 - pr / cap);

    // Mild coupling with global state: many open bins with high mean residual ->
    // discourage adding another loose bin.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize leftover space, but with a non-linear (quartic) waste curve.
    let mut score = norm_post.powf(4.0) * 12.0 + post * 0.01;

    // Smooth coupling: leftover space is less tolerable early (bins are cheap to fill later),
    // so weight post_residual by a decreasing function of progress.
    score += (1.0 - progress) * norm_post * 2.0;

    // Reward tight fits with a smooth bump peaked near post_residual == 0.
    let tightness = (-norm_post * 6.0).exp();
    score -= tightness * 4.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    } else {
        // Mild penalty when many alternatives exist, smoothly scaled.
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.15;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving that gap;
    // smooth sigmoid on whether next item fits.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap_util = next_item_size as f64 / cap;
        score -= fits_next * gap_util * (2.0 + 3.0 * progress);
    }

    // Mean residual context: bins far from the mean residual get a smooth divergence penalty.
    let mean_post = mean_residual - item_size as f64;
    let div = (post - mean_post) / cap;
    score += div * div * 1.5;

    // Crowd penalty: many open bins with large residuals -> prefer filling existing ones.
    score -= (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0) * 0.8;

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 6.0 - 5.0 * pressure * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual (mod-10 classes) ---
    let pr = post_residual;
    let class = pr % 10;                 // residue class
    let quot = pr / 10;                  // decade bucket (0..=9)
    let frac = pr as f64 / bin_capacity as f64; // capacity fraction

    // Reward exact/near-exact fits strongly (post_residual in small classes).
    // Class 0 = perfectly partitioned residual (ideal, e.g. 0,10,20,...)
    // but only if truly small or exactly fillable by future items.
    let class_reward: f64 = match class {
        0 => 18.0,
        1 => 14.0,
        2 => 11.0,
        3 => 7.0,
        4 => 4.0,
        5 => 2.0,
        6 => -2.0, // awkward mid-range dead space
        7 => -4.0,
        8 => -6.0,
        _ => -8.0, // class 9: worst dead space
    };
    score -= class_reward;

    // Strong reward for a perfect fill.
    if pr == 0 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for any plausible item
    // (items >= 1, but small scraps are rarely usable): pr in 1..=5.
    if pr >= 1 && pr <= 5 {
        score += 12.0 - 2.0 * pr as f64;
    }

    // Lookahead coupling: reward residual that exactly accommodates next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 55.0; // chain fill: this bin will be perfectly consumed
        } else if pr >= next_item_size {
            let slack = pr - next_item_size;
            // Harmonic class of the leftover after the next item.
            let slack_class = slack % 10;
            if slack_class == 0 {
                score -= 22.0;
            } else if slack_class <= 2 {
                score -= 12.0;
            } else if slack_class >= 7 {
                score += 8.0; // bad leftover class after lookahead
            }
            // If nothing else can absorb the slack, mild penalty.
            if slack > 0 && slack < 10 {
                score += 4.0;
            }
        } else {
            // Next item cannot fit here: residual becomes final dead space.
            score += 6.0 + 0.15 * pr as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if pr <= 20 {
            score -= 8.0; // still a decent fit
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    // Base score already = capacity - item_size (large), so it loses unless
    // all open bins fit badly. Give it a calibrated bonus/penalty:
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item is large relative
        // to capacity (fresh bin gives clean harmonic structure).
        let size_frac = item_size as f64 / bin_capacity as f64;
        // Slight attraction when item is big (size_frac > ~0.6) and few bins open.
        score -= 14.0 * size_frac * size_frac;
        if open_bins_count == 0 {
            score -= 100.0; // must open something
        }
        // Discard new-bin temptation early in the stream when many bins exist.
        if open_bins_count > 3 {
            score += 3.0;
        }
    } else {
        // Slight preference for reusing bins when many are already open.
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Mean-residual coupling: prefer bins near the mean residual (keeps the
    // bin pool balanced, avoids stranding one huge and one tiny residual).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Stream progression: late in the stream, be greedier (tight fits matter
    // more since no future amortization); early, allow exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - frac); // late stream: favor tight fits more

    // Decade-bucket micro-adjustment: prefer residuals in "clean" buckets.
    score -= match quot {
        0 => 5.0,
        1 => 3.0,
        2 => 1.0,
        3 => 0.0,
        4 => -1.0,
        5 => -2.0,
        6 => -3.0,
        7 => -4.0,
        8 => -5.0,
        _ => -6.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strict dead-space avoidance: unusable small gaps (< 10, min item size) are pure waste.
    if post > 0.0 && post < 10.0 {
        score += 60.0 * (10.0 - post) / 10.0;
    }
    // Small-but-usable gaps are risky: only a narrow band of items can use them.
    if post > 0.0 && post < 25.0 {
        score += 18.0 * (1.0 - post / 25.0);
    }

    // Reward tight fits (waste ratio).
    let fill_ratio = item / cap;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post == 0.0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are already partially filled
    // relative to the fleet average (consolidation).
    if bin_residual < bin_capacity {
        score += 0.4 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if next item fits in post_residual, bonus; if next item is large
    // and this placement leaves a gap it can't use, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0;
        } else if post > 0.0 {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: neutral-ish score so it wins only when all open bins
    // would create severe dead space or none offer a decent fit.
    if bin_residual == bin_capacity {
        let base = 55.0 + 2.0 * open_bins_count as f64;
        // If the next item is large, having a fresh bin is more valuable.
        let adj = if next_item_size >= 60 { -10.0 } else { 0.0 };
        return base + adj;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits tightly afterwards.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to tightness of the follow-up fit.
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus if the follow-up leaves a still-usable chunk.
        if slack >= 10.0 {
            score -= 5.0;
        }
    }
    // Dead space: post_residual too small for the next item (but nonzero).
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize unusable sliver, scaled by how close it is to being useful.
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Compare post_residual against mean residual: prefer keeping residuals balanced.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., item would leave a large awkward residual in existing bins).
    if bin_residual == bin_capacity {
        let awkward = if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            1.0
        } else {
            0.0
        };
        // Base penalty so a fresh bin is only chosen when existing bins waste space.
        score += 35.0;
        // Slightly cheaper to open a new bin when many bins are already open.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        // If this item would create dead space elsewhere, new bin becomes competitive.
        score -= 40.0 * awkward;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream consumed: dynamic time horizon.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: relative fill of the bin after placement.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly (best-fit core with amplification).
    score -= fill * fill * 40.0;

    // Penalize small post-residuals only when they are truly dead space:
    // a residual too small for the smallest plausible item (1..100 => threshold 10)
    // is wasted, but a moderate residual is a resource for future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this placement is doubly valuable; subtract a bonus proportional to it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 18.0 + snug * 22.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize proportionally to waste.
        score += (next_item_size.min(post_residual.max(1)) as f64) * 0.15;
    }

    // Last-chance dynamics: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, discriminate more finely on fit quality.
        score += (fitting_bins_count as f64 - 1.0) * 2.5;
    }

    // Global state: prefer filling bins in bins with below-average residual
    // (compact the fleet), keep some slack spread around when many bins are open.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.35 * (1.0 - t * 0.5);

    // Late in the stream, consolidate aggressively: waste is less recoverable.
    score += (1.0 - t) * 6.0 + t * (post_residual as f64) * 0.10;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when no open bin offers a decent fit,
    // i.e. when the best available post-residual would be very small (poor fit).
    // We approximate "poor fit" via item_size: large items leave little room,
    // so opening a fresh bin for large items is less costly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin (encourage using open bins).
        score += 30.0;
        // But relax the penalty when the item is large relative to capacity
        // and few bins fit it (poor-fit scenario): a fresh bin yields a clean
        // residual for the future.
        let size_frac = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count <= 1 {
            score -= 45.0 * size_frac;
        }
        // Late in the stream, a fresh bin is rarely worth it.
        score += t * 20.0;
        // If the next item is large, a fresh bin's clean residual is valuable.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its non-linear coupling with stream progress.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * (0.5 + progress);

    let mut score = pr + 20.0 * poly;

    // Reward tight fits, more strongly later in the stream.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (30.0 + 40.0 * progress);

    // Penalize dead space below smallest plausible item (1).
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bin bonus: strongly favor using it rather than opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 5.0 * (1.0 - pr / (next_item_size as f64).max(1.0)).min(1.0);
        }
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual.
    let mean_gap = mean_residual - pr;
    score += 0.1 * mean_gap * (1.0 - progress);

    // New-bin candidate: penalize opening a bin unless residual is large and stream is early.
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is already the base; add a harmonic-class bonus
    // for post_residuals that fall into "usable" modulo classes.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: classify by integer division thresholds
    // class 0: pr == 0 (perfect fill) -> strong reward
    // class 1: pr <= 10 (small dead space)
    // class 2: pr <= 20 (medium)
    // class 3: otherwise (large residual, still usable)
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 15.0;
    } else if pr <= 20 {
        score -= 6.0;
    }

    // Modulo arithmetic: residuals that are multiples of 5 or 10 are more likely
    // to be exactly filled by future items (sizes 1..100, common classes).
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fill).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let after_next = pr - next_item_size;
            // reward small leftover after the chained placement
            if after_next <= 10 {
                score -= 8.0;
            } else {
                score -= (after_next as f64) * 0.05;
            }
        } else {
            // next item cannot use this bin's residual: slight penalty for
            // stranding capacity, scaled by residual size
            score += (pr as f64) * 0.03;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the item fits poorly everywhere.
    // Penalize the new bin moderately so existing bins with decent fits win,
    // but relax the penalty when the item is large relative to residual options.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 20.0;
        // if many bins already open, discourage proliferation
        score += (open_bins_count as f64) * 0.5;
        // if item is large (>= 50% capacity), a fresh bin is more acceptable
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
        // late in the stream, prefer reusing existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
        // if the mean residual of open bins can't hold the item well,
        // new bin becomes more attractive
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward bins whose residual is close to the item (good fit)
        let slack = (bin_residual - item_size) as f64;
        score += slack * 0.02; // tiny extra nudge on top of post_residual base
        // prefer filling bins with smaller residuals first (best-fit bias)
        score += (bin_residual as f64) * 0.01;
    }

    // Slight global pressure: keep open-bin count low by rewarding placements
    // into bins when many are open.
    score -= (open_bins_count as f64).ln() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the minimum item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large item or high bin pressure); otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 25.0 * big_item - pressure.clamp(0.0, 5.0);
    }

    // Mild open-bin pressure: discourage scattering across many bins.
    score += 0.4 * open_bins_count as f64;

    // Slight preference for tighter bins (smaller residual before placement).
    score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus: lookahead item fits with little slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead-space penalty: post_residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (good consolidation).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when open bins could fit reasonably.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual dominates, but discount it when fit is very tight.
    let tightness = post_residual as f64 / bin_capacity as f64;
    if tightness < 0.15 {
        score -= 12.0 * (1.0 - tightness / 0.15);
    }

    // Penalize dead space that is too small to ever be useful (below min item size 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0; // hard-to-fill zone
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild preference for the fullest bin (best-fit bias).
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: penalize leaving a residual that barely blocks the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score += 6.0; // next item barely fits; may cause fragmentation later
            } else {
                score -= 3.0; // next item fits comfortably here too
            }
        } else {
            // Next item won't fit after this placement; slight penalty unless residual is dead space.
            if post_residual >= 10 {
                score += 5.0;
            }
        }
    }

    // New-bin candidate handling: opening a new bin is expensive early/late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 14.0;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_cost += 10.0 * progress;
        // Many open bins already: discourage adding more.
        new_bin_cost += 1.5 * open_bins_count as f64;
        // If this is the last-chance situation, opening a bin is acceptable fallback.
        if fitting_bins_count == 1 {
            new_bin_cost -= 20.0;
        }
        // Large items (>=50) start fresh bins more readily.
        if item_size >= 50 {
            new_bin_cost -= 5.0;
        }
        score += new_bin_cost;
    }

    // Global state coupling: when mean residual across open bins is high, prefer
    // bins below the mean (rebalance toward fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild preference for bins that already have content (avoid spreading).
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Time-horizon term: early stream, keep bins flexible (prefer larger post_residual slightly);
    // late stream, squeeze hard (already dominated by post_residual, add small boost).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: prefer minimal post-residual, with smooth non-linear emphasis.
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling of post-residual with stream progress:
    // tight packing matters more as the stream progresses.
    let tightness = 1.0 - pr_norm;
    score -= progress * (2.0 * tightness + 1.5 * tightness * tightness) * cap * 0.25;

    // Reward near-perfect fits smoothly (quadratic decay of the bonus).
    let perfect = 1.0 - (pr_norm - 0.0).abs().powi(4);
    score -= perfect * fit_norm * cap * 0.3;

    // Penalize creating small unusable dead space relative to typical next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt as u32 {
            score += 0.6 * (nxt - pr) * (1.0 + progress);
        } else {
            // Smooth reward when the residual can still host the lookahead item.
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack * slack) * 3.0;
        }
    }

    // Last-chance bin: strong smooth bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - pr_norm);
    }

    // Mild preference for bins deviating from mean residual (diversity of gaps),
    // penalized smoothly the further the residual sits above the mean.
    score += 0.05 * (pr as f64 - mean_residual).abs();

    // New-bin candidate: keep it moderately attractive only early or when fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_norm < 0.5;
        score += if poor_fit { -2.0 + 10.0 * progress } else { 6.0 + 8.0 * progress };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "friendly" residue classes (multiples of 10, or small enough to be
    // reusable) are rewarded; dead-space zones are penalized.
    let pr = post_residual;
    let r10 = pr % 10;
    let r25 = pr % 25;

    // Perfect fit: zero residual is ideal.
    if pr == 0 {
        score -= 60.0;
    } else {
        // Residue-class rewards: leftovers divisible by 10 align with the
        // common item-size lattice and are likely reusable.
        if r10 == 0 {
            score -= 12.0;
        } else {
            score += r10 as f64 * 1.5; // off-lattice leftovers are dead space
        }
        // Quarter-lattice alignment (25/50/75) also tends to pair well.
        if r25 == 0 {
            score -= 8.0;
        }
        // Very small leftovers (1..=5) are nearly dead space: penalize.
        if pr <= 5 {
            score += 18.0;
        }
        // Mid-range leftovers are the most reusable.
        if (10..=30).contains(&pr) {
            score -= 6.0;
        }
    }

    // Harmonic check: does post_residual exactly accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size && (pr % next_item_size.max(1)) == 0 {
            score -= 10.0; // leftover divides evenly into next item classes
        }
        if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 5.0; // next item would almost perfectly fit here
        }
        // If next item cannot fit anywhere else well, prefer keeping space for it
        if next_item_size > pr {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Spread preference: with several fitting bins, prefer tighter fits.
        score += 2.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more aggressive about filling bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits or the item
    // is large and would leave an awkward leftover in an existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let awkward = item_size >= 60 && post_residual > 0 && post_residual < 10;
        let no_fit = fitting_bins_count == 0;
        if no_fit {
            score -= 40.0;
        } else if awkward {
            score -= 15.0;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: keep it expensive so we only open
    // a new bin when every open bin would strand dead space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 30.0;
        // If no open bin can fit at all, opening a new bin is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer closing out bins over spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        return score;
    }

    // Strict dead-space avoidance: residuals in [1,9] are unusable for
    // typical items -> heavy penalty so we don't strand tiny gaps.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64 * 2.0;
    }
    // Perfect fit is ideal.
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can no longer use this bin's leftover,
    // the leftover is dead weight -> penalize proportionally.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += (next_item_size - pr) as f64 * 1.5;
    }
    // If next item fits exactly in the leftover, reward strongly.
    if next_item_size > 0 && pr == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, mild pressure toward tighter fits
        // relative to the fleet mean residual.
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few bins, slightly encourage filling existing bins.
    let op_pressure = (open_bins_count as f64 - 3.0).max(0.0) * 0.8;
    score += op_pressure * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.8;
            // if next item cannot fit into post_residual, penalize dead space
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Penalize bins that are already tight (low residual) — risk of waste
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += tightness * 12.0;

    // Compare post_residual relative to mean residual: leaving much more than
    // average residual is bad (fragmentation), much less is good
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += mean_gap * 0.35;
    } else {
        score += mean_gap * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when item is large or
    // existing residuals are poor. Penalize opening a new bin early in stream
    // when good fits exist; allow it when item is big.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 15.0 + progress * 10.0 - big_item_bonus;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can absorb next item too if small
            if next_item_size + item_size <= bin_capacity {
                score -= 6.0;
            }
        }
    }

    // Slight preference to fill bins with larger items tightly
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 {
        let wasted = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
        if post_residual < next_item_size {
            // residual too small for next item: penalize proportionally
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        } else {
            // residual can host next item: reward
            score -= 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
        let _ = wasted;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fewest bins.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (larger post_residual ok);
    // late in stream, push toward filling bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Global state coupling: if mean residual is high, discourage spreading; favor filling existing bins.
    if mean_residual > item_size as f64 && bin_residual < bin_capacity {
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh bin is fine when more large items follow
        }
        if open_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
    }

    // Slight preference for bins with residual close to item (exact-fit bonus).
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic) penalty on wasted space.
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Stream-progress coupling: early on, keep bins flexible (favor larger residuals later);
    // late in the stream, reward tight packing more aggressively.
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * 30.0 * pr_norm * pr_norm;

    // Smooth interaction: post_residual vs mean residual — prefer bins whose remaining
    // space deviates usefully from the average (below mean residual = well-utilized bin).
    let mean_norm = mean_residual / cap;
    score += 20.0 * (pr_norm - mean_norm) * (pr_norm - mean_norm) * (1.0 - progress);
    score -= 15.0 * (mean_norm - pr_norm) * progress;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly;
    // if post-residual is too small for the next item (dead space), penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 25.0 * fit_quality * fit_quality;
        } else {
            let overshoot = (nxt - pr) / cap;
            score += 18.0 * overshoot * overshoot;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (smooth exponential-style boost).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 - pr_norm);
    }

    // Penalize opening new bins when decent open bins exist (new-bin candidate has
    // bin_residual == bin_capacity); make empty-bin score less attractive as bins accumulate.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() + 1.0;
        score += 12.0 + 6.0 * crowding * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create dead-space classes.
    let r = post_residual % 10;
    // Small nonzero residues (1..=4) are nearly unusable dead space -> penalize.
    if r > 0 && r <= 4 {
        score += (5 - r) as f64 * 6.0;
    }
    // Perfectly clean residuals (multiples of 10) are valuable -> reward.
    if r == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division threshold classes on post_residual.
    let q = post_residual / 10;
    match q {
        0 => score += 4.0,          // post_residual < 10: bin effectively closed
        1 => score -= 2.0,          // 10..19: can host small future items
        2 | 3 => score -= 5.0,      // 20..39: flexible mid zone
        _ => score -= 3.0,          // large leftover: keep, but not over-reward
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nr = post_residual - next_item_size;
            score -= 12.0 - (nr % 10) as f64 * 0.5;
            if nr % 10 == 0 && nr > 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here regardless; mild penalty for hoarding space.
            score += 2.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Avoid opening a new bin when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score = bin_capacity as f64 * 1.5;
        // Open it early in the stream when few bins exist and mean residual is high.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 {
            score -= 60.0;
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 30.0 * (1.0 - progress);
        }
        // If many open bins with slack, discourage new bin.
        score += mean_residual * 0.4;
    } else if fitting_bins_count > 2 {
        // Plenty of alternatives: mild penalty to prefer tighter fits elsewhere.
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the next item (when it exists) are likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 35.0;
    }
    // Reward tight fits: post_residual exactly 0 is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to open-bin count and mean residual.
        score += 45.0 + bin_pressure * 3.0 + mean_residual * 0.5;
    } else {
        // Existing bin: reward filling bins with large residual (consolidation).
        score -= (bin_residual as f64 / cap) * 5.0 + bin_pressure * 0.3;
    }

    // Prefer bins whose residual is close to item_size (minimal leftover).
    score -= 20.0 * (1.0 - ((bin_residual - item_size) as f64 / cap).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        // Aggressive 2-step lookahead: reward exact match of post_residual to next item
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;

        // Perfect two-item fill is a jackpot
        if post_residual == next_item_size {
            score -= 40.0;
        }

        // If next item would also fit here after this placement, mild bonus
        if next_item_size <= post_residual {
            score -= 8.0;
        }

        // Dead space: post_residual too small for next item and small in absolute terms
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    }

    // Compare against mean residual across open bins
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize unless current bin fit is truly bad
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen when they beat a poor fit
        score += 30.0;
        // Late in the stream, or with many open bins, discourage new bins more
        score += 10.0 * progress + 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is more attractive
        score -= 0.15 * item_size as f64;
    }

    // Penalize very tight fits creating tiny dead space (fragmentation)
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Reward tight fits overall (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 14.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space that likely can't fit future items.
    if post_residual > 0 && post_residual < 10 {
        // small but nonzero gap: mostly dead space for items >= 10
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else {
        // When many bins fit, prefer the tightest one; mild spread penalty.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            // leaving room for next item is good, scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large leftovers slightly
            score += 0.05 * (post_residual as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 5.0 * consolidation * (1.0 - progress);

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin fits the item poorly (high post residual waste) or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // But if current bin is a poor fit (post residual large relative to capacity),
        // a fresh bin becomes more attractive.
        let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
        if waste_ratio > 0.5 {
            score -= 8.0 * (waste_ratio - 0.5);
        }
        // Late in the stream, avoid opening new bins (hard to fill them).
        if progress > 0.85 {
            score += 15.0 * (progress - 0.85);
        }
        // If the next item is large, a fresh bin with big residual is useful.
        if next_item_size > 0 && post_residual >= next_item_size && next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mild penalty when few bins remain open but stream is long: keep bins usable.
    if open_bins_count == 1 && progress < 0.5 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_ir = ir / cap;

    // Base: post-residual with non-linear shaping (dead space penalized super-linearly)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more; residual waste is amplified.
    let coupling = norm_pr * norm_pr * (1.0 - norm_pr) * (progress * 2.0 + 0.5);
    score += 40.0 * coupling;

    // Reward filling the bin well: subtract a smooth function of item size vs residual
    let fill = norm_ir * (1.0 - norm_pr);
    score -= 25.0 * fill * (0.5 + progress);

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Mean residual context: placing into a bin below mean residual (loose bin) is cheaper
    score -= 3.0 * ((mean_residual - pr) / cap);

    // New-bin candidate: bin_residual == bin_capacity (empty). Penalize mildly so
    // it only wins when open bins are genuinely bad fits (high post_residual there).
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are
    // "usable" by common item sizes (multiples of 5/10 classes).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 && pr >= 10 {
        -25.0 // residual matches the coarsest harmonic class
    } else if pr % 5 == 0 {
        -12.0
    } else {
        // awkward residue: dead-space penalty scaled by how small it is
        15.0 * (1.0 - pr as f64 / 20.0).max(0.0)
    };
    score += class_bonus;

    // Integer-division threshold: residuals in (0..10] are nearly dead space
    // unless consumed now — strongly favor filling them.
    if pr > 0 && pr <= 10 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item can land exactly in the
    // post-residual, this placement chains nicely.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 35.0;
        } else if (pr % next_item_size) == 0 {
            score -= 18.0;
        } else {
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        }
    } else if next_item_size > pr {
        // next item won't fit here; penalize leaving a mid-size orphan
        if pr > 0 && pr < 40 {
            score += 10.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): opening a new bin
    // should only win when existing fits are poor. Make the empty-bin
    // baseline sit above well-fitting open bins.
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in the stream, or when open bins are crowded, a fresh bin
        // is cheaper — soften the penalty
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 25.0; // existing bins are nearly full anyway
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate space into few bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit anywhere else, avoid blocking this bin awkwardly.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * open_bins_count as f64 - 10.0 * mean_residual / bin_capacity as f64;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward scaled by closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit -> dead space penalty proportional to shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * shortfall;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual), already the base term.
        score -= 5.0;
    }

    // Compare against mean residual: bins with residual near the mean are "normal";
    // penalize bins whose post-residual deviates strongly upward (wasteful leftovers).
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.1 * dev; // slightly reward below-mean leftovers
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize so it is only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper; late in stream, be conservative.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= 0.2 * next_item_size as f64;
        }
        // Many open bins -> discourage adding another.
        score += 1.5 * open_bins_count as f64;
    }

    // Slight preference for filling bins tighter than the naive residual ordering
    // when the item is large (big items are hard to place later).
    if item_size > bin_capacity / 2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 12.0;
    } else {
        // Penalize dead space that is too small for the smallest future item.
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Lookahead: penalize if placing here blocks the next item from fitting.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 6.0;
        } else {
            // reward leaving space that exactly accommodates next item
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // mild preference to spread across many options (keep flexibility)
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a bin is usually wasteful,
    // but attractive when the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // base penalty for opening a new bin
        let mut open_penalty = 18.0;
        // large items justify new bins
        open_penalty -= fill_frac * 20.0;
        // if only this bin fits, opening is competitive
        if fitting_bins_count == 1 {
            open_penalty -= 10.0;
        }
        // early in stream, opening is cheaper (more future items to fill it)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        open_penalty -= (1.0 - progress) * 8.0;
        // many open bins with high mean residual: better to use one of them
        open_penalty += (open_bins_count as f64).ln().max(0.0) * 2.0
            + (mean_residual / cap).clamp(0.0, 1.0) * 5.0;
        score += open_penalty;
    }

    // Slight preference for bins below mean residual (balance residuals),
    // keeping mid-size gaps available for medium items.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 3.0;

    // Small time-dependent nudge: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: tight fit reward via non-linear polynomial in post_residual
    let mut score = post * (1.0 + 0.012 * post / cap);

    // Smooth penalty on small post_residuals (dead space) — quadratic coupling
    let tiny = (1.0 - (post / cap).min(1.0)).powi(2);
    score += 8.0 * tiny * (1.0 - fill);

    // Stream progress coupling: prefer tighter packing later in the stream
    score -= 6.0 * fill * fill * (0.5 + progress);

    // Lookahead: reward if next item fits into post_residual (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (1.0 - (nxt / post.max(1.0)).min(1.0)).powi(2);
        score -= 4.0 * fits * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 + 5.0 * fill;
    }

    // Mean residual coupling: prefer bins deviating smoothly from mean
    score += 0.05 * (mean_residual - post).abs();

    // New-bin candidate: penalize unless residual is very large relative to item
    if is_new_bin {
        score += 14.0 - 6.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo 10
    // Post-residuals in 1..=9 are near-unusable dead space -> strong penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Post-residual divisible by 10 or 25 leaves "harmonic" chunks reusable
    // by typical item sizes -> reward those classes.
    if post_residual >= 10 {
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack <= 9 {
            score += 15.0; // next item leaves dead space here
        } else {
            score -= 6.0;
        }
    }
    // If next item cannot fit in post_residual, mild penalty for blocking.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // New-bin candidate: penalize so we prefer reusing open bins,
    // unless the stream is early (bootstrap) or bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = cap * 0.6 + 30.0 * (1.0 - progress);
        if open_bins_count as f64 > mean_residual {
            nb -= 10.0; // many bins with small residuals -> new bin attractive
        }
        if fitting_bins_count == 0 {
            nb -= 100.0; // must open a new bin
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (>=1),
    // but tiny gaps (< 10) are pure dead space; gaps just below next_item_size are wasted too.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // gap can't serve the lookahead item
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0; // perfect lookahead fit
    }

    // Reward tight fits strongly (exact fill is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness;
    }

    // Penalize creating gaps that are "awkward": large but not large enough for typical items.
    if post_residual > 50 && post_residual < 60 {
        score += 8.0;
    }

    // Last chance: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the fit is bad everywhere.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits tightly, allow new bin when open-bin count is low.
        if post_residual < item_size / 2 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += (open_bins_count as f64) * 0.8;

    // Slight preference to fill bins with low mean residual (consolidate emptier bins later).
    score -= 0.05 * mean_residual;

    // Late-stream tightening: near the end, avoid leaving many partial bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        if next_fit == 0 {
            score -= 400.0; // chain perfect fit
        } else {
            score -= 150.0 * (1.0 - (next_fit as f64) / (bin_capacity as f64));
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize dead space creation
        score += 40.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize bins far from mean residual (prefer balanced usage)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_residual - item_size) as f64;
        // base penalty to prefer existing bins
        score += 60.0;
        // if few fitting bins and this fit is bad, encourage new bin
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
        // encourage new bin when post_residual would be tiny dead space in existing bins
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 100.0;
        }
        // reward large leftover in new bin (usable for future items)
        score -= 0.2 * waste;
    }

    // Tight fit preference: smaller post_residual relative to item size is good
    score += 0.1 * (post_residual as f64);

    // Late in stream: consolidate, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Penalize leaving tiny, unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item cannot fit in the post-residual,
    // this bin becomes sealed; penalize sealing with lots of space left,
    // reward sealing when little space remains.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * post_residual as f64;
        } else {
            score -= 4.0;
            // Bonus if next item fits snugly after this placement.
            let next_fit = (post_residual as f64 - next_item_size as f64).abs();
            score -= 6.0 / (1.0 + next_fit);
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes nothing now,
    // but should only win when the fit here is poor. Make the empty bin
    // attractive only via a mild baseline, penalized when open bins exist
    // and mean residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 20.0 * progress;
        if open_bins_count > 0 {
            score += mean_residual * 0.25;
        }
        // Never open a new bin on the very last item if anything fits.
        if next_item_size == 0 && open_bins_count > 0 {
            score += 100.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.6 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean toward tightness.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    let mut score = post;

    // Reward tight fits: small post_residual relative to capacity, smoothly.
    let tightness = 1.0 - post / cap; // 0..1, 1 = perfect fill
    let tight_reward = tightness * tightness * (20.0 + 30.0 * progress);
    score -= tight_reward;

    // Penalize dead space: residuals too small to be useful later (non-linear).
    let dead_zone = (1.0 - post / (0.35 * cap)).clamp(0.0, 1.0);
    let dead_penalty = dead_zone * dead_zone * (10.0 + 20.0 * (1.0 - progress));
    score += dead_penalty;

    // Lookahead coupling: bonus if next item fits the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - (post - next_item_size as f64) / cap;
        score -= 8.0 + 15.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Mild penalty if next item cannot follow into this bin.
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * (item / cap);
    }

    // Spread pressure: when many bins are open, prefer consolidating into fuller bins.
    let fullness = 1.0 - resid / cap;
    score -= fullness * fullness * (5.0 + 3.0 * (open_bins_count as f64).ln().max(1.0));

    // Mean-residual coupling: deviating favorably from the mean residual is good.
    let dev = (mean_residual - post) / cap;
    score += 6.0 * dev * dev * dev.signum();

    // New-bin candidate handling: make empty bins attractive only when current
    // bin fits are poor, via smooth competition rather than hard thresholds.
    if bin_residual == bin_capacity {
        let stream_pressure = progress * (1.0 - item / cap);
        score += 12.0 + 18.0 * (1.0 - stream_pressure);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core tight-fit reward: exponential decay of wasted space.
    let waste_frac = post_residual as f64 / cap;
    score -= 60.0 * (-waste_frac * 8.0).exp();

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes on post_residual: small dead-space classes are
    // reusable by typical small items (1..=100 range).
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 25.0,               // round residual, highly reusable
        1 | 2 | 3 => score -= 12.0,       // near-round, moderately reusable
        4 | 5 | 6 => score -= 6.0,
        _ => {}                            // 7..9: awkward slivers, no reward
    }
    // Integer-division thresholds: bins that can still host a medium item.
    if pr / 25 >= 1 { score -= 15.0; }   // residual >= 25
    if pr / 50 >= 1 { score -= 15.0; }   // residual >= 50

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            score -= 30.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // Next item cannot use this residual: penalize leaving medium gaps.
            score += 8.0 * (1.0 - (pr as f64 / next_item_size.max(1) as f64)).min(1.0);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a decent fit (all residuals small relative to item).
    if bin_residual == bin_capacity {
        // Base penalty so open bins with any reasonable fit win.
        score += 70.0;
        // But if mean residual across open bins can barely fit items,
        // opening fresh space is good.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 90.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large items open fresh bins more readily (less packable).
        if item_size >= 50 {
            score -= 25.0;
        }
    }

    // Prefer filling bins that are already mostly full (fewer partially
    // filled bins competing for future items).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 20.0 * fill;

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful for typical items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // completely dead gap
        } else if post_residual <= 20 {
            score += 25.0; // near-dead gap
        } else if post_residual <= 35 {
            score += 8.0;  // marginal gap
        } else {
            score -= 5.0;  // still usable residual
        }
    } else {
        score -= 40.0; // perfect fill: strongly reward exact closure
    }

    // Reward tight fits relative to item size (small relative slack).
    let slack_ratio = post_residual as f64 / (bin_capacity as f64).max(1.0);
    score += 30.0 * slack_ratio;

    // Open-bin pressure: when many bins are open, discourage opening more
    // unless the fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 15.0; // next item cannot use this dead gap
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below the
    // mean (i.e., tighter than average bins get priority).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are very full on average and many bins are already open.
    if bin_residual == bin_capacity {
        // Baseline penalty so a new bin is chosen only for poor fits elsewhere.
        score += 20.0;
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 30.0; // open bins are nearly dead; open a fresh one
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space penalty, non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // this placement is ideal — heavily reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward, scaled by tightness.
            let look_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * look_ratio * look_ratio;
        } else {
            // Next item cannot use the leftover: penalize wasted space.
            score += 10.0;
        }
    }

    // Compare residual against the mean residual of open bins: prefer bins
    // that are more filled than average (below-mean residual).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 8.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 6.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable slivers (dead space < 10 can't fit anything).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect closure: best possible outcome.
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual relative to item) late in the stream.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64) - fragmentation
        } else {
            0.0
        };
        score = 55.0 + 30.0 * progress - 20.0 * pressure.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space left behind (hard-to-use slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // Bonus if both current and next item pack perfectly together.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: any leftover is pure waste, push toward tightest fill.
        score += 15.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins with slack -> consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score -= 0.05 * open_pressure * (1.0 - progress);

    // Mean residual coupling: if average slack is high, prefer bins below mean
    // (drain the fullest useful bins first), keeping many small slacks consolidated.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: default penalty so we only open a new bin
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            // Desperation grows when every fitting bin would leave a bad leftover.
            let best_possible = 1.0 - fit_ratio.min(1.0);
            (1.0 - best_possible).clamp(0.0, 1.0)
        };
        score += 55.0 - 35.0 * desperation + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post_residual, but with non-linear polynomial shaping.
    let mut score = post + 12.0 * post_norm * post_norm * cap;

    // Stream-progress coupling: early on, tolerate loose fits (score softened);
    // late in the stream, penalize wasted space quadratically.
    let late = progress * progress;
    score += 60.0 * late * post_norm;

    // Smooth interaction: post_residual vs mean residual deviation.
    let dev = post_norm - (mean_residual / cap);
    score += 25.0 * dev * dev;

    // Lookahead coupling: reward residual that can still hold the next item,
    // penalize residual that neither fits next item nor is near zero (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 18.0 * (1.0 - post / (post + nxt)) * (1.0 + late);
        } else {
            score += 15.0 * (1.0 - post / nxt) * (0.5 + late);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Mild penalty when many bins are open, encouraging consolidation.
    score += 0.4 * open_bins_count as f64 * post_norm;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let tight = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 30.0 * tight + 20.0 * post_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual ---
    // Class 0: post_residual is a multiple of a "nice" quantum (10) -> highly reusable.
    // Class 1: post_residual < smallest item (dead space) -> heavy penalty.
    // Class 2: post_residual small but usable -> moderate penalty.
    let quantum: u32 = 10;
    let dead_zone: u32 = 10; // smallest plausible item size

    if post_residual < dead_zone {
        // Dead space: unusable remainder
        score += 45.0 + (dead_zone - post_residual) as f64 * 2.0;
    } else if post_residual % quantum == 0 {
        // Perfectly aligned residual: subtract reward, deeper alignment = better
        let alignment = (post_residual / quantum) as f64;
        score -= 12.0 + alignment.min(8.0) * 1.5;
    } else {
        // Misaligned residual: penalize by distance to next lower multiple of quantum
        let off = (post_residual % quantum) as f64;
        score += off * 0.8;
    }

    // --- Harmonic class of the item itself (capacity fraction) ---
    let frac = item_size as f64 / cap; // in (0,1]
    // Items that are exact capacity fractions (0.25, 0.5, 0.75) pack cleanly;
    // prefer bins where such items leave aligned residuals.
    let near_half = (frac - 0.5).abs();
    if near_half < 0.05 {
        score -= 6.0; // half-capacity items: keep them in well-filled bins
    }

    // --- Integer-division threshold coupling: post_residual vs next_item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can chain into this bin: strong reward, scaled by slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + slack.min(30.0) * 0.3;
            // Bonus if chained placement also lands on a quantum boundary
            if (post_residual - next_item_size) % quantum == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's remainder: mild penalty for wasting space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: just dump it anywhere it fits; prefer tightest fit
        score += 0.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits: strongly prefer using it over opening a new bin
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; make it competitive only when
        // existing residuals are poor (high mean residual waste).
        score = cap - (item_size as f64);
        // Open a new bin if existing bins are too full/fragmented on average
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
        // Late in the stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // Many open bins already: discourage more sprawl
        score += open_bins_count as f64 * 0.5;
    }

    // --- Mean-residual coupling: prefer bins near the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // --- Fill-level incentive: reward bins that are already heavily loaded ---
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * fill * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable
    // for any future item, so penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps just above the minimum item size are fragile; mildly penalize.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        score += 25.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
        // If next item could use this bin's residual after placement, soften.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight preference when residual is below mean (tighter bin).
        score -= 5.0 + (mean_residual - bin_residual as f64).max(0.0) * 0.1;
    }

    // Lookahead synergy: if the next item exactly fits the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-gap / 8.0).exp();
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item larger than post_residual: this residual is dead space for next step
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Penalize unusable dead space relative to minimum item size
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 1 {
        score -= 30.0; // perfect fill
    } else if post_residual < 10 {
        score -= 8.0 * (1.0 - post_residual as f64 / 10.0);
    } else {
        score += 0.15 * post_residual as f64 * (0.5 + 0.5 * progress);
    }

    // Compare against mean residual: prefer bins with less residual than average (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: discourage unless few bins open or item is large
    if bin_residual == bin_capacity {
        let new_bin_bonus = 20.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            - 0.5 * open_bins_count as f64;
        score += new_bin_bonus.max(-5.0) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item could fit into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits (within 10), mild reward.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 * 0.8 {
        score -= 4.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or many bins are open.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.6;
        if poor_fit && (open_bins_count > 3 || progress > 0.5) {
            score -= 12.0; // open new bin rather than fragment an existing one badly
        } else {
            score += 40.0; // discourage opening new bins when decent fits exist
        }
    }

    // Global fragmentation pressure: if mean residual is low, conserve remaining space harder.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Time horizon: late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Slight penalty for using a bin whose residual is much larger than mean (preserve big bins).
    if bin_residual as f64 > mean_residual + 20.0 && !is_new_bin {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, dead space is penalized more.
    let prog_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0 * progress; // smooth ramp
    score += 0.35 * (pr / cap) * (pr / cap) * cap * prog_coupling;

    // Reward filling bins deeply, scaled by how full the bin becomes
    let fill_ratio = 1.0 - (pr / cap);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead: if next item fits exactly in the post residual, reward strongly (smooth kernel)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_kernel = (-gap * gap / (2.0 * 25.0)).exp(); // gaussian around exact fit
        score -= 8.0 * fit_kernel * (0.5 + progress);
        // penalize post residuals too small for the next item (dead space)
        let too_small = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 15.0 * too_small * too_small * cap / 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild pressure toward consolidating into fewer bins when many are open
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced, smooth quadratic term)
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: make empty bins slightly unattractive unless the item
    // is large relative to capacity (smooth term, no piecewise cutoff)
    if bin_residual == bin_capacity {
        let large_item = (it / cap).powi(3);
        score += 6.0 - 6.0 * large_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: strongly reward small post_residual.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class of post_residual: residual buckets mod 10.
    // Residuals that are "harmonically awkward" (small, hard to fill) get penalized.
    let cls = (post_residual % 10) as f64;
    if post_residual > 0 {
        // small leftovers (1..=9) are near-dead space
        score += 12.0 * (10.0 - cls) / 10.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward if next item can still fit here
        let slack = post_residual - next_item_size;
        score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here: mild penalty, worse for tiny post_residual
        score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Reward using bins that are already relatively full (harmonic fraction of capacity).
    let fill_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Penalize opening a new bin when decent open bins exist, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost so it's only chosen when it returns lowest score
        score += 60.0 + 40.0 * progress;
        // but if no open bin fits, this becomes the natural choice
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (fuller than average).
    score += 10.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;

    // Harmonic integer-division threshold: residual / item ratio classes.
    if item_size > 0 {
        let ratio = post_residual as f64 / item_size as f64;
        if ratio < 0.25 {
            score -= 10.0; // very tight fit relative to item
        } else if ratio > 1.5 {
            score += 8.0; // item much smaller than residual: wasteful pairing
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are disproportionately penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space penalty grows super-linearly as the gap becomes unusable-small.
        score += 40.0 / (gap * gap + 1.0);
        // Anything below the smallest plausible follow-up item is nearly dead space.
        if gap < 10.0 {
            score += 60.0 - gap * 5.0;
        }
    } else {
        // Perfect fill is strongly rewarded.
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are healthy.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    // New-bin candidate handling: only attractive when no open bin offers a good fit
    // (i.e., mean residual across open bins is small relative to the item).
    if bin_residual == bin_capacity {
        let mean_fit_gap = mean_residual - item_size as f64;
        if mean_fit_gap >= 0.0 && mean_fit_gap < 15.0 {
            // Open bins can absorb the item acceptably; make new bin unattractive.
            score += 80.0;
        } else {
            // Poor fits elsewhere: opening a fresh bin is reasonable; slight discount
            // so it beats bins that would leave tiny dead gaps.
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Lookahead coupling: if the next item would exactly fill the resulting gap, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        let nd = next_item_size as f64;
        if (nd - gap).abs() <= 2.0 {
            score -= 45.0;
        } else if nd <= gap {
            score -= 10.0 * (1.0 - (gap - nd) / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste after placement.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Two-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits here too; prefer bins leaving a good follow-up fit
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit after placement: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    } else {
        // last item: minimize final residual hard
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: prefer bins with residual near the mean (balanced usage),
    // but allow deviation when it creates a perfect lookahead match.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * progress; // penalize new bins more as stream progresses
        if next_item_size > 0 && bin_capacity as f64 - item_size as f64 >= next_item_size as f64 {
            score -= 20.0; // fresh bin can host current + next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize dead space relative to smallest possible future item
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * 30.0;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 5.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // the item fits poorly everywhere or the stream is nearly done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin
        score += 40.0;
        // More willing to open new bin when item is large or few bins fit it
        score -= fit_ratio * 20.0;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Near end of stream, prefer compacting into existing bins
        score += progress * 15.0;
        // If mean residual across open bins is small (bins are full-ish), new bin reasonable
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Prefer tighter existing bins: penalize bins with large residual when mean is low
    let res_gap = bin_residual as f64 - mean_residual;
    score += res_gap * 0.1;

    // Mild preference to fill bins that are already heavily used
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 10.0;

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * dead_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual.
    let mut score = post;

    // Smooth non-linear reward for tight fits (quartic in normalized fill).
    let fill = 1.0 - post / cap;
    score -= 18.0 * fill * fill * fill * fill;

    // Penalize dead space that cannot fit typical future items: quadratic coupling
    // of post_residual with stream progress.
    score += 0.004 * post * post * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if post residual leaves room for the next item,
    // penalize if the next item could have fit here but this placement strands it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Next item can still go here: good.
            score -= 6.0 * (1.0 - post / cap);
        } else if bin_residual >= nxt && nxt >= item_size as f64 {
            // We consumed space the next (larger) item needed.
            score += 10.0 * (nxt - post) / cap;
        }
        // Smooth bonus for exact-ish chaining: post close to next size.
        let gap = (post - nxt).abs();
        score -= 5.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap).max(0.0);
    }

    // Slight preference for consolidating into bins below mean residual
    // (fill emptier bins first, keep tight bins tight) — smooth coupling.
    score += 0.05 * (post - mean_residual) * (0.5 + progress);

    // Mild encouragement to open new bins early when many bins are open
    // and the fit is mediocre (post residual large).
    score += 0.02 * post * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate handling: neutral-ish baseline, penalized when a good
    // fit exists elsewhere; favored when item barely fits nothing well.
    if bin_residual == bin_capacity {
        score += 8.0 - 12.0 * (1.0 - item_size as f64 / cap);
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let fifth = cap / 5.0;

    // Dead-space penalty: leftovers that no future item (sizes 1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }
    // Integer-division thresholds on post_residual: classes of 20 (capacity / 5).
    let class = post_residual / 20;
    score += match class {
        0 => 0.0,                       // 0..19: near-perfect fill
        1 => 6.0,                       // 20..39: still useful
        2 => 14.0,                      // 40..59: moderate
        3 => 20.0,                      // 60..79: poor
        _ => 8.0,                       // 80..100: new-bin candidate handled below
    };

    // Modulo-arithmetic harmony: leftover that matches common item sizes is valuable.
    // Favor residuals that are multiples of 10 or 25 (likely future fits).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Harmonic coupling: next item leaves a good class again.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score += (next_post as f64) * 0.15;
        } else {
            // Next item cannot use this bin's leftover anyway; leftover is dead weight
            // unless another bin takes the next item. Penalize proportionally.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should only win
    // when open bins offer genuinely bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: a bit worse than a decent fit.
        score = cap * 0.75;
        // If the current item would leave a great class in a fresh bin (exact fill),
        // opening is cheap.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // If no open bin can fit the item, the new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Early stream: opening bins is fine; late stream: prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If mean residual across open bins is large, we should use them instead.
        score += mean_residual * 0.3;
    }

    // Mild preference to spread into emptier bins when many are open.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: small unusable gaps are heavily penalized ---
    if post_residual > 0 && post_residual <= 12 {
        score += 30.0; // tiny sliver gaps are almost never reusable
    } else if post_residual > 12 && post_residual <= 25 {
        score += 10.0; // moderately awkward gaps
    }

    // --- Reward tight fits (small post_residual relative to item size) ---
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fit_ratio;

    // --- Lookahead: if next item fits exactly in the post residual, reward this bin ---
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // --- Open-bin pressure: prefer consolidating into fewer bins ---
    score += 0.8 * open_bins_count as f64;

    // --- Last-chance bonus: if this is the only bin that can fit the item ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is usually worse than using an existing fitting bin...
        let mut new_bin_penalty = 18.0 + 0.5 * open_bins_count as f64;
        // ...unless no open bin fits (this is the only option)
        if fitting_bins_count == 0 {
            new_bin_penalty = -50.0;
        }
        // ...or the item is huge and would leave a good usable residual elsewhere
        if fit_ratio > 0.8 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // --- Mild stream-progress adaptation: early on, be more willing to open bins
    // to keep flexibility; later, consolidate tightly ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // --- Mean residual coupling: if average residual is large, discourage adding waste ---
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fits post_residual,
    // penalize if next item cannot fit and post_residual is too small to be useful.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space, worse if small
            let dead = post_residual as f64;
            score += 0.5 * dead * dead / bin_capacity as f64;
            if dead < 10.0 {
                score += 50.0; // tiny unusable sliver
            }
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins),
    // penalize placing into bins far above mean (wasteful large residual usage).
    let res = bin_residual as f64;
    score += 0.3 * (res - mean_residual);

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., item is large relative to typical residual) or few fitting bins exist.
    if bin_residual == bin_capacity {
        // Base new-bin cost: opening a bin is expensive.
        score += 250.0;
        // But if the item is large and would leave a big residual in any open bin,
        // a fresh bin is competitive: subtract when item large.
        score -= 2.0 * item_size as f64;
        // If next item is small, a fresh bin can absorb both: reduce cost.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 100.0;
        }
        // Fewer fitting bins -> new bin more acceptable.
        score -= 40.0 * (fitting_bins_count as f64).recip().max(0.0) * 10.0;
    } else {
        // Slight preference to keep many open bins from growing: mild penalty
        // proportional to open bin count to encourage consolidation.
        score += 0.05 * open_bins_count as f64;
    }

    // Stream progression: late in stream, prefer closing bins tightly (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
