    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins open or item is huge relative to mean residual.
        let pressure = open_bins_count as f64 * (1.0 + progress);
        let item_rel = item_size as f64 / mean_residual.max(1.0);
        score += 15.0 + pressure - 8.0 * item_rel;
        if item_size >= 50 && item_rel > 1.2 {
