    if bin_residual == bin_capacity {
        let base = 10.0 + 14.0 * progress;
        let pressure = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        score += base * pressure;
    }

    // Mild preference for consolidating into fewer bins as stream advances
    score += 0.02 * (open_bins_count as f64) * progress;

    score
}

