        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else if post_residual >= 10 {
        // Larger usable residual is mildly rewarded relative to raw value.
        score -= 3.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use leftover space: penalize proportionally.
        score += 4.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.4;

    // Mean residual coupling: penalize bins deviating far below mean residual
    // (they will become dead space soon).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists or item is huge.
    if bin_residual == bin_capacity {
        score += 18.0; // default bias toward using existing bins
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size >= 70 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score += 8.0; // keep space free for a big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: only attractive when no good fit exists
    // among open bins (few fitting bins) or the fit would be very tight.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        // Reward a fresh bin when open bins are scarce or fragmented.
        let bonus = 40.0 * fit_pressure + (open_bins_count as f64) * 0.5;
        // Penalize opening new bins when plenty of bins fit decently.
        let penalty = if fitting_bins_count > 2 { 60.0 } else { 0.0 };
        return 120.0 - bonus + penalty;
    }

    // Aggressive 2-step lookahead: perfect match of leftover with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact fill of the remainder by the next item -> excellent.
            score -= 55.0;
        } else if post_residual > next_item_size {
            // Next item still fits afterward; reward proportional slack usage.
            score -= 10.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space smaller than next item: penalize heavily, scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 + 0.6 * gap;
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 5.0;
    }

    // Last chance bin (only fitting bin): strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty so we prefer bins that are the unique fit elsewhere.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residual below mean (denser bins) to consolidate waste.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight late-stream bias toward filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: prefer placements that leave small post-residual.
    let tightness = 1.0 - (post / cap);
    score -= 60.0 * tightness * tightness;

    // New-bin candidate: penalize opening a new bin, strongly when other bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Late in the stream, opening new bins is cheaper (less future waste risk).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
    } else {
        // Last-chance bonus: only fitting bin -> strongly prefer using it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Lookahead: if next item fits exactly-ish in post residual, reward.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 55.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // post residual too small for next item: penalize dead space.
            score += 12.0;
        }
        // Prefer bins with residual below mean (consolidate emptier bins for future items).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // Avoid leaving residuals too small to ever be useful (below min item size 1..100 guess ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Non-linear coupling of post_residual with stream progress:
    // early on, residual waste is cheap; late, it is expensive (quadratic ramp).
    let progress_waste_penalty = post * (1.0 + 2.5 * progress * progress);

    // Normalized post-residual dead-space term, superlinear to punish small slivers.
    let post_norm = post / cap;
    let sliver_penalty = post_norm.powi(3) * cap;

    // Reward tight fits: subtract when post_residual is small relative to item.
    let tight_fit_bonus = -(fit * (cap - post) * (0.5 + 0.5 * progress));

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    let mut lookahead_bonus = 0.0;
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let exactness = 1.0 - (post - nxt) / cap;
            lookahead_bonus -= 6.0 * exactness * exactness;
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            lookahead_bonus += 0.05 * (nxt - post).min(cap) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    let last_chance_bonus = if fitting_bins_count == 1 { -8.0 } else { 0.0 };

    // New-bin candidate handling: penalize opening a new bin, but relax late in
    // the stream or when open bins have large mean residual (fragmented state).
    let mut new_bin_penalty = 0.0;
    if bin_residual == bin_capacity {
        new_bin_penalty += 4.0 + 3.0 * progress;
        // If existing bins are heavily fragmented, a fresh bin is more attractive.
        new_bin_penalty -= (mean_residual / cap).min(1.0) * 3.0 * progress;
    }

    // Mild dispersion term: prefer bins whose residual deviates from the mean
    // in a way that consolidates space (bring post closer to mean residual).
    let consolidation = -0.15 * (mean_residual - post).abs() / cap * cap * 0.01;

    let mut score = progress_waste_penalty
        + sliver_penalty
        + tight_fit_bonus
        + lookahead_bonus
        + last_chance_bonus
        + new_bin_penalty
        + consolidation;

    // Tie-breaker: tiny deterministic nudge toward lower residual bins.
    score += post as f64 * 1e-3;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item granularities (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal closure
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 6.0; }
        if pr % 50 == 0 { bonus += 10.0; }
        score -= bonus;

        // Dead-space penalty: residual too small for the smallest plausible item.
        if pr < 10 {
            score += 45.0;
        } else if pr <= 15 {
            score += 12.0;
        }

        // Integer-division thresholds: how many "medium" chunks (>=20) fit.
        let chunks = pr / 20;
        score -= chunks as f64 * 4.0;

        // Harmonic match with the lookahead item: reward residuals that the
        // next item can exactly fill or leave a good residue class.
        if next_item_size > 0 {
            let ni = next_item_size;
            if ni <= pr {
                let nxt_post = pr - ni;
                if nxt_post == 0 {
                    score -= 25.0; // next item closes this bin perfectly
                } else if nxt_post % 10 == 0 {
                    score -= 10.0;
                }
                // penalize if next item leaves a tiny unusable remainder
                if nxt_post < 10 && nxt_post > 0 {
                    score += 8.0;
                }
            } else {
                score += 6.0; // next item cannot reuse this residual at all
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        let tight = (item_size as f64 / cap) > 0.7;
        if tight {
            score -= 25.0; // big item: fresh bin is fine
        }
        if open_bins_count > 0 && post_residual >= 30 && fitting_bins_count > 0 {
            score += 15.0; // avoid opening bins when decent fits exist
        }
    }

    // Phase of the stream: late in the stream, prefer closing bins tightly.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * (post_residual as f64) * 0.3;
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Mean-residual coupling: when open bins are already loose, penalize
    // leaving this one loose too.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard (super-linear).
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            score += 25.0 * (10.0 - pr); // tiny gap = pure waste
        } else if pr < 25.0 {
            score += 6.0 * (25.0 - pr); // awkward gap
        }
    }

    // Reward if the lookahead item can also fit in the resulting gap (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for next item: mild penalty proportional to how close it was
        score += 2.0 * (1.0 - (next_item_size - post_residual) as f64 / 100.0).max(0.0);
    }

    // Open-bin pressure: discourage spreading across many bins; favor tightening.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space penalty already dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets post_residual = capacity - item,
    // which is large; add extra cost so new bins open only when placement elsewhere
    // would create severe dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if no open bin fits at all, opening is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit reward).
    score -= 0.3 * (bin_residual - item_size) as f64;

    // Mild progress adaptation: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_capacity as f64 - pr - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect two-item pairing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // Exact match: strong bonus (post residual exactly fits next item).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Slight overfill risk: if next item cannot fit, mild penalty
        // proportional to how much dead space is created.
        if post_residual < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    // (best-fit flavor), penalize bins looser than average.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when no open bin fits well, i.e. penalize opening
    // a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 20.0 + 0.5 * mean_residual;
        } else {
            score -= 5.0;
        }
        // Late in the stream, opening new bins is cheaper (fewer future
        // items to consolidate); reduce the penalty slightly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Prefer keeping the number of open bins manageable: when many bins
    // are open, favor filling existing ones (implicit via post_residual),
    // but when few bins are open, small extra encouragement to pack tight.
    if open_bins_count < 4 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, especially small post-residuals that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver given min item size 1..100 unknown, mild penalty
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    }
    // Penalize bins that would leave post-residual just below the next item (dead zone).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when the item is large and open bins are crowded (high mean residual).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / bin_capacity as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        // Base cost of a new bin, discounted when item is huge and bins are full.
        score += 55.0
            - 0.35 * item_size as f64
            + 30.0 * (1.0 - crowding)
            - 8.0 * open_pressure
            - 10.0 * progress;
    }

    // Mild global-state coupling: prefer bins below mean residual early (keep big
    // holes available), prefer bins above mean residual late (consolidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let diff = bin_residual as f64 - mean_residual;
    score += (1.0 - 2.0 * progress) * 0.05 * diff;

    // Fragmentation guard: discourage leaving residuals that few future sizes fit.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post_residual, with non-linear sharpening.
    let mut score = pr + 12.0 * (pr / cap).powi(2) * cap;

    // Polynomial coupling with stream progress: late in the stream,
    // dead space becomes more costly (less chance to fill it).
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * (pr / cap) * 40.0;

    // Early stream: mildly favor spreading (keep residuals balanced).
    let early = 1.0 - late;
    score -= early * ((pr - mean_residual) / cap) * 10.0;

    // Penalize very tight fits that leave unusable slivers when the
    // next item cannot use them; reward when next item fits the sliver.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let tight = 1.0 - ((pr / cap).powi(3));
        score += tight * (1.0 - fits_next) * 25.0;
        score -= fits_next * 15.0 * (pr / cap);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mild penalty for many open bins (consolidation pressure).
    score += (open_bins_count as f64) * (pr / cap) * 2.0;

    // New-bin candidate: keep it attractive when the fit is poor,
    // but discourage opening bins when post_residual is already small.
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.6 + pr * 0.2 + late * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fit is perfect; small nonzero
    // remainders are dead space; remainders in "useful" classes stay valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect packing, strongly reward
    } else if pr < 10 {
        score += 25.0; // tiny dead space, heavily penalize
    } else {
        // class residual mod 10: multiples of 10 pair well with mid-size items
        let cls = pr % 10;
        score += (cls as f64) * 1.5; // prefer residuals on harmonic grid
        // integer-division thresholds: residuals >= 50 can host another big item
        if pr >= 50 {
            score -= 8.0;
        } else if pr >= 25 {
            score -= 3.0;
        } else {
            score += 6.0; // 10..24 band: marginal usefulness
        }
    }

    // Lookahead: does this bin's post-residual fit the next item?
    if next_item_size > 0 && pr >= next_item_size {
        // harmonic match: next item lands exactly or on-grid
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score += 10.0; // would create dead space next step
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        score += 5.0; // next item cannot follow here
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize bins that are outliers vs mean residual (fragmentation control)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev.abs();

    // Early stream: keep bins tight; late stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: make it attractive only when item is large and
    // existing residuals are fragmented (many open bins, high mean residual).
    if bin_residual == bin_capacity {
        let large_item = item_size >= 50;
        let fragmented = open_bins_count >= 3 && mean_residual > 30.0;
        if large_item && fragmented {
            score -= 20.0; // allow opening a fresh bin
        } else {
            score += 40.0; // prefer existing bins otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful are heavily penalized (unusable gaps).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalty if the leftover gap cannot fit the lookahead item but could
    // otherwise have been useful (wasted pairing opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward reserving space so the next item still fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance pressure: strongly prefer using the only bin that fits
    // before being forced to open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new bin is cheap so don't over-reward reuse.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early / few bins, costly when many
        // bins are already open.
        score += pressure * 8.0 - 10.0;
    } else {
        // Reward filling existing bins more when open-bin count is high.
        score -= pressure * 2.0;
    }

    // Bias toward bins with residuals below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual large enough for next item: mild reward proportional to closeness.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.3 * (post_residual as f64 - next_item_size as f64).min(20.0);
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize unusable remainder.
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize creating very small dead space (< 10, unusable for min-size items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it less attractive than decent fits,
    // but competitive when all open bins would leave large waste.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Early in stream, be slightly conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward near-perfect fills strongly.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize small dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if we wasted a big residual.
            score += 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // New-bin candidate handling: empty bin should be chosen only when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, decaying when many bins are open or fit is scarce.
        let mut new_bin_penalty = 10.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        // Late in stream or many open bins: opening fresh bins is cheaper (less fragmentation risk).
        new_bin_penalty *= 1.0 - 0.4 * progress;
        if open_bins_count > 8 {
            new_bin_penalty -= 2.0;
        }
        score += new_bin_penalty;
        // Slight tie-break preference for new bins when mean residual is very low (all bins tight).
        if mean_residual < 15.0 {
            score -= 3.0;
        }
    }

    // Global fragmentation signal: penalize placements that diverge from mean residual,
    // encouraging balanced residual distribution across open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild exploration term early in the stream: prefer spreading load across bins
    // when few bins are open, to build a diverse residual portfolio.
    if progress < 0.3 && open_bins_count < 5 {
        score += 2.0 * (1.0 - progress);
    }

    // Penalize leaving residuals that match no plausible item (items are 1..100).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: post residual, scaled smoothly by progress
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let x = pr / cap; // normalized post residual
    score += 30.0 * x * x * (1.0 - x) * (0.5 + progress);

    // Penalize large post residuals late in the stream (dead space)
    score += 15.0 * x * x * progress;

    // Reward tight fits (small post residual) with smooth falloff
    score -= 20.0 * (-x * 6.0).exp();

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 12.0 * (1.0 - nx) * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 8.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    } else {
        score += 4.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for filling bins when many are open
    score -= 3.0 * (1.0 - x) * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 5.0 * ((mean_residual - pr) / cap).tanh();

    // New-bin candidate: penalize unless current fits are very poor
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fraction classes
    let post = post_residual;
    let quarter = bin_capacity / 4;
    let tenth = bin_capacity / 10;
    let class = post / tenth; // 0..10 harmonic class of leftover

    // Reward tight fits (small post_residual) with non-linear bonus
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post <= tenth {
        score -= 30.0;
    } else if post <= quarter {
        score -= 12.0;
    } else if post <= bin_capacity / 2 {
        score -= 4.0;
    }

    // Penalize dead space: leftover too small for the smallest plausible item (1..100 unknown, use 10 as safe floor)
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if (post as f64) >= ns {
            // leftover reusable by next item -> reward, scaled by how well it fits
            let slack = (post as f64 - ns) / cap;
            score -= 15.0 * (1.0 - slack);
        } else {
            // leftover can't host next item: dead space unless class is tiny
            score += 8.0;
            if post >= 10 && post < (next_item_size as u32) {
                score += 6.0;
            }
        }
    }

    // Last chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this empty bin
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; relax late in the stream or when many bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 35.0;
        // If current item is large relative to capacity, new bin is fine
        if (item_size as f64) > 0.7 * cap {
            new_bin_penalty -= 15.0;
        }
        // If mean residual across open bins is small, open bins are nearly full anyway
        new_bin_penalty -= (mean_residual / cap).min(1.0) * 10.0;
        new_bin_penalty -= progress * 5.0;
        score += new_bin_penalty;
        // Empty-bin post_residual equals capacity; neutralize the base term partially
        score -= 20.0;
    }

    // Mild preference to keep fewer open bins when many are open
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.05;
    }

    // Harmonic class tie-break: prefer leftovers in "nice" classes (multiples of quarter)
    if post % quarter == 0 && post > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still host the next item (useful gap).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the lookahead item: penalize extra.
        score += 8.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer tighter (already filled) bins when many bins are open.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 6.0;

    // New-bin candidate: only attractive when current bins are nearly full or item is huge.
    if bin_residual == bin_capacity {
        let tight_bins = mean_residual < item_size as f64;
        if item_size > 70 || (open_bins_count > 0 && !tight_bins && fitting_bins_count > 2) {
            score += 25.0; // discourage opening a new bin when reasonable fits exist
        } else {
            score += 5.0; // mild default penalty; new bins are last resort
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when other bins can fit the item,
        // but reduce penalty if this is the only fitting bin (forced).
        let penalty = if fitting_bins_count <= 1 { 20.0 } else { 45.0 };
        score += penalty;
        // Late in the stream, opening fresh bins is less harmful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
        return score;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: this bin's post residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 60.0; // strong reward: chains two items perfectly
        } else if post_residual >= next_item_size {
            // Next item fits here afterward: reward proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit after placement: penalize leftover dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0;
    }

    // Reward tight overall fit relative to mean residual of open bins.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mean_r {
        score -= 0.25 * (mean_r - post_residual as f64);
    } else {
        score += 0.15 * (post_residual as f64 - mean_r);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Small nudge toward filling nearly-full bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress) * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainability bonus, stronger early in the stream
            score -= 10.0 + 10.0 * (1.0 - progress);
        } else if post_residual > 0 {
            // penalize creating dead space that blocks the next item
            score += 5.0 + 0.1 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist; prefer the tightest anyway
        score += 1.0 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            // must open a bin
            score -= 30.0;
        } else {
            // opening a new bin is justified only when existing fits are poor:
            // penalize proportionally to how many bins fit and how full they are
            score += 12.0
                + 4.0 * (fitting_bins_count as f64)
                + 0.15 * mean_residual
                + 8.0 * progress;
        }
    }

    // Global state coupling: when mean residual is large, prefer reusing big-residual bins
    score -= 0.05 * mean_residual;

    // Slight preference for placing into emptier bins early, tighter bins late
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more.
    let tightness = (1.0 - norm_post).clamp(0.0, 1.0);
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score -= progress_weight * tightness * tightness * 8.0;

    // Penalize dead space non-linearly: small post_residual is fine,
    // mid-range residual (hard to fill later) penalized quadratically.
    let dead = norm_post * (1.0 - norm_post);
    score += 6.0 * dead * (0.5 - norm_post).abs() * 4.0 * (1.0 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = (post - nxt) / cap;
            score -= 4.0 * (1.0 - slack_after_next);
        } else {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (keep residuals balanced) with smooth falloff.
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin, more so early and
    // when other bins fit the item.
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * (1.0 - progress) + 6.0 * (fitting_bins_count as f64);
        // Allow opening a new bin late in stream if residuals are fragmented
        score -= 3.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bin capacity split into 4 integer-division bands.
    let band = post_residual / (bin_capacity / 4);
    score += match band {
        0 => -12.0, // tiny residue: excellent fill, strong reward
        1 => -4.0,  // moderate residue: mild reward
        2 => 3.0,   // large residue: penalty for wasted space
        _ => 10.0,  // nearly empty bin used for a small item: bad
    };

    // Modulo-10 harmonic class of post_residual: residues near multiples of 10
    // are more reusable by typical item sizes.
    let m = post_residual % 10;
    score -= (5 - (m as i32 - 5).abs()) as f64 * 0.8;

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (next_item_size as f64 / bin_capacity as f64) * 4.0;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating a dead residue.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the current item barely fits
    // anywhere else or open bins are fragmented.
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64) / (bin_capacity as f64);
        score = bin_capacity as f64 * (1.0 - tight_fit) * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            score += 8.0; // discourage skipping the sole fitting bin
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        score += open_bins_count as f64 * 0.5;
    }

    // Mild alignment with mean residual: avoid bins far from the mean
    // (keeps residue distribution homogeneous).
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: perfect packing leaves no dead space.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Slack after the follow-up placement: penalize proportionally.
            score += 0.6 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; penalize relative to mean residual.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent fits exist, unless residual would be tiny.
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it only when item is large (little waste elsewhere)
        score += 25.0;
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does most of this).

    // Penalize dead space that is too small for typical future items.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Dead space penalty grows quadratically when residual is small.
        let dead = (bin_capacity as f64 - pr).min(pr);
        score += 0.15 * (bin_capacity as f64 - pr) * (1.0 - pr / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += 2.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: it should only win when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: open a new bin only if existing fits are poor.
        score = bin_capacity as f64 * 0.5 + 0.3 * post_residual as f64;
        // Late in stream, discourage opening many new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If open bins are already full-ish, new bin is more acceptable.
        score -= 0.05 * mean_residual;
        // If many bins fit the item, opening new bin is wasteful.
        score += 4.0 * fitting_bins_count as f64;
        // Exact fit of current item in a fresh bin is fine.
        if item_size == bin_capacity {
            score -= 40.0;
        }
    } else {
        // Reward filling an existing bin nearly completely.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio * fill_ratio;
        // Mild penalty for spreading across too many open bins when bins are sparse.
        if open_bins_count > 0 && mean_residual > bin_capacity as f64 * 0.6 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted space (post residual), scaled by capacity.
    let mut score = post * (1.0 + post / cap);

    // Smooth stream-progress coupling: waste is less forgivable later in the stream.
    score *= 1.0 + 0.5 * progress * (post / cap);

    // Reward tight fits: subtract when post_residual is small (smooth, non-linear).
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * (item_size as f64 / cap);
    }

    // Deter opening new bins when plenty of open bins exist and item fits elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced when item is large (packing density).
        score = 15.0 + 0.15 * open_bins_count as f64 - 8.0 * (item_size as f64 / cap);
        // If next item could combine with this one in a fresh bin, slightly favor new bin.
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= cap {
            score -= 3.0;
        }
        // Late in stream, avoid opening bins for small items.
        score += 6.0 * progress * (1.0 - item_size as f64 / cap);
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
        // Lookahead: bonus if post_residual accommodates next item.
        if next_item_size > 0 {
            if (post_residual as f64) >= next_item_size as f64 {
                score -= 4.0;
            } else {
                score += 2.0 * (1.0 - post / next_item_size.max(1) as f64);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Harmonic class logic: classify post_residual by integer division into bands
    let band = post_residual / 10; // harmonic class of dead space
    score += match band {
        0 => -60.0,                 // post_residual < 10: near-perfect fit, strongly reward
        1 => -20.0,                 // 10..20: small dead space
        2 => 5.0,                   // 20..30
        3 => 15.0,                  // 30..40
        4 => 25.0,                  // 40..50: half-empty, mediocre
        _ => 35.0 + (band as f64),  // large residual: mostly empty bin
    };

    // Modulo coupling: residuals that are multiples of common small sizes are reusable
    let reusable = |r: u32| -> bool {
        (r % 10 == 0) || (r % 15 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 30 == 0)
    };
    if post_residual > 0 && reusable(post_residual) {
        score -= 12.0;
    }
    // Penalize odd, unusable residuals (prime-ish gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers below smallest item class are dead space
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the next item, scaled by how well it fits
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.3 * slack;
        // Extra reward if post residual exactly matches next item or a harmonic multiple
        if post_residual == next_item_size {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item won't fit here: penalize residual just below next item size (near-miss waste)
        let gap = (next_item_size - post_residual) as f64;
        if gap < 10.0 {
            score += 20.0; // agonizing near-miss
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: neutral-ish base, but discourage when open bins fit well
    if bin_residual == bin_capacity {
        score = 100.0
            + 10.0 * (open_bins_count as f64).ln().max(0.0)
            - 0.5 * mean_residual.max(0.0);
        // Opening a new bin is fine late in the stream when many bins are open
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Late in the stream, prefer compacting into existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Mild preference for filling fuller bins when several fit
    if fitting_bins_count > 1 {
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range,
    // min item 1) are pure waste; penalize especially gaps in the 1..=10 "dead zone".
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight packing: small relative post residual.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 30.0;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward keeping it usable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // post residual can't serve the next item; penalize proportionally.
            score += (post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encouraging consolidation into existing bins.
    let new_bin_candidate = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if new_bin_candidate {
        score += 8.0 + (open_bins_count as f64) * 1.5;
        // But if existing residuals are all tiny (mean residual too small to be useful),
        // a new bin becomes more attractive.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 20.0;
        }
    }

    // Early in the stream, prefer filling existing bins aggressively (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Slight preference for bins with larger residual when ties occur (keep big gaps
    // available only if they stay big).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: perfect match means next item exactly fills leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect follow-up fill
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how much of the leftover it consumes
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill_frac;
        } else {
            // next item cannot use the leftover: penalize dead space creation
            score += 15.0;
        }
    } else {
        // last item: strongly prefer minimal leftover
        score -= 10.0;
    }

    // Relative to mean residual: placing into a bin with residual below mean
    // concentrates waste and preserves large-residual bins for larger items.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // this bin would leave awkward dead space or the item is large relative to residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Large items benefit from a fresh bin when few bins fit them.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // Late in the stream, prefer closing out bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual already does this).

    // Lookahead reward: if the next item fits into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * chain_quality;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize proportionally to how stranded it is.
        score += 4.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize bins whose residual is far below the mean residual (they are already fragmented),
    // unless the fit is tight.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if bin_residual != bin_capacity {
        score += 3.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64 * (1.0 - tightness);
    }

    // New-bin candidate logic: opening a new bin is attractive early in the stream or when
    // the item leaves a large, reusable residual; it is unattractive near the end or when
    // open bins are plentiful and could still absorb the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let reusability = post_residual as f64 / bin_capacity as f64;
        let fit_scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        // Favor new bin when item is small (large residual left) and few alternatives exist.
        score -= 18.0 * reusability * fit_scarcity * (1.0 - 0.5 * progress);
        // Penalize new bins when many open bins exist that could take the item.
        score += 2.0 * open_bins_count as f64 * (1.0 - reusability);
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress;
    }

    // Mild preference for filling bins with larger residuals (biggest-fit flavor),
    // modulated by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, prefer filling bins tightly (low post_residual);
    // later, dead space becomes more costly, so amplify the quadratic term.
    let mut score = post * (1.0 + 0.8 * progress) + norm_post * norm_post * cap * (0.5 + 1.5 * progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * tightness * 12.0 * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            // Penalize leaving a residual just below the next item (dead space).
            let gap = (nxt - post) / cap;
            score += 10.0 * gap * gap * cap * 0.1;
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Prefer it only when open bins are already quite full on average, or when
    // this bin would leave an awkward residual.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let mean_fill = 1.0 - (mean_residual / cap);
        let awkward = if post_residual > 0 && post_residual < 10 {
            1.0
        } else {
            0.0
        };
        // New bin score: moderate; drops (more attractive) as mean fill rises.
        score = cap * 0.55 - mean_fill * cap * 0.5 + awkward * 6.0 - progress * 4.0;
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64) * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how close it is to a "perfect" usable residue
    // Perfect residues are multiples of the smallest plausible item class (10) —
    // residues near multiples of 10 are reusable; residues in dead zones (1..9 mod 10) waste space.
    let post_class = post_residual % 10;
    if post_residual > 0 {
        // dead-space penalty: worst when residue is small-but-nonzero
        let dead = (10 - post_class) as f64;
        score += dead * (1.0 + 40.0 / (post_residual as f64));
        // exact multiple of 10 (or zero) is harmonically clean
        if post_class == 0 {
            score -= 12.0;
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Integer-division thresholds: residue large enough for next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // can host next item: reward proportionally to how well next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic bonus if post_residual is an exact fit for next item
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // residue below next item size: dead space unless class-clean
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // modulo coupling: next item and residue share a harmonic class
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Tight-fit reward for current item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when existing residues are genuinely bad
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0; // fresh bin can host next item
        }
        if fitting_bins_count <= 1 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Progress coupling: late in stream, prefer consolidating (avoid many small residues)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a leftover bin
    if (bin_residual as f64) < mean_residual * 0.5 && bin_residual != bin_capacity {
        score -= 6.0; // using up a nearly-full bin is good
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item can use are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 60.0; // perfect fill
    } else if post_residual > 0 && post_residual < 10 {
        score += 80.0; // unusable sliver => dead space
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // gap can't hold the known next item: likely dead space
        score += 35.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0; // gap exactly fits lookahead item
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + tightness);

    // Last chance: only bin that fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residuals far from mean (consolidate waste into few bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // New-bin candidate: only attractive when no open bin is a good fit
    // (large post_residual otherwise => keep it high so open bins win).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pairing potential with lookahead: fresh bin can host both
            score -= 30.0;
        } else {
            score += 45.0;
        }
        // late in the stream, opening new bins is fine since leftovers won't matter much
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let residual_f = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Core best-fit signal: smaller leftover space -> lower score.
    let mut score = post;

    // Consolidation pressure: when many bins are open, amplify the cost of
    // leaving large residuals behind, pushing toward tighter placements.
    score += post * (open_bins_count as f64).min(20.0) * 0.008;

    // Mean-residual coupling: bins tighter than average hold scarce space,
    // prefer consuming them; looser-than-average bins get a mild penalty so
    // flexible capacity survives for future items.
    if residual_f < mean_residual {
        score -= ((mean_residual - residual_f) * 0.12).min(6.0);
    } else {
        score += ((residual_f - mean_residual) * 0.05).min(4.0);
    }

    // New-bin candidate is a fallback: keep it slightly penalized so an
    // existing (even mediocre) fit is preferred unless it is truly better.
    if is_new_bin {
        score += 3.0;
    } else if fitting_bins_count == 1 {
        // Last chance bin: reward using it to avoid proliferating bins,
        // strongest early in the stream.
        score -= 4.0 + 3.0 * (1.0 - progress);
    }

    // Aggressive 2-step lookahead against the next item.
    if next > 0.0 {
        if post == 0.0 {
            // Placement closes the bin exactly: excellent, especially early.
            score -= 18.0 + 8.0 * (1.0 - progress);
        } else if next == post {
            // Perfect 2-step match: next item exactly consumes the leftover.
            score -= 22.0;
        } else if next < post {
            // Next item still fits here; reward small slack after it lands.
            let gap = post - next;
            score -= (14.0 - gap.min(14.0)) * (1.0 - 0.4 * progress);
        } else {
            // Next item no longer fits after this placement.
            if next <= residual_f {
                // It WOULD have fit before: we destroyed a viable slot.
                score += 5.0 + 0.08 * next;
            }
            score += 2.0;
        }
    } else if post == 0.0 {
        // Last item in the stream: strongly prefer exact closure.
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual more strongly.
    score -= 12.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);

    // Penalize small, hard-to-use dead space (post residual in awkward range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item can't use this space: penalize proportionally
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 5.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, tolerate new bins less; late, prefer tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global residual balance: if this bin's residual is far below mean, it's
    // relatively full already; prefer it (keeps mean residual spread even).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // New-bin candidate: neutral-ish baseline, but discouraged when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, opening a new bin is cheaper than wasting space.
        if progress > 0.7 {
            score -= 20.0 * progress;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are acceptable (flexibility); late, we punish
    // leftover dead space more aggressively since remaining items are fewer.
    let poly = post * post / cap;
    score += poly * (0.25 + 1.5 * progress * progress);

    // Reward tight fits: normalized fill ratio of the item in the bin.
    let fill = item / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Dead space that blocks the known next item: penalize.
        score += 4.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the current item is large
    // (a fresh bin gives maximal future flexibility) or no bin fits well.
    if bin_residual == bin_capacity {
        let fresh_penalty = 10.0 + 20.0 * (1.0 - fill);
        score += fresh_penalty;
        if item >= 0.5 * cap {
            score -= 15.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean,
    // consolidating space into fewer bins.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals that are "dead"
    // (too small for the smallest plausible item) are penalized heavily.
    let dead_threshold: u32 = 10; // smallest item size class
    if post_residual >= dead_threshold {
        // Reward usable leftovers, scaled by how well they sit in
        // harmonic classes (divisibility structure of capacity).
        let class = post_residual / 10; // harmonic decile class
        score -= 8.0 + class as f64 * 1.5;
        // Perfect harmonic residuals (multiples of 20 / 25) are ideal slots
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
    } else {
        // Dead space: penalize proportionally to how close to full it is.
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // Exact fit is the best possible outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual
    // (aligned on a harmonic class), reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Bonus when next item exactly consumes the leftover.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize if leftover is
        // stranded in an awkward class (small but nonzero).
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // existing residuals are poor. Make the empty bin mildly unattractive
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // Large items benefit from a fresh bin; small items should reuse.
        score += 30.0 - load_frac * 45.0;
    }

    // Stream progression: late in the stream, consolidate aggressively
    // to avoid leaving many half-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Prefer bins with residual close to the mean (balanced packing),
    // penalize outliers that would create fragmented leftovers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: a leftover gap smaller than the minimum
    // item size is permanently unusable -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 400.0;
    }

    // Gaps that are small-but-usable are mildly risky (few items can use them).
    if post_residual >= 10 && post_residual < 20 {
        score += 40.0;
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the incoming item.
        score += 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate implicitly since its score stays high).
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 8.0 * (0.5 + progress);

    // Prefer bins tighter than average (below-mean residual is a good fit).
    score -= (mean_residual - bin_residual as f64) * 1.5;

    // New-bin candidate: only attractive when the item leaves a large,
    // reusable residual and no tight option exists; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 120.0 - (post_residual as f64);
        if post_residual < 10 {
            score += 300.0; // opening a bin that will be stranded immediately
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 40.0).max(0.0);
    }
    // Penalize dead space: post_residual too small for next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // New bin candidate: penalize unless item is large relative to capacity
    // or current open bins have poor residuals
    if is_new_bin {
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        let mean_res_ratio = mean_residual / bin_capacity as f64;
        score += 45.0 - 30.0 * large_item_bonus - 20.0 * mean_res_ratio;
        // Late in stream, prefer consolidating into open bins
        score += 25.0 * progress;
    }

    // Prefer bins tighter than the mean (less wasted space elsewhere)
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference for tight fits overall
    score += 0.1 * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fill is gold.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead: if the next item fits into the post-residual, this bin stays useful.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0;
            // Bonus scaled by how well next item fills leftover space.
            let next_fill = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 25.0 * next_fill;
        } else {
            // Dead space: leftover too small for the next item.
            let waste_frac = (post_residual as f64) / (bin_capacity as f64);
            score += 40.0 * waste_frac;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 30.0 + 0.5 * (item_size as f64);
        if post_residual <= 10 {
            score -= 30.0; // nearly perfect fill on last chance
        }
    }

    // New-bin candidate (empty bin): prefer it only when open bins are crowded
    // or the item is large and fits would be sloppy.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream horizon.
        let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 - 15.0 * horizon;
        // If many bins are open and mean residual is high, opening new bins is wasteful.
        score += 0.35 * (open_bins_count as f64) + 0.25 * mean_residual;
        // Large items deserve fresh bins more often.
        if (item_size as f64) / (bin_capacity as f64) > 0.6 {
            score -= 18.0;
        }
        // If the next item is huge, a fresh bin may serve both better.
        if next_item_size > 0 && next_item_size > post_residual.max(1) && next_item_size >= item_size {
            score -= 12.0;
        }
    }

    // Global crowding pressure: when few bins fit the item, prefer reusing existing space.
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + 1.0 / (fitting_bins_count as f64));
    }

    // Mild penalty for leaving residuals in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) emphasis.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight packing matters more (dead space is costlier).
    score += 60.0 * norm_pr * norm_pr * progress * (2.0 - progress);

    // Lookahead: reward post_residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - snug * snug);
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - norm_pr);
    }

    // Penalize leaving post_residual in an unusable band (too small for typical items),
    // as a smooth function rather than hard thresholds.
    let unusable = (1.0 - (pr / 10.0).min(1.0)) * (1.0 - ((pr - 100.0_f64.min(pr)).abs() / 100.0).min(1.0));
    score += 12.0 * unusable;

    // New-bin candidate: make empty bins less attractive unless residual is huge
    // or the item fits almost perfectly, with mild dependence on open bin count.
    if bin_residual == bin_capacity {
        let waste = item_size as f64 / cap;
        score = pr + 45.0 * (1.0 - waste * waste) + 8.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild tie-break toward bins already below mean residual (consolidation).
    score += 5.0 * ((mean_residual - bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins with tiny leftovers are "harmonically perfect".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual below smallest plausible item is nearly unusable.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward matching with the lookahead item (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect pair
        } else if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here; penalize by wasted fraction
            score += 0.3 * pr;
        }
    }

    // Modulo-class bonus: residuals that are multiples of 10 are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd harmonic classes slightly penalized.
    if post_residual % 2 == 1 {
        score += 1.5;
    }

    // Integer-division thresholds on post_residual (quarter classes of capacity).
    let quarter = post_residual / 25;
    score -= match quarter {
        0 => 0.0,
        1 => 2.0,
        2 => 5.0,
        _ => 8.0,
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high; only attractive when
    // open bins would create heavy dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score -= 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // future item (min size 1..100, but small gaps < 10 are almost surely
    // unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Gaps that exactly fit the lookahead item are valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize gaps that cannot hold the lookahead item but could have.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Tightness reward: fraction of the bin consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage opening new bins when several bins
    // are already open; a new empty-bin call has residual == capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 22.0 * (open_bins_count as f64 / 12.0).min(1.0) + 10.0 * progress;
    } else {
        score -= 2.0 * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // avoid leaving bins far below mean residual untouched.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: bin exactly fits item + next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Penalize dead space: post_residual that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Small unusable slivers are wasteful; scale by how close it is to fitting.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 2.0;
    }
    // Reward leaving space close to next item (near-perfect fit softness).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (10.0_f64.min(slack)) * 3.0;
    }

    // Last-chance bonus: if this is the only bin that can fit, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when current bin leaves a terrible fit for the next item.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 1.5; // default moderately bad
        if next_item_size > 0 {
            // New bin fits item + next item comfortably: acceptable when no open bin does.
            if item_size + next_item_size <= bin_capacity && (post_residual as f64) >= mean_residual {
                score -= 150.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // forced new bin anyway
        }
    }

    // Mild coupling with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalization of wasted space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize new-bin candidate unless current fit is poor or many bins would be stranded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        let crowd_penalty = (open_bins_count as f64) * 0.5;
        score += 25.0 + fit_quality * 30.0 + crowd_penalty;
        // Late in the stream, opening new bins is relatively cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    } else {
        // Reward using bins with large residuals (consolidate fullness).
        score -= 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 0.25 * next_item_size as f64;
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            score += 0.10 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer the fullest usable bin.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to the item (minimal slack).
    let slack = (bin_residual - item_size) as f64;
    score += 0.20 * slack;

    // Mild preference for bins below mean residual when few bins are open (balance load).
    if open_bins_count > 1 && !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Base preference for tight fits: penalize large post_residual non-linearly.
    let tight = pr / cap;
    score += 12.0 * tight * tight;

    // Reward filling bins deeply as the stream progresses.
    score -= (1.0 - tight) * (1.0 - tight) * (4.0 + 8.0 * progress);

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            // Next item won't fit here; penalize creating dead space.
            score += 5.0 * tight;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation control).
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Smooth pressure against opening new bins as many bins accumulate.
    let open_norm = open_bins_count as f64;
    score += 0.5 * (open_norm / (open_norm + 5.0)) * (pr / cap);

    // Late-stream inertia: favor closing out bins with small residuals.
    score -= 3.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residuals are "dead space".
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score += 12.0; // nearly dead space
    } else {
        // modulo classes: residuals divisible by common item sizes are reusable
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
        if reusable {
            score -= 8.0;
        }
        // coarse integer-division threshold on residual size
        let class = pr / 10; // 0..=10 harmonic band
        score += class as f64 * 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0);
            if slack % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or mean residual across open bins is very fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap_f;
        let big_item = item_size as f64 > 0.7 * cap_f;
        if big_item || (frag < 0.25 && open_bins_count > 3) {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Progress pressure: late in stream, consolidate rather than open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Tightness reward: filling a bin nearly full is good.
    let fill = 1.0 - (post_residual as f64) / cap_f;
    score -= 10.0 * fill;

    // Penalize leaving residual in a band that few item sizes can use (prime-ish gaps).
    if pr > 0 && pr < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // moderately wasteful zone
        score += 8.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only one that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from number of open bins: with many open bins, prefer consolidating
    score += open_bins_count as f64 * 0.6;

    // Lookahead: if the next item could use the leftover space, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0;
    }

    // Brand-new empty bin candidate: only attractive when it leaves a large,
    // reusable residual and other fits are poor
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64
            + 15.0
            + open_bins_count as f64 * 0.4;
        // If the new bin's leftover could host the next item, soften the penalty
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity - item_size {
            score -= 10.0;
        }
        // Perfect fit in a fresh bin is still decent
        if item_size == bin_capacity {
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches the
    // post residual, penalize when next item cannot fit into post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * frac; // larger fill of remaining space is better
        } else {
            // next item won't fit here: dead-space risk grows with small post residual
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // Compare against mean residual: prefer bins whose residual is below mean
    // (compact bins), gently penalize outliers with large residual.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive by default, but attractive when
    // the item fits nowhere well or next item pairs badly with the leftover.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let mut new_bin_score = base_penalty + post_residual as f64;
        // If no other bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // If next item is large and current item is small, reserving a fresh bin
        // can be beneficial: slightly reduce the penalty.
        if next_item_size > 60 && item_size < 40 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    // Mild stream-progression pressure: later in the stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward bins whose post-residual can host the lookahead item (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - (next_item_size as f64) / cap);
    }
    // Penalize if lookahead item cannot fit here (dead-end risk), stronger near end of stream.
    if next_item_size > post_residual && next_item_size > 0 {
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 8.0 * t;
    }

    // Penalize unusable slivers (dead space below min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discourage scattering across many open bins: prefer fuller bins when many are open.
    let fill = (bin_capacity.saturating_sub(bin_residual)) as f64 / cap;
    score -= 10.0 * fill * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Prefer bins below mean residual (relatively full bins) mildly.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    // (large post_residual already penalizes it; add extra barrier when alternatives exist).
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count > 1 {
            score += 12.0;
        }
        // Late in stream, avoid opening bins for small items.
        if item_size < 40 {
            score += (40 - item_size) as f64 * 0.5;
        }
    }

    // Mild penalty for very large items going into nearly-empty bins (waste potential),
    // unless it is the only option.
    if item_size >= 70 && bin_residual == bin_capacity && fitting_bins_count > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / capacity;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = post * (1.0 + 0.8 * post / capacity);

    // Quadratic dead-space penalty: residual below ~half capacity becomes increasingly useless
    let dead = post / capacity;
    score += 12.0 * dead * dead * (1.0 - fit_ratio);

    // Cubic coupling of post_residual with stream progress:
    // late in the stream, waste is more costly (fewer chances to reuse it)
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 6.0 * post * prog_term;

    // Lookahead: reward bins whose post_residual can hold the next item (k=2 lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 4.0 * (1.0 - gap / capacity) * (1.0 - progress * 0.5);
        } else {
            score += 2.0 * (gap / capacity) * (post / capacity);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + fit_ratio);
    }

    // Crowd penalty: with many open bins, discourage fragmenting further
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 10.0);
    score += 5.0 * crowd * dead;

    // Mean-residual coupling: if mean residual is high, prefer bins below the mean
    // (consolidate toward tighter bins) via smooth interaction
    let dev = (mean_residual - post) / capacity;
    score -= 3.0 * dev * (1.0 - prog_term);

    // New-bin candidate: empty bin must not win unless all fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * fit_ratio + 20.0 * prog_term;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0 (exact fill) is perfect; small leftovers (1..=10) are near-dead space.
    let r = post_residual;
    let class = r % 10;
    let band = r / 10; // 0..=9 bands of ten

    // Reward exact fills strongly.
    if r == 0 {
        score -= 60.0;
    }

    // Penalize tiny dead-space leftovers (unusable for typical items).
    if r > 0 && r <= 10 {
        score += 12.0 - (r as f64);
    }

    // Harmonic reward: leftover divisible by 10 aligns with common item sizes.
    if r >= 10 && class == 0 {
        score -= 4.0 + 0.5 * (band as f64);
    }
    // Leftovers matching next item size exactly are gold.
    if next_item_size > 0 && r == next_item_size {
        score -= 25.0;
    }
    // Leftover can host the next item comfortably.
    if next_item_size > 0 && r >= next_item_size {
        score -= 3.0 + 0.3 * (next_item_size as f64) / 10.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty scaled by mismatch.
        score += 2.0 + ((next_item_size - r) as f64) * 0.1;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins with high mean residual: encourage consolidation.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else if open_bins_count > 3 && (bin_residual as f64) < mean_residual * 0.5 {
        score += 2.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when the
    // item is large and would leave an awkward tiny residual in any bin.
    if bin_residual == bin_capacity {
        let base = 35.0 + 0.2 * (open_bins_count as f64);
        // If this bin is the only fitting option, opening is inevitable-ish;
        // keep the penalty so existing fits win, but drop it for big items.
        let big_item = item_size >= 50;
        score = if big_item { base - 10.0 } else { base };
        // Late in the stream, slightly prefer reusing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
    }

    // Mild preference for tighter existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately awkward gaps (10..=20) get a graded penalty.
    else if post_residual > 0 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit in the resulting gap, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / 100.0) * 8.0;
    }
    // If next item would NOT fit in the post residual, mild penalty proportional to gap waste.
    else if next_item_size > post_residual {
        score += post_residual as f64 * 0.15;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred when they fit reasonably.
        score += 35.0;
        // If very few bins can fit the item, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Open-bins pressure: mildly discourage accumulating many open bins.
    score += open_bins_count as f64 * 0.3;

    // Slight alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is better,
    // but only if the leftover is not unusably small dead space.
    if post_residual > 0 {
        // Penalize creating tiny unusable fragments (dead space).
        if post_residual < 10 {
            score += 25.0;
        } else {
            score -= 10.0; // reward decent tight fits
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: check if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent chaining opportunity: reward proportionally to how snugly
            // the next item will fill the remaining space.
            let snug = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - snug / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 20.0; // perfect 2-step chain
            }
        } else {
            // Next item won't fit here: penalize if post_residual is large
            // relative to mean residual (wasting space vs. other bins).
            let waste = post_residual as f64 - mean_residual;
            if waste > 0.0 {
                score += 0.15 * waste;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a good fit. Make the empty bin moderately attractive by default...
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But if current bins are heavily fragmented (high mean residual spread
        // vs item), a new bin becomes more attractive when the item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > bin_capacity / 2 {
            score -= 15.0 + 10.0 * progress;
        }
        // If many bins already fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // Lookahead: if next item is small, a fresh bin has good future utility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    // Mild preference for consolidating into bins with lower residual overall
    // (best-fit bias relative to the mean residual of open bins).
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Slight tie-breaking noise-free structural term: prefer bins with more
    // remaining usable space when many items remain in the stream.
    if total_items > step_index.saturating_add(1) {
        score += 0.02 * (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits: penalize proportion of bin wasted relative to capacity.
    score += 0.6 * (post / cap) * (post / cap) * cap;

    // Reward using bins with small residual overall (compact the bins).
    score += 0.25 * (res - mean_residual);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward; else penalize dead space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 0.5 * nx;
        } else {
            score += 0.4 * (nx - post);
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity (better to start fresh) or few bins are open.
    if bin_residual == bin_capacity {
        let large_item_bonus = 0.5 * (item - 0.35 * cap);
        score -= large_item_bonus;
        // Early in the stream, opening bins is cheaper; late, prefer filling existing bins.
        score -= (1.0 - t) * 12.0;
        // Many open bins with slack: opening more is wasteful.
        score += 0.15 * open_bins_count as f64;
        // If next item is small, a fresh big residual is useful.
        if next_item_size > 0 && (next_item_size as f64) < 0.3 * cap {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;                      // normalized dead space after placement
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64; // how tightly the item fits

    // Base: quadratic growth of dead space, modulated by stream progress.
    // Late in the stream, dead space matters more (fewer chances to fill it).
    let mut score = post * (1.0 + 1.5 * progress) + norm_post * norm_post * cap * (0.5 + progress);

    // Smooth reward for tight fits (fit_ratio near 1) via a soft saturation term.
    score -= (fit_ratio * fit_ratio) * cap * 0.6;

    // Interaction: tight fit is more valuable late in the stream.
    score -= fit_ratio * progress * cap * 0.4;

    // Lookahead coupling: if the next item fits the post residual, reward this placement
    // with a smooth saturating function of the residual match.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((post - nxt).abs() / cap);
        score -= match_term * match_term * cap * 0.8 * (1.0 - progress);
        // Penalize leaving a residual slightly too small for the next item (dead space trap)
        if post < nxt {
            score += (nxt - post) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin), scaled smoothly by how many bins are open.
    if fitting_bins_count == 1 {
        score -= cap * (0.8 + 0.4 * progress);
    } else {
        // Mild crowding penalty: spreading items across many bins is fine,
        // but prefer bins with residuals close to the mean (balance residuals).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += dev * dev * cap * 0.3;
    }

    // New-bin candidate handling: an empty bin has large post residual; make it
    // unattractive unless all alternatives are poor. Penalize it smoothly, with
    // relief late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.4 * progress);
        // But if the item is large relative to capacity, a fresh bin is reasonable.
        score -= (item_size as f64 / cap) * cap * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in the "dead zone"
    // (0 < post_residual < 10) are nearly unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 8.0; // perfect fit is excellent
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align
    // with the classic item size grid, making them more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Integer-division thresholds: penalize large leftover chunks that
    // cannot host the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 5.0; // lookahead item can't use this bin's leftover
        } else {
            // reward if post residual can host lookahead with harmonious slack
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 3.0;
            } else if slack % 10 == 0 {
                score -= 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has no dead space yet, but
    // opening it should be penalized mildly so we prefer existing bins
    // unless they would create very poor fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If the item is large relative to capacity, opening fresh is fine.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 14.0;
        }
    }

    // Prefer filling bins whose residual is far below the mean (tight bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late in the stream, tighten packing: penalize waste more heavily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    // Crowding: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 4 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can't fit a plausible future item
    // (small residuals) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Lookahead: if the next item could have fit in this bin's residual
    // but won't fit after placement, penalize; if it still fits, reward.
    if next_item_size > 0 {
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 15.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless the fit elsewhere
    // would be terrible; scale pressure with number of open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // Allow opening when the stream is early and items are large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 2.0;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (fill the emptiest usable bins first to leave tight bins for tight items).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // ---- 2-step lookahead matching ----
    // Reward bins whose post_residual exactly (or nearly) matches the next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();

        // Perfect 2-step chain: post_residual == next_item_size -> big reward.
        if diff < 0.5 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 20.0 - 3.0 * diff;
        } else {
            // Penalize dead space that the next item cannot use.
            score += 0.15 * diff;
        }

        // If next item cannot fit into post_residual, this bin's leftover is likely waste.
        if pr < ni {
            score += 0.25 * (ni - pr);
        }
    }

    // ---- Relative-to-mean coupling ----
    // Prefer closing bins that are far below the mean residual (tight fits),
    // avoid wasting bins that still have lots of room relative to average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // ---- Last-chance bonus ----
    // If this is the only bin that fits, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Default: discourage opening a new bin when existing bins fit.
        score += 30.0;
        // But if the item is large and would leave a big hole elsewhere,
        // a fresh bin is cleaner: post_residual already dominates.
        // Slight discount when item is large relative to capacity.
        score -= 0.1 * item_size as f64;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild penalty for leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear waste shaping: penalize residuals that are too small to be useful
    let norm_post = post / cap;
    let dead_zone = (norm_post * (1.0 - norm_post)).sqrt(); // low near 0 and near cap
    score += 12.0 * (1.0 - dead_zone) * (1.0 + 0.5 * progress);

    // Tight fits are valuable: reward small post_residual relative to item size
    let tightness = 1.0 - (item / (bin_residual as f64 + 1.0));
    score -= 8.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = ((post - nxt) / cap).sqrt();
            score -= 6.0 * slack * (1.0 - 0.5 * progress);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Mean residual coupling: prefer bins deviating from the mean when mean is large
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 3.0 * dev * (1.0 - progress.abs() * 0.5);

    // New-bin candidate: penalize opening a new bin, more so early and when open bins exist
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group dead space into buckets of 10
    // (capacity fractions). Small classes are good (tight fit), large ones waste.
    let post_class = post_residual / 10;
    match post_class {
        0 => score -= 25.0,                     // near-perfect fit
        1 => score -= 15.0,                     // very tight
        2 => score -= 6.0,
        3 => score -= 0.0,
        4 => score += 6.0,                      // half-bin dead space
        5 => score += 12.0,
        6 => score += 18.0,
        7 => score += 24.0,
        8 => score += 30.0,
        _ => score += 38.0,                     // nearly empty bin wasted
    }

    // Modulo-10 residue coupling: if the next item exactly fills the leftover
    // (post_residual == next_item_size), strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to how tight
            let rem_after_next = post_residual - next_item_size;
            let cls = rem_after_next / 10;
            score -= match cls {
                0 => 14.0,
                1 => 8.0,
                2 => 3.0,
                _ => 0.0,
            };
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins that are already partially loaded (avoid bin proliferation)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Penalize opening a new bin when several open bins could still fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost so it's chosen only when fits are poor
        score += 35.0;
        if open_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // early in stream, opening bins is cheaper (more future items to pack)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else if fitting_bins_count > 3 {
        score += 3.0; // plenty of alternatives: be picky about fit quality
    }

    // Mean-residual coupling: if average leftover across bins is large,
    // be stricter about fit quality (avoid compounding fragmentation).
    if mean_residual > 30.0 && post_residual > 20 {
        score += (mean_residual - 30.0) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post residual)
    score += post_residual as f64;

    // Dead-space penalty: residuals that are small but nonzero are hard to reuse
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // If this bin can also fit the lookahead item after placement, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // lookahead item won't fit in the leftover gap -> dead space likely
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (20.0 + 30.0 * progress + 2.0 * open_bins_count as f64);

    // New bin only attractive if item is large and no bin fits well
    if new_bin > 0.5 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight tie-break toward fuller bins (smaller residual)
    score += 0.05 * bin_residual as f64 * 0.1;

    // Mean residual coupling: if this bin's residual is below mean, it's a tighter bin, favor it
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.1 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 250.0;
        } else if post_residual < next_item_size {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 3.0 * waste;
        }
        // residual too small for next item and small in absolute terms = dead space
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    }

    // Compare post_residual against mean residual: avoid leaving much more space than average
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 1.2;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // chaining two items into a fresh bin is fine
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative, must open
        }
    }

    // Late in stream: consolidate aggressively into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    // Mild preference for tighter (fuller) bins generally
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: squared post-residual scaled down so small dead space is cheap
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        // residual too small for any item (min size 1, but tiny residual is near-dead)
        score += 15.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // elsewhere is bad or the item is large relative to residual.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        let mut new_bin_penalty = 45.0;

        // If many open bins exist, penalize more (consolidation pressure)
        new_bin_penalty += open_bins_count as f64 * 1.5;

        // If mean residual across open bins is large, opening a new bin wastes space
        if mean_residual > item_size as f64 {
            new_bin_penalty += (mean_residual - item_size as f64) * 0.5;
        }

        // Late in stream, prefer closing out bins rather than opening new ones
        new_bin_penalty += 25.0 * progress;

        // If next item is small and would fit in the leftover of a typical open bin,
        // opening a new bin is less attractive.
        if next_item_size > 0 && next_item_size <= mean_residual {
            new_bin_penalty += 10.0;
        }

        // If item barely fits anywhere (item close to residual of typical bins),
        // relax penalty: new bin may be the right call.
        if item_size as f64 > mean_residual {
            new_bin_penalty -= (item_size as f64 - mean_residual) * 0.8;
        }

        score += new_bin_penalty;
    } else {
        // Open-bin placement: reward using existing space, especially when
        // post-residual can still host the next item (lookahead pairing).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // dead space that next item cannot use: mild penalty
            score += 8.0;
        }

        // Reward filling bins with high residual less eagerly when the item is small
        // (save big residual for bigger future items): scale by item size.
        let waste_averse = (post_residual as f64) * (1.0 - item_size as f64 / bin_capacity as f64);
        score += waste_averse * 0.3;

        // When few fitting bins remain relative to open bins, favor this bin more.
        if fitting_bins_count > 1 {
            score += fitting_bins_count as f64 * 0.5;
        }
    }

    // Global state coupling: high mean residual across open bins means space is
    // abundant -> be pickier about which bin absorbs the item.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr + 25.0 * norm_pr * norm_pr * norm_pr;

    // Tight fits are strongly rewarded; coupling with stream progress
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Cubic coupling between post_residual and item size (favor dense packing)
    score -= 10.0 * (fit * (1.0 - norm_pr)) * (1.0 + progress);

    // Penalize bins whose residual diverges from the mean residual (non-linear)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 - progress);

    // Last-chance bin: strongly favor using it when it fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 + 18.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty scaled by how much it misses by
        let miss = (next_item_size as f64 - pr) / cap;
        score += 8.0 * miss * miss;
    }

    // New-bin candidate: discourage opening new bins early, allow late in stream
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) * (1.0 - progress);
        score -= 10.0 * progress;
        // Extra penalty if open bins could fit (fitting_bins_count counts them)
        if fitting_bins_count > 1 {
            score += 25.0;
        }
    }

    // Mild penalty for too many open bins, smoothed
    score += 2.0 * (open_bins_count as f64).powf(1.2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues mod 10 (capacity fractions).
    let post = post_residual;
    let class = post % 10;
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward exact fit strongly.
    if post == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals 1..=9 are nearly unusable (items >= 10 in classic
    // streams; but sizes go down to 1, so weight by how many sizes could fit).
    // Small nonzero residuals are penalized proportionally to their uselessness.
    if post > 0 && post < 10 {
        score += 60.0 - (post as f64) * 5.0;
    }

    // Harmonic tiers: residual >= half is still flexible; quarter..half is medium;
    // below quarter is risky.
    if post >= half {
        score -= 15.0;
    } else if post >= quarter {
        score -= 5.0;
    } else if post > 0 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post == next_item_size {
        score -= 200.0;
    } else if next_item_size > 0 && post >= next_item_size {
        // next item fits with a good leftover class
        let nxt_post = post - next_item_size;
        if nxt_post % 10 == 0 || nxt_post == 0 {
            score -= 40.0;
        }
        if nxt_post < 10 && nxt_post > 0 {
            score += 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post {
        // next item won't fit here: mildly penalize leaving mid-range gaps
        if post >= quarter {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer using existing bins unless they fit poorly. New bin is neutral-ish
        // baseline; penalize opening when many bins are open and mean residual is large.
        score = (bin_capacity as f64) * 0.5 + (open_bins_count as f64) * 2.0;
        if mean_residual > (item_size as f64) * 1.5 {
            score += 30.0;
        }
        // If item is large relative to capacity, opening fresh bin is fine.
        if (item_size as f64) / (bin_capacity as f64) > 0.6 {
            score -= 20.0;
        }
        return score;
    }

    // Tightness reward: the fuller the bin relative to capacity, the better.
    let fill = 1.0 - (post as f64) / (bin_capacity as f64);
    score -= fill * 25.0;

    // Step-based mild adaptation: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit reward.
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    if open_bins_count > 4 {
        if bin_residual != bin_capacity {
            score -= (open_bins_count.min(20) as f64) * 2.0;
        } else {
            // New-bin candidate: penalize when many bins already open.
            score += (open_bins_count.min(20) as f64) * 4.0;
        }
    }

    // New-bin candidate baseline: only attractive when it yields low dead space
    // relative to mean residual situation (e.g., item larger than typical gaps).
    if bin_residual == bin_capacity {
        score += 10.0;
        // If lookahead item is small, new bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
        // If this bin is the only fitting option, opening a new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 50.0;
        }
    }

    // Lookahead coupling: if the next item would fit the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already fragmented; slightly deprioritize.
    let frac = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 8.0 * (0.5 + frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward leaving exactly next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: reward closeness of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
    }

    // Penalize tiny unusable dead space (waste), unless it's the only fitting bin.
    if post_residual < 10 && post_residual > 0 && fitting_bins_count > 1 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (post_residual would be small compared to next item or mean residual is low).
    if bin_residual == bin_capacity {
        score += 15.0; // base reluctance to open new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin has room for the next item too
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0; // existing bins are fragmented; new bin is good
        }
    }

    // Slight preference for bins below mean residual (balance load) early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (post_residual as f64) < mean_residual {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that no plausible item can fill (min item ~1, typical small)
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small but hard-to-use gap is actually good
    } else if post_residual >= 10 && post_residual < 25 {
        score += 3.0; // moderately awkward gap
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / bin_capacity as f64) * 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += ((next_item_size - post_residual) as f64 / bin_capacity as f64) * 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // early stream or low mean residual -> prefer open bins
        score += 30.0;
        score -= crowding * 25.0;
        score -= progress * 10.0;
        // big next item favors a fresh bin
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Prefer reusing bins with already-small residual (consolidation)
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: post_residual shaped by stream progress.
    // Early on, prefer tight fills (minimize post); late, waste matters more,
    // so amplify large post_residual quadratically with progress.
    let norm_post = post / cap;
    score += 30.0 * progress * norm_post * norm_post * cap * 0.1;

    // Reward near-perfect fills more strongly as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit typical future items (smooth estimate).
    let avg_future = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    let unusable = ((avg_future - post) / cap).max(0.0);
    score += 25.0 * unusable * unusable * (1.0 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size as f64 <= post {
        let gap = (post - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild preference for consolidating into fewer bins as open bins grow.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Deviation from mean residual: prefer bins below mean residual (tighter).
    let dev = (mean_residual - post) / cap;
    score -= 5.0 * dev.tanh();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Harmonic classes: dead space that no future item can plausibly fill.
    // Items are 1..=100; residuals below the smallest plausible next gap are risky.
    let pr = post_residual as f64;
    let mod10 = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual >= 10 {
        // Fractional capacity classes: residual mod 10 == 0 means it can be
        // tiled by standard-size items -> keep such bins attractive.
        if mod10 == 0 {
            score -= 6.0;
        } else {
            score += (mod10 as f64) * 0.4;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_gap = post_residual - next_item_size;
            score -= 8.0 - (nxt_gap.min(30) as f64) * 0.2;
        } else {
            // next item won't fit here: penalize leaving this bin stranded
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only good when the
    // current item is large and existing residuals are small/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        // Penalize new bins mildly by default...
        score += 20.0;
        // ...but reward opening when item is big and mean residual can't host it well.
        if item_frac > 0.5 && mean_frac < item_frac {
            score -= 35.0;
        }
        // Early in the stream, spreading load is cheap.
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream, avoid hoarding open bins with large waste.
        if progress > 0.8 && mean_frac < 0.2 {
            score += 15.0;
        }
        let _ = next_item_size; // handled above generically
    } else {
        // Prefer bins whose residual is above the item (safety) and near mean.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Mild penalty for very large leftover relative to capacity (dead space).
    score += (pr / cap) * (pr / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a plausible
    // future item (min size 1, but practically tiny gaps are waste) are heavily penalized.
    if post_residual > 0 {
        // gap smaller than 10 units is almost certainly dead space
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // making new bins less attractive.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Attractive early when few bins are open; unattractive later.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 45.0 * progress;
        // If the next item would fit in the leftover of this new bin, opening is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // If no existing bin fits well (this bin is one of few candidates), soften.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Lookahead synergy: if next item exactly fills this bin's post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (i.e., this bin is already "used up" relative to others).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain fill).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead match strongly rewarded.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits here later: moderate reward scaled by closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 15.0 * (1.0 - diff / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Compare against mean residual: filling bins below average residual
    // is desirable (keeps roomier bins for larger future items).
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item fits poorly
    // everywhere (handled by last-chance logic) or item is large.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= bin_capacity / 2 {
            score -= 15.0; // large items are fine in a fresh bin
        }
    }

    // Late in stream: tighten packing, discourage wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (low post residual).
    let mut score = post;

    // Time horizon: later in the stream, consolidate more aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * t * (1.0 - post / cap);

    // Lookahead: penalize post-residual that is unusable for the next item,
    // reward residuals that exactly accommodate it.
    if nxt > 0.0 {
        if post >= nxt {
            let slack = post - nxt;
            // reward if next item fits snugly
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // dead space: post residual too small for next item
            score += 10.0 * (post / cap) * (1.0 - t);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - post / cap) * 3.0;

    // Global state coupling: if mean residual is high, prefer bins below mean
    // (drain the emptiest-feeling bins first).
    if bin_residual as f64 > mean_residual {
        score += 2.0 * (bin_residual as f64 - mean_residual) / cap;
    } else {
        score -= 1.0 * (mean_residual - bin_residual as f64) / cap;
    }

    // New-bin candidate: penalize unless current fits are very poor
    // (post residual large relative to capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * t;
        // If no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // If the item is large, a fresh bin keeps flexibility.
        if item > 0.6 * cap {
            score -= 8.0;
        }
    }

    // Small penalty for very tiny post residuals that fragment space,
    // unless it's a perfect fit.
    if post > 0.0 && post < 5.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) tightening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: late in the stream, tighten residual preference more
    let late = progress * progress;
    score += pr * 0.9 * late * norm_item;

    // Penalize large residuals relative to mean residual (wasted space divergence)
    score += 6.0 * (mean_residual - pr).abs() / cap * (1.0 + late);

    // Reward near-perfect fits smoothly (bell-shaped around zero post-residual)
    let fit_quality = (-norm_pr * norm_pr / 0.02).exp();
    score -= 25.0 * fit_quality;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - late * 0.5);
    }

    // Lookahead: reward leaving residual that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - (nxt / (pr + 1.0)) - 0.5).abs() * 0.0
                   - 8.0 * (1.0 - ((nxt - pr / 2.0).abs() / (pr / 2.0 + 1.0)).min(1.0));
        } else {
            // post-residual too small for next item: penalize dead space smoothly
            score += 5.0 * (nxt - pr) / cap * (1.0 + late);
        }
    }

    // Mild penalty when many bins are open: encourage consolidation
    score += (open_bins_count as f64).ln() * 0.6 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: dead space is worse
    // when it falls into "unusable" modular classes. Residuals that are
    // multiples of common item sizes (10/20/25/50) are re-usable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -18.0
    } else if pr % 20 == 0 {
        -15.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr < 10 {
        25.0 // tiny dead space, unusable
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Capacity-fraction coupling: reward filling past half-full thresholds
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 1.0 {
        score -= 80.0;
    } else if fill_frac >= 0.75 {
        score -= 30.0;
    } else if fill_frac >= 0.5 {
        score -= 12.0;
    } else {
        score += 10.0 * (0.5 - fill_frac);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr - next_item_size < 10 {
            score -= 20.0; // near-perfect chain
        } else if next_item_size > pr {
            score += 8.0; // next item won't fit here; bin will close anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate penalty: only open a new bin when all open bins
    // would leave very poor fits (item barely squeezes in).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score = 150.0 - 40.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Waste ratio: penalize residual relative to current item size
    score += (pr as f64) / (item_size.max(1) as f64) * 4.0;

    // Slight preference to close bins early in the stream (keep bin count low)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (fill_frac);

    // Deviation from mean residual: prefer bins that are outliers (very full)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Integer-division threshold on post_residual: reward coarse buckets
    let bucket = pr / 10;
    score -= match bucket {
        0 => 5.0,
        1 => 3.0,
        2 => 1.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item.
    let min_item = 10u32.min(item_size.max(1));
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }
    // Perfect fit reward: strong bonus for zero post_residual.
    if post_residual == 0 {
        score -= 120.0;
    } else {
        // Reward tight fits generally: penalize wasteful large gaps proportionally.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste_ratio * waste_ratio;
    }

    // Coupling with next item: if the next item fits exactly in post_residual,
    // strongly favor this bin (chaining perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; small leftover gap becomes dead space.
            score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    if bin_residual < bin_capacity {
        score -= 20.0 * open_pressure;
    } else {
        // New-bin candidate: penalize opening a new bin unless the item is huge
        // relative to the mean residual (poor fit everywhere).
        score += 55.0 + 15.0 * open_pressure;
        let spread = mean_residual - item_size as f64;
        if spread < -20.0 {
            score -= 40.0; // item much bigger than typical residuals -> new bin OK
        }
    }

    // Mild progression term: later in the stream, tightening matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter residual after placement is better (best-fit flavor).
    score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Lookahead matching (k=2) ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect lookahead match: post_residual exactly equals next item size.
        // Strongly reward (subtract) so this bin wins.
        let exact = (post - nxt).abs();
        if exact < 0.5 {
            score -= 60.0;
        } else {
            // Partial coupling: reward when post_residual is close to next item,
            // scaled by how "usable" the leftover would be.
            let closeness = 1.0 / (1.0 + exact / 10.0);
            score -= 25.0 * closeness;

            // Penalize dead space that cannot host the next item and is small.
            if post < nxt && post < 10.0 {
                score += 20.0; // nearly unusable sliver
            }
        }

        // If placing here leaves room for next item AND next item is large,
        // extra reward (chains items together).
        if post >= nxt && nxt >= 30.0 {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 5.0;
    }

    // ---- Mean residual coupling ----
    // Favor bins with residual below the mean (already tight bins), penalize
    // dumping into the emptiest bin when a tighter option exists.
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual + 1.0 {
        score += 6.0 * (resid_f - mean_residual) / bin_capacity as f64;
    } else if resid_f < mean_residual - 1.0 {
        score -= 4.0 * (mean_residual - resid_f) / bin_capacity as f64;
    }

    // ---- Last-chance bin ----
    // If this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // ---- New-bin candidate handling ----
    // A brand-new empty bin (residual == capacity) should only win when the fit
    // is poor elsewhere. Give it a penalty that scales with how well the item
    // would fill a fresh bin, plus a mild pressure to consolidate as bins grow.
    if bin_residual == bin_capacity {
        score += 18.0; // default: prefer existing bins
        // But if the item is large relative to capacity, opening fresh is fine.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 22.0 * fill;
        // Early in the stream, opening bins is cheap; late, avoid it.
        score += 15.0 * progress;
        // If many bins are open, discourage another one.
        score += 1.5 * open_bins_count as f64;
    }

    // Mild global tightening pressure as stream progresses.
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic reward for small post-residual.
    score -= 2.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: post residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Chain reward: residual after next item also small.
            let r2 = post_residual - next_item_size;
            score -= 4.0 * (1.0 - r2 as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate logic: penalize opening a new bin unless it's genuinely useful.
    if bin_residual == bin_capacity {
        // Base penalty for wasting an existing bin's residual.
        score += 25.0;
        // Large items (relative to capacity) justify a fresh bin.
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
        // Early in stream, prefer consolidating; later, allow spreading.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // Many open bins with high mean residual: opening a new bin is wasteful.
        if mean_residual > item_size as f64 {
            score += 12.0;
        }
        // If only one fitting bin exists, avoid the new bin.
        if fitting_bins_count <= 1 {
            score += 40.0;
        }
    }

    // Mild preference for fuller bins among many open bins.
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: as stream progresses, prioritize tight packing more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits less aggressively (leave room); late, pack tightly.
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * cap * x * x * (1.0 - progress);

    // Smooth dead-space penalty: strongly punish small unusable residuals,
    // weighted by whether the next item could use them.
    let next_fit: f64 = if next_item_size > 0 {
        (next_item_size as f64 / cap).min(1.0)
    } else {
        0.0
    };
    let unusable = (1.0 - x) * x; // peaks at x=0.5, vanishes at 0 and 1
    score += 6.0 * unusable * (1.0 - next_fit);

    // Reward when this bin is the last fitting option (avoid opening new bin).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 0.4 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Mild coupling with global state: many open bins -> prefer filling existing ones.
    score -= 0.15 * (open_bins_count as f64).ln() * (1.0 - x);
    score += 0.1 * (mean_residual - pr) / cap;

    // Smooth lookahead bonus: if next item fits exactly in post_residual.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0 * (post_residual as f64 - next_item_size as f64) / cap;
    }

    // New-bin candidate: keep it mildly attractive only when residuals are poor.
    if bin_residual == bin_capacity {
        let avg_x = mean_residual / cap;
        score = 0.45 * cap + 10.0 * avg_x * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: quantize dead space into capacity fractions ---
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity left

    // Class the residual into harmonic buckets (eighths of capacity).
    let class = (post_residual * 8) / bin_capacity; // integer division: 0..8
    let class_center = (class as f64 + 0.5) * cap_f / 8.0;

    // Reward residuals near harmonic centers (usable slots for common item classes),
    // penalize residuals in "dead zones" between harmonic classes.
    let dist_to_center = (post_f - class_center).abs();
    score += 0.6 * dist_to_center;

    // Perfect-fit classes: exact multiples/halves are highly desirable.
    if post_residual == 0 {
        score -= 50.0; // closed bin, perfect fit
    } else if post_residual % 10 == 0 {
        score -= 6.0; // residual aligned to decimal harmonic class
    }

    // Penalize tiny unusable residuals (dead space < smallest item class).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo coupling between post_residual and next_item_size:
    // reward if the next item can exactly consume the residual class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // next item closes this bin perfectly
        } else if post_residual >= next_item_size {
            score -= 4.0; // next item also fits here
        } else {
            score += 3.0; // residual too small for lookahead item
        }
        // Harmonic divisibility: residual divisible by next item suggests stacking
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 2.5;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        let mut new_bin_score = cap_f * 0.55 - 8.0 * pressure;
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // forced open
        }
        if frac < 0.35 {
            new_bin_score += 20.0; // don't open bins for tiny items
        }
        score += new_bin_score;
    }

    // Mild preference for tighter (fuller) bins overall.
    score += 0.15 * (mean_residual - post_f);

    // Stream progression: later in stream, be greedier about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (frac - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual before placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { -30.0 } else { 45.0 + 3.0 * fitting_bins_count as f64 };
        score += escape;
    }

    // Lookahead: favor bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild stream progression term: early on, be more conservative about filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (progress - 0.5);

    // Deviation from mean residual: prefer bins below mean residual (denser bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 45.0; // ideal: this bin will be exactly filled by next item
        } else {
            score += gap * 0.35; // penalize mismatch with lookahead
        }
        // Bonus if next item fits exactly after combining with current fill
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: just minimize leftover
        score -= 10.0;
    }

    // Penalize unusable dead space (post residual smaller than min plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage unless current bin would leave awkward residue
    if bin_residual == bin_capacity {
        let awkward = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        score += if awkward { 15.0 } else { 40.0 + open_bins_count as f64 * 2.0 };
        // Early stream: new bins are cheap to open
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Prefer filling larger-residual bins to consolidate fragmentation
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate risk appetite.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: if post_residual is tiny but nonzero, it's wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: penalize leaving a residual that neither fits the next item well
    // nor is comfortably large.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can follow here — reward proportional fit quality.
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty unless residual is essentially full.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins that are already below-mean residual (i.e., emptier-than-average
    // bins should be preserved; fuller bins should be consumed first).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // New-bin candidate logic: an empty bin has bin_residual == bin_capacity.
    // Only allow opening a new bin when the fit into existing bins is poor,
    // i.e. post_residual would be large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when genuinely better.
        score += 8.0;
        // Early in the stream, be more willing to open bins (spread items out);
        // later, be conservative and squeeze into existing bins.
        score += 10.0 * (1.0 - progress);
        // If many bins are already open, discourage yet another one.
        score += 0.5 * open_bins_count as f64;
    }

    // Slight preference for larger items into emptier bins overall (balance load).
    score -= 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with mild non-linear squaring to punish dead space.
    let mut score = pr + 12.0 * pr_norm * pr_norm;

    // Tight-fit reward: smooth bell around post_residual == 0, decaying with residual size.
    let tightness = (-pr_norm * 6.0).exp();
    score -= 18.0 * tightness * (0.35 + 0.65 * progress);

    // Lookahead coupling: reward residuals that still fit the next item, punish stranding it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= next_item_size {
            // Next item still fits: bonus grows with how well it nests (small leftover after next).
            let after2 = pr - ni;
            let nest = 1.0 - (after2 / cap).clamp(0.0, 1.0);
            score -= 10.0 * nest * nest;
        } else {
            // Next item won't fit here: penalize proportionally to how close we came (near-miss waste).
            let miss = (ni - pr) / cap;
            score += 6.0 * miss * (1.0 - miss);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 14.0 + 8.0 * progress;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly penalize consuming scarce low-residual bins.
        score += 3.0 * (1.0 - pr_norm) / fitting_bins_count as f64;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual waste avoided) or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        let waste_penalty = 10.0 * (1.0 - tightness);
        let crowd = (open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0))).ln_1p();
        score += waste_penalty - 2.0 * progress * crowd;
    }

    // Smooth stream-progress coupling: later items tolerate larger residuals slightly less
    // (consolidation pressure), implemented as a polynomial interaction.
    let interaction = pr_norm * (1.0 - pr_norm) * (progress - 0.5);
    score += 9.0 * interaction;

    // Mild preference to balance residuals toward the mean (avoid extreme outliers).
    score += 1.5 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes of 10.
    let class = post_residual % 10;
    // Perfect fits and tiny dead space are strongly rewarded.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if class == 0 {
        // Post residual is a multiple of 10: a "round" leftover, easy to fill later.
        score -= 15.0;
    }

    // Penalize awkward dead space classes that rarely get filled.
    if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }
    if post_residual > 40 {
        score += 0.05 * (post_residual as f64 - 40.0);
    }

    // Can the next item fit into the post residual? Reward that strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(30.0) as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here; mild penalty scaled by how much it misses.
        score += 0.3 * (next_item_size - post_residual).min(50) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).min(8.0);
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize when a good fit exists elsewhere.
        score += 70.0;
        if post_residual > 0 && fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: opening is right
        }
        if next_item_size >= bin_capacity - item_size && next_item_size > 0 {
            score -= 20.0; // pairing opportunity in a fresh bin
        }
        score += 0.02 * open_bins_count as f64;
    }

    // Progression: slightly tighten packing later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Penalize residuals that can only fit very small items relative to what
    // the next item needs: if post_residual cannot hold next_item_size, the
    // leftover is likely dead space for the immediate future.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect fit for the next item: strong reward.
        score -= 25.0;
    }

    // Reward tight fills (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Last-chance bin: if this is the only fitting bin, strongly discourage
    // opening a new bin by rewarding this one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid leaving scattered
    // residuals; prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the current bin would leave a bad dead space.
    if bin_residual == bin_capacity {
        let bad_leftover = post_residual > 0 && post_residual < 10;
        if bad_leftover {
            score -= 80.0; // opening fresh bin beats creating dead space
        } else {
            score += 15.0 + mean_residual * 0.1; // default: reuse open bins
        }
    }

    // Mild bonus when this bin's residual matches mean residual (typical bin),
    // keeping packing balanced.
    score -= (bin_residual as f64 - mean_residual).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with next_item_size (perfect two-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item still fits: reward proportionally to tightness of fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space: next item cannot use the leftover
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 150.0 * waste;
            // extra penalty for very small unusable remnants
            if post_residual < 10 {
                score += 120.0;
            }
        }

        // Bonus when placing here makes bin_residual perfectly match next item too
        if bin_residual == item_size + next_item_size {
            score -= 300.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Many open bins: prefer consolidating into bins with residuals near mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Late in the stream: tighten packing, penalize large leftovers more
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += 0.5 * (post_residual as f64) * progress;

    // Penalize leaving exactly awkward gaps (e.g. residual that few sizes can use)
    if post_residual > 0 && post_residual < 20 {
        score += 30.0;
    }

    // Mild preference for filling bins tightly overall
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
