pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: penalize wasted space quadratically (dead space is bad).
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth stream-progress coupling: early on, prefer filling bins snugly;
    // later, waste tolerance grows slightly to keep more bins open.
    let progress_waste = 1.0 + 0.35 * progress * (pr / cap);
    score *= progress_waste;

    // Reward tight fit: small post_residual relative to capacity.
    score -= 6.0 * (1.0 - pr / cap).powi(3);

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 3.0 * (1.0 - pr / (next_item_size as f64 + pr)).powi(2);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize leaving a mid-sized gap.
        let gap_frac = pr / cap;
        score += 2.5 * gap_frac * (1.0 - gap_frac);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for bins with more residual among many candidates.
        score += 0.5 * (bin_residual as f64 / cap);
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        // Opening a new bin is fine early (many items remain) but costly late;
        // also costly if it would strand tight residuals in existing bins.
        let horizon = 1.0 - progress;
        let strand_pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 + 14.0 * (1.0 - horizon) + 6.0 * strand_pressure;
        // But if no existing bin fits, opening is unavoidable — soften penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual is near the item size
    // (smooth kernel around perfect fit).
    let fit_kernel = ((bin_residual as f64 - item_size as f64) / cap).powi(2);
    score += 2.0 * fit_kernel;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by modulo classes.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "harmonic" with common item sizes (multiples of 5/10) are reusable.
    let harmonic_bonus = match class {
        0 => 12.0,
        5 => 6.0,
        2 | 8 => 2.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residuals too small to hold even the smallest item (1) are fine,
    // but residuals in awkward ranges (1..=9) are nearly dead if next item can't use them.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // Harmonic check: does post_residual sit in the same decade class as next item?
            if pr / 10 == (next_item_size as u32) / 10 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize large leftover.
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: empty bin gets a baseline tied to stream progression.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins would waste lots of space
        // (poor fit) or late in the stream when consolidation matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 40.0 && item_size > 50;
        if poor_fit {
            score -= 18.0 + 10.0 * progress;
        } else {
            // Slight preference to reuse open bins normally.
            score += 5.0 + 3.0 * (1.0 - progress);
        }
        // If many bins are open, mildly discourage adding more.
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, it's cramped;
    // prefer bins with residual near/above mean to balance load.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff.abs();

    // Fraction-of-capacity harmonic thresholds on item size.
    match item_size / 10 {
        0 => score -= 1.0,           // tiny items fit almost anywhere
        5 => score -= 2.0,           // half-capacity items are valuable to place well
        8 => score += 1.0,           // huge items: prefer tightest bin (post_residual already does)
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gap too small for the next item: penalize proportionally (dead space until close).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }
    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }
    // Tight-fit reward scaled by item size (big items deserve tight fits).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., item barely fits everywhere else) or residual would be dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If the item would leave a large usable gap in an existing bin, opening
        // a fresh bin is worse; if existing fits are terrible, this becomes best.
        let would_be_tight = item_size as f64 / bin_capacity as f64 > 0.85;
        if would_be_tight {
            score -= 40.0; // big item: fresh bin gives max flexibility
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // next item may pair better in a fresh bin
        }
        // If mean residual is small (open bins nearly full), new bin is fine.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 35.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space too small for any plausible item (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare post_residual against mean residual: prefer bins that become tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size == 0 || post_residual > 0 && (post_residual as f64) > mean_residual + 30.0;
        score += if bad_fit { 10.0 } else { 45.0 };
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strongly prefer bins left with little waste.
    let tight = 1.0 - post / cap;
    score -= 40.0 * tight * tight;

    // Penalize dead space that cannot fit a typical future item.
    if post > 0.0 && post < 10.0 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after = post - nxt;
            score -= 25.0 * (1.0 - slack_after / cap);
        } else {
            score += 8.0; // next item won't chain here
        }
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when existing bins fit poorly
        // or few bins can fit the item. Penalize moderately otherwise.
        let scarcity = if fitting_bins_count <= 1 { 0.0 } else { (fitting_bins_count as f64).ln() + 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, avoid spawning bins; early, be more tolerant.
        let time_penalty = 20.0 + 40.0 * progress;
        score += time_penalty * scarcity;
        // If item is large relative to capacity, new bin is natural for it.
        score -= 10.0 * (item_size as f64 / cap);
    } else {
        // Reward using existing bins, more so when they are the last resort.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins whose residual deviates from mean residual in a useful way:
        // filling a bin with above-average residual reduces fragmentation.
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.3 * dev;
        // Mild penalty on proliferating bins.
        score += 0.05 * open_bins_count as f64;
    }

    // Small global time modulation to break ties differently over the stream.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (t * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: quadratic-ish growth in leftover space (dead space is bad).
    let mut score = post * post / cap + post;

    // Reward tight fits: normalized fill ratio, smooth cubic coupling with progress.
    let fill = (cap - post) / cap;
    score -= 12.0 * fill * fill * fill * (0.5 + progress);

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial reward for keeping usable space for the lookahead item.
        let usable = next_item_size as f64 / (post + 1.0);
        score -= 8.0 * usable * (1.0 - progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally to deadness.
        score += 6.0 * (1.0 - (post / cap)) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening new bins, more so late in stream,
    // but allow it when mean residual across open bins is low (all bins tight).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight = (cap - mean_residual) / cap;
        score += 15.0 + 25.0 * progress - 20.0 * tight * tight;
    } else {
        // Favor bins whose residual is below mean (consolidating fuller bins).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev;
    }

    // Mild penalty for bin sprawl late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: post_residual == 0 is perfect; small residuals are good.
    score -= 12.0 * (1.0 - (post_residual as f64) / cap_f).powi(4);

    // Dead-space penalty: residuals too small for the smallest possible item (1..100 unknown,
    // but treat < 10 as likely dead) are wasted capacity.
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    }

    // Harmonic class logic: classify post_residual into residue classes modulo 25
    // (quarter-capacity bands). Residues near a quarter boundary pair well with
    // typical item sizes; residues just above a class boundary are awkward.
    let quarter = bin_capacity / 4;
    let r = (post_residual % quarter) as f64;
    let cls = post_residual / quarter;
    match cls {
        0 => score += r * 0.10,           // tiny leftover: mostly dead
        1 => score -= r * 0.05,           // roomy: fits small items well
        2 => score += r * 0.03,           // mid: neutral-ish
        _ => score -= r * 0.02,           // large residual: flexible
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item won't fit: mildly penalize, worse when post_residual is large (wasted).
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing else fits well.
        // Penalize by open-bin count pressure and stream progress.
        score += 20.0
            + 2.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if the item is huge, a fresh bin is a clean fit — soften the penalty.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If no open bin can fit, this is the fallback: reduce penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing).
    score += 0.10 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
