        score += 4.0;
    }

    // Mean residual coupling: prefer bins deviating from mean to consolidate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Late stream: tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity as f64 - gap) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item fits exactly, avoid wasting that residual on junk
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // dead space penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize bins whose post_residual is small and unlikely to be reusable
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 30.0 * (1.0 - pr / 10.0);
    }

    // Relative-to-mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - pr);

    // New-bin candidate handling: make empty bin attractive only when
    // existing fits are poor (large post_residual waste) or it's a tight item
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = 0.35 * (post_residual as f64) + 20.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // forced new bin anyway
        }
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 15.0; // fresh bin enables perfect lookahead pair
        }
    }

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Penalize opening a new bin, more so when other bins fit the item.
    if is_new_bin {
        let escape_pressure = if fitting_bins_count == 0 { 0.0 } else {
            6.0 + 0.15 * open_bins_count as f64 + 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64)
        };
        score += escape_pressure;
        // Late in the stream, closing out open bins matters more.
        score += 8.0 * progress;
    } else {
        // Reward tight fits: small post_residual is already the base score.
        // Reward exact fills strongly.
        if post_residual == 0 {
            score -= 15.0;
        } else {
            // Nonlinear waste penalty: quadratic in residual, scaled by capacity.
            let r = post_residual as f64;
            score += 0.02 * r * r / bin_capacity as f64;
        }

        // Last-chance bin: strongly favor using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }

        // Lookahead: penalize leaving a residual that barely fails to fit the next item,
        // reward leaving a residual that fits it well.
        if next_item_size > 0 && !is_new_bin {
            let next = next_item_size as f64;
            let r = post_residual as f64;
            if r >= next {
                // Next item fits here: bonus scaled by how snugly.
                score -= 4.0 * (1.0 - (r - next) / bin_capacity as f64);
            } else {
                // Dead space relative to lookahead: penalize near-misses.
                let gap = next - r;
                if gap <= 20.0 {
                    score += 3.0 * (1.0 - gap / 20.0);
                }
            }
        }

        // Prefer spreading into bins with above-average residual when many bins are open
        // (balances load), but prefer below-average residual when few bins are open
        // (consolidation).
        let dev = bin_residual as f64 - mean_residual;
        if open_bins_count > 3 {
            score -= 0.05 * dev;
        } else {
            score += 0.05 * dev;
        }

        // Mild early-stream consolidation: keep few bins open while the horizon is long.
        score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on tolerate slack; late in the stream penalize residual waste harder.
    let progress_coupling = norm_pr * (0.5 + 2.5 * progress) * (1.0 - norm_pr) * 4.0;
    score += progress_coupling * cap * 0.1;

    // Polynomial interaction: residual^2 scaled by progress to amplify late waste
    score += (norm_pr * norm_pr) * cap * (0.2 + 1.5 * progress * progress);

    // Lookahead: reward bins whose post-residual could host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_margin = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - fit_margin) * (1.0 + 0.5 * progress);
        } else {
            // dead space relative to next item: penalize smoothly
            let dead = (nxt - pr) / cap;
            score += 4.0 * dead * (1.0 + dead);
        }
    }

    // Last-chance bin: strongly reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, scaled by how tight the fit is
        score += (fitting_bins_count.min(10) as f64 - 1.0) * 0.4 * (1.0 - norm_pr);
    }

    // Context: penalize bins far from mean residual (encourage balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate handling: empty bin should only win when it genuinely helps.
    if bin_residual == bin_capacity {
        // penalize opening new bins generally, more so early (fewer items committed)
        score += 10.0 + 8.0 * (1.0 - progress);
        // but if all open bins are nearly full (tiny residuals), soften the penalty
        let mean_norm = mean_residual / cap;
        if mean_norm < 0.25 {
            score -= 6.0 * (0.25 - mean_norm) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / cap;
    score -= (1.0 - tightness).powi(3) * 60.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            score -= 4.0; // bin stays usable for lookahead item
        }
        // Harmonic class: exact fit of next item leaves perfect residue
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Modulo / harmonic-class logic on post_residual
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect bin closure
    } else if pr < 10 {
        score += 15.0; // tiny unusable sliver
    } else {
        // residue classes by integer division thresholds
        let class = pr / 10;
        match class {
            0 => score += 10.0,
            1 => score -= 3.0,
            2 => score -= 5.0,
            3 => score -= 4.0,
            4 => score += 2.0,
            5 => score -= 6.0,
            _ => {}
        }
        // reward residues that are multiples of common item sizes
        if pr % 20 == 0 { score -= 5.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when nothing fits well elsewhere
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            // discourage abandoning existing bins unless they'd be badly fragmented
            score += 35.0 + mean_residual * 0.2;
            // allow new bin late in stream if mean residual is very low
            let progress = step_index as f64 / total_items.max(1) as f64;
            if mean_residual < item_size as f64 * 0.5 {
                score -= 20.0 * progress;
            }
        }
    }

    // Mild preference for fuller bins among many open bins
    score += open_bins_count as f64 * 0.15;

    // Prefer bins whose residual is close to mean (keep residuals homogeneous)
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much more than large ones.
    // A residual gap is "dead" if it's too small for the smallest plausible item.
    let min_item = 1.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_item {
        score += 1000.0;
    }
    // Non-linear penalty: small gaps are quadratic-bad, large gaps mildly bad.
    if pr < 15.0 {
        score += (15.0 - pr) * (15.0 - pr) * 0.5;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: prefer filling already-open bins; the more open bins, the
    // stronger the pull toward existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin unless the current item would leave a very tight fit
    // in an existing bin (i.e., post_residual would be tiny/wasteful anyway).
    if bin_residual == bin_capacity {
        score += 120.0;
        // If the item is huge, a fresh bin is actually a good idea (near-full pack).
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 100.0;
        // If many bins are open and mean residual is high, opening fresh is cheaper
        // than fragmenting.
        score -= (mean_residual / bin_capacity as f64) * open_bins_count as f64 * 2.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual gap,
    // reward this placement (perfect chaining).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 30.0;
        } else if diff <= 5 {
            score -= 15.0;
        } else if (post_residual as u32) < next_item_size {
            // gap too small for next item: dead space for the lookahead
            score += 10.0;
        }
    }

    // Slight preference for tighter fits overall (best-fit core).
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that exactly fits next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item can still go here: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover: penalize dead space
            score += 80.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin candidate unless current bins are all poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // open fewer bins early in stream; more bins later is fine
        score += 30.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    } else {
        // reward tightness relative to mean residual
        if (bin_residual as f64) < mean_residual {
            score -= 40.0;
        } else {
            score += 20.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
        }
    }

    // Large items: prefer bins with small residuals to avoid fragmenting big bins
    if item_size > bin_capacity / 2 {
        score -= 30.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead fit: leaving space exactly for next item is great.
            let gap = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post residual too small for next item -> potential dead space.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is large or
    // existing residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Opening a new bin is penalized mildly, less so late in the stream
        // or when open bins have high residuals (poor fit elsewhere).
        score += 15.0 - 10.0 * progress + 0.1 * open_bins_count as f64 - 0.05 * fragmentation;
        // Large items benefit from a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (use up the most constrained bins first).
        score -= 0.08 * (mean_residual - bin_residual as f64);
    }

    // Mild penalty for very small post-residuals that no item (min size 1..10)
    // could realistically use, encouraging full utilization.
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * pr_norm) + 18.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.4 + 0.6 * progress);

    // Last-chance bin bonus: penalize alternatives mildly when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits exactly into post residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins with large mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: keep it moderately attractive only when residuals are tight
    if bin_residual == bin_capacity {
        score = pr + 15.0 - 10.0 * (mean_residual / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot" of capacity it falls into.
    // Small post residuals are desirable (tight packing); reward them nonlinearly.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post <= eighth {
        score -= 35.0;
    } else if post <= quarter {
        score -= 20.0;
    } else if post < bin_capacity / 2 {
        score -= 8.0;
    } else if post < (3 * bin_capacity) / 4 {
        score += 6.0;
    } else {
        score += 14.0; // large dead space penalty
    }

    // Harmonic match: does the lookahead item fit the post residual (or a harmonic fraction)?
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx > post {
            // lookahead cannot fit here; penalize unless residual is tiny anyway
            if post <= eighth {
                score += 2.0;
            } else {
                score += 10.0;
            }
        } else if nx == post {
            score -= 40.0; // next item exactly fills this bin
        } else if post - nx <= eighth {
            score -= 25.0; // near-perfect chain
        } else if post - nx <= quarter {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
        // If next item is huge, prefer conserving this bin for it when post residual is large
        if nx >= (3 * bin_capacity) / 4 && post >= nx && post - nx > quarter {
            score += 8.0; // wasteful chain, mild penalty
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: slightly above a mediocre existing fit.
        score = cap * 0.62;
        if open_bins_count == 0 {
            score = -1000.0; // must open the first bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity / 2) {
            score -= 15.0; // lookahead is huge, a fresh bin is fine
        }
        if item_size >= (3 * bin_capacity) / 4 {
            score -= 20.0; // very large item: fresh bin is natural
        }
    } else {
        // Encourage tighter existing bins slightly when many bins are open.
        let tightness = 1.0 - (bin_residual as f64) / cap;
        score -= tightness * 5.0 * ((open_bins_count as f64).ln() + 1.0).min(4.0);
    }

    // Progress-aware nudge: early in the stream, be a bit more liberal with new bins;
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Penalize bins with large residuals being consumed poorly.
    if post_residual > 0 && post_residual < item_size as u32 {
        // post_residual can't fit a copy of this item: potentially dead space.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Base cost of opening a new bin, scaled by open bin pressure.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // If no existing bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item exactly fits the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit anywhere after this placement, penalize wasting space.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Prefer bins below mean residual (tighter bins) for large items.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that match the next item exactly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (post_residual as f64 - n).abs();
        if post_residual as u64 >= next_item_size as u64 {
            // Next item fits: reward tight match, penalize loose leftover.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space that is too small to reuse.
            score += 10.0 + 0.5 * post_residual as f64;
        }
        // Mild pull toward mean residual to keep bin sizes balanced.
        score += 0.1 * (post_residual as f64 - mean_residual);
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the new-bin call scores even lower).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with small residual overall (tight packing).
    score += 0.3 * (post_residual as f64);

    // Slight penalty for wasting space relative to capacity when item is large.
    if item_size >= 60 {
        score += 0.2 * (bin_residual - item_size) as f64;
    }

    // Discourage opening new bins when many bins are already open and one fits.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a fresh bin.
        score += 40.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0; // a fresh bin is good for the next item too
        }
    }

    // Progress-based mild decay: early in stream, be more conservative about
    // fragmenting bins; late in stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    score -= 2.0 * (bin_residual as f64 - item_size as f64).abs().recip().min(1.0) * (bin_capacity as f64 * 0.5);

    // Penalize dead space: post_residual below smallest plausible item is waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // If next item cannot fit in post residual but could fit in another bin, mild penalty for leaving awkward gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin when many bins are open and fragmented.
        score -= (open_bins_count as f64).ln() * 6.0;
        // If mean residual is small (bins are full), new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // Large items justify a fresh bin more.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Time horizon: later in the stream, consolidate more aggressively (avoid new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 12.0;
    } else {
        score += progress * 25.0;
    }

    // Prefer bins with residual close to item size relative to mean fragmentation.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = bin_residual as f64;
    let sz = item_size as f64;

    // Base: prefer tight fits (small post_residual), non-linearly amplified.
    let mut score = pr * (1.0 + 0.6 * (pr / cap) * (pr / cap));

    // Reward filling the bin deeply (low residual fraction) with smooth coupling.
    score -= 8.0 * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Non-linear coupling with stream progress: as stream advances, prefer
    // tighter packing (larger effective weight on post_residual).
    score += pr * 1.5 * progress * (1.0 - progress + 0.25);

    // Dead-space penalty: residual too small for the smallest plausible item,
    // smooth quadratic in normalized residual.
    let dead = (pr / cap).powi(2) * ((pr < 10.0) as f64);
    score += 25.0 * dead * (1.0 + 2.0 * progress);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Smooth penalty proportional to shortfall.
        let gap = (next_item_size as f64 - pr) / cap;
        score += 10.0 * gap * gap * cap * 0.1;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr / cap);
    }

    // New-bin candidate (empty bin): penalize opening a bin when open bins fit,
    // penalized smoothly more as the stream progresses; allow late-stream
    // relaxation via progress coupling.
    if ir == cap {
        score += 20.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive.
        score -= 0.15 * next_item_size as f64 * progress;
    }

    // Mild preference for bins with residuals below the mean (compact usage).
    score += 0.05 * (pr - mean_residual) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (divisible by common small item sizes) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class bonus: post_residual divisible by 10/20/25/50 leaves room for
    // typical future items.
    let mut class_bonus = 0.0;
    if post_residual > 0 {
        if post_residual % 10 == 0 { class_bonus += 6.0; }
        if post_residual % 20 == 0 { class_bonus += 4.0; }
        if post_residual % 25 == 0 { class_bonus += 4.0; }
        if post_residual % 50 == 0 { class_bonus += 3.0; }
        if post_residual % item_size.max(1) == 0 { class_bonus += 5.0; }
    } else {
        // Perfect fill is ideal.
        class_bonus += 25.0;
    }
    score -= class_bonus;

    // Penalize large dead space quadratically: a residual that no plausible
    // item can use is waste. Items are 1..=100, so residual >= 100 in a
    // non-full bin is impossible, but small unusable residuals (<10) are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Relative waste term: (post_residual / capacity)^2 scaled.
    score += 8.0 * (post / cap) * (post / cap);

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness of that fit.
            let n = next_item_size as f64;
            score -= 10.0 * (n / (post + n));
        } else {
            // Next item won't fit here: slight penalty if this was the only
            // fitting bin (forces a new bin anyway).
            if fitting_bins_count <= 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the item is huge relative to
    // residual space of existing bins or the fit here is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If stream is early, more items are coming: new bins are less bad.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is small, existing bins are
        // crowded: a new bin becomes more acceptable.
        score -= 5.0 * (mean_residual / cap).max(0.0);
        // Large items prefer fresh bins when they'd leave a big awkward gap.
        if item_size as f64 > 0.6 * cap && post_residual > 0 && post_residual < 20 {
            score -= 18.0;
        }
    } else {
        // Existing-bin preference: reward using open bins to keep bin count low.
        score -= 4.0;
        // Tight fit reward: fraction of residual consumed by the item.
        let tight = 1.0 - (post / bin_residual.max(1) as f64);
        score -= 10.0 * tight * tight;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 12.0; // blocks the next item into a dead gap
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * pressure;

    // Prefer filling bins with small residual relative to mean (consolidation).
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no good fit exists elsewhere
    // (i.e., item would leave a dead gap in every fitting bin or nothing fits well).
    if bin_residual == bin_capacity {
        let would_create_dead_space = post_residual > 0 && post_residual < 10;
        if would_create_dead_space {
            score -= 200.0; // fresh bin avoids dead space entirely
        } else if fitting_bins_count == 0 {
            score -= 150.0;
        } else {
            score += 40.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but not zero-waste obsession.
    let fit_ratio = item_size as f64 / bin_residual as f64; // 1.0 = perfect fit
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 45.0 * (-gap / 20.0).exp(); // exponential match reward
        // Penalize leaving a residual that is *almost* but not exactly fitting the next item
        if gap > 0.0 && gap < 10.0 {
            score += 12.0 * (1.0 - gap / 10.0);
        }
        // If post_residual cannot hold next item at all, mild penalty scaled by waste
        if post_residual < next_item_size {
            score += 0.15 * post_residual as f64;
        }
    }

    // Dead space penalty: residuals too small to hold any plausible future item (min size 1..100 unknown, assume >=10 typical)
    if post_residual < 10 {
        score += 25.0; // near-perfect fit is great, but tiny residual is fine too; keep small
        score -= 20.0; // net small bonus: perfect fill
    }

    // Relative to mean residual: filling below-average-residual bins is efficient consolidation.
    if mean_residual > 0.0 {
        score -= 8.0 * (1.0 - bin_residual as f64 / (mean_residual + 1.0)).max(-1.0).min(1.0);
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if lookahead shows next item pairs perfectly with a full bin after this item, allow it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Later in the stream, be more conservative about opening bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Prefer filling bins with larger residual first when many bins are open (reduce bin sprawl)
    score -= 0.05 * bin_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Convex dead-space penalty: small post-residuals are cheap, large ones expensive.
    score += (post_residual * post_residual) as f64 / (2.0 * cap);

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }

    if is_new_bin {
        // Opening a new bin is only attractive for large items or when no decent fit exists.
        score += 30.0 - 0.3 * item_size as f64;
        if fitting_bins_count > 0 && item_size < 50 {
            score += 18.0; // discourage abandoning open bins for small items
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 6.0; // slight dampening: fresh-bin lookahead bonus is less trustworthy
        }
    } else {
        // Last-chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Late in the stream, favor bins that end tight (consolidation pressure).
        score -= 10.0 * t * (1.0 - post / cap);
    }

    // Mild global pressure: when many bins are open, prefer tighter fits to avoid sprawl.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Alignment with mean residual: bins already below-average residual are better targets.
    score += 0.1 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = (pr / cap).clamp(0.0, 1.0);

    // Base: prefer tight fits (small post_residual), but with a smooth
    // polynomial that penalizes BOTH large waste and unusable dead space.
    let mut score = pr as f64;

    // Dead-space penalty: residuals too small for the smallest plausible
    // future item are wasted. Smooth quadratic bump around tiny residuals.
    let dead_threshold = 10.0;
    let deadness = ((dead_threshold - pr).max(0.0) / dead_threshold).powi(2);
    score += 40.0 * deadness;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate slack (future items can fill it); late in the
    // stream, tighten aggressively via a rising polynomial weight.
    let slack_weight = 0.5 + 1.5 * progress * progress;
    score += slack_weight * (x * (1.0 - x)) * cap * 0.2;

    // Reward bins whose post_residual can still hold the lookahead item
    // (smooth coupling, avoids hard piecewise logic).
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let fits_next = ((pr - nx).max(0.0) / cap).clamp(0.0, 1.0);
        score -= 8.0 * fits_next * (1.0 - progress);
        // Penalize if this placement makes the bin unable to host next item
        // while the bin was nearly a perfect two-item match.
        let combo = ((it + nx) / cap).clamp(0.0, 1.0);
        let misses_next = ((nx - pr).max(0.0) / cap).clamp(0.0, 1.0);
        score += 12.0 * combo * misses_next * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for bins already tighter than the mean (keep diversity),
    // scaled smoothly by how many bins are open.
    let spread = (mean_residual - bin_residual as f64) / cap;
    score += 3.0 * spread * spread * (open_bins_count as f64).sqrt().min(5.0);

    // New-bin candidate: penalize slightly so it only wins when open bins
    // would create real dead space (their deadness penalty dominates).
    if bin_residual as f64 >= cap - 0.5 {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    // Dead-space penalty: residuals that are unusable for typical items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity quarters.
    let quarter = (bin_capacity / 4).max(1);
    let pr_mod = post_residual % (quarter * 2);
    if post_residual > 0 {
        // Penalize residuals that fall in awkward classes (too small for most items).
        if post_residual < 10 {
            score += 60.0; // nearly dead space
        } else if pr_mod < 5.0 && post_residual < 30 {
            score += 25.0; // awkward small class
        } else {
            score -= 12.0; // usable residual class
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Fractional fill reward: how much of the bin is consumed.
    let fill = (bin_residual as f64 - pr) / cap;
    score -= fill * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let large = item_size as f64 > 0.6 * cap;
        let poor_fit = pr > 0.45 * cap || fitting_bins_count == 0;
        if large || poor_fit {
            score -= 70.0; // opening a new bin is fine for big items / no alternatives
        } else {
            score += 80.0 + 0.5 * open_bins_count as f64; // discourage bin proliferation
        }
    }

    // Lookahead coupling: if next item fits the post-residual nicely, reward.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr && pr - ns < 10.0 {
            score -= 20.0; // chain fit
        } else if ns > pr && ns <= bin_residual {
            score += 10.0;
        }
        // Harmonic divisibility: next item divides residual cleanly.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Stream progression: early on, be conservative with open bins;
    // late in stream, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 10.0 * fill;
    } else if progress < 0.2 {
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual context: if mean residual is low, preserve high-residual bins.
    if (mean_residual - pr).abs() < 5.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: strongly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Medium dead space (10..25) is partially unusable too.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 6.0 * pressure;
    } else {
        // New-bin candidate: penalize opening bins unless existing fits are terrible.
        score += 25.0 + 8.0 * pressure;
        // If the current item leaves a large gap and next item could use a fresh bin, soften.
        if post_residual >= 40 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving residual it can't use.
            score += 4.0;
        }
    }

    // Favor bins with below-mean residual (tighter bins get priority).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 3.0 * diff.min(30.0) / 10.0;
        }
    }

    // Stream progression: late in stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead match
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-diff / 10.0).exp();
    }

    // Penalize dead space relative to mean residual: bins with unusually small
    // remaining space after placement are good (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness);

    // Bonus for last-chance bin (only fitting bin): avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating very small unusable residuals unless they match next item
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || post_residual != next_item_size) {
        score += 25.0;
    }

    // Prefer bins with residual below mean (denser bins first)
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Slight preference to keep new bins closed early in the stream
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual quadratically.
    score -= 0.5 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize post_residual that is too small to fit any plausible future item
    // (dead space). Items can be as small as 1, so only exact zero is truly dead,
    // but very small residuals are likely wasted.
    if post_residual > 0 && post_residual < 8 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't chain here: mild penalty scaled by how much we miss by.
        let miss = (next_item_size as f64 - post_residual as f64).min(40.0);
        score += 0.15 * miss;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling bins,
    // keep flexibility); late in the stream, squeeze harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below mean residual (fill the emptiest relative bins).
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh start. Prefer opening
    // a new bin only when the current item is large and would leave a large,
    // awkward residual in an existing bin, or when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: modest, so tight fits in existing bins win.
        score = (bin_capacity - item_size) as f64 + 5.0;
        // If item is large, new bin is more attractive (large items pair poorly).
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // If next item is small, a fresh bin has good chaining potential.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 8.0;
        }
        // Late in the stream, avoid opening new bins.
        score += progress * 12.0;
        // If several bins fit already, opening a new one is wasteful.
        if fitting_bins_count >= 2 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial coupling: post-residual warped by stream progress
    let mut score = x * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);
    score += 0.6 * x * x;
    score -= 0.4 * x * x * x * (1.0 - progress);

    // Penalize dead space that cannot fit the next item (smoothly)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 0.9 * gap * gap;
        // Reward leaving room exactly for next item
        let fit_gap = (pr - nxt).abs() / cap;
        score -= 0.25 * (1.0 - fit_gap) * (1.0 - fit_gap);
    }

    // Last-chance bonus: avoid opening a new bin when only this bin fits
    if fitting_bins_count == 1 {
        score -= 1.5 + 0.5 * progress;
    }

    // Mild pressure toward consolidation as bins accumulate
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate: neutral baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = 1.0 + 1.2 * progress - 0.3 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, bin closes
    }

    // Harmonic class of post_residual: group residuals into capacity-fraction classes.
    // Small residuals (< smallest item) are dead space; penalize proportionally.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space class: residual too small for any item
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Integer-division threshold classes on post_residual (capacity quarters).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = post_residual / quarter; // 0..4
    score += class as f64 * 5.0;

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward, scaled by how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 - snug * 0.4;
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic class of next_item_size vs residual class
        let nclass = next_item_size / quarter;
        if nclass == class && post_residual >= next_item_size {
            score -= 10.0; // same harmonic class, likely perfect chaining
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9; // 90.0, worse than most good fits
        if fitting_bins_count == 0 {
            score = -50.0; // forced: must open new bin
        } else if fitting_bins_count == 1 {
            // Existing last-chance bin should usually win; keep new bin slightly worse.
            score = 20.0;
        } else {
            // Multiple fitting bins: new bin only wins if all fits are terrible
            // (approximated via mean residual being very large / fragmented).
            if mean_residual < 15.0 {
                score = 200.0; // open bins are nearly full anyway, keep new bin unattractive
            }
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // Large items justify fresh bins more (less fragmentation risk).
        if item_size >= half {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // room to chain next item in fresh bin
        }
        return score;
    }

    // Slight preference for fuller bins overall (best-fit bias via residual).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Modulo-arithmetic tiebreak: residual congruence classes mod 10.
    score += (post_residual % 10) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below the minimum item size
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // awkward gap that few items can use
    }

    // Reward tight fits (exact fill strongly rewarded).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize very loose fits that waste capacity relative to bin size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins;
    // reusing existing bins is cheaper than opening new ones.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item cannot use the gap
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a new bin, growing with progress.
        score += 45.0 + 30.0 * progress;
        // If other bins can fit the item, opening a new bin is rarely good.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If the item would leave a large gap in an existing bin anyway,
        // a fresh bin is more attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Penalize post_residual that cannot fit next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: penalize unless it enables a perfect lookahead fit.
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && post_residual == next_item_size;
        score += if perfect { 5.0 } else { 30.0 + 0.5 * open_bins_count as f64 };
    }

    // Mild late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing (min size 1..100 unknown) can use,
    // but only mildly for large residuals.
    if post_residual > 0 {
        score += 4.0 / (post_residual as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // More alternatives -> mild penalty for wasting a scarce bin.
        score += 0.6 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; slightly discourage leaving awkward gaps.
            score += 2.0;
        }
    }

    // Time horizon: early in the stream, prefer keeping bins flexible
    // (penalize near-full bins less later since fewer chances remain).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 8.0 * (1.0 - progress); // dead space early is costly
    } else {
        score -= 4.0 * progress; // later, pack aggressively
    }

    // Global state: many open bins -> prefer consolidating into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Compare against mean residual: bins far below mean residual are "wasted";
    // filling them is good.
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev;

    // New-bin candidate handling: an empty bin has full residual.
    // Only attractive when no open bin fits well (many fitting bins => keep new bin closed).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin
        } else {
            score += 10.0 + 3.0 * fitting_bins_count as f64; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: penalize small post_residual more strongly than linearly.
    let tightness = 1.0 - (post / cap);
    score -= 40.0 * tightness * tightness * (0.6 + 0.4 * progress);

    // Penalize large dead space quadratically (unusable slack).
    score += 0.004 * post * post;

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            score -= 12.0 * (1.0 - slack_after_next / cap) * (1.0 - progress);
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot.
            score += 6.0 * (nxt - post) / cap * (1.0 - progress);
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: discourage opening a new bin unless residual waste is high.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 0.05 * mean_residual;
        // Allow opening when item is large (poor fit elsewhere likely).
        score -= 0.25 * item;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (more filled bins).
    score += 0.08 * (mean_residual - post).max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "dead-space quality".
    // Residuals in {0} are perfect; small residues (1..=9) are near-perfect;
    // mid-range residues are less useful. Penalize via class table.
    let class = (post_residual % 10) as f64;
    let class_penalty = match post_residual % 10 {
        0 => -6.0,               // perfect fit class
        1..=4 => -2.0,           // near-perfect
        5..=7 => 1.5,            // awkward middle
        _ => 0.5,                // large-ish residue
    };
    score += class_penalty * (1.0 + class / 10.0);

    // Integer-division thresholds: how many "typical" items (size ~10) still fit.
    let fits_k = post_residual / 10;
    score -= (fits_k.min(10)) as f64 * 2.0;

    // Lookahead harmony: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // chain a perfect follow-up
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post % 10 == 0 {
                score -= 7.0; // lookahead lands on harmonic boundary
            } else if new_post < 10 {
                score += 3.0; // lookahead leaves tiny dead space
            }
        } else {
            // next item cannot use this bin's remainder: residue risk
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are tight
    // or mean residual cannot host the item comfortably.
    if bin_residual == bin_capacity {
        let tight = (mean_residual < item_size as f64) as f64;
        let crowded = (open_bins_count as f64 / 8.0).min(1.0);
        score += 25.0 - 20.0 * tight - 10.0 * crowded;
        // late in stream, prefer consolidating rather than opening
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 8.0;
    }

    // Mild preference for tighter existing bins (small residual before placement).
    score += (bin_residual as f64) * 0.02;

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // "wasted space" elsewhere; nudge selection toward below-mean bins.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are wasted forever.
    if post_residual < 10 {
        score += 500.0; // tiny useless gap -> very bad
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 40 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 3.0 * (item_size as f64) / (bin_residual as f64).max(1.0) * 10.0;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // next item cannot use the gap; penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Mean residual coupling: prefer bins far from the mean to consolidate space.
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate handling: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut base = 250.0 + 3.0 * open_bins_count as f64;
        if post_residual < 20 {
            base += 300.0; // opening a bin that will strand space is terrible
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            base -= 60.0;
        }
        if fitting_bins_count == 0 {
            base -= 400.0; // no alternative anyway
        }
        score = score.max(base);
    }

    // Slight stream-progression tie-breaker: later in stream, prefer reusing bins.
    if total_items > 0 {
        score -= 5.0 * (step_index as f64) / (total_items as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u64 >= next_item_size as u64 {
            // Next item can chain into this bin: reward closeness to exact chain fit.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
