            }
        } else {
            // Next item cannot follow into this bin: penalize small dead space that blocks chaining.
            score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize leaving residuals that are likely unusable (small dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin before opening a new bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer bins with residual below mean residual (compact bins), avoid fragmenting large-residual bins.
    if (bin_residual as f64) < mean_residual {
        score -= 12.0;
    } else {
        score += 6.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred.
        score += 35.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 60.0;
        }
        // If this is the only fitting candidate and lookahead is poor, allow opening a new bin
        // to preserve flexibility for the next item.
        if fitting_bins_count <= 1 && next_item_size > 0 && (next_item_size as f64) > (bin_capacity as f64 - item_size as f64) {
            score -= 55.0;
        }
        // Late in the stream, avoid opening new bins unnecessarily.
        if next_item_size == 0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly prefer minimal waste.
    score *= 1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 + 12.0 * chain_quality;
    }

    // Penalize leaving dead space below the smallest plausible item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins (tighten spread).
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.15 * consolidation;
        score -= 0.5 * open_bins_count as f64;
    }

    // Early stream: be slightly conservative (keep bins flexible for future items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // New empty bin candidate: baseline cost of opening a bin.
    // Should only win when all fits are poor (high post_residual / dead space).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + 10.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // new bin can host the current + next item pair
        }
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64; // forced: no open bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = post + 12.0 * post_norm * post_norm;

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, tighten more aggressively (quartic ramp)
    let ramp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score *= 1.0 + 0.9 * ramp * (1.0 - post_norm) * (1.0 - post_norm);

    // Penalize dead space relative to mean residual (non-linear coupling)
    let dev = post - mean_residual;
    score += 0.05 * dev * dev.abs();

    // Last-chance bonus: only fitting bin -> strong reward, modulated by progress
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * ramp;
    }

    // Lookahead: reward leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let slack = post_norm - nxt;
        if slack >= 0.0 {
            score -= 15.0 * slack * (1.0 - slack.abs());
        } else {
            score += 10.0 * (-slack) * (1.0 + ramp);
        }
    }

    // Mild penalty for many open bins (encourage consolidation), smooth in count
    score += 0.8 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * ramp);

    // Slight preference against opening a new bin when item is small
    score += 5.0 * (1.0 - fit_ratio) * (1.0 - ramp);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins partitioned into residue classes mod 10.
    // Small post_residual classes (1..=9) are near-perfect fits; reward them strongly.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if pr <= 5 {
        score -= 40.0 - class; // tiny dead space, nearly perfect
    } else if pr < 10 {
        score -= 20.0 - class;
    } else {
        // Larger residuals: penalize "dead" classes that few future items can use.
        // Residuals in 1..=10 after a big item are useless; residuals >= 20 are reusable.
        if pr < 20 {
            score += 15.0; // unusable sliver
        } else {
            // Reward residuals that are harmonically compatible with typical item sizes.
            // Items are multiples of common steps; reward residuals divisible by 5 or 10.
            if pr % 10 == 0 {
                score -= 12.0;
            } else if pr % 5 == 0 {
                score -= 6.0;
            } else {
                score += 3.0;
            }
        }
    }

    // Tightness: fraction of the bin consumed by this placement.
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead coupling (k=2): if the next item can exactly use this bin's post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 18.0;
        } else if next_item_size > pr {
            // Next item won't fit here: mild penalty scaled by wasted potential.
            score += 6.0;
        }
    } else {
        // Last item: prefer minimal residual outright.
        score += pr as f64;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (item_size as f64 / cap) * 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if the current fit is very poor (large post_residual relative to capacity)
        // or this bin is a lone sliver, opening fresh is attractive.
        let poor_fit = (post_residual as f64) / cap;
        if poor_fit > 0.5 {
            score -= 30.0 * (poor_fit - 0.5);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative at all
        }
        // Early in the stream, having a fresh bin available is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Open-bin pressure: discourage scattering residual capacity across many bins.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Mean residual coupling: prefer bins deviating below the mean (tighter bins first).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps left over are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Next-item lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= post_residual + 10 {
        // leaving a gap that *almost* fits next item is bad
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Pressure against opening new bins when open bins exist and fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 35.0 + 2.0 * open_bins_count as f64;
        } else {
            // no alternative: neutral baseline slightly below mean residual
            score -= 5.0;
        }
    }

    // Tight-fill bonus: prefer bins whose fill ratio is already high.
    let fill = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 15.0 * fill;

    // Prefer bins tighter than the mean residual (well-packed bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Slight late-stream consolidation: fewer open bins is better as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect match for the next item is highly desirable.
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact match bonus.
        if post_residual as u32 == next_item_size {
            score -= 80.0;
        }
        // Penalize post_residual that is small but cannot fit the next item (dead space).
        if (post_residual as f64) < next {
            score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score += 10.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // A tight fit into an existing bin is always better than a new bin.
        if post_residual as f64 <= 0.25 * bin_capacity as f64 {
            score += 500.0;
        } else {
            score += 120.0 - 60.0 * tightness;
        }
        // Fewer open bins -> slightly discourage new bins.
        score += 5.0 * (open_bins_count as f64).sqrt();
    }

    // Prefer filling bins more completely overall.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    // Mild stream-progression pressure: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so near-perfect packing is strongly preferred.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item can fit into the resulting residual,
    // strongly reward this placement (pairing effect).
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_tightness = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.5 * pair_tightness;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: residual may become dead space; mild penalty scaled by gap.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else (few fitting bins) or bins are very full.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin.
        score += 55.0;
        // Attract new bins early when many bins are open but fragmented.
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else if fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.4 * mean_residual.max(0.0);
        // Late in the stream, discourage proliferation of bins.
        score += 30.0 * progress;
    }

    // Global fragmentation pressure: when many bins are open, prefer consolidating
    // into bins with above-average residual (keep small-residual bins for small items).
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.08 * diff;
        // Mild crowding penalty: spreading across many open bins is fine, but
        // very large open_bins_count suggests fragmentation; reward tight reuse more.
        if open_bins_count > 8 {
            score -= 0.05 * (post_residual as f64);
        }
    }

    // Time-horizon modulation: early items favor flexibility (keep residuals large),
    // late items favor squeezing into whatever fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, non-linearly coupled with stream progress.
    // Late in the stream, small post_residuals are more valuable (less waste).
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - norm_pr));

    // Penalize large post residuals more strongly as progress increases (quadratic coupling).
    score += 20.0 * progress * norm_pr * norm_pr;

    // Reward tight fits: post_residual close to zero gets a smooth bonus.
    score -= 15.0 * (1.0 - norm_pr).powi(2) * (1.0 - progress * 0.5);

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - progress * 0.3) * (norm_pr - norm_next);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize slightly, more so late in the stream.
        score += 6.0 * (0.5 + 0.5 * progress) * norm_next * norm_item;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins vs mean residual alignment.
    score += 0.05 * open_bins_count as f64 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: prefer opening a new bin only early or when post residual is huge.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 25.0 * progress * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but keep dead space usable.
    // Reward small post_residual, but penalize "almost full" waste less than unusable slivers.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = post / cap; // capacity fraction left

    // Harmonic class of post_residual: bins whose leftover is in a "useful" class
    // (divisible into common item sizes) are more valuable.
    let useful = |r: u32| -> f64 {
        let mut v = 0.0;
        for &s in &[10u32, 20, 25, 50] {
            if s <= r && r % s == 0 {
                v += 4.0;
            }
        }
        v
    };
    score -= useful(post_residual);

    // Penalize unusable slivers (< smallest plausible item) heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Next-item lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well next item fits
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: mild penalty scaled by closeness
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // modulo harmony between next item and post residual
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when placement in
    // existing bins would be very poor (large post_residual or dead sliver).
    if bin_residual == bin_capacity {
        // Neutral baseline relative to typical post-fit residual.
        score = cap * 0.75;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can always take the next item; slight incentive
            score -= 2.0;
        }
        // Late in the stream, opening new bins is less attractive (fewer future
        // items to consolidate into existing space).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins with slack: prefer filling them.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Coupling with mean residual: if this bin is much emptier than average,
    // prefer filling it (balance residuals across bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - (bin_residual as f64);
        score += 0.15 * dev;
    }

    // Small tie-breaker on exact-fill classes.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit anything useful
    // (below the minimum plausible item size) are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        // small unusable gap -> strongly penalize (this bin becomes dead)
        score += 200.0;
    } else if post_residual <= 25 {
        score += 40.0;
    }

    // Perfect-fit reward scaled by tightness of the placement.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // reward tight fits relative to capacity
        score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones;
    // when few are open, opening a new bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * 20.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure
        score += 120.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 60.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this bin's remainder: mild penalty for waste
        score += 10.0;
    }

    // Prefer bins whose residual is below the mean (consolidating waste),
    // avoid draining well-packed bins.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus (strong subtraction).
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize mismatch proportional to how badly the next item would waste space.
            let waste = if (post_residual as i64) < (next_item_size as i64) {
                // Next item cannot fit here; residual becomes dead space relative to next item.
                post_residual as f64
            } else {
                diff
            };
            score += 0.35 * waste;
        }
    }

    // Reward tight fits in the current step: low post_residual is already the base; add extra
    // shaping so that leaving very small residuals is doubly preferred.
    if post_residual > 0 && post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Compare against mean residual: bins with residual well below mean are "tight" bins;
    // filling them is good (keeps many bins usable). Bins with residual far above mean are
    // roomy; penalize slightly to prefer spreading items across tight bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.25 * (mean_residual - res);
    } else {
        score += 0.15 * (res - mean_residual);
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // If no open bin fits at all, opening a new bin is necessary: remove the penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // If the next item exactly fills a fresh bin after this one, opening is attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Slight late-stream preference to consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, but dead space
    // below the minimum item size is especially wasteful.
    if post_residual > 0 {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64).powf(2.0);
    }
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0; // nearly-perfect fill
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += 4.0 * (post_residual as f64 / 100.0);
        }
    }

    // Global state coupling: prefer filling bins with large residuals when
    // many bins are open (reduce bin count pressure).
    score -= 2.0 * (bin_residual as f64 / bin_capacity as f64)
        * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Mean residual deviation: choose bins whose residual deviates from the mean
    // in a way that consolidates space (prefer bins with residual below mean
    // when item is large, above mean when item is small).
    let dev = bin_residual as f64 - mean_residual;
    if item_size as f64 > mean_residual {
        score -= 0.5 * dev;
    } else {
        score += 0.3 * dev;
    }

    // New-bin candidate handling: empty bin starts at full residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default penalty: opening a new bin is usually worse than a decent fit.
        score += 12.0;
        // But if no open bin fits well (large post_residual everywhere else),
        // or this is a huge item, allow opening a new bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 70 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 10.0 * progress;
        // If next item is huge, keep a fresh bin available.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 10.0;
        }
    }

    // Small time-horizon modulation: early on, be slightly more willing to
    // spread items (explore); later, pack tightly.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let tightness = 1.0 - (post / cap);

    let mut score = post;

    // smooth non-linear coupling of post_residual with stream progress
    let poly = progress * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= poly * (cap - post) * 0.35;

    // reward tight fits more strongly as stream progresses (smooth cubic)
    score -= tightness.powi(3) * (10.0 + 30.0 * progress);

    // penalize dead space that can't fit the next item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        score += (gap * gap) / cap * (1.0 + progress);
    }

    // last-chance bonus, smoothly scaled by scarcity of fitting bins
    if fitting_bins_count <= 1 {
        score -= 8.0 + 12.0 * progress;
    } else {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // mild alignment with mean residual state
    score += (post - mean_residual) * 0.08 * (0.5 + progress);

    // slight penalty for opening a fresh bin late vs early (smooth)
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress * progress;
        score -= fit * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue classes
    let pr = post_residual as usize;
    let class = pr % 10;
    // Favor residuals that are "harmonically useful": 0, 10, 20, 25, 50
    let useful = matches!(pr, 0 | 10 | 20 | 25 | 30 | 40 | 50 | 60 | 70 | 75 | 80);
    if useful {
        score -= 6.0;
    } else {
        score += 0.05 * class as f64; // mild penalty for odd residues
    }

    // Perfect fit is a jackpot
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space: small nonzero residual is waste
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Coupling with lookahead item: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * (next_item_size as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 2.0; // dead space for the known next item
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are bad fits
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Prefer filling fuller bins when many bins are open
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill;

    // Progress-based nudge: later in stream, be greedier about tight fits
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // Pull toward mean residual: avoid creating outliers far above mean
    score += 0.02 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large leftovers.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fit reward
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // But if this bin is the only fitting option, strongly prefer it over new bin.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Lookahead: if next item fits well in a fresh bin's residual, soften penalty.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 3.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it instead of opening a new bin.
        score -= 18.0;
    }

    // Prefer bins whose residual is close to the item (tight fit), relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.05 * tightness;

    // Late-stream consolidation: as stream progresses, favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead synergy: reward if next item exactly fills resulting residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a superlinear penalty
    // on dead space so fragmented residuals are strongly discouraged.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: reward when the next item exactly matches the post residual
    // (perfect chained fit), penalize when post_residual cannot host next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            // perfect next-item match: big reward
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits, reward proportional to how snugly
            score -= 12.0 * (1.0 - (pr - nxt) / (bin_capacity as f64));
        } else {
            // next item won't fit here: penalize wasted potential
            score += 6.0 + 0.25 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "almost full" — prefer packing them (closes bins out).
    let res = bin_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { res };
    score -= 0.5 * (mean - res);

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the empty bin moderately; the
    // lookahead perfect-match reward can still override it.
    if bin_residual == bin_capacity {
        score += 45.0;
        // late in the stream, be even more reluctant to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract proportional fill achieved.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving dead space that is hard to reuse.
    // Dead space becomes dangerous when post_residual is small but nonzero.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let dead_penalty = if dead < 10.0 {
            // Tiny unusable sliver: strongly penalize.
            30.0 * (1.0 - dead / 10.0)
        } else {
            // Larger leftovers: mild penalty scaled by global mean residual.
            0.05 * dead
        };
        score += dead_penalty;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // we can afford to be picky; penalize mediocre fits more.
    score += 0.08 * mean_residual * (1.0 - fill_ratio);

    // Late in the stream, prefer consolidating into existing bins.
    score -= 10.0 * progress;

    // New-bin candidate: bin_residual == bin_capacity means an empty bin.
    // Make it unattractive unless it would beat a terrible fit: add a fixed
    // opening cost, slightly reduced early in the stream when exploration helps.
    if bin_residual == bin_capacity {
        let open_cost = 40.0 - 15.0 * (1.0 - progress);
        score += open_cost;
    } else {
        // Existing-bin stability: slight preference for bins already below mean residual
        // (concentrating packing into emptier bins keeps others flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - (post_residual as f64) / cap;

    // Reward tight fits more aggressively as the stream progresses (smooth coupling).
    let tight_bonus = fill * fill * (1.0 + 2.0 * progress) * 20.0;
    score -= tight_bonus;

    // Penalize dead space that is too small to ever be useful (non-linear).
    let dead = post_residual as f64;
    let dead_pen = (dead / 40.0).powi(3) * (1.0 - progress);
    score += dead_pen;

    // Lookahead: reward leaving room for the next item (smooth gaussian-like term).
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        let fit_next = (-gap * gap / 400.0).exp();
        score -= 12.0 * fit_next;
    } else {
        score -= 8.0; // last item: prefer any placement over opening a bin
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open and this fit is loose (encourage consolidation).
    let loose_pen = (post_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += loose_pen;

    // New-bin candidate: keep it slightly worse than a decent fit, better than a terrible one.
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Opening a new bin: pay an opening tax so it only wins when every
        // open-bin fit would strand unusable dead space.
        let mut nb = post_residual as f64 + 25.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 20.0 * progress;
        // If the next item is small, a fresh bin has good future utility.
        if next_item_size > 0 && (next_item_size as f64) < 0.25 * cap {
            nb -= 8.0;
        }
        return nb;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Dead space: unusable for any item (sizes >= 10 in classic streams,
        // but small items may exist; scale penalty by how dead it is).
        score += 30.0 - 2.0 * (post_residual as f64);
    }

    // Harmonic class: residuals that are multiples of 10 pair well with
    // common item sizes; mildly reward them.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    // Quarter-class residuals (25/50/75) are also flexible.
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // extra reward if it hosts it nearly exactly.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if gap < 10 {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid
    // opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        if post_residual >= 10 {
            score -= 45.0;
        } else {
            // Even a dead-space fit beats wasting a fresh bin's capacity.
            score -= 40.0;
        }
    }

    // Prefer bins tighter than the fleet average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space: heavy penalty.
            score += 60.0;
        } else if post_residual < 25 {
            // Hard to fill with items >= 10 unless exactly matched later.
            score += 25.0 + (25.0 - post_residual as f64) * 1.5;
        } else {
            // Usable residual: mildly reward larger usable space.
            score -= (post_residual as f64 - 25.0) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bins pressure: many open bins -> discourage spreading, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += bin_pressure * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mean residual coupling: if this bin's residual is well below mean, it's a good consolidation target.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Lookahead: if next item can exactly use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item cannot use the leftover gap -> penalize leaving it.
            score += (post_residual as f64) * 0.35;
        }
    }

    // New empty bin candidate: only attractive when no open bin is a decent fit
    // (i.e., item barely fits or many bins but poor fits). Penalize by default.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 35.0 + open_bins_count as f64 * 2.0;
        // But if the item is huge relative to typical residuals, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual near zero is great.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item exactly matches the post_residual,
    // this is a perfect chain — strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 80.0;
        } else {
            let diff = (post - nxt).abs();
            // Penalize leaving a gap that the next item wastes.
            if post_residual < next_item_size {
                // next item can't fit here; residual becomes dead-ish space
                score += 0.35 * post;
            } else {
                // next item fits but leaves another gap
                score += 0.25 * diff;
            }
            // Reward post_residual that can host next item with small slack
            if post_residual >= next_item_size && diff <= 10.0 {
                score -= 20.0;
            }
        }
    }

    // Compare residual relative to mean residual across open bins:
    // prefer consuming bins with large residuals (big waste potential)
    // when their residual is much larger than the item.
    let waste = post_residual as f64 / cap;
    score += 40.0 * waste * waste;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Penalize the fresh bin mildly so tight fits win,
    // but reward it when the item is large relative to residual patterns.
    if bin_residual == bin_capacity {
        // baseline penalty: prefer existing bins with good fits
        score += 15.0;
        // if item is large and mean residual is small, new bin is reasonable
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
        // late in the stream, avoid spawning many bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Prefer bins whose residual is close to the item (minimal leftover)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * tightness;

    // Slight preference to fill bins with many open bins (consolidation)
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: post_residual chunks that are too small for typical items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 25.0;
        } else if nd > 0 {
            score -= 6.0 * (1.0 - (nd as f64) / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize slightly more if post_residual is stranded
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins among many open bins (mild pressure to consolidate).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0) / 3.0;

    // Mean-residual coupling: when mean residual is high (lots of slack), avoid wasting this bin's space.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Time horizon: early in the stream, be more conservative (slightly favor new bins to diversify);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a neutral-ish score that beats only bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad existing fits would be.
        let mut new_bin_score = 55.0 - 20.0 * (item_size as f64) / 100.0;
        // If item is large (hard to place later), opening a fresh bin is more attractive.
        if item_size >= 60 {
            new_bin_score -= 12.0;
        }
        // If many bins are open with slack, prefer reusing one of them.
        new_bin_score += 0.2 * mean_residual;
        // If the only alternative is a poor fit (large post_residual), opening new bin is good.
        new_bin_score -= 0.0; // baseline; comparisons do the work
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are tolerable; late, they are penalized more.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress * progress;
    score += 60.0 * poly;

    // Reward near-exact fits smoothly (small post_residual gets extra discount).
    score -= 40.0 * (1.0 - norm_pr).powi(6);

    // Dead-space penalty: residuals too small for typical future items.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - pr).max(0.0) / cap;
        score += 25.0 * unusable * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    } else {
        // Mild penalty when many bins compete (spread items less).
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    score -= 8.0 * (mean_residual - pr) / cap;

    // Slight preference for consolidating into fewer bins early.
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are more likely to be sealed efficiently.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: reward tight fits (small post_residual), with quadratic growth
    // of waste penalty.
    score = pr * (1.0 + pr / cap);

    // Modulo-class logic: residues of post_residual relative to capacity
    // fractions. Residues below 10 are near-dead space; heavily penalize
    // unless the fit is near-perfect.
    let dead_zone = (bin_capacity / 10) as f64;
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (dead_zone - pr) * 2.0;
    }

    // Integer-division threshold classes on post_residual:
    // classify leftover into quarters of capacity; middle quarters are
    // the most reusable, so discount them.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    match class {
        0 => score -= 4.0,                    // tiny leftover: good sealing
        1 => score -= 6.0,                    // quarter-left: very reusable
        2 => score -= 3.0,                    // half-left: decent
        _ => {}                               // nearly empty: no bonus
    }

    // Harmonic coupling with next item: if the next item can exactly fill
    // this bin's post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits here: mild reward proportional to how well
        // it would nest.
        let nest = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - nest / cap);
    } else if next_item_size > post_residual {
        // Next item cannot use this leftover: penalize large stranded space.
        score += 0.05 * pr;
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a
    // new bin at (almost) any fit cost.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual so
    // it scores high by default; only allow it when current bins fit badly
    // (large post_residual everywhere) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Reward opening a new bin when the stream is early or bins are
        // congested with big residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = mean_residual / cap;
        score -= 20.0 * (1.0 - congestion) * (1.0 - progress);
        // Penalize new bins when plenty of bins already fit the item.
        score += 12.0 * (fitting_bins_count as f64).min(5.0) / 5.0;
        // Exact-fill lookahead bonus: if next item equals item_size, a fresh
        // bin pairs nicely.
        if next_item_size == item_size {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is harmonically aligned with
    // the item (residual mod item small => good packing rhythm).
    if item_size > 0 {
        let r = (bin_residual % item_size) as f64;
        score -= 3.0 * (1.0 - r / item_size as f64);
    }

    // Tie-breaker: slightly prefer more crowded bins (keeps bin count low).
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible future item are "dead". Penalize them heavily.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect or near-perfect fits deserve a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Penalize leaving a gap that is just barely too small for the next item
    // (wasted potential), but reward gaps that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chainable placement
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mean residual coupling: bins far below mean residual are underused;
    // prefer placing into bins with residuals near/below the mean.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize it, but relax the penalty when the
    // item is large relative to residual in every open bin context.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0;
        let size_relief = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += base_penalty - size_relief;
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit wins.
    score += 0.35 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // 2-step lookahead: reward residuals that match the next item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let match_bonus = 1.0 - ((pr - nxt).abs() / bin_capacity as f64);
            score -= 14.0 * match_bonus * match_bonus;
        } else {
            // Next item cannot fit here; penalize proportionally to wasted space.
            score += 6.0 * (nxt - pr) / bin_capacity as f64;
        }
    }

    // Dead-space penalty: residuals too small for the minimum item size.
    let dead = if post_residual < 10 { 10 - post_residual } else { 0 } as f64;
    score += 9.0 * dead / 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter than average).
    score += 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate: neutral-ish default; only attractive when current bins are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 0.25 * mean_residual;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 {
            score += 2.0; // slight bias toward filling existing bins
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: tight fit reward (lower post_residual => lower score).
    let mut score = post_residual as f64;

    // Non-linear tightness: strongly reward near-perfect fits.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: penalize placements that block the next item unless residual still fits it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // keeps bin useful for lookahead item
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
        // Perfect pairing: current + next exactly fill the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer fuller bins: deviation below mean residual suggests this bin is already
    // committed; slightly favor bins tighter than the average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, avoid proliferating bins: penalize new-bin candidates more.
    let new_bin_penalty = if is_new_bin {
        35.0 + 40.0 * progress + 2.0 * (open_bins_count as f64)
    } else {
        0.0
    };
    score += new_bin_penalty;

    // Mild penalty for very loose fits relative to item size.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, squeeze harder into existing bins.
    let coupling = pr * (progress * progress) * (1.0 - progress) * 4.0;
    score += 0.5 * coupling;

    // Penalize dead space relative to the mean residual of open bins (smooth quadratic)
    let dead = (pr - mean_residual) / cap;
    score += 30.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap);
    }

    // Mild penalty for proliferating bins early (encourages consolidation)
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 50.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins with residual in a "usable band"
    // (e.g. multiples of 25 or residual >= 50) are more valuable to preserve.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional position of post_residual within capacity.
    let frac = pr / cap;

    // Penalize leaving residuals in awkward classes (1..9 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Reward exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-25 harmonic class: residuals that are multiples of 25 are
    // "clean" slots (can host items of size 10..80 in many combos).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Penalize odd residuals (cannot be exactly filled by even items).
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - nest / cap);
        } else {
            // Next item won't fit here: penalize wasting a big residual.
            score += 6.0 * frac;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a tight fit (post_residual small) and mean residual is already fragmented.
    if bin_residual == bin_capacity {
        // Base new-bin score: moderately high so tight fits win.
        score = cap * 0.5;
        // If all open bins would leave large dead space, opening fresh is good.
        if mean_residual > cap * 0.6 {
            score -= 20.0;
        }
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If item is large, a fresh bin is attractive.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with below-mean residual (tighter bins first).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Small tie-breaker favoring fewer open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residuals that are too small
    // to be usable by future items (assume minimum item size ~1..100, so gaps
    // below a conservative threshold are near-worthless).
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 15.0 + 8.0 * open_pressure;
        // But if the next item could pair well with this one in a fresh bin
        // and no current bin fits both, mildly encourage opening.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let gap_fit = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if gap_fit <= 3.0 {
                score -= 20.0;
            }
        }
        // Late in the stream, opening new bins is worse (fewer future items
        // to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Filling an open bin: reward more when mean residual is high
        // (bins are loose), penalize slightly when bins are tight already.
        if (mean_residual - post_residual as f64) > 0.0 {
            score -= 4.0;
        }
        // If next item fits exactly into the post-residual, reward reserving it.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that no item can ever use (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward if the next item fits into post_residual,
    // penalize otherwise (chained placement keeps bins dense).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 + 60.0 * tightness;
        } else {
            // Next item won't chain here; penalize more if leftover is small (wasted).
            if post_residual > 0 && post_residual < 20 {
                score += 25.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit style), but only mildly.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress;

    // New-bin candidate (residual == capacity): penalize unless the item
    // leaves a large, usable residual AND open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is more attractive when few bins exist or
        // the item is large (would leave big residual elsewhere anyway).
        score -= (item_size as f64 / 10.0) * 6.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(3);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize leaving dead space that no plausible future item can use.
    // Items are at least size 1; penalize residuals smaller than a typical
    // small item more harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item can exactly fit in the post_residual,
    // reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves more waste: mild reward scaled by fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack);
        } else {
            // next item cannot fit here: slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / 100.0);
        }
    } else {
        // Last item in stream: just minimize waste directly.
        score = post_residual as f64;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = mean_residual / bin_capacity as f64;
    score -= 15.0 * pressure * (0.5 + progress);

    // Penalize the brand-new empty bin candidate, unless it's early in the
    // stream or no other bin fits well (post_residual of a new bin equals
    // capacity minus item, which is large, so add a fixed penalty).
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress);
        // If item is large relative to capacity, opening a fresh bin is
        // actually fine; reduce the penalty.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * item_frac;
        // If open bins are already fragmented (high mean residual), allow
        // opening a new bin.
        score -= 20.0 * pressure;
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Smooth polynomial coupling of post_residual with progress:
    // early on, tolerate larger post_residuals (score discounted);
    // late in the stream, dead space is penalized more heavily.
    let poly = 0.5 + 1.5 * progress * progress; // smooth ramp 0.5 -> 2.0
    score *= poly;

    // Non-linear fit-quality term: reward tight fits (small post_residual
    // relative to capacity) with a saturating quadratic.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_frac = pr / cap; // 0 = perfect fit, 1 = empty
    score -= (1.0 - fit_frac) * (1.0 - fit_frac) * cap * 0.35;

    // Penalize residuals that are too small to be useful later
    // (smooth trough around mid-range residuals).
    let mid = 0.5 * cap;
    let dev = (pr - mid) / cap;
    score += 4.0 * dev * dev * dev * dev * cap * 0.1;

    // Lookahead coupling: if the next item can use this bin's post_residual,
    // reward; penalize if post_residual is nonzero but next item won't fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item fits here: reward proportionally to how well it fills
            let fill = (nxt / pr).clamp(0.0, 1.0);
            score -= 6.0 * fill * fill;
        } else if pr > 0 {
            // dead space for the next item: penalty grows with progress
            score += 8.0 * (1.0 - pr / nxt) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing bins fit poorly. Penalize the empty-bin candidate mildly,
    // scaled by how many bins are already open and the mean residual.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        // If open bins are quite full on average, a new bin is reasonable.
        let fullness = 1.0 - (mean_r / cap).clamp(0.0, 1.0);
        score += 10.0 + 0.5 * open_bins_count as f64 - 12.0 * fullness;
        // Late in the stream, avoid opening bins with big remaining capacity
        score += progress * 6.0;
    }

    // Mild penalty for bin proliferation early in the stream
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: mod-10 buckets (dead-space classes) ---
    let pr = post_residual;
    let class = pr % 10;
    // Small nonzero residuals (1..=9) are near-perfect fits: strongly reward.
    if pr > 0 && pr <= 9 {
        score -= 25.0 - 2.0 * class as f64;
    }
    // Harmonic sweet spots: residual exactly divisible by common item classes
    // (10,20,25,50) are reusable by many future items -> reward.
    if pr > 0 {
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 7.0; }
        else {
            // awkward residue: penalize proportionally to distance from class boundary
            let dist = class.min(10 - class) as f64;
            score += 2.0 * dist;
        }
    }

    // --- Lookahead: does next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // perfect chaining: next item exactly fills remainder
            if next_item_size == pr { score -= 30.0; }
            else { score -= 6.0 + 10.0 * (next_item_size as f64 / pr.max(1) as f64); }
        } else {
            // next item won't fit: this bin becomes dead space for the horizon
            let gap = (next_item_size - pr) as f64;
            score += 4.0 + gap * 0.15;
        }
    } else {
        // last item: minimize leftover only
        score -= 5.0;
    }

    // --- Tightness reward relative to bin fill fraction ---
    let fill = 1.0 - (post_residual as f64 / cap);
    score -= 20.0 * fill * fill;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if:
        //  - no (or one last-chance) fitting bin, or
        //  - item is large and existing residuals are poor fits.
        let pressure = if fitting_bins_count == 0 { 1.0 }
            else if fitting_bins_count == 1 { 0.55 }
            else { 0.15 };
        let big_item = (item_size as f64 / cap) > 0.6;
        let penalty = if pressure >= 0.55 || big_item { 8.0 } else { 60.0 };
        // slight discount as stream progresses (avoid hoarding early)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += penalty - 10.0 * progress * pressure;
    } else {
        // --- Last-chance bonus: sole bin that fits avoids opening a bin ---
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins below mean residual (balance across bins) mildly
        score += 0.05 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0);
    }

    // --- Integer-division threshold on post_residual: classify usability ---
    let usable = pr / 10; // harmonic decade class
    score += match usable {
        0 => -8.0,          // residual < 10: essentially sealed, but tiny waste
        1 => -3.0,          // 10..19: fits smallest class
        2..=4 => 0.0,       // mid classes: neutral
        5..=7 => 2.0,       // large leftover: mild penalty already in base
        _ => 4.0,           // near-empty bin after placement: wasteful placement
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // future item (1..=100 interface) are wasted. Penalize small-but-nonzero
    // post residuals harshly; large residuals are still usable.
    if post_residual > 0 {
        let dead_threshold = 10.0f64; // below smallest plausible useful item
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Penalty grows as post_residual becomes "awkward": small relative to
        // a typical item but not zero.
        let awkward = if post_residual < item_size { 1.0 } else { 0.0 };
        score += awkward * (20.0 - (post_residual.min(20)) as f64) * 0.5;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (post_residual close to 0 relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 10.0;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        // But if the fit leaves a big dead gap, soften the reward.
        if post_residual > 0 && post_residual < item_size {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing) — penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward heavily (chaining placements).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only prefer it when existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline; dead-space logic above already penalizes bad fits
        // in open bins. Slight bonus so it beats awful fits, slight penalty
        // so good existing fits win.
        score += 5.0 - (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        if post_residual == next_item_size {
            // Exact fit for the next item: strongly reward
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits here with leftover slack
            let slack = post - nxt;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit the post-placement residual: penalize
            let miss = nxt - post;
            score += 6.0 * (miss / 100.0).min(1.0);
        }

        // Bonus if both current and next item nearly fill the bin
        let two_step_fill = (item_size as f64 + nxt) / bin_capacity as f64;
        if two_step_fill >= 0.99 && bin_residual >= item_size + next_item_size {
            score -= 15.0;
        }
    }

    // Penalize creating tiny unusable dead space (waste)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Reward tight fits relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= 3.0 * (mean_residual - post_residual as f64) / 100.0;
    } else {
        score += 2.0 * ((post_residual as f64 - mean_residual) / 100.0).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing bins are all poor fits (large residuals relative to item)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 - 10.0;
        // If the new bin would give a perfect 2-step chain, make it attractive
        if next_item_size > 0 && next_item_size + item_size == bin_capacity {
            score -= 25.0;
        }
        // Late in the stream, discourage opening new bins slightly
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets extra discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize leaving a residual that is too small to be useful
    // for typical future items (dead-space penalty).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item cannot use the leftover: mild penalty scaled by waste.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make it
    // unattractive unless the item is large and current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let new_bin_penalty = 25.0 - 8.0 * fit_ratio - 0.02 * crowding - 3.0 * progress;
        score += new_bin_penalty.max(2.0);
    } else {
        // Mild preference for filling already-open bins when many are open.
        score += 0.05 * open_bins_count as f64;
    }

    // Global-state coupling: when mean residual is high, prefer bins that
    // reduce dispersion (place into bins below the mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Late-stream urgency: toward the end, close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: tightness of fit, non-linearly sharpened (quartic coupling).
    let tightness = 1.0 - post / cap; // 0 = perfect fit, 1 = empty-ish
    let mut score = post * (1.0 + 2.5 * tightness * tightness * tightness * tightness);

    // Penalize dead space relative to the mean residual across open bins.
    score += 0.35 * (post - mean_residual).abs();

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - post).max(0.0) / cap;
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate handling: attractive early, less so as stream matures,
    // and only when the current fit is loose (post_residual large).
    if is_new_bin {
        let fit_looseness = (bin_residual as f64 - item_size as f64) / cap;
        score = cap * (0.55 + 0.45 * progress) * (0.4 + 0.6 * fit_looseness);
        if fitting_bins_count == 1 {
            score += 8.0; // don't open a new bin when it's the only fit
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 1.5;
        }
    }

    // Mild stream-progress drift: later items favor tighter packing.
    score *= 1.0 - 0.15 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "usable bands".
    // Small residuals (dead space) get penalized more when they are awkward classes.
    let pr = post_residual;
    let dead = (pr > 0 && pr < 10) as i32;
    score += dead as f64 * 60.0;

    // Harmonic band penalty: post_residual in awkward mid-bands (11..=30) is hard to fill
    let band = match pr {
        0 => 0.0,
        1..=10 => 0.0,
        11..=20 => 8.0,
        21..=30 => 14.0,
        31..=50 => 4.0,
        _ => 0.0,
    };
    score += band;

    // Perfect-fit harmonic classes: post_residual divisible by common item sizes
    // (10, 20, 25, 50) is a likely future fit -> reward.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 20 == 0) {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward proportional to how snugly next item fits
        score -= 20.0 * (next_item_size as f64 / pr as f64);
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use this residual; penalize small leftover
        score += 6.0 + (pr as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin should only win when the item
    // is large relative to capacity and no good fit exists.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty so new bins are used sparingly
        score += 35.0;
        // large items tolerate fresh bins
        if item_size >= 50 {
            score -= 30.0;
        }
        // early in stream, fresh bins are cheaper
        score -= 15.0 * (1.0 - progress);
        // many open bins with high mean residual -> avoid opening more
        score += 0.4 * open_bins_count as f64 + 0.2 * mean_residual;
    } else {
        // Prefer filling bins with low residual relative to mean (tight packing)
        score -= 0.1 * (mean_residual - bin_residual as f64);
    }

    // Integer-division threshold: residual chunks of >= 50 are valuable; keep them.
    if pr >= 50 {
        score += 5.0; // don't waste a big residual on a tiny leftover gain
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    // (items >= 10 in the canonical case, but sizes 1..100 possible here),
    // so penalize gaps that are tiny relative to typical item sizes.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        // Dead space: the smaller the gap, the worse the waste ratio.
        score += (20.0 - pr) * 2.5;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, consolidate into existing ones
    // to keep the active set small.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item exactly fills the remaining space.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: penalize leaving a gap it can't fit.
        score += 4.0;
    }

    // Mild preference for tighter bins (low residual relative to mean).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;

    // New-bin candidate guard: an empty bin should only win when the item is
    // small relative to capacity (large post_residual already penalizes it),
    // and especially when few bins are open and the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Exact match is ideal: post_residual == next_item_size leaves zero dead space after step 2.
            let match_gap = (post_residual as f64 - next).abs();
            score -= 60.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to how much it misses.
            let miss = next - post_residual as f64;
            score += 25.0 * (miss / bin_capacity as f64);
        }
        // If next item fits perfectly, strongly favor this bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize post residual, with a small bonus for near-perfect fill.
        if post_residual <= 2 {
            score -= 30.0;
        }
    }

    // Tight fit reward: small post-residual is good dead-space-wise.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize creating tiny unusable slivers (dead space that nothing can use).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: prefer bins that are already more filled than average
    // (keeps residuals concentrated, leaves other bins roomy).
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * rel;

    // New-bin candidate handling: only open a new bin when all open bins give bad fits.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: slightly worse than a decent fit,
        // but better than a terrible one.
        score = (bin_capacity - item_size) as f64 + 8.0;
        // If the current item plus next item pack perfectly into a fresh bin, favor opening.
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        // Don't open new bins early in the stream unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly as it approaches zero.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward small gaps that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead space for the known next item.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bin would be badly wasted.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so new bins are chosen only when placement elsewhere is poor.
        score += 20.0;
        // If placing here leaves a great future fit (item pairs), soften.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
        // Few open bins and early stream: opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count < 3 || progress < 0.2 {
            score -= 6.0;
        }
    }

    // Prefer filling bins with large residuals when global mean residual is high (fragmentation risk).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late in stream: prioritize closing out bins (minimize post_residual harder).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * (0.5 + 0.5 * progress);

    let mut score = post + 20.0 * poly;

    // Reward tight fits (low post_residual) more strongly as stream advances
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (30.0 + 40.0 * progress);

    // Penalize leaving dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let gap = post - next_item_size as f64;
        if gap < 0.0 {
            score += (-gap) * (0.5 + progress);
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to fill open bins when many are open
    score += open_bins_count as f64 * 0.05 * (1.0 - norm_post);

    // New-bin candidate: make it unattractive unless open bins are very full on average
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Perfect fit reward ---
    if pr == 0 && !is_new_bin {
        score -= 50.0;
    }

    // --- Harmonic dead-space classes on post_residual ---
    if !is_new_bin && pr > 0 {
        // Residuals below 10 are effectively dead space (min item is small)
        if pr < 10 {
            score += 20.0;
        }
        // Quarter-class modulation: tiny leftover worse than half-full leftover
        score += match pr / 25 {
            0 => 5.0,
            1 => 2.0,
            2 => 0.5,
            _ => 0.0,
        };
        // Odd/even harmonic flavor: odd residuals fragment space slightly more
        if pr % 2 == 1 {
            score += 1.0;
        }
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 && !is_new_bin {
        if next_item_size <= pr {
            // this bin can also absorb the next item: strong reward
            score -= 8.0;
        } else {
            // dead space relative to lookahead demand
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        if fitting_bins_count == 0 {
            // no open bin fits: must open a new bin
            score -= 100.0;
        } else {
            // generally prefer existing bins over opening a new one
            score += 15.0;
            // but if the current item fills a fresh bin exactly and the
            // next item pairs with it, opening is attractive
            if pr == 0 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                score -= 20.0;
            }
            // late in the stream, avoid sprawling bin sets
            let t = step_index as f64 / (total_items.max(1) as f64);
            score += 5.0 * t;
        }
    }

    // --- Mild global tightness pressure as stream progresses ---
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * t;

    // --- Mean-residual anchor: keep bin states balanced ---
    score += 0.05 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_gap = 1u32;
    if post_residual < min_gap {
        score += 1000.0;
    } else if post_residual <= 10 {
        // Gap too small for any realistic item (sizes >= 1, but small gaps rarely reusable)
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // If this bin is the only one that fits, strongly prefer using it (avoid new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // but with few bins, consolidation is fine.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure.
        score += 30.0 + 8.0 * bin_pressure;
    } else {
        // Slight reward for using existing bins when many are open.
        score -= 0.5 * bin_pressure;
    }

    // Lookahead: if next item fits into the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap will be dead for the next item: mild penalty.
        score += 8.0;
    }

    // Prefer bins with below-mean residual (fill emptier bins to balance).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += 0.3 * (res - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual), but reward perfect 2-step matches strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Exact match for the next item: huge reward.
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Reward proportional to how close next item lands to a perfect fit,
            // scaled by fraction of capacity consumed after both placements.
            let combined_use = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * combined_use * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize if this bin becomes dead space.
        score += 8.0;
    }

    // Penalize creating tiny unusable residuals (dead space), especially when
    // the next item can't use them.
    if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: placing into a bin with residual above the
    // mean helps equalize, slightly reward; below mean, slight penalty.
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Late in the stream, be more aggressive at closing bins (favor low post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it unattractive unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if this is a last-resort situation (only one fitting bin) and the
        // next item pairs badly, allow the new bin to compete.
        if fitting_bins_count <= 1 && next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
        // Early stream: opening bins is cheaper, soften the penalty.
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is nearly consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small dead space that few items can use.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score -= 6.0; // small dead space is fine (bin almost full)
        } else {
            // dead space in the "hard to fill" band gets penalized
            let awkward = ((pr - 30.0).abs()) / 30.0;
            score += 4.0 * (1.0 - awkward.min(1.0));
        }
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra bonus for near-exact chain fit
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: slight penalty for fragmentation
            score += 2.0;
        }
    } else {
        // last item: just fill as tightly as possible
        score -= 8.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
        if fit_ratio < 0.35 {
            score += 10.0; // don't burn the last bin on a tiny item
        }
    }

    // Global state: many open bins with slack -> prefer reusing existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    score -= 0.6 * (open_f - mean_residual / 10.0).max(0.0);
    score += 0.3 * mean_residual * (1.0 - progress) * 0.05;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as stream progresses
        // (fewer future items to fill it) and with many open bins already.
        let mut new_bin_cost = 22.0 - 14.0 * progress;
        // If the current item is large, a fresh bin is more attractive.
        if item_size >= bin_capacity / 2 {
            new_bin_cost -= 6.0;
        }
        // If mean residual across open bins is small, existing bins are tight;
        // opening a new bin is reasonable.
        new_bin_cost -= (mean_residual / 20.0).min(5.0);
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), scaled by capacity
    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early in the stream, tolerate larger residuals; later, penalize them super-linearly
    let progress_weight = 1.0 + 2.0 * t * t;
    score += progress_weight * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits more strongly as the stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 40.0 * t);

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic gap penalty)
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += (gap * gap) / cap * (5.0 + 20.0 * t);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 30.0 * t;
    }

    // Mild penalty when this bin is far above mean residual (fragmentation avoidance)
    score += ((pr - mean_residual) / cap).powi(2) * 10.0;

    // New-bin candidate: smooth penalty that relaxes late in the stream
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - t * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual), but not zero-waste obsession
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space below smallest plausible item is bad
    let dead = if post_residual > 0 && post_residual < 10 { 1 } else { 0 };
    score += 45.0 * dead as f64;

    // Modulo-class penalty: residuals in awkward classes (e.g. 1..9 mod 10) create unusable gaps
    let awkward = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += 0.6 * awkward;
    }

    // Perfect fill is excellent
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if next item fits into post_residual, reward; if it exactly fills, extra reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item can't follow here: penalize slightly more for very tight fits
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: only attractive when few bins fit or mean residual is small
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        score = 40.0 + 30.0 * scarcity - 25.0 * pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin is fine
        }
    } else {
        // Slight penalty for spreading across many bins when mean residual is high
        score += 0.15 * (open_bins_count as f64) * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    }

    // Late in the stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    }
    // Gaps that can't fit the lookahead item are less useful; mild penalty.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 12.0;
    }
    // Reward near-perfect fills (small but usable residuals).
    if post_residual > 0 && post_residual <= 15 {
        score -= 25.0;
    }
    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / cap;
    score -= 30.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, keep score
    // higher for bins with large residuals when bins are plentiful.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 50.0);
    score += 3.0 * pressure * (post_residual as f64 / cap);

    // New-bin candidate: make it moderately attractive only when nothing fits
    // well; baseline penalty keeps it from being chosen casually.
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // large item coming: fresh bin is fine
        }
    }

    // Slight late-stream tightening: prefer best fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fits are gold: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post residual, this is a great pairing.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack.min(60.0);
            if slack == 0.0 {
                score -= 150.0; // perfect 2-chain
            }
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // large unusable space and next item is large.
    if bin_residual == bin_capacity {
        let base = 40.0;
        let lookahead_bonus = if next_item_size > 0 && next_item_size as f64 > bin_residual as f64 * 0.9 { -20.0 } else { 0.0 };
        score += base + lookahead_bonus;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild preference for fuller bins among many open bins.
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize bins with large residual that would be wasted on a small item.
    let fill_fraction = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_fraction;

    // Reward using bins that are hard to fill later (small residual relative to mean).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += 8.0 * (rel - 1.0);
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that matches next item poorly,
    // reward leaving residual exactly usable by next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // residual too small for next item: dead space penalty scaled by size
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0;
    }

    // Encourage closing out old/nearly-full bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: opening a new bin should only win if it's genuinely better.
    if bin_residual == bin_capacity {
        score += 25.0 + post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Dead-space penalty grows as stream progresses: unusable slivers late in the stream are costly.
    let dead_threshold = 0.25 * cap;
    if post < dead_threshold {
        let d = (dead_threshold - post) / cap;
        score += 14.0 * d * d * (0.4 + 0.6 * progress);
    }

    // Coupling with next item: reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            let miss = (nxt - post) / cap;
            score += 5.0 * miss * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Scarcity pressure: few fitting bins overall nudges toward using existing bins.
    if fitting_bins_count > 1 {
        score += 2.0 * ((fitting_bins_count as f64).ln()) * (1.0 - progress) * norm_post;
    }

    // Penalize over-fragmenting the bin set when many bins are open with high mean residual.
    score += 1.5 * (open_bins_count as f64).ln() * (mean_residual / cap) * norm_post;

    // New-bin candidate guard: empty bin must not win unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny post-residuals are gold (perfect fit).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic classes: residual modulo 10 — residues that pair well with
    // common item sizes (multiples of 10) are more reusable.
    let r = post_residual % 10;
    if r == 0 {
        score -= 30.0; // clean multiple of 10
    } else {
        score += r as f64 * 2.0; // awkward residue penalized
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 60.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; penalize large leftover
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly
    // everywhere else (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = item_size as f64 / bin_capacity as f64;
        // Opening a fresh bin is good when item is big or many bins are open.
        let appeal = 400.0 * tight - 100.0 * progress - 5.0 * open_bins_count as f64;
        score = 100.0 + post_residual as f64 - appeal.max(0.0);
    }

    // Mild preference for filling bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 20.0;

    // Coupling with mean residual: bins below mean residual are "dense",
    // favor them slightly.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // A post_residual below the minimum item size (1..100 range => treat < 15 as dead)
    // is pure waste; smaller gaps are worse.
    if post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0;
    } else if post_residual < 30 {
        // Moderately hard to fill: mild penalty.
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins => discourage spreading, prefer
    // consolidating into existing bins; new bin gets penalty when many open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
    } else {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 5.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item would be blocked by a tiny dead gap, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins close to mean residual (balanced packing),
    // slightly, to keep options open.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Early in stream: mild preference for opening new bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // Perfect two-item chain bonus: item + next fills bin exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits after placement: mild reward proportional to tightness.
        if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit: penalize creating stranded residual.
            score += 12.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize large unusable dead space relative to mean residual.
    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless item is huge
    // relative to residual space of typical open bins.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 40.0 * big_item;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin also serves the next item well
        }
    }

    // Late-stream consolidation: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 18.0 / (1.0 + tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Small dead space is nearly useless for future items (sizes >= 1, but typically >= 10).
        score += 12.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins fit, to prefer the best-fitting one via post_residual.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: placing into a bin with residual far above mean
    // (large bin) is good; placing into a below-mean residual bin may waste it.
    let residual_diff = bin_residual as f64 - mean_residual;
    score -= 0.15 * residual_diff;

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively (dead space matters less).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness).clamp(0.0, 1.0);

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // Opening a new bin is more attractive when:
        // - few bins fit the item (avoid wasting existing bins badly)
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        // - the item is large relative to capacity (poor fit anywhere)
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * large_item;
        // - many open bins already exist with high mean residual (fragmentation)
        score -= 0.05 * open_bins_count as f64;
        // - late in the stream, prefer consolidating into existing bins
        score += 25.0 * progress;
        // If next item could pair with this item in a fresh bin, opening is fine.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized quantities
    let pr = post_residual as f64 / cap;               // post-fit residual ratio
    let fit = item_size as f64 / cap;                  // item fraction
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64); // slack fraction after fit

    // Smooth polynomial coupling: prefer tight fits, scaled by stream progress
    let poly = pr * pr * (1.0 - progress) + pr * progress;
    score += 12.0 * poly;

    // Reward near-perfect fills more strongly as stream advances
    score -= 8.0 * (1.0 - pr) * (1.0 - pr) * (0.5 + progress);

    // Dead-space penalty: small residuals that likely become unusable
    if post_residual > 0 {
        let dead = 1.0 - (post_residual as f64 / cap).sqrt();
        score += 4.0 * dead * dead * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr * cap {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty proportional to wasted opportunity
        score += 3.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Penalize scattering across many open bins when residuals are large
    let spread = (open_bins_count as f64).ln() + 1.0;
    score += 1.5 * spread * pr * (1.0 - progress);

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 - tightness);

    // New-bin candidate handling: opening a new bin wastes capacity; penalize
    // unless the current item is huge and no tight alternative exists.
    if bin_residual == bin_capacity {
        let huge = fit > 0.6;
        let desperate = fitting_bins_count <= 1;
        if huge && desperate {
            score -= 10.0; // allow fresh bin for big items with no alternatives
        } else {
            score += 20.0 + 10.0 * progress; // discourage new bins generally
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // residue classes modulo 10 (the coarse granularity of item sizes).
    let res_mod = post_residual % 10;
    let dead_zone = (res_mod >= 1 && res_mod <= 4) as i32 as f64;
    score += 6.0 * dead_zone; // leftover 1..4 is nearly unusable dead space

    // Perfect-fit harmonic classes: post_residual in {0,10,20,...} is reusable.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Integer-division threshold: how many "medium" items (>=25) still fit?
    let fits_med = post_residual / 25;
    score -= 2.5 * fits_med as f64;

    // Lookahead coupling: does next_item_size land in the same harmonic class
    // as post_residual (i.e. next item exactly consumes the leftover)?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            // fractional capacity match quality
            let frac = next_item_size as f64 / post_residual as f64;
            if frac > 0.8 {
                score -= 6.0 * frac;
            } else if frac < 0.4 {
                score += 3.0 * (1.0 - frac); // wasteful pairing
            }
        } else {
            score += 4.0; // next item cannot use this bin's leftover anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate penalty: prefer existing bins unless the fit is bad
    // or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        score += 18.0 - 10.0 * pressure.min(2.0);
        if post_residual == 0 {
            score -= 10.0; // item fills a fresh bin exactly
        }
    }

    // Small items early: keep them out of large-residual bins to preserve
    // capacity for bigger arrivals; allow them late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size <= 20 && progress < 0.5 {
        score += 3.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any item (min size 1, but
    // practically small gaps) are wasted. Penalize gaps that no plausible item fits.
    if post_residual < item_size.min(10) {
        score += 60.0; // gap almost certainly unusable
    } else if post_residual <= 10 {
        score += 25.0; // very tight gap, low utility
    } else if post_residual <= 25 {
        score += 10.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer compacting.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in the post_residual, reward leaving useful space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // leaving a gap the next item cannot use is bad
        score += 8.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (denser bins).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: empty bin should only win when current bins give bad fits.
    // Add a fixed opening cost so it loses to decent fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if nothing fits well elsewhere (many dead-space penalties already applied),
        // the base score (post_residual = capacity) is large, so it can still win.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (post_residual == 0 is ideal)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // perfect chain: next item fills this bin exactly after current one
        if post_residual == next_item_size {
            score -= 55.0;
        } else {
            score -= 18.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize dead space the next item cannot use
        let waste = (post_residual - next_item_size.min(post_residual)) as f64;
        score += waste * 0.35;
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins tighter (smaller residual) than average
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.25;
    } else {
        score += (residual_f - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // spread across bins slightly, avoid over-concentrating on one
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: opening a new bin is expensive unless current bin
    // would leave large unusable residue and the stream is early/mid progression
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // default penalty so existing bins win unless they look bad
        score += 30.0;
        // if this bin would be a poor host (big post_residual that next item can't use),
        // opening fresh is more attractive
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 45.0 * (1.0 - progress * 0.5);
        }
        if post_residual >= 1 && post_residual <= 10 {
            score += 25.0; // a fresh bin wastes capacity on tiny leftovers
        }
    }

    // Small late-stream tightening: keep bins packed when nearing the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared residual punishes wasted space super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would be blocked, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Time horizon: late in the stream, consolidation matters more (avoid new bins);
    // early on, spreading is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins are open.
        let mut nb = 20.0 + 60.0 * progress + 3.0 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is more attractive.
        nb -= (item_size as f64 / bin_capacity as f64) * 25.0;
        // If the mean residual across open bins is high, opening a bin is less justified.
        nb += mean_residual * 0.15;
        // Last chance: opening a new bin here is wasteful.
        if fitting_bins_count == 1 {
            nb += 80.0;
        }
        score += nb;
    } else {
        // Favor bins whose residual is close to the mean (balanced packing),
        // but only early/mid stream.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08 * (1.0 - progress);
        // Late stream: prefer the fullest usable bins (smallest post-residual).
        score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap; // fraction of bin filled after placement

    let mut score = pr;

    // Reward tight fits with a smooth non-linear coupling to stream progress.
    // Squared fill term grows as the bin gets fuller; stronger late in the stream.
    score -= 30.0 * fill * fill * (0.5 + progress);

    // Penalize dead space: small but nonzero post_residual is worst (unusable).
    let prn = pr / cap;
    score += 25.0 * prn * (1.0 - prn) * (1.0 - fill); // hump penalizes mid-range leftover
    score += 15.0 * (-prn * 12.0).exp(); // sharp penalty for tiny leftover slivers

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tightness = 1.0 - (pr - nxt) / cap;
            score -= 20.0 * tightness * tightness;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // when many bins fit, prefer the emptiest reasonable target mildly
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: avoid dumping items into bins when the
    // average residual is already low (stream nearing saturation).
    let mrn = mean_residual / cap;
    score += 10.0 * (1.0 - mrn) * prn;

    // New-bin candidate: bin_residual == bin_capacity (empty bin).
    // Opening a new bin is only attractive when existing fits are poor,
    // i.e. when post_residual would be large AND progress is early.
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).max(0.0);
        score += 18.0;                 // base cost of opening a new bin
        score -= 25.0 * prn * early;   // cheaper early in stream with big leftover
        score += 12.0 * (1.0 - prn) * progress; // expensive late with tight fit
    }

    // Mild penalty for proliferating open bins.
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: mod-10 buckets on capacity fractions
    let pr = post_residual;
    let frac = pr as f64 / cap; // 0..1 usable-space fraction
    let class = (pr % 10) as f64;

    // Penalize residuals that fall into "dead" harmonic classes:
    // small leftovers (<10) are unusable since items >= 1... but tiny gaps waste capacity.
    if pr > 0 && pr < 10 {
        score += 25.0; // nearly dead space
    }
    // Residuals in [10,20) are half-dead: only small items can fill them
    if pr >= 10 && pr < 20 {
        score += 8.0 + 0.5 * class;
    }

    // Perfect fit reward: harmonic alignment with capacity quarters
    let quarter = bin_capacity / 4;
    if pr == 0 {
        score -= 60.0;
    } else if pr % quarter == 0 {
        score -= 20.0; // residual aligns with 25/50/75 grid
    } else if pr % 10 == 0 {
        score -= 10.0; // decade-aligned residual is easy to fill
    }

    // Lookahead coupling: does next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // chain fit
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0; // harmonic chain
            }
        } else {
            score += 6.0 + 0.15 * (next_item_size - pr) as f64; // next item won't chain here
        }
    } else {
        // last item: prefer tightest fill anywhere
        score -= 30.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        // base new-bin cost; cheap when existing residuals are large & many
        score = 45.0 + 0.5 * frac * cap - pressure.min(40.0);
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0;
        }
        return score;
    }

    // Mild global pressure term: when many bins are open with small mean residual,
    // prefer consolidating into tight fits (low post_residual already does this).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (frac - 0.5); // early: prefer fuller bins slightly

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (low waste relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: prefer already-open bins as congestion grows.
    score += open_bins_count as f64 * 0.5;

    // Penalize new-bin candidate slightly unless residuals are all tight.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item would fit in the leftover of this placement, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // If current item is large and no bin fits well, new bin is acceptable.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead: bonus if the post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // dead space w.r.t. next item
    }

    // Mean residual coupling: avoid placing into bins far from the mean (keeps a spread of sizes).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: small post_residual is good, but zero dead space is best.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Slack after placing next item; smaller slack is better.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 - (slack_after_next as f64).min(40.0);
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(60.0);
        }
    }

    // Compare against mean residual: bins with less residual than average are more
    // "complete"; prefer packing into them to consolidate full bins.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.5;
    } else {
        score += (res_f - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins could still reasonably fit,
    // unless the current open bins are all quite full (high mean fill).
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin is more acceptable late in the stream or when existing bins are full.
        score += 200.0 - mean_fill * 2.0 - progress * 50.0;
        // If next item is large, an empty bin gives flexibility.
        if next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Mild late-stream tightening: waste matters more as stream nears end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize creating dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            // Exact chain fill is excellent.
            if post_residual as u32 == next_item_size {
                score -= 10.0;
            }
        } else {
            // Dead space for the known next item.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when the item is large or open bins are poor fits.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening a new bin is justified for big items or when existing bins are crowded.
        let open_bias = 14.0 * (1.0 - load) * (1.0 + 0.5 * progress);
        let crowding = if mean_residual < item_size as f64 { 10.0 } else { 0.0 };
        score += open_bias - crowding;
        // Late in the stream, avoid spawning bins with small residual slack.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 8.0; // discourage opening when alternatives exist
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Global residual dispersion: if this bin is far below mean residual, using it balances loads.
    let dev = mean_residual - bin_residual as f64;
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base cost: remaining space after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (bins get filled later); late, waste is expensive.
    let waste_weight = 0.5 + 2.5 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.35;

    // Reward tight fits: perfect fill gets strong subtraction, smooth in residual ratio
    let tightness = 1.0 - (pr / cap);
    score -= 6.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize bins that are outliers vs mean residual (prefer balanced usage),
    // coupled smoothly with progress
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.02 * deviation * deviation / cap * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            // next item cannot fit here: mild penalty proportional to wasted opportunity
            score += 1.5 * (pr / cap);
        }
    }

    // Slight preference for consolidating into fewer bins early
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate handling: empty bin has no history; make it attractive
    // only when it avoids extreme fragmentation (large post_residual is fine on fresh bin)
    if bin_residual == bin_capacity {
        // neutral-ish baseline; the polynomial waste term above already scales it
        score += 2.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if it's not
    // a "dead space" sliver that nothing can use later.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Harmonic classes: classify post_residual by capacity fractions.
    // Post-residuals that are large enough to be reusable are valuable;
    // tiny ones (< 10) are dead space -> penalize.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // dead space penalty
    }

    // Modulo classes on post_residual relative to common item sizes (1..100 unknown,
    // but capacity fractions give robust thresholds).
    let q = post_residual / (bin_capacity / 4); // quarter classes: 0..4
    match q {
        0 => score += 5.0,   // <25: marginal
        1 => score -= 8.0,   // 25..50: decent
        2 => score -= 12.0,  // 50..75: good
        3 => score -= 10.0,  // 75..100: still usable
        _ => score -= 6.0,
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0; // perfect chained fit
        } else if slack < 10 {
            score -= 20.0; // near-perfect chain, dead space avoided
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slightly prefer keeping larger residuals.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: residual == capacity means fresh bin.
    // Opening a new bin is only attractive when current fit is awful
    // (large post_residual waste or dead space) — otherwise penalize.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fit_quality > 0.7 {
            score -= 10.0; // big item: fresh bin is fine
        } else {
            score += 12.0; // small item: prefer existing bins
        }
        // If many bins are open and mean residual is high, discourage new bins.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);
    }

    // Mild pressure against bin proliferation as stream progresses.
    if open_bins_count > 0 {
        score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference to consolidate into bins below mean residual
    // (balances residuals across bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are near-unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    }
    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Last chance: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins, and make opening a new bin costly.
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only when fit is bad or bins are few.
        score += 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
        // Early in stream, opening bins is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins far below mean residual
    // (i.e. emptier bins) to balance, but only mildly.
    score -= 0.05 * (mean_residual - bin_residual as f64).abs();

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        // Exact match: big bonus (subtract).
        if diff == 0.0 {
            score -= 40.0;
        } else if post >= nxt {
            // Reward closeness to next item (smoothed lookahead match).
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space smaller than next item: penalize proportionally.
            let waste_ratio = 1.0 - post / nxt;
            score += 15.0 * waste_ratio;
        }

        // Bonus if post_residual can also fit next item comfortably (>= next + min item size 1).
        if post >= nxt + 1.0 {
            score -= 2.0;
        }
    } else {
        // Last item: minimize residual as usual.
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tight bins first).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Default: slightly discourage new bin.
        score += 10.0;
        // But if item is huge and bins are crowded, allow opening.
        score -= 25.0 * big_item * crowd * (0.5 + 0.5 * progress);
        // If no open bin fits well (post_residual would be tiny), new bin more attractive.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 8.0;
        }
    }

    // Tight-fit reward: filling a bin almost completely is good.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward bins whose post-residual can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 8.0 * tightness;
    }

    // Penalize dead space that nothing small can ever use again (post_residual < min item).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins can fit the item.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 30.0 + 0.3 * open_bins_count as f64;
        // In late stages of the stream, be more conservative about opening bins.
        new_bin_score += 10.0 * progress;
        // If the lookahead item would fit nicely in the fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 8.0;
        }
        // If mean residual across open bins is large, opening a new bin is wasteful.
        new_bin_score += 0.15 * mean_residual;
        score = new_bin_score;
    }

    // Slight global pressure: when many bins are open, prefer consolidating into existing ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
        // Prefer bins whose residual is close to mean residual (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: smooth polynomial in post_residual with progress-dependent weights
    let mut score = pr
        + 24.0 * (1.0 - progress) * norm_pr * norm_pr
        + 40.0 * progress * norm_pr * norm_pr * norm_pr;

    // Reward tight fits: quadratic bonus shrinking with post_residual
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize bins whose residual deviates strongly from mean residual
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bin (only fitting bin): strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Coupling with lookahead: penalize blocking next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - progress) * (1.0 - pr / cap);
        } else {
            score += 8.0 * progress * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it competitive only when residuals are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (mean_residual / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Harmonic class of post_residual (dead-space granularity classes) ---
    // Residuals that are "harmonically compatible" with typical item sizes (multiples
    // of 10-ish) are more reusable; odd/prime-ish residuals are dead space.
    let pr = post_residual;
    let harmonic_class = if pr == 0 {
        0.0 // perfect fit, ideal
    } else if pr % 50 == 0 {
        1.0
    } else if pr % 25 == 0 {
        2.0
    } else if pr % 10 == 0 {
        2.5
    } else if pr % 5 == 0 {
        4.0
    } else {
        6.0 // awkward residual
    };
    score += harmonic_class * 0.6;

    // Integer-division threshold coupling: residual bucket vs next item fit
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can also go here: reward keeping residual usable
            let buckets = pr / next_item_size.max(1);
            score -= 2.0 + buckets as f64 * 0.5;
        } else {
            // Next item cannot use this residual; penalize proportionally to waste
            let waste_frac = 1.0 - (pr as f64 / next_item_size as f64).min(1.0);
            score += 3.0 * waste_frac;
            // modulo resonance: if next_item_size and residual share a gcd class, soften
            let g = gcd(pr.max(1), next_item_size);
            if g > 1 {
                score -= 1.0;
            }
        }
        // Lookahead size class (harmonic bands of 20)
        let next_class = (next_item_size - 1) / 20; // 0..4
        score += next_class as f64 * 0.4; // big next item -> prefer roomier bins slightly
    } else {
        // Last item: prefer zero residual strongly
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Default: opening a new bin is costly
        score += 12.0;
        // But if item is huge and fills the new bin well, opening is attractive
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.8 {
            score -= 10.0 * (fill - 0.8) / 0.2;
        }
        // If no existing bin can fit (we are the only candidate), make it cheap
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Late in stream, slightly prefer consolidating into open bins
        score += progress * 3.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's tight -> good
    let res_f = bin_residual as f64;
    score += (mean_residual - res_f) * 0.05;

    // Many open bins: discourage spreading, favor tight bins (small residual)
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 + post_residual as f64 * 0.02 * (open_bins_count as f64 / 10.0).min(1.0);

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // for future items (min size 1, but practically items are larger), so
    // penalize them heavily beyond their raw residual value.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64) / 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 100.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins; when few bins are open, tolerate spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * (1.0 - progress));
    score += 8.0 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward keeping this bin for a chained perfect placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mildly reward leaving usable space.
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier small gap; prefer placing here to normalize residuals.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 3.0 * dev.min(50.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make opening a new bin attractive only when no open bin offers a
    // good fit (i.e., this call is for the empty bin and the item would
    // leave a large residual anyway), otherwise penalize new bins mildly
    // so existing bins win.
    if bin_residual == bin_capacity {
        let would_be_tight = item_size as f64 / bin_capacity as f64 >= 0.9;
        if would_be_tight {
            score -= 20.0; // big item into fresh bin is fine
        } else {
            score += 15.0 + 10.0 * pressure; // discourage spreading for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            // Slack after hosting next item: smaller leftover is better.
            score -= 60.0 + 1.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            score += 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64 / bin_capacity as f64).sqrt();
        // New bin only attractive for large items or when no open bin fits well.
        let open_penalty = if fitting_bins_count == 0 { 0.0 } else { 350.0 * (1.0 - tightness) };
        score += open_penalty + 40.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0);
    }

    // Dead-space penalty: very small leftover that nothing can use (min item 1).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild nonlinearity
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize if we leave awkward gap
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer the tightest (already via fit_ratio),
        // but add mild diversity pressure to keep some bins flexible
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: when many bins are open with high mean residual,
    // discourage spreading; when mean residual is low, slightly favor consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score += 5.0 * mean_res_norm * (1.0 - progress);

    // Penalize bins that deviate strongly from mean residual (keep balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 6.0 * dev * dev;

    // New-bin candidate logic: an empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slight penalty so good existing fits win
        score += 15.0;
        // But late in the stream or when open bins are crowded, opening is cheap
        if open_bins_count > 0 && mean_residual < 0.25 * bin_capacity as f64 {
            score -= 10.0;
        }
        if progress > 0.8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Base: prefer minimal post_residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * (5.0 + 20.0 * progress);

    // Penalize very small dead space less than mid-range waste: cubic shaping of post_residual
    let x = pr / cap;
    score += 10.0 * x * (1.0 - x) * (1.0 - x);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 * fit_ratio * (1.0 - fit_ratio);
    } else if next_item_size > 0 {
        // Penalize leaving residue that cannot host next item, scaled by closeness
        let gap = (next_item_size as f64 - pr) / cap;
        score += 6.0 * (1.0 - gap.abs());
    }

    // Mean residual coupling: prefer bins deviating from mean toward lower residual early,
    // but allow spreading later to balance open bins
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (10.0 * (1.0 - progress) - 5.0 * progress);

    // New-bin candidate: acceptable early or when it enables a clean split, penalized otherwise
    if is_new_bin {
        score = 0.55 * cap + 0.35 * cap * progress;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Favor opening a new bin if the current item is large relative to capacity
        score -= 0.2 * (item_size as f64 / cap) * cap * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "reusable" residue class (multiples of 10 or 25) are more valuable.
    let class_bonus = if post_residual == 0 {
        -60.0 // perfect fit: strongly preferred
    } else if post_residual % 25 == 0 {
        -18.0
    } else if post_residual % 10 == 0 {
        -12.0
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize residuals that are too small to be useful for any plausible item
    // (dead space): post_residual in [1..10] is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if it cannot fit into post_residual but could fit a
    // slightly larger residual, mild penalty for wasting the pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer it
    // strongly over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to the
    // capacity (poor fit elsewhere likely) or many bins are already open.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 55.0
            - 60.0 * size_frac
            + 2.0 * open_bins_count as f64;
        // Reserve a fresh bin when the next item is large and would need one anyway.
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 20.0 * progress;
        score = new_bin_score;
    } else {
        // Mild preference toward tighter (fuller) bins among open candidates.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;
        // Discard candidates whose residual deviates wildly from the mean
        // (keeps a coherent pool of residual classes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (1) are pure loss; gaps that can't hold a mid-size item
    // are risky. Penalize unusable small gaps heavily.
    if post_residual > 0 {
        // dead space = residual too small to ever fit another item comfortably
        // treat residual <= 10 as near-dead, and residual < 30 as risky
        if post_residual <= 10 {
            score += 40.0; // effectively dead gap
        } else if post_residual < 30 {
            score += 18.0 * (1.0 - post_residual as f64 / 30.0);
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits generally
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * fit_ratio;
    }

    // New-bin candidate handling: empty bin gets post_residual = capacity - item.
    // Only attractive when the item is large relative to capacity or when
    // open-bin pressure is low / fits are bad.
    if bin_residual == bin_capacity {
        // neutral baseline for a fresh bin; make it slightly unattractive
        // unless item is big (item_size >= 60 leaves little room anyway)
        score += 12.0;
        if item_size >= 60 {
            score -= 30.0 * (item_size as f64 / 100.0);
        }
    }

    // Open-bins pressure: more open bins -> favor filling existing bins,
    // penalize spreading out.
    score += 1.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Stream progression: early on, be conservative with new bins; late,
    // allow tighter packing aggression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    // Lookahead coupling: if next item fits the post-residual exactly or well,
    // reward leaving that gap; if next item won't fit, penalize the gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // an outlier gap; filling it normalizes the pool.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

