    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize very small dead space that is hard to fill later (e.g. 1..5)
    if post_residual > 0 && post_residual < 6 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3; // good continuation
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer the fullest (smallest residual already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 35.0;
