        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Cheaper if item fits poorly in all open bins (large mean residual mismatch)
        let waste = (mean_residual - item_size as f64).abs();
        if waste > 20.0 {
            score -= 10.0;
