        if next_item_size > item_size && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Slight preference for bins with residual close to mean (balanced depletion)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: late in stream, be more conservative about fragmentation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += tightness * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - pr / cap; // how full the bin becomes
    let mut score = pr;

    // Reward tight fits with a smooth non-linear coupling to stream progress.
    score -= cap * tight.powi(3) * (0.5 + progress);

    // Penalize dead space (small unusable post-residual) with smooth coupling.
    let dead = if pr > 0.0 && pr < item_size as f64 { (1.0 - pr / cap).exp() } else { 0.0 };
    score += 8.0 * dead * (1.0 - progress);

    // Last-chance bonus: only one bin fits -> encourage using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-average residual (concentrate packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev - 2.0 * dev;

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * fit_frac * (1.0 - fit_frac) * (1.0 + progress);
    }

    // Penalize opening a new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are "useless" for typical
    // item sizes get heavily penalized. Class dead space by integer division
    // thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space classes: post_residual in [1..10] is nearly unusable -> reward.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    } else {
        // large leftover: penalize proportionally beyond base
        score += (pr - 30.0) * 0.35;
    }

    // Lookahead coupling: if the next item exactly fits the post_residual,
    // strongly reward; if next item could fit, mild reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (pr - nxt as f64) / cap);
        } else {
            // next item won't fit here: penalize bins whose post_residual is
            // just below the next item size (wasted capacity)
            score += 6.0 * (1.0 - (nxt - pr) / 40.0).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a moderate baseline score.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.1 - (open_bins_count as f64) * 0.5;
        // late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Slight preference for tighter bins overall (lower residual bins win ties)
    score += (bin_residual as f64 / cap) * 3.0;

    // Mean-residual coupling: when open bins are already loose, be pickier
    // about creating more dead space.
    if mean_residual > 40.0 {
        score += (pr / cap) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are heavily penalized (unusable gaps).
    let dead_threshold = 10u32; // minimum item size
    if post_residual < dead_threshold {
        score += 0.0; // tiny leftover is near-perfect fill, no penalty
    } else if post_residual < 25 {
        // gap too small for most items but not a clean fill -> dead space
        score += 60.0 * (1.0 - (post_residual as f64) / 25.0);
    } else {
        // larger residuals are partially reusable; mild penalty decreasing with size
        score += 10.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Strong reward when the leftover can exactly fit the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leftovers just below the next item size (frustrating near-miss).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer using existing bins when many are open,
    // unless this is the fresh-bin candidate (bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are plentiful / fragmented,
        // reward opening only when mean residual is tight (poor fits elsewhere).
        score += 35.0 + 2.0 * open_bins_count as f64 - 0.15 * mean_residual;
        // Late in the stream, opening new bins is more costly (bins may go unused).
        score += 30.0 * progress;
    } else {
        // Reward placing into existing bins, more so with many open bins.
        score -= 1.5 * open_bins_count as f64;
        // Slight preference for bins tighter than the mean (good consolidation).
        score -= 0.1 * (mean_residual - bin_residual as f64);
    }

    // Prefer tight fits overall: reward small post_residual relative to item size.
    score -= 0.5 * (item_size as f64) * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    let mut score = pr + 0.25 * pr.powf(1.25);

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the next item (chained fit).
            score -= 3.0 + 4.0 * (1.0 - progress);
        }
        // Reserve-room heuristic: keep exactly next_item_size if possible.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.08 * gap;
    }

    // Tight fit reward: small post-residual is good, exact fits great.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Last chance: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Many open bins with slack: prefer consolidating into existing slack.
    if open_bins_count > 1 && mean_residual > item_size as f64 {
        score -= 2.0 * ((mean_residual - item_size as f64) / bin_capacity as f64);
    }

    // New-bin candidate: add a startup penalty so a fresh bin is only chosen
    // when every open bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        score += 15.0 - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = post * (1.0 + 0.6 * fit_ratio * (1.0 - progress));

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = post / cap;
    score += 8.0 * p * p * (0.5 + 0.5 * progress);
    score -= 6.0 * p * (1.0 - p) * progress;

    // Tight fits are good: reward when post_residual is small relative to capacity
    score -= 4.0 * (1.0 - p) * (1.0 - p) * fit_ratio;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if the next item can use the resulting post-residual, reward
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 3.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 2.0 * next_ratio;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    // Coupling with mean residual: bins far below mean are attractive
    score -= 0.05 * (mean_residual - post);

    // New-bin candidate: keep it competitive only when current bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let mut score = post;

    let is_new_bin = bin_residual == bin_capacity;

    // ---- Harmonic decade classes of the post-placement residual ----
    // Classify post_residual into 10 capacity-fraction decades; reward low
    // (tight) residuals, penalize awkward mid-range "dead zone" residuals.
    let decade = ((post_residual.min(bin_capacity) * 10) / bin_capacity.max(1)) as usize;
    let decade_bonus: [f64; 11] = [18.0, 12.0, 4.0, -3.0, -6.0, -4.0, 0.0, 3.0, 6.0, 9.0, 6.0];
    let d = decade.min(10);
    score -= decade_bonus[d];

    // Fine harmonic structure: residuals landing exactly on a 5/10 grid are
    // slightly more reusable by typical item sizes.
    let m = (post_residual % 5) as f64;
    if post_residual > 0 {
        score += m * 0.4;
    }

    // Perfect fill is the ideal outcome.
    if post_residual == 0 && !is_new_bin {
        score -= 10.0;
    }

    // ---- Lookahead coupling with next item (k=2) ----
    if next > 0.0 {
        if next <= post {
            // Next item can chain into this bin's residual: strong reward.
            score -= 8.0;
        } else if post > 0.0 {
            // Residual is stranded for the next item: penalize wasted space.
            score += (post / cap) * 14.0;
        }
    }

    if is_new_bin {
        // ---- New-bin candidate tuning ----
        // Base score is already (cap - item): large items naturally favor a
        // fresh bin. Amplify for items above half capacity.
        if item >= cap * 0.5 {
            score -= (item - cap * 0.5) * 0.6;
        }
        // A fresh bin that can also host the next item is attractive.
        if next > 0.0 && next <= post {
            score -= 10.0;
        }
        // If any open bin already fits, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 4.0;
        }
        // Plenty of aggregate space still open -> prefer existing bins.
        score += mean_residual * 0.12;
        // Late in the stream, avoid spawning bins that will end half-empty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 12.0;
        // Fixed amortized cost of opening a bin.
        score += 6.0;
    } else {
        // ---- Existing-bin tuning ----
        if fitting_bins_count == 1 {
            // Last chance: use this bin or waste a future bin opening.
            score -= 30.0;
        } else if fitting_bins_count >= 2 {
            // Many alternatives: be picky, demand a genuinely tight fit.
            score += (fitting_bins_count as f64 - 1.0) * 1.5;
        }
        // If open bins are collectively quite full, slightly favor reuse.
        if mean_residual < cap * 0.2 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if !is_new_bin {
        // --- Strict dead-space avoidance on existing bins ---
        let pr = post_residual;
        // Tiny unusable gaps: heavy penalty ramping up as the gap shrinks
        if pr < 10 {
            score += 80.0 * (1.0 - pr as f64 / 10.0);
        } else if pr < 20 {
            score += 25.0 * (1.0 - (pr - 10) as f64 / 10.0);
        } else if pr < 35 {
            score += 6.0 * (1.0 - (pr - 20) as f64 / 15.0);
        }
        // Reward tight fits (high fill ratio of the current residual)
        score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);
        // Last-chance bonus: if this is the only bin that fits, strongly prefer it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Lookahead: if the next item can still use the post residual, reward it
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else if next_item_size > 0 {
            // next item cannot use the leftover: mild dead-space penalty
            score += 8.0;
        }
    } else {
        // --- New-bin candidate: penalize opening bins, pressure grows with open count ---
        let pressure = (open_bins_count.min(25) as f64) * 6.0;
        score += 35.0 + pressure + 12.0 * fitting_bins_count as f64;
        // If no open bin fits at all, opening a new bin is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item is large and won't fit the leftover here anyway,
        // opening a fresh bin is less wasteful
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score -= 25.0;
        }
    }

    // Mild coupling to global state: prefer bins whose residual is near the mean
    // (keeps the pool of open bins homogeneous and reusable)
    score += 0.08 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (post_residual as f64 + 1.0)).max(0.0);
        // Exact match for the next item: strong bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If the next item cannot fit in the post residual, penalize dead space.
        if (post_residual as i64) < (next_item_size as i64) {
            score += 8.0 * (1.0 - post_residual as f64 / (bin_capacity as f64));
        }
    }

    // Compare post residual against mean residual of open bins:
    // leaving a residual far above mean wastes space; far below mean is a tight fit (good).
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if post_residual as f64 > mr {
        score += 0.6 * (post_residual as f64 - mr);
    } else {
        score -= 0.3 * (mr - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild preference for keeping many open bins consolidated when item fits tightly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 5.0 * tightness * tightness;

    // Late in the stream, prefer tighter packings more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress * tightness;
    }

    // Slight penalty for having many open bins, encouraging consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - 2.0 * tightness).max(-1.0);

    // Penalize dead space: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: penalize if post_residual can't fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
        // Bonus if post_residual exactly accommodates next item (chain packing).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state coupling: when many bins are open, prefer filling existing ones
    // over spreading; when few open, tolerate opening new bins less.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bins are very full/fragmented.
        score += 15.0;
        score -= 0.5 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    } else {
        // Existing bin: reward closeness to mean residual (balance load).
        let drift = (bin_residual as f64 - mean_residual).abs();
        score += drift * 0.05;
    }

    // Time horizon: late in the stream, be more conservative, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;
    if progress > 0.8 {
        score += 0.1 * post_residual as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - pr / cap; // 0..1, higher = tighter fit
    score -= tightness * tightness * (1.0 + 40.0 * progress * progress);

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 4.0 * (1.0 - (pr - nxt).abs() / cap);
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize opening new bins, more so early in the stream.
    if is_new_bin {
        score += 10.0 + 20.0 * (1.0 - progress);
        // But allow new bins when open bins are all nearly full.
        let mean_tight = 1.0 - mean_residual / cap;
        score -= 15.0 * mean_tight * mean_tight;
    } else {
        // Mild penalty for spreading across too many open bins.
        score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;
    }

    // Smooth polynomial interaction: residual^2 scaled by progress.
    score += (pr * pr) / (cap * cap) * (2.0 + 6.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual via modulo classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr % 10 == 0 {
        score -= 25.0; // round class: likely reusable by future items
    } else if pr % 5 == 0 {
        score -= 15.0;
    } else {
        // dead-space penalty for awkward remainders
        score += (pr % 5) as f64 * 2.0;
    }

    // Integer-division threshold: penalize large unusable residuals
    let quarter = bin_capacity / 4;
    if pr > quarter {
        score += (pr - quarter) as f64 * 0.3;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.4;
        } else {
            // next item won't fit here; penalize leaving medium dead space
            score += 8.0;
        }
    }

    // New-bin candidate handling: neutral-ish baseline, slightly above good fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // open a new bin early when current fits are poor and mean residual is high
        if mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.5 {
            score -= 35.0;
        }
    }

    // Prefer denser packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score -= open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item (1..=100)
    // are pure waste; penalize hard, scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (post_residual near zero or perfectly reusable)
    if post_residual == 0 {
        score -= 25.0;
    }

    // If lookahead item fits exactly in the post residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 50.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit in the gap: penalize proportionally to gap size (dead space risk)
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // mildly encourage filling existing bins anyway (best-fit bias already via post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below the mean residual (more filled bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0) * 0.1;

    // New-bin candidate: only attractive when nothing fits well (large dead-space creation
    // otherwise) — make empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If current item is large relative to capacity, opening fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are desperate.
        // Penalize new bins unless this is the only fitting option.
        score += 40.0;
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Slightly prefer opening new bins early in the stream.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        return score;
    }

    // Dead-space penalty: very small residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward if next item fits snugly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect two-item packing
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Reward tight fits (small post_residual overall).
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let tightness = 1.0 - fit_ratio; // 0 = perfect fit, 1 = loose fit

    // Reward tight fits (low post_residual relative to bin capacity)
    let tight_reward = (1.0 - (post_residual as f64 / bin_capacity as f64)) * 40.0;
    score -= tight_reward;

    // Penalize dead space: small residuals that most future items cannot use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64 + 0.5);
        } else {
            // post_residual too small for next item: penalize proportionally to wasted potential
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: strongly prefer perfect fill
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }
    // Many alternatives: slight penalty to keep flexibility
    if fitting_bins_count > 2 && !is_new_bin {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate logic: only attractive when no good open option exists
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open a new bin
        } else if fit_ratio < 0.35 && open_bins_count > 0 {
            // item is small relative to capacity; prefer existing bins
            score += 30.0;
        } else if tightness > 0.6 {
            // big item: opening fresh bin is fine
            score -= 5.0;
        } else {
            score += 10.0;
        }
        // Early in stream, more willing to open bins; late, consolidate
        score += (1.0 - progress) * 5.0 - progress * 5.0;
    } else {
        // Prefer bins tighter to the current item among open bins
        score += tightness * 15.0;
        // Prefer bins whose residual deviates favorably from the mean
        score += (bin_residual as f64 - mean_residual) * 0.15;
        // Late in the stream: strongly consolidate into fewest bins
        if progress > 0.7 {
            score -= 6.0;
        }
    }

    // Mild pressure to use open bins when many are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic waste penalty on leftover space
    let mut score = post * (1.0 + 0.02 * post / cap);

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, tight fills matter more
    let prog_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 8.0 * prog_coupling * (post / cap);

    // Reward near-perfect fits (small post_residual) increasingly
    let fit_ratio = post / cap;
    score -= 12.0 * (1.0 - fit_ratio).powi(6) * (1.0 + prog_coupling);

    // Last-chance bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * prog_coupling;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - ((post - nxt) / cap).abs();
            score -= 10.0 * snug * snug;
        } else {
            // next item cannot use leftover: mild penalty for large dead space
            score += 4.0 * fit_ratio * (nxt / cap);
        }
    }

    // Prefer bins below mean residual (concentrate filling)
    score += 0.05 * (post - mean_residual);

    // New-bin candidate: penalize opening a new bin, more so late in stream
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + 20.0 * prog_coupling;
        // but allow opening if all fits are terrible (large post_residual elsewhere)
        score -= 10.0 * fit_ratio; // fit_ratio == 1 for empty bin, cancels part
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (divisible by common small item sizes) are rewarded.
    let usable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if r >= *d && r % d == 0 {
                bonus += 6.0;
            }
        }
        bonus
    };
    score -= usable(post_residual);

    // Penalize dead space: post_residual too small for the minimum item size.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual > 0 && post_residual <= 15 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or within a harmonic class, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 10.0;
        if gap == 0 {
            score -= 15.0;
        } else if gap % 10 == 0 || gap % 25 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Post residual too small for lookahead item -> dead space penalty.
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 - (bin_capacity as f64 - item_size as f64)).abs() < 0.5;
        if poor_fit {
            score -= 5.0 + 10.0 * progress;
        } else {
            score += 18.0 - 8.0 * mean_residual / bin_capacity as f64;
        }
    }

    // Prefer filling bins that deviate below the mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Integer-division threshold on bin_residual: half-full or more gets a nudge.
    if bin_residual * 2 <= bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = pr;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10.0_f64.min(cap * 0.1);
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0 + 12.0;
    }

    // Smooth "wasted fraction" penalty, super-linear in waste.
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 18.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 4.0;
    }

    // Pressure from open bins: with many open bins, favor consolidation
    // (penalize opening/spreading); with few bins, be lenient.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (2.0 + 4.0 * progress);
    score += pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    // Tie-break toward bins tighter than the mean residual.
    score -= (mean_residual - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64) * 0.5;

    // 2-step lookahead: reward bins whose post_residual matches the next item size,
    // penalize post_residuals that waste space relative to the upcoming item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match for the next item: big reward.
        if post_residual as f64 >= nxt {
            score -= (20.0 - diff.min(20.0)) * 1.5;
        } else {
            // Post residual too small to host next item: mild penalty scaled by gap.
            score += (nxt - post_residual as f64).min(30.0) * 0.3;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose post_residual sits below
    // the mean residual (i.e., we are filling an already-loose bin tighter).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.25;
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.10;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, prefer the emptier ones slightly (spread load
        // only when many options exist).
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when the item is large relative to capacity or no good fit exists;
    // otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Penalize new bin unless item is big (few future co-tenants needed anyway)
        // or it is the only option.
        score += desperation * (30.0 - large_item * 40.0).max(0.0);
        // Lookahead: opening a new bin is good if the next item also fits well with
        // this item (post_residual close to next size).
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 15.0;
        }
    }

    // Slight late-stream tightening: as the stream progresses, be more tolerant of
    // opening new bins (fewer future items to pair with residual space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Tightness reward: strongly favor small post_residual (best-fit core) ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // ---- Dead-space penalty: leftover space too small to be useful later ----
    // Anything below ~ (smallest plausible item) is nearly unusable; penalize hard.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    } else {
        // Mild decay of usefulness as residual shrinks toward the threshold.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // ---- Perfect-fill bonus ----
    if post_residual == 0 {
        score -= 60.0;
    }

    // ---- Lookahead coupling: reward bins whose leftover can host the next item ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-fit reward, scaled by how snugly the next item would fit after.
            let next_leftover = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_leftover as f64 / bin_capacity as f64);
        } else {
            // Leftover cannot host the next item: mild penalty, worse if it's tiny.
            score += 3.0;
            if (post_residual as f64) < dead_threshold {
                score += 5.0;
            }
        }
    }

    // ---- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and no
        // open bin offers a decent home, or the fleet is saturated.
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0;                       // base cost of a fresh bin
        score -= 20.0 * (item_size as f64 / 100.0); // large items justify fresh bins
        score += 10.0 * progress;            // late in the stream, prefer consolidation
        if fitting_bins_count == 0 {
            score -= 40.0;                   // forced: no alternative
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;                   // plenty of slack elsewhere: don't open
        }
        let _ = crowded;
    }

    // ---- Global state modulation ----
    // When mean residual across open bins is high, prefer bins below the mean
    // (drain the emptiest-relative space first to consolidate fullness).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;                 // bins with more space than average get penalized
    }

    // ---- Time-horizon term: early stream, keep bins flexible; late stream, pack tight ----
    score -= (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 4.0;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: polynomial coupling of post-residual with stream progress.
    // Early on, prefer tight fits (low post_residual); late in stream,
    // leave slightly larger residuals that can still absorb future items.
    let base = pr * (1.0 + 0.6 * norm_pr * norm_pr) * (1.0 - 0.35 * progress);

    // Dead-space penalty: residuals too small to ever fit a plausible item
    // (items >= 1, but realistically tiny residuals are wasted).
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 2.5 } else { 0.0 };

    // Lookahead: reward residuals that can still hold the next item.
    let look = if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            -8.0 * (1.0 - pr / cap)
        } else {
            6.0 * (next_item_size as f64 - pr) / cap
        }
    } else {
        0.0
    };

    // Last-chance bin: strongly favor filling the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Mild penalty for scattering across many open bins relative to mean residual.
    let spread = 0.05 * (open_bins_count as f64).ln() * (pr - mean_residual).abs();

    base + dead + look + last_chance + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fill — best outcome
    } else {
        // Integer-division thresholds: classify dead space into usability bands
        if post % 10 == 0 {
            score -= 8.0;
            if post % 50 == 0 {
                score -= 6.0;
            } else if post % 25 == 0 {
                score -= 3.0;
            }
        } else if post % 5 == 0 {
            score += 2.0;
        } else {
            // odd residue: likely dead space
            score += 6.0;
        }

        // Fractional capacity bands: post_residual as fraction of capacity
        let frac = post as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score += 10.0; // tiny sliver, nearly unusable
        } else if frac < 0.30 {
            score -= 2.0;
        } else if frac < 0.60 {
            score -= 4.0;
        }
    }

    // Reward tight fits: small post_residual relative to item size
    let tightness = post as f64 / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + tightness)) * 12.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size < post {
            let nxt_post = post - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 5.0;
            }
            if nxt_post == 0 {
                score -= 15.0;
            }
            score -= (post - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use this residual — penalize leaving mid-size gaps
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has large residual; make it
    // unattractive unless no good open-bin fit exists (large post_residual
    // or many open bins with small residuals).
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin: its post_residual is large, so add a
        // bias that grows with how many bins are already open
        score += 15.0 + 0.5 * open_bins_count as f64;
        // but if stream is late and mean residual is small, fresh bin is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Mild pressure against accumulating many half-empty bins
    score += mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit the smallest
    // plausible future item (<= ~20) are wasted capacity.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Mid-range residuals are only mildly useful; large residuals are fine.
    if post_residual >= 20 && post_residual < 40 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; slightly penalize leaving large gap
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins when mean residual
    // is already low (bins nearly full -> consolidate).
    if bin_residual != bin_capacity {
        score -= 0.15 * open_bins_count as f64;
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    } else {
        // New bin candidate: penalize mildly so it's chosen only when open
        // bins offer bad fits; penalty grows with stream progression.
        score += 30.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still fit the next item: reward proportional to slack.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space scaled by unusable gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.35 * gap;
    }

    // Compare against mean residual: placing into a bin with residual below mean
    // concentrates waste and keeps larger residuals available.
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 0.10 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is large
    // or the fit is very tight; otherwise penalize so open bins are preferred.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= 20.0 * fill_ratio;
        } else {
            score += 35.0 * (1.0 - fill_ratio);
        }
    }

    // Late in the stream, tighten packing (avoid leaving many small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins already: prefer consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // residual can host next item: reward proportionally
            score -= 0.4 * (next_item_size as f64) / (post_residual as f64);
        }
    }

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            (post_residual as f64) / (bin_capacity as f64)
        };
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 20.0 - 10.0 * poor_fit - pressure.min(8.0);
    }

    // Prefer filling bins with small residual relative to mean residual across bins
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Time-horizon modulation: early in stream, be conservative (pack tight);
    // late in stream, prefer closing out bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * t * tightness;

    // Slight penalty for item barely fitting (fragmentation risk)
    if item_size as f64 > 0.85 * bin_residual as f64 && bin_residual < bin_capacity {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer minimal post residual (tight fit), non-linearly amplified.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Penalize wasting a large residual on a small item (dead-space coupling).
    let waste = pr / cap;
    score += 18.0 * waste * waste * (it / cap);

    // Smooth progress coupling: late in the stream, tightness matters more.
    score -= 10.0 * (1.0 - progress) * (pr / cap);
    score += 8.0 * progress * (pr / cap) * (pr / cap);

    // Lookahead: reward leaving room exactly matching the next item.
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let match_bonus = 1.0 - ((pr - nx).abs() / cap);
        score -= 6.0 * match_bonus.max(0.0) * (1.0 - progress * 0.5);
        // Penalize post residual that is unusable for the next item.
        if pr < nx {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that deviate smoothly.
    score += 0.15 * (pr - mean_residual).abs() / cap;

    // New-bin candidate guard: empty bin keeps its naturally high post residual,
    // but allow it to win when the stream is early and fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it's small-but-nonzero
    // (unusable by typical items). Classify via modulo classes and division thresholds.
    let pr = post_residual;
    if pr > 0 {
        // Small dead-space pockets (1..=9) are nearly unusable: heavy penalty.
        if pr <= 9 {
            score += 40.0 + (10 - pr) as f64 * 3.0;
        }
        // Harmonic classes by divisibility: residuals divisible by 10 or 25 pair
        // well with future items; odd/prime-ish residuals are less reusable.
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else if pr % 2 == 1 {
            score += 4.0;
        }
        // Integer-division thresholds: which size classes can still fit.
        let fits_10 = pr / 10; // how many minimum-size items fit
        if fits_10 == 0 {
            score += 25.0; // residual < 10: total dead space
        } else if fits_10 == 1 {
            score += 8.0; // only tiny items fit
        } else if fits_10 >= 5 {
            score -= 10.0; // half-empty bin stays flexible
        }
        // Fractional capacity classes: post_residual relative to capacity quarters.
        let quarter = cap / 4.0;
        if (pr as f64) < quarter {
            score += 6.0;
        } else if (pr as f64) > 2.0 * quarter {
            score -= 5.0;
        }
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - (slack as f64).min(20.0) * 0.2;
            if slack <= 9 {
                score -= 8.0; // near-exact chain fit
            }
        } else {
            score += 5.0; // next item can't use this residual
        }
        // Modulo harmony between item and next item sizes.
        if item_size % 10 == 0 && next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (mean_residual / cap).min(1.0);
        // Penalize new bins when existing bins are fairly empty; discount late in stream.
        score += 55.0 - 35.0 * crowd - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Mild pressure to consolidate into emptier bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins
    // unless the fit is good (post_residual already encodes fit quality).
    score += (open_bins_count as f64) * 0.5;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Mean residual coupling: avoid bins far below mean residual when mean is tight.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: residual == capacity. Make it attractive only when
    // the item is large (would leave big gap in existing bins anyway).
    if bin_residual == bin_capacity {
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        // But if a decent fit exists elsewhere, keep new bin less attractive.
        if fitting_bins_count > 1 && post_residual < 15 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can follow: reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space that next item cannot use
            let dead = (next_item_size - post_residual) as f64;
            score += 1.5 * dead;
        }
    }

    // Penalize residuals that are too small to ever fit typical items (1..100 min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: should only win when fit is truly bad.
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred
        score += 300.0;
        // if item barely fits nothing else, opening a new bin is fine
        if fitting_bins_count <= 1 {
            score -= 250.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * (1.0 - progress);
    }

    // Slight preference for well-filled bins overall
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_residual as f64);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            score -= 6.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more when we leave lots stranded.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current bin
    // is very full or the fit is poor everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tight = 1.0 - mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins are mostly full and few bins fit the item.
        score = 100.0
            - 40.0 * mean_tight
            - 10.0 * (fitting_bins_count as f64).recip()
            - 20.0 * progress
            - (item_size as f64 / bin_capacity as f64) * 15.0;
        if post_residual > 0 && post_residual < 10 {
            score += 5.0;
        }
    }

    // Spread pressure: when many bins are open, consolidate to avoid fragmentation.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild time-dependence: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (dead space is less recoverable).
    let tightness = (norm_pr * norm_pr) * (1.0 + 2.0 * progress) * 40.0;
    score += tightness;

    // Reward near-perfect fits more aggressively as stream progresses.
    let perfect_bonus = (1.0 - norm_pr).powi(4) * (20.0 + 30.0 * progress);
    score -= perfect_bonus;

    // Lookahead coupling: if the next item fits the post-residual well,
    // reward this placement (chaining), scaled by remaining stream.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain_fit = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 15.0 * chain_fit * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize, more so mid/late stream.
        score += 8.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure against spreading across many open bins.
    score += (open_bins_count as f64).ln() * 1.5;

    // Penalize residuals that are awkwardly small (dead space) but not zero.
    if pr > 0 && pr < 10.0 {
        score += 10.0 * (10.0 - pr) / 10.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by small
    // class sizes (10/20/25/50) are more reusable by future items.
    let classes: [u32; 4] = [10, 20, 25, 50];
    let mut class_bonus = 0.0;
    for (i, &c) in classes.iter().enumerate() {
        if post_residual % c == 0 && post_residual > 0 {
            class_bonus += match i { 0 => 6.0, 1 => 4.0, 2 => 3.0, _ => 8.0 };
        }
    }
    score -= class_bonus;

    // Dead space penalty: tiny unusable leftovers (1..=9) are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let chain = post_residual - next_item_size;
            if chain % 10 == 0 {
                score -= 10.0;
            }
            score -= 5.0;
        } else {
            // next item won't fit here at all; mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // give poor fits. Penalize new bin mildly, more when good fits exist.
    if bin_residual == bin_capacity {
        score += 8.0 + (fitting_bins_count as f64) * 4.0;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins when mean residual is high (fragmentation risk).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Reward filling bins deeply as stream progresses.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item are "dead". Penalize them nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable gap of <10
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else if post_residual < 20 {
        score += 25.0; // likely dead space under unknown distribution
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this placement would leave a large, useful residual anyway, or when
    // existing bins are all nearly full (high mean fill).
    if bin_residual == bin_capacity {
        // New bin baseline: item leaves residual = capacity - item_size.
        let new_res = (bin_capacity - item_size) as f64;
        // Penalize new bins more as open bins grow (unless item is huge).
        let huge = item_size as f64 / bin_capacity as f64 > 0.7;
        score += if huge { -10.0 } else { 20.0 + open_bins_count as f64 * 2.0 };
        // A fresh bin with small residual (big item) is fine; large residual
        // from a small item wastes a bin unless nothing fits elsewhere.
        if new_res < 30.0 {
            score -= 25.0;
        }
        let _ = mean_residual; // mean fill implicitly drives via open_bins_count
    } else {
        // Existing bin: reward bins whose residual is close to item size.
        let slack = (bin_residual - item_size) as f64;
        score += 0.15 * slack;
        // If next item fits exactly in the post residual, reward strongly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_tight / bin_capacity as f64);
        }
        // If next item won't fit here but would fit elsewhere, slight penalty
        // for leaving a tempting-but-blocked residual.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if lookahead_gap == 0 {
            // Perfect chain: this bin will be exactly completed by the next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - lookahead_gap as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; the post_residual becomes dead space.
            score += 10.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(40.0);
        }
    }

    // Penalize small unusable post_residual (dead space), unless it's zero.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when it enables a tight future fit
    // (i.e., placing here leaves exactly room for the next item).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 20.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        }
        if fitting_bins_count <= 1 {
            // No good alternative exists; opening a new bin is reasonable.
            score -= 25.0;
        }
    }

    // Mild bias toward fuller bins relative to the mean residual.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Early in the stream, be more open to starting new bins (better long-run packing).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a gap; mild reward scaled by leftover quality.
            let leftover = post_residual - next_item_size;
            score -= 10.0 * (leftover as f64 / bin_capacity as f64);
        } else {
            // Next item would not fit here; slight penalty for wasting tight space.
            score += 3.0;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, new bins are cheaper (fewer future consolidation needs).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor) with
    // a non-linear coupling to global mean residual.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;
    score -= 0.05 * (mean_residual - bin_residual as f64).abs();

    // Slight preference to fill bins with more siblings open (consolidation).
    score -= 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nx = next_item_size as f64;
    let fits = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer small post-residual, with non-linear tightening
    let mut score = pr * (1.0 + 0.35 * progress * (pr / cap));

    // Quadratic penalty for mid-range waste (dead space that is hard to fill)
    let waste = pr / cap;
    score += 8.0 * waste * (1.0 - waste) * (1.0 - progress);

    // Reward tight fits strongly (near-zero post residual)
    let tight = (1.0 - pr / cap).max(0.0);
    score -= 12.0 * tight * tight * it / cap;

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fits - 1.0).ln().max(0.0);
    }

    // Lookahead coupling: reward if next item fits post residual smoothly
    if nx > 0.0 {
        let gap = (pr - nx).abs();
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score += 0.15 * gap / cap;
        score -= 6.0 * fit_next * (nx / cap) * (1.0 - gap / cap);
        // Penalize leaving a residual just barely too small for next item
        if pr < nx && pr > 0.0 {
            score += 5.0 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // New-bin candidate handling: residual == capacity means empty bin
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Penalize opening a new bin mildly; stronger early, weaker when
        // open bins are crowded (low mean residual) or item is large
        let crowd = mean_residual / cap;
        score = cap * (1.0 - 0.5 * progress)
            - 10.0 * (1.0 - crowd)
            - 8.0 * (it / cap) * (1.0 - it / cap)
            + 6.0 * fits;
        if nx > 0.0 && nx <= cap {
            score -= 3.0 * (nx / cap);
        }
    }

    // Mild dispersion penalty: prefer bins deviating from mean residual
    // in the direction of filling (below-mean residual = fuller bin)
    score += 0.05 * (pr as f64 - mean_residual);

    // Smooth stream-progress coupling: late stream favors consolidation
    score -= 4.0 * progress * (1.0 - waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    // into capacity fractions. Small leftovers in tight classes are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class thresholds: post_residual <= 10 -> near-perfect fit (heavily reward)
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 18.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        // Large leftover: penalize dead space, worse for bigger leftovers
        score += (pr / cap) * 12.0;
    }

    // Modulo arithmetic on post_residual: leftovers matching common item-size
    // harmonic classes (multiples of 10, 20, 25, 50) are more reusable.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 {
            score -= 6.0;
            if pr_u % 20 == 0 { score -= 3.0; }
            if pr_u % 50 == 0 { score -= 3.0; }
        }
        if pr_u % 25 == 0 { score -= 3.0; }
        // Odd, awkward leftovers are less reusable
        if pr_u % 2 == 1 && pr_u < 30 {
            score += 4.0;
        }
    }

    // Lookahead: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: excellent chaining, reward proportionally
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / cap);
            // Exact fill is the best outcome
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: leftover may become dead space
            score += 6.0;
            // If leftover is small anyway, it's still a decent bin to sacrifice
            if post_residual <= 15 {
                score -= 8.0;
            }
        }
    } else {
        // Last item: just minimize leftover
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): it should only win when no open bin fits
    // well. Penalize opening a new bin unless current bin's fit is terrible.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 45.0;
        // If item leaves a huge unusable remainder in any bin, new bin is OK
        if post_residual < 15 || next_item_size == 0 {
            score -= 20.0;
        }
        // Prefer opening new bins early in the stream (more future use)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // Few fitting bins makes opening a new bin more attractive
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Tight-fit bonus: item filling most of the bin is good regardless
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 10.0;

    // Mean residual coupling: when open bins are generally full (low mean
    // residual), be more generous rewarding good fits here.
    if mean_residual < 20.0 {
        score -= 8.0;
    } else if mean_residual > 60.0 {
        // Lots of slack spread across bins: avoid fragmenting further
        score += 5.0 * (mean_residual - 60.0) / 40.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never hold the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tight = (bin_residual - item_size) as f64;
    score += (tight * tight) / (bin_capacity as f64 * 4.0);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, avoid spreading; with few, allow.
    score += (open_bins_count as f64) * 0.6;

    // New-bin candidate handling: only attractive when it enables a good future pairing.
    if bin_residual == bin_capacity {
        score += 30.0; // default penalty: prefer existing bins
        if next_item_size > 0 && next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            if pair_waste < 15 {
                score -= 45.0; // opening a bin that fits item + next item tightly is great
            }
        }
        // Late in stream, opening new bins is rarely worth it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    } else {
        // Lookahead: penalize leaving a gap that neither helps nor fits the next item.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 12.0;
        }
    }

    // Mild alignment with mean residual: prefer bins below average residual (loose bins).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can fit next item but with slack: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }

    // Dead space: post residual too small for next item and below typical min item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Waste is likely dead; penalize proportionally.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: this is a crowded field; prefer tightest fits via base post_residual,
    // but add slight penalty to discourage spreading across too many open bins.
    if fitting_bins_count > 2 {
        score += 2.0;
    }

    // Relative to mean residual: bins with residual above mean are "loose"; prefer filling them.
    if (bin_residual as f64) > mean_residual + 1.0 {
        score -= 3.0;
    } else if (bin_residual as f64) < mean_residual - 1.0 {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        let mut penalty = 45.0;
        // If next item is large and current residuals are all small, opening may be wise.
        if next_item_size > 0 {
            let avg_post = mean_residual - item_size as f64;
            if avg_post < next_item_size as f64 && mean_residual < item_size as f64 + next_item_size as f64 {
                penalty -= 30.0;
            }
        }
        // Fewer open bins => cheaper to open early in stream.
        penalty -= 2.0 * (open_bins_count as f64).min(10.0);
        score += penalty.max(5.0);
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: reward bins that can also accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Global residual coupling: prefer bins tighter than the mean.
    score += 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only open a new bin when it is clearly better.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 10.0
            - 2.0 * fitting_bins_count as f64
            - 0.5 * item_size as f64
            - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 15.0;
        }
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Late-stream consolidation pressure.
    score -= 5.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Base: tightness of fit, non-linearly scaled
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Reward near-perfect fits superlinearly
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0 + 55.0 * (1.0 - progress) * (1.0 - progress);
        score += new_bin_penalty;
        // If next item could use the fresh bin's full space, soften penalty
        if next_item_size as f64 > 0.5 * cap {
            score -= 15.0;
        }
    } else {
        // Lookahead: reward leaving room compatible with the next item
        if next_item_size > 0 {
            let gap = post as f64 - next_item_size as f64;
            if gap >= 0.0 {
                // next item still fits here afterwards: good
                score -= 8.0 * (1.0 - gap / cap);
            } else {
                // dead space relative to next item: penalize proportionally
                score += 6.0 * (-gap / cap);
            }
        }
        // Penalize fragmenting bins far above mean residual (waste)
        let waste = (post - mean_residual).abs();
        score += 0.15 * waste * (0.5 + progress);
        // Mild preference for bins with larger residuals when many bins open
        score -= 0.05 * resid * (open_bins_count as f64).ln().max(0.0) / (1.0 + progress);
    }

    // Late-stream urgency: consolidate into existing bins
    score *= 1.0 + 0.3 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base preference: minimize post_residual (tight fit).
    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are worth more than dead space.
    let pr = post_residual;
    let usable = (pr == 0)
        || (pr % 10 == 0)
        || (pr % 20 == 0 && pr <= 40)
        || (pr % 25 == 0 && pr <= 50)
        || (pr % 30 == 0 && pr <= 60);
    if usable {
        score -= 6.0;
    } else {
        // dead-space penalty grows for awkward leftovers (small odd gaps)
        if pr < 10 {
            score += 4.0 * (10.0 - post) / 10.0;
        }
    }

    // Perfect fit is golden.
    if pr == 0 {
        score -= 25.0;
    }

    // Reward very tight fits (leftover below smallest item).
    if pr > 0 && pr < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item exactly matches the post_residual,
    // this bin is a perfect setup for the future.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if next_item_size > pr {
            // next item can't use this bin's leftover; slight penalty if leftover is large
            if pr >= 30 {
                score += 3.0;
            }
        }
    } else {
        // Last item in stream: any fit is fine, prefer tightest.
        score -= 5.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when the item is large (poor fit
    // potential elsewhere) or many bins exist and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap_f;
        // default: new bin is mildly discouraged
        score += 15.0;
        // large items (>= 60% capacity) justify fresh bins
        if item_frac >= 0.6 {
            score -= 10.0 + 10.0 * (item_frac - 0.6);
        }
        // if existing bins are crowded (mean residual low), a new bin is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0;
        }
        // late in the stream, avoid proliferation of nearly-empty bins
        if open_bins_count > 4 && mean_residual > cap_f * 0.4 {
            score += 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        }
        // harmonic guard: small items early on should reuse bins
        if item_size <= 30 && progress < 0.5 {
            score += 12.0;
        }
    }

    // Slight preference to fill bins with more content already (lower residual).
    score += (bin_residual as f64) * 0.05;

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (low post residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last fitting bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling.
    score += 2.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Opening a new bin is costly when other bins can fit the item.
            score += 55.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // dead space that nothing typical can use.
    let post = post_residual as f64;

    // 2-step lookahead: reward bins where the NEXT item fits exactly well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Next item fits: reward proportionally to how snug the chain is.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 6.0 * snug;
            // Bonus if the pair leaves almost nothing (perfect 2-chain).
            if post_residual - next_item_size <= 2 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: mild penalty, scaled by how badly it misses.
            let miss = (next_item_size - post_residual as u32) as f64;
            score += 0.5 * (miss / bin_capacity as f64).min(1.0);
        }
    } else {
        // Last item in stream: minimize residual directly, nothing ahead to plan for.
        score -= 2.0;
    }

    // Dead-space penalty: residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10.0 - post) / 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter;
    // prefer filling tighter bins (small residual) — already implicit, but add
    // mild reward when this bin is much tighter than average.
    if post < mean_residual {
        score -= 1.5 * ((mean_residual - post) / bin_capacity as f64).min(1.0);
    } else {
        score += 1.0 * ((post - mean_residual) / bin_capacity as f64).min(1.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post / bin_capacity as f64);
        score -= 3.0 + 4.0 * tightness;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when many bins are already open and usable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is huge and would leave a bad residual anywhere, a fresh
        // bin is naturally fine — soften penalty for very large items.
        if item_size >= 80 {
            score -= 4.0;
        }
        // Lookahead: if next item is large too, a fresh bin can host the chain.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 5.0;
        }
    }

    // Prefer placing into already-open bins slightly more when many are open
    // (consolidation pressure).
    if bin_residual != bin_capacity {
        score -= 0.2 * (open_bins_count as f64).min(10.0);
    }

    // Small fit-ratio shaping: reward high fill ratio of this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 3.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> conservative, late stream -> greedy tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward last-chance bins strongly (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize dead space that the lookahead item cannot use
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > score {
            score += (next_item_size as f64 - score) * 0.6;
        } else {
            // post_residual can still host the next item: reward slightly
            score -= 3.0;
        }
    }

    // New-bin candidate handling: penalize opening a bin, but less for large items
    if bin_residual == bin_capacity {
        score += 18.0 - (item_size as f64 - 50.0) * 0.25;
        // If item barely fits anywhere (mean residual small), opening new bin is fine
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 12.0;
        }
        // Late in the stream, prefer closing out tight fits instead of new bins
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the item (perfect-ish fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Mild preference for bins with larger residual when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
