pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are reusable; penalize awkward classes.
    let post = post_residual as i64;
    let mut class_bonus = 0.0f64;
    if post > 0 {
        if post % 50 == 0 { class_bonus -= 14.0; }
        else if post % 25 == 0 { class_bonus -= 9.0; }
        else if post % 20 == 0 { class_bonus -= 7.0; }
        else if post % 10 == 0 { class_bonus -= 5.0; }
        else if post % 5 == 0 { class_bonus -= 2.0; }
        else { class_bonus += 6.0; } // awkward dead space class
    }

    // Tight fit reward: quadratic bonus for small post residual.
    score -= 40.0 / (1.0 + (post_residual as f64) * (post_residual as f64) / 50.0);

    // Lookahead: reward if next item fits into the post residual exactly or well.
    if next_item_size > 0 && (next_item_size as u64) <= post_residual as u64 {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // perfect chain fill
        } else {
            score -= 12.0 * (slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        score += 4.0; // next item won't fit here; slight penalty
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or this bin's residual would be truly unusable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_gap = (mean_residual - item_size as f64).max(0.0);
        // Opening a new bin is good when existing residuals are tight/dead
        // or the item is huge relative to typical residual.
        score = 25.0 + avg_gap * 0.6 - 15.0 * (1.0 - progress);
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // huge item into fresh bin leaves clean residual
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        // Harmonic: fresh bin residual = capacity, a perfect class
        if bin_capacity % 10 == 0 {
            score -= 3.0;
        }
    }

    // Mild pressure against leaving many nearly-empty bins around.
    score += (mean_residual - post_residual as f64) * 0.05;

    score += class_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // practically gaps < ~15 are hard to reuse) are strongly penalized.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 60.0 * (15.0 - post_residual as f64) / 15.0;
        } else if post_residual < 30 {
            score += 12.0 * (30.0 - post_residual as f64) / 15.0;
        }
    }

    // Reward very tight fits (post_residual near zero is good).
    if post_residual == 0 {
        score -= 40.0; // perfect fit: bin closed, no dead space
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening is more attractive when many bins are already open
        // (consolidation pressure) — reduce penalty slightly.
        score -= (open_bins_count as f64).min(20.0);
        // But if the next item would fit in the leftover, opening is bad.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score += 15.0;
        }
    }

    // Lookahead: if next item exactly fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bins pressure: mildly prefer filling already-open bins when many are open.
    score += (open_bins_count as f64).min(30.0) * 0.4;

    // Progress: late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight non-linearity
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // New-bin candidate: heavily penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0;
        // If this is the only fitting option, opening a new bin is fine
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    // 2-step lookahead: reward if next item exactly fills the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.35; // penalize leftover after hypothetical next placement
            if post_residual - next_item_size < 10 {
                score -= 8.0; // near-perfect chain fill bonus
            }
        } else {
            // next item can't fit in this bin after current placement
            score += (next_item_size - post_residual) as f64 * 0.12;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (already tighter than average)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 0.25;
    } else {
        score += (res - mean_residual).min(50.0) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Early stream: be more exploratory, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 3.0;
    }

    // Prefer bins with larger current residual slightly (keep small-residual bins for small items)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that becomes unusable: residuals below typical small item size (<=10)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize leaving a gap that is close-but-too-small.
            let gap = (post_residual as f64) - (next_item_size as f64);
            if gap > -15.0 && gap < 0.0 {
                score += 4.0;
            }
        }
        // If next item is large, prefer leaving big residuals in other bins; mildly prefer
        // filling this bin tightly now.
        if next_item_size >= 60 && post_residual < next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with below-mean residual (consolidate space usage).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline cost that rises with
    // open_bins_count, so we only open new bins when fits elsewhere are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 2.5 * (open_bins_count as f64) + 5.0 * (1.0 - progress);
    }

    // Mild preference for already-open bins as stream progresses (avoid bin proliferation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight-fit reward: quadratic bonus as post-residual approaches 0
    let tightness = 1.0 - (post / cap);
    score -= 24.0 * tightness * tightness * tightness;

    // Penalize awkward dead space: mid-range residuals that likely can't fit future items
    let dead_zone = (post / cap) * (1.0 - (post / cap));
    score += 18.0 * dead_zone * (1.0 + progress);

    // Stream progress coupling: later in stream, value tightness more, waste less
    score += progress * post * 0.35;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - post / cap);
    }

    // New-bin candidate: penalize opening a new bin, more so when good fitting bins exist
    if bin_residual == bin_capacity {
        let open_penalty = 20.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        score += open_penalty;
        // but allow new bin if item is large and residual spread suggests poor fits elsewhere
        if item > 0.7 * cap {
            score -= 12.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced use)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

