    let item_class = item_size % 10;
    let next_class = next_item_size % 10;

    // Perfect fit reward: post_residual in harmonic residue classes that are reusable
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 18.0; // leaves a class-0 chunk, highly reusable
    } else if post_residual <= 9 {
        score += 10.0; // tiny dead space is nearly unusable
    }

    // Integer-division thresholds on post_residual: quarters of capacity
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 8.0;
    } else if post_residual < quarter {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        // harmonic class match between next item and residual chunk
        if next_class == post_residual % 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize wasting the slot
        score += 4.0;
    }

    // Last-chance bin: strongly favor filling it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap - item_size as f64;
        if item_size >= half {
            score -= 12.0; // large items are fine to start a bin with
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        } else {
            // only open a new bin if existing fits are terrible (large post-residual waste)
            let avg_waste = mean_residual - item_size as f64;
            if avg_waste < 15.0 {
                score += 45.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 6.0;
    }

    // Prefer bins with residual close to item (tight fits)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 10.0;

    // Mild preference to use bins with larger residuals first (best-fit-like)
    if bin_residual < bin_capacity {
        score -= (bin_residual as f64 / cap) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps (1..15) are nearly unusable for future items
    if post_residual > 0 && post_residual < 15 {
