    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus relative to bin capacity
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large or nothing fits well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).powf(1.3);
        let poor_fit = post_residual as f64 > 60.0 && item_size < 50;
        if poor_fit || fitting_bins_count == 0 {
            score -= 20.0 + pressure * 0.5;
        } else {
            score += 35.0 + pressure * 0.3;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for next item: penalize proportionally
        score += (post_residual as f64) * 0.4;
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * fill_ratio;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

