    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bin is fine for big items or late stream; costly otherwise.
        score += 45.0 * pressure * (1.0 - item_frac) * (1.0 - 0.5 * late);
        // If next item is small and current item is small, opening new bin wastes capacity.
        if next_item_size > 0 && next_item_size < 30 && item_size < 30 {
            score += 15.0;
        }
    }

    // Slight penalty for leaving awkward dead space (small unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual that is too small to ever hold a typical item
    // (min size 1, but small slivers are still wasteful) gets penalized.
    if post_residual > 0 {
        let sliver = post_residual as f64 / bin_capacity as f64;
        if sliver < 0.10 {
            score += 12.0 * (0.10 - sliver) / 0.10;
        }
    } else {
        // Perfect fit: huge reward.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item would fit exactly in the post residual,
    // reward heavily; if the next item cannot fit in post residual but could fit
    // in the bin without this item, penalize lightly (blocking risk).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here after placement; small penalty scaled by
            // how much it overflows, but only if this bin was uniquely fitting.
            if fitting_bins_count <= 1 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: recognize empty bin by bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer open bins with decent fits; only open a new bin when the item
        // is large relative to capacity (poor fit everywhere) or few bins open.
        let size_frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 - 14.0 * size_frac + 6.0 * open_pressure - 5.0 * progress;
    } else {
        // Mild preference for bins with residual below the mean (consolidate space).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Small time-horizon modulation: late in the stream, be greedier about
    // minimizing residual (less future to amortize waste over).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: normalized post-residual (waste created by this placement)
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more (weight grows with progress).
    let tightness = (pr / cap).powi(2);
    score += (0.5 + 1.5 * progress) * tightness;

    // Reward near-perfect fits with a smooth cubic decay
    score -= 0.6 * (1.0 - pr / cap).powi(3);

    // Penalize bins whose residual is already far below the mean (bad state)
    score += 0.3 * ((mean_residual - bin_residual as f64) / cap).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // smooth reward proportional to how snugly the next item fits
            score -= 0.4 * (1.0 - (pr - nxt) / cap);
        } else {
            // penalize leaving a residual that just barely fails the next item
            score += 0.25 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * (open_bins_count as f64 / (1.0 + progress * 10.0)) / (1.0 + open_bins_count as f64);

    // New-bin candidate: empty bin has residual == capacity. It should only win
    // when no good fit exists; add a smooth barrier scaled by available alternatives.
    if bin_residual == bin_capacity {
        let barrier = 0.8 + 0.6 * (1.0 - progress);
        score += barrier;
        // But if the item is large relative to capacity, opening fresh is less bad
        score -= 0.3 * (item / cap).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands exactly on
    // "reusable" residue classes (multiples of 10, 20, 25, 50) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 6.0; }
        // Small dead space (< 10) is nearly unusable given min item size 10.
        if pr < 10 { score += 15.0 * (10 - pr) as f64 / 10.0; }
    }

    // Next-item coupling: reward if next item fits the post residual exactly or
    // leaves a good class again; penalize if next item cannot use leftover.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            if npr % 10 == 0 { score -= 6.0; }
            if npr < 10 { score += 5.0; }
        } else {
            score += 4.0; // leftover blocks the lookahead item
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / cap_f;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default is expensive; only attractive when many open
    // bins exist with large mean residual (fragmentation) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 18.0;
        if open_bins_count as f64 > mean_residual / 10.0 { open_penalty -= 6.0; }
        if mean_residual > cap_f * 0.6 { open_penalty -= 8.0; }
        if progress > 0.8 { open_penalty += 5.0; }
        score += open_penalty;
    }

    // Mild preference to spread across bins when many are open with slack.
    score += 0.02 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..100, be
    // conservative: treat gaps < 10 as unusable unless they can host the lookahead item).
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 20.0;
        } else {
            score -= 8.0 / (1.0 + slack * 0.1);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover can't host lookahead: mild penalty proportional to gap.
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto emptier bins
    // and discourage opening new ones; consolidate instead.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when it enables
        // a perfect or lookahead-perfect fit.
        score += 30.0 + 10.0 * pressure;
        if post_residual == 0 {
            score -= 70.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= 5.0 {
            score -= 25.0;
        }
        // Late in the stream, opening new bins is expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Prefer fuller bins when many bins are open (best-fit bias scales with pressure).
        score -= pressure * (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Slight preference for bins below mean residual (balance exploitation).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next fits, but penalize leftover slack after the chain
            score -= 100.0 - (post_residual - next_item_size) as f64;
        }
        // Penalize if next item is too big for post_residual but small enough that
        // this residual is likely dead space
        else if next_item_size > post_residual && post_residual < 10 {
            score += 50.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize creating tiny unusable residuals relative to mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.3 {
        score += 30.0;
    }

    // Mild penalty for opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    // Late in the stream: prefer tighter packing (smaller post residual weight slightly higher)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in the stream, prefer tighter consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Lookahead: reward leaving space that the next item can still use.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 8.0 * progress;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize proportionally.
        let waste = (post_residual as f64) / (next_item_size as f64);
        score += 6.0 * (1.0 - waste.min(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize creating tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Reward placements well below the mean residual (tight packing).
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate handling: fresh empty bin.
    if bin_residual == bin_capacity {
        // Large items benefit from a fresh bin; small items should reuse open bins.
        let size_frac = item_size as f64 / bin_capacity as f64;
        if size_frac > 0.6 {
            score -= 10.0 * (size_frac - 0.6) / 0.4;
        } else {
            score += 8.0 * (0.6 - size_frac) / 0.6;
        }
        // Early in the stream, allow opening bins more freely for future flexibility.
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: quadratic in normalized post-residual (favor tight fits).
    let x = pr / cap; // in [0,1]
    let mut score = 2.0 * x + 1.5 * x * x;

    // Smooth coupling with stream progress: late in the stream, waste is costlier.
    score += 2.0 * progress * x * x;

    // Coupling with mean residual: penalize bins whose residual deviates
    // (creates heterogeneous dead space); smooth cubic interaction.
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev + 0.4 * dev * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 3.0 + 2.0 * (1.0 - x);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64) / pr.max(1.0);
        score -= 1.2 * fit_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by leftover size.
        score += 0.5 * x;
    }

    // New-bin candidate: smooth penalty that decays as the fit here would be poor
    // anyway (large x) or late in the stream where consolidation pays off.
    if is_new_bin {
        let poor_fit_pressure = x * x; // if we'd open a bin anyway, residual is large
        score += 2.5 - 2.0 * poor_fit_pressure - 1.5 * progress;
        score += 0.3 * (open_bins_count as f64);
    } else {
        // Using an existing bin relieves bin count pressure.
        score -= 0.2 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Harmonic class logic on post_residual: dead space that cannot
    // fit the smallest plausible item is nearly useless.
    let min_item = 10u32.min(bin_capacity);
    if post_residual < min_item && post_residual > 0 {
        score += 50.0; // small dead space, but item fits exactly-ish, fine
    }

    // Penalize residual classes that are awkward: post_residual mod 10
    // small classes (1..3) are hard to fill; classes near 10 are good.
    let pr_class = post_residual % 10;
    if post_residual > 0 {
        score -= (10 - pr_class) as f64 * 2.0;
    }

    // Reward bins whose residual can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Extra reward if post_residual - next_item_size becomes tiny.
        let pr2 = post_residual - next_item_size;
        if pr2 <= 10 {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residual can't host next item: mild penalty scaled by gap.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when current bins
    // are poor fits (large item, tight residuals) or few bins open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 300.0;
        // Cheaper to open new bin early in the stream or when few bins open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 80.0;
        if open_bins_count < 3 {
            score -= 100.0;
        }
        // If mean residual is large, open bins have room; penalize new bin.
        score += mean_residual * 1.5;
        // If item is large relative to capacity, new bin is attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 120.0;
        // If next item also large, opening now gives flexibility.
        if next_item_size >= 50 {
            score -= 50.0;
        }
        // If no other bin fits (fitting_bins_count == 1 refers to this new bin),
        // opening is forced: reduce cost.
        if fitting_bins_count <= 1 {
            score -= 400.0;
        }
    } else {
        // Existing bin: slight preference for bins with less residual used badly.
        // Prefer fuller bins (smaller residual) beyond raw post_residual.
        score += (bin_residual as f64 / bin_capacity as f64) * 10.0;
        // If many bins fit the item, competition: prefer the tightest anyway
        // via post_residual; add small penalty to avoid scattering.
        if fitting_bins_count > 2 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (or the
    // lookahead item) are nearly worthless; penalize them hard.
    if post_residual < item_size.min(10) {
        score += 40.0; // completely dead gap
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 25.0; // gap likely unusable for the next item
    } else if post_residual < 10 {
        score += 30.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when
    // few are open, opening a new bin is cheap so don't overfill early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate (empty bin): only attractive when the current fit is
    // terrible (large dead space) — make it slightly worse than a decent fit
    // so it wins only via the dead-space penalties above.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.05;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
    }

    // Mild preference for tight fits relative to the fleet's mean residual.
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 25.0 * (-diff / 20.0).exp();
        } else {
            // Post residual too small for next item: dead space penalty.
            score += diff * 0.8;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Penalize small unusable post residuals (dead space) unless it fits next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    let mean_gap = mean_residual - bin_residual as f64;
    score += mean_gap * 0.3;

    // Discourage opening a new bin when a reasonable fit exists in open bins.
    if bin_residual == bin_capacity {
        score += 8.0;
        // New bin attractive only if no open bin fits well and next item is large.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight late-stream pressure to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how full this bin will be after placement (0..1).
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward high fill ratio, scaled by stream progress (tight packing matters more later).
    score -= fill * 40.0 * (0.5 + 0.5 * t);

    // Dead-space penalty: small post-residuals that can't fit typical items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits into the resulting residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 18.0;
            // Extra reward if next item fills this bin almost exactly after current placement.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here: penalize slightly, less if bin is nearly full anyway.
            score += 8.0 * (1.0 - fill);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many items remain relative to open bins.
        score += 70.0;
        // Slightly cheaper to open bins early in the stream (more future items to fill them).
        score -= 25.0 * (1.0 - t);
        // If open bins are already crowded on average, new bin is less painful.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    } else {
        // Mild preference for reusing already-open bins, scaled by how many are open.
        score -= 5.0;
        // Encourage draining bins when too many are open.
        if open_bins_count > 8 {
            score -= (open_bins_count as f64 - 8.0) * 1.5;
        }
    }

    // Small tie-breaker: prefer bins whose residual is closest to item size (snuggest fit).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let base = pr_norm.powf(1.0 + 1.5 * progress);

    // Penalize tight fits that create dead space, more so late in the stream.
    let dead = (1.0 - pr_norm).powi(2) * (0.5 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -2.0 - 2.0 * progress } else { 0.0 };

    // Lookahead: reward residual that can still fit the next item.
    let look = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -0.6 * (1.0 - (next_item_size as f64) / cap)
    } else if next_item_size > 0 {
        0.4 * (next_item_size as f64 / cap)
    } else {
        0.0
    };

    // Mild preference for consolidating into bins below mean residual.
    let mean_term = 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: neutral baseline slightly above good fits.
    let new_bin = if bin_residual == bin_capacity {
        1.0 + 1.5 * (1.0 - progress)
    } else {
        0.0
    };

    let score = base + dead + last_chance + look + mean_term + new_bin;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let cls = pr % 10; // harmonic class on tens digit
    let div = pr / 10; // integer division threshold

    // Reward small post residual (tight fit) non-linearly.
    score -= 30.0 * (1.0 - (post_residual as f64 / cap)).powi(4);

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // pure dead space
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Harmonic class bonus: post_residual divisible by common item sizes (10, 20, 25, 50)
    // leaves space reusable by future harmonic items.
    let harmonic_bonus: f64 = if pr == 0 {
        25.0
    } else if pr % 50 == 0 {
        15.0
    } else if pr % 25 == 0 {
        10.0
    } else if pr % 20 == 0 {
        8.0
    } else if pr % 10 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size as i64 == pr {
            score -= 35.0;
        } else if (pr as u32) >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual as i64 - item_size as i64) < 10
            || (next_item_size > 0 && (bin_residual as i64 - item_size as i64) < next_item_size as i64);
        if poor_fit {
            score -= 20.0 + 15.0 * (1.0 - progress);
        } else {
            // Prefer filling existing bins early; allow new bins when many are open late.
            score += 10.0 + 5.0 * (open_bins_count as f64).sqrt() - 10.0 * progress;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward smaller values (concentrate small residuals).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Slight preference for bins with larger residual when item is large.
    if item_size > bin_capacity / 2 {
        score += 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Mild class penalty for awkward division thresholds.
    if div > 0 && cls > 5 && cls < 9 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward using a bin whose residual matches the item well (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> encourage reuse.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: penalize bins far from the mean residual (outliers create dead space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: neutral-ish default; only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Penalize gaps that cannot fit the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Slack left over after next item would fit; mild penalty for excess slack
            score += ((post_residual - next_item_size) as f64) * 0.3;
        }
    }

    // Reward tight fits relative to bin residual (small post_residual is good)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize bins far from the mean residual (avoid fragmenting many bins evenly)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, prefer closing out bins (reduce waste)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // New-bin candidate: penalize opening a new bin unless current residuals are all tiny
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0; // open bins are nearly full -> new bin is justified
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins (small bin_residual) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: late in the stream, be more conservative about opening new bins
    // is handled by the new-bin candidate's score; here, penalize spreading load early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: base penalty grows with number of open bins and progress.
        score += 10.0 + 8.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Slight penalty for very fragmented state (many open bins with high mean residual).
    if open_bins_count > 4 && mean_residual > 40.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Early on, prefer tight fills less aggressively; late, dead space is costly.
    let mut score = x * x * (1.0 + progress) * cap;

    // Smooth cubic coupling: very small residuals are valuable (near-perfect fit),
    // reward them progressively more as the stream advances.
    score -= (1.0 - x).powi(3) * (0.5 + progress) * cap * 0.35;

    // Interaction with mean residual: placing into a bin whose residual is below
    // average concentrates space use; penalize bins far above the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (0.5 + progress) * 10.0;

    // Lookahead coupling (smooth): if the next item fits the post residual,
    // reward this placement proportionally to how well it matches.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (nx - x).abs();
        score -= (1.0 - gap.min(1.0)) * (1.0 + progress) * 8.0;
    }

    // Last-chance bonus (smooth via inverse count): when this is the only fitting
    // bin, strongly favor using it to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        score += 2.0 / fitting_bins_count as f64;
    }

    // Mild penalty for proliferation of open bins early in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 1.5;

    // New-bin candidate: neutral-ish baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + x * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: which "waste class" does the leftover fall in?
    // Class boundaries at multiples of 10 (typical item granularity).
    let class = post_residual / 10;
    let class_center = (class * 10 + 5) as f64;

    // Reward being near the bottom of a class (tight fit inside its class),
    // penalize sitting just below the next boundary (dead space a small item could have used).
    let within = post - class_center;
    score += 0.35 * within;

    // Perfect fit classes: multiples of 10 are highly reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 12.0; // exact closure is ideal
    }

    // Dead zone: leftover that no plausible item (>=1) can pair with next.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 4.0; // cannot host the next item
        } else {
            // Reward residuals that can host next item, scaled by snugness.
            let snug = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - snug / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): only attractive when current fit is bad
    // or mean residual across bins is high (fragmentation).
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        if post_residual < 20.0 || frag > 0.5 {
            score -= 8.0 * frag;
        } else {
            score += 15.0; // prefer filling existing bins
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (post_residual % 5 == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins with small post_residual (tight fit).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>=1, but
    // practically >=10) can use are pure waste. Penalize tiny unusable gaps hard.
    let pr = post_residual;
    if pr > 0 {
        if pr < 10 {
            // Dead space: nothing in [10,80] can ever fill it.
            score += 40.0 + (10 - pr) as f64 * 8.0;
        } else if pr < 20 {
            // Marginal zone: only very small items could use it.
            score += 12.0 + (20 - pr) as f64 * 2.0;
        } else if pr < 30 {
            score += 4.0;
        }
    }

    // Perfect fill is ideal.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // next item creates another near-perfect fit here
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: residual becomes a waiting gap.
        if post_residual < 30 {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 10 {
            // Dead space anyway; a new bin may be better — soften the penalty.
            score += 0.0;
        } else {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin should win only when the fit in
    // existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slight preference for keeping bins tight.
        score = 55.0 + (bin_capacity - item_size) as f64 * 0.2;
        // If next item also fits well in the fresh bin, mildly encourage opening.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Few open bins -> less pressure to consolidate; opening is cheaper.
        score -= open_bins_count as f64 * 0.5;
    } else {
        // Open-bin count pressure: with many open bins, favor consolidating
        // into existing bins (subtract to prefer them over new bins).
        score -= open_bins_count as f64 * 0.3;
        // If mean residual is high, bins are loose; prefer the tightest fit more.
        score += (mean_residual - post_residual as f64).max(0.0) * 0.05;
    }

    // Late in the stream, avoid opening new bins (fewer future items to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: bin residual after placement exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still accommodate the next item: mildly good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Dead space: post-residual too small for the next item (and likely for future items).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 5.0;
        // If next item would perfectly fill this new bin later, slightly favor it.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0;
        }
        // Many open bins with large mean residual: avoid opening yet another bin.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Early in stream: be conservative, keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize large dead space after placement, non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // tiny leftover is fine (nearly perfect fit)
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0;
    } else if post_residual >= 25 {
        score += 5.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid wasting an open bin's space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, this is a
    // great placement (chains future packing); reward it.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 8.0;
            // Extra reward for exact chain fit.
            let gap = post_residual as i64 - next_item_size as i64;
            if gap < 10 {
                score -= 4.0;
            }
        } else if next_item_size as f64 > post_residual as f64 * 1.5 {
            // Next item is much larger than what's left here; leaving a big
            // unusable remainder is bad, penalize proportionally.
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // could already fit the item; make the empty bin less attractive.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (fitting_bins_count as f64).sqrt();
        // But if the stream is early and few bins are open, allow expansion
        // to keep flexibility for future large items.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.25 && open_bins_count < 4 {
            score -= 12.0;
        }
        // If mean residual across open bins is small (bins nearly full),
        // opening a fresh bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    // Global pressure: when many open bins exist with high mean residual,
    // prefer consolidating into existing bins (avoid fragmentation).
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Mild time-horizon effect: late in the stream, prioritize closing bins
    // out (tight fits) even more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit preferred (small post_residual wins), scaled by progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth non-linear coupling: penalize residual that is neither tight nor reusable
    let norm_pr = pr / cap;
    let dead_zone = 4.0 * norm_pr * (1.0 - norm_pr); // peaks at half-full residual
    score += 18.0 * dead_zone * (0.5 + 0.5 * progress);

    // Reward if next item can fit into post_residual (smooth lookahead coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - (pr - nx) / cap;
            score -= 10.0 * snug * (nx / cap);
        } else {
            let gap = (nx - pr) / cap;
            score += 6.0 * gap * gap; // next item won't fit: mild penalty for wasteful fit
        }
    }

    // Last chance: strongly favor using this bin before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Encourage consolidation: deviation from mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // Mild preference for fewer open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize so it only wins when all fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantization
    // Residuals in small classes (1..=10) are near-perfect; large ones waste.
    let harmonic_class = post_residual / 10; // 0..=9 class index
    score += harmonic_class as f64 * 3.0;

    // Perfect fit reward: post_residual exactly 0 is ideal
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can follow: reward proportionally to how well it nests
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nest;
            // Harmonic bonus if next item exactly fills the leftover
            if next_item_size == post_residual {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize wasted potential slightly,
            // scaled by how much dead space is stranded
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * stranded * stranded;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 55.0;
        // Reduce penalty late in the stream or when many bins are open
        // (spreading load can help), and when the item is large
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        if open_bins_count > 3 {
            score -= 5.0;
        }
        if item_size >= 60 {
            score -= 10.0;
        }
        // If next item is huge, a fresh bin preserves flexibility
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Modulo-class coupling on item vs residual: items leaving residuals
    // divisible by common item sizes (10,20,25) keep space reusable
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Mild pressure toward consolidating into bins below mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size)
    // are the worst outcome. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Non-linear penalty on wasted residual relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 40.0 / (1.0 + tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 60.0 + 8.0 * open_bins_count as f64;
        // Opening a new bin is acceptable if the item is large and would leave
        // a bad gap elsewhere, or if the next item is large and needs fresh space.
        if item_size >= 70 {
            score -= 70.0;
        }
        if next_item_size > 0 && next_item_size >= 80 {
            score -= 40.0;
        }
    }

    // Lookahead coupling: if the post_residual can exactly host the next item,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // If next item fits comfortably in post_residual, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 30.0;
    }
    // Penalize leaving residual that neither fits next item nor is useful.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0;
    }

    // Early in the stream, allow more bins; late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - waste_ratio);

    // Prefer bins with residual below the mean residual (more filled bins) for balance.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item -> strong reward.
        if (post_residual as u32) == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item can't fit here; penalize proportionally to leftover waste.
            score += 4.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins far below mean residual are
    // already "used up"; prefer them to keep fatter bins flexible.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 3.0 * dev / bin_capacity as f64;
    } else {
        score += 2.0 * (-dev) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 8.0 + pressure;
        // Allow new bin only if no open bin fits well (large post waste elsewhere).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild late-stream conservatism: squeeze more out of existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for over-constraining.
            score += 5.0;
        }
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // the current fit is poor relative to global residual state.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 45.0;
        // If existing bins are nearly full (small mean residual), a new bin is fine.
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        // If this item is huge relative to residual capacity, new bin is justified.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 25.0;
        }
        // Few open bins early on: cheaper to open another.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    } else {
        // Slight preference for filling bins that are already mostly full.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fullness;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = item_size as f64 / cap;
    let res_frac = bin_residual as f64 / cap;
    let post_frac = pr / cap;

    // Base: prefer small post residual, smoothly scaled by stream progress.
    let mut score = pr * (1.0 + 0.6 * progress);

    // Smooth non-linear reward for tight fit: (1 - post_frac)^2 coupling with item size.
    score -= 12.0 * (1.0 - post_frac) * (1.0 - post_frac) * (0.5 + fit_frac);

    // Penalize creating dead space that cannot fit the lookahead item (smooth hinge).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack_deficit = (nx - pr).max(0.0) / cap;
        score += 9.0 * slack_deficit * slack_deficit;
        // Reward when post residual still accommodates the next item.
        if pr >= nx {
            score -= 4.0 * (pr - nx) / cap * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 * (0.4 + 0.6 * progress);
    }

    // Penalize the brand-new empty bin candidate, more so when good fits exist.
    if bin_residual == bin_capacity {
        let penalty = 6.0 + 10.0 * (1.0 - fit_frac) * (1.0 - fit_frac);
        score += penalty * (0.5 + 0.5 * progress);
    }

    // Mild coupling with mean residual: prefer bins deviating below mean (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild congestion pressure: many open bins -> favor consolidating into existing bins.
    score -= 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_frac);

    // Smooth polynomial coupling term between residual fraction and progress.
    score += 5.0 * res_frac * res_frac * progress * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls in a
    // "usable" class (multiples of 10, or large enough for typical items)
    // should be favored. Penalize dead-space classes.
    let post_class = post_residual / 10;
    let next_class = next_item_size / 10;

    // Reward if next item fits exactly into post residual (perfect chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.05;
    }

    // Penalize residuals that are too small to ever hold another item
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Harmonic class matching: leftover class equal to next item's class
    // suggests modular alignment (e.g., residual 30, next 30 -> perfect)
    if next_item_size > 0 && post_class == next_class && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Integer-division threshold: post_residual in [50, 100) is still
    // half-empty -> mildly good; in [1, 20) is nearly dead -> bad.
    if post_residual >= 50 {
        score -= 1.5;
    } else if post_residual < 20 && post_residual >= 10 {
        score += 2.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open
    // bins are all poor fits (handled above) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 - 4.0 * progress;
        // If next item is large and this bin would be fresh, slight bonus
        if next_item_size >= 50 {
            score -= 1.0;
        }
    }

    // Prefer bins tighter than the average residual (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    // Modulo coupling: penalize post residuals that waste capacity in
    // awkward classes (not divisible by 5)
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item are pure waste.
    // Items in [1,100]; treat residual gaps < 12 as unusable dead space.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: the fuller the bin becomes, the better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, mildly
    // prefer reusing existing bins over opening new ones (new-bin candidate gets
    // a natural penalty via this term too).
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current item leaves a very tight fit
        // in every other bin (approximate via high post_residual being bad anyway).
        score += 8.0 + 3.0 * pressure;
        // But if next item is large and this item would leave a tiny gap elsewhere,
        // opening fresh can be right; soften when item is large.
        score -= 0.05 * item_size as f64;
    } else {
        score -= 2.0 / pressure;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would NOT fit but would fit the full empty bin, mildly penalize
    // consuming a bin that could serve the next item well.
    if next_item_size > post_residual && next_item_size > bin_residual - post_residual.min(bin_residual) && bin_residual == bin_capacity {
        score -= 4.0;
    }

    // Stream progression: late in the stream, waste matters less than bin count;
    // tighten dead-space penalty early, relax later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 12 {
        score -= 25.0 * progress;
    }

    // Mean residual context: if this bin's post-residual is far below the mean,
    // we are compacting well; reward it.
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mildly reward
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.9;
    }

    // Penalize leaving tiny unusable slivers (below minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // When many bins fit the item, prefer the tightest (lowest residual) implicitly;
    // add mild penalty proportional to excess residual over mean to spread load sensibly
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Early in the stream, encourage filling existing bins rather than spawning many
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early on, less when stream is nearly done
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // --- Tightness reward: strongly favor small post_residual ---
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // --- Lookahead coupling: if the next item fits into post_residual, this is great ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space risk: post_residual too small for next item
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste_frac * waste_frac;
    }

    // --- Last-chance bonus: if this is the only bin that fits, use it before opening a new one ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // --- Penalize opening new bins when open bins can fit reasonably well ---
    if is_new_bin {
        // New bin is attractive only if existing residuals are fragmented / high
        let mean_res_norm = mean_residual / bin_capacity as f64;
        // If mean residual is small, open bins are nearly full -> new bin is fine
        score += 20.0 * (1.0 - mean_res_norm);
        // Early in the stream, opening bins is cheap; late, prefer consolidation
        score += 15.0 * (1.0 - progress);
        // Many open bins -> discourage adding more
        score += 1.5 * open_bins_count as f64;
        // If next item is large and would need a fresh bin anyway, opening now is neutral
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    } else {
        // Reward placing into bins whose residual is close to the item (perfect fit)
        let fit_gap = (bin_residual - item_size) as f64;
        score -= 3.0 * (1.0 - fit_gap / bin_capacity as f64);
        // Slight preference for bins with larger residual (use the emptiest useful bin)
        score -= 0.05 * bin_residual as f64;
    }

    // --- Global fragmentation coupling ---
    // High mean residual with many bins suggests fragmentation; prefer tight placements
    let frag = mean_residual * (open_bins_count as f64).ln();
    score += 0.02 * frag;

    // --- Time-horizon modulation: as stream ends, squeeze harder into existing bins ---
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: tight fits favored more as stream progresses
    let tight = (1.0 - norm_post).powi(3);
    score -= tight * (30.0 + 40.0 * progress);

    // Penalize large dead space superlinearly
    score += norm_post * norm_post * 25.0;

    // Last-chance bonus, amplified with progress
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - (pr - n) / cap).abs() * (0.5 + progress);
        } else {
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Prefer fuller bins relative to mean residual, smoothly coupled to progress
    score -= (mean_residual - pr) * 0.15 * (0.5 + progress);

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny post_residual is excellent (near-perfect fit).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    }

    // Harmonic class of post_residual modulo 10: residuals in the "dead zone"
    // (1..10 mod 10 classes that no small item can efficiently fill) are bad.
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,          // exact decade: reusable by 10-multiples
        1 | 2 | 3 => score += 18.0,  // nearly dead space
        4 | 5 | 6 => score += 6.0,   // mediocre
        _ => {}                       // 7..9: fillable by mid items
    }

    // Lookahead coupling: if the next item fits the post_residual exactly,
    // strongly reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= (20.0 - waste as f64).max(0.0);
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when all open
    // fits would leave large unusable residue or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: prefer it unless it would waste heavily.
            score += 10.0;
        } else {
            score += 40.0 + open_bins_count as f64 * 2.0;
        }
        if next_item_size > 0 && next_item_size >= 40 && next_item_size <= 60 {
            score -= 15.0; // fresh bin useful for upcoming mid-size item
        }
    } else {
        // Prefer fuller bins: reward high fill fraction via integer division threshold.
        let fill_class = (bin_capacity - bin_residual) / 25; // 0..4 quartiles
        score -= fill_class as f64 * 8.0;

        // Late in the stream, consolidate harder.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;

        // Slightly prefer bins below mean residual (balance spread).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item can use are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable micro-gap below minimum item size
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap too small for the known next item
        } else if post_residual < 20 {
            score += 12.0; // risky small gap under unknown distribution
        } else {
            score -= 8.0; // gap large enough to be reusable
        }
    } else {
        score -= 30.0; // perfect fill
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // Pressure from number of open bins: discourage spreading across many bins.
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual deviates favorably from the mean (fill laggards).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current fit is bad and stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_fit = (post_residual as f64) > 40.0 && fitting_bins_count > 1;
        let early = (step_index as f64) / ((total_items.max(1)) as f64) < 0.5;
        if bad_fit && early {
            score -= 45.0; // open fresh bin rather than fragment an old one
        } else {
            score += 50.0; // default: avoid opening new bins
        }
    }

    // Lookahead: if next item exactly fills the post-residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward small post residuals non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64); // penalize large dead space quadratically
        score -= 20.0 / pr; // small bonus for very tight fits
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item fits: reward proportional to how snugly it will match.
            let gap_after_next = post_residual as f64 - nxt;
            score -= 15.0 * (1.0 - gap_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leaving residual that is close-but-insufficient.
            let shortfall = nxt - post_residual as f64;
            if shortfall < 30.0 {
                score += shortfall * 0.4;
            }
        }
    }

    // Relative to mean residual: prefer bins that are already relatively full
    // (low residual compared to the mean) to consolidate packing.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current open bins are nearly saturated
    // or the item is large and would leave a well-matched residual for the next item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let saturation = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let mut new_bin_score = 60.0 + saturation * 5.0;
        // If next item fits snugly in a fresh bin alongside the current item, encourage it.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        new_bin_score += 20.0 * (1.0 - progress);
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Strong penalty for opening a new bin when other bins could fit.
    if is_new_bin {
        score += 60.0 + 25.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, opening new bins is even worse.
        score += 40.0 * progress;
        // If this is the only fitting option, soften the penalty.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // If the next item is large and wouldn't fit a new bin later, slightly soften.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Reward tight fits: small post residual.
        score -= 0.35 * (item_size as f64);

        // Last-chance bin: strongly favor using it.
        if fitting_bins_count == 1 {
            score -= 45.0;
        } else {
            score -= 6.0 * (fitting_bins_count as f64).ln().max(0.0);
        }

        // Lookahead: reward if next item fits into post_residual (chaining).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0 * (1.0 - progress);
            // Extra reward if next item fills the bin exactly after chaining.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            // Penalize leaving dead space that next item cannot use.
            score += 0.25 * (post_residual as f64);
        }

        // Prefer bins whose residual deviates favorably from the mean
        // (use below-mean-residual bins to keep large-residual bins flexible).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.10 * dev;

        // Penalize leaving very small unusable slivers unless exact fill.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Mild global pressure: many open bins -> prefer packing into existing ones.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (post_residual as f64 / cap).min(1.0);

    // Base: prefer small post-residual (tight fit), scaled smoothly.
    let mut score = post * (1.0 + 0.5 * tightness * tightness);

    // Reward tight fits more as stream progresses (consolidate early slack later).
    score -= 30.0 * tightness * tightness * (0.3 + progress);

    // Penalize bins that are far below mean residual (wasteful outlier).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post residual, big reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_bonus = (1.0 - gap / cap).max(0.0);
        score -= 20.0 * fit_bonus * fit_bonus * fit_bonus;
        // Penalize leaving residual slightly larger than next item (attractive trap).
        if post_residual > next_item_size && gap < 8.0 {
            score += 6.0;
        }
    }

    // Mild penalty on opening a new bin when many bins are open (encourage packing).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
        // But allow new bin when item is large and nothing fits well.
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod-10 residue classes) ---
    let pr = post_residual;
    let class = pr % 10;
    // Residues 0..3 are "dead" slivers: heavily penalize creating them.
    match class {
        0 => score -= 6.0,                    // perfectly reusable slot
        1 | 2 | 3 => score += 9.0,            // near-dead space
        4 | 5 | 6 => score += 1.5,            // awkward mid-class
        _ => { /* 7..9: reasonably usable */ }
    }

    // Integer-division threshold: post_residual buckets of size 10.
    let bucket = pr / 10;
    if bucket <= 1 {
        score += 4.0; // tiny leftover bins are low value
    } else if bucket >= 5 {
        score -= 3.0; // generous leftover keeps flexibility
    }

    // --- Tightness reward: fraction of bin consumed by this item ---
    let fill_ratio = item_size as f64 / cap;
    score -= 8.0 * fill_ratio;

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            // Bin can still serve the next item: reward proportional to fit quality.
            let slack = pr as f64 - nx;
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin: penalize leaving a "trap" gap
            // that is too small for the lookahead.
            score += 2.0 + 3.0 * (nx - pr as f64) / cap;
        }
        // Harmonic check: does post_residual mod 10 align with next item's class?
        if pr % 10 == (next_item_size as u32) % 10 && pr >= next_item_size {
            score -= 2.5;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin: pay the cost of fresh capacity.
        score += 14.0;
        // But large items justify fresh bins (avoid stranding big items in cramped bins).
        score -= 12.0 * fill_ratio;
        // If few bins can fit this item, opening fresh capacity is attractive.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        } else if fitting_bins_count <= 2 {
            score -= 4.0;
        }
        // Early in the stream, building a diverse pool of open bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
        // If mean residual across open bins is low, new capacity is valuable.
        score -= (cap - mean_residual).max(0.0) * 0.05;
    }

    // --- Last-chance logic: if this is the ONLY fitting bin, prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Mild pressure against proliferating many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * (open_bins_count as f64) * progress;

    // Slight preference for bins whose residual is below the mean (consolidation).
    score += 0.03 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100,
    // but practically small gaps < ~25 are hard to fill) can use are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny sliver: worst outcome, capacity wasted
        } else if post_residual < 25 {
            score += 18.0; // small gap, rarely reusable
        } else if post_residual < 50 {
            score += 6.0; // moderately risky gap
        } else {
            score -= 8.0; // large usable residual is good
        }
    } else {
        // Perfect fit: strongly reward closing the bin cleanly.
        score -= 30.0;
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 10.0;
        }
    }

    // Mean-residual coupling: placing into a bin far below mean residual spreads space well.
    score -= 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate handling: an empty bin starts with full residual.
    // Only prefer it when no existing bin offers a decent fit (post residual large
    // and item small relative to capacity); otherwise push it behind open bins.
    if bin_residual == bin_capacity {
        if post_residual >= 60 && item_size <= 40 {
            score -= 5.0; // item too small to justify opening a bin unless nothing fits well
        } else {
            score += 25.0 + 2.0 * open_bins_count as f64; // discourage needless bin opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Exact 2-step chain: item + next item fills bin completely
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize leaving a residual that no plausible item (>=1) can use well
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Compare against mean residual: bins tighter than average are better targets
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin boost: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are all poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if lookahead chains nicely into a fresh bin (item + next <= capacity), soften
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 80.0;
        }
        // Late in the stream, discourage proliferation of barely-used bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Mild preference for filling already-open bins when many are open
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post residual).
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize dead space relative to what future items could use.
    // A residual that cannot hold any plausible item (>= min size 1..100, be conservative: >= 25)
    // is likely wasted.
    if post_residual < 25 {
        score -= 8.0; // small dead space is fine, it's "closed" capacity
    } else {
        // Larger leftover: penalize proportionally, but soften if it could fit the next item.
        let waste = post_residual as f64 / bin_capacity as f64;
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0 * waste; // leftover is reusable by lookahead item
        } else {
            score += 25.0 * waste; // likely unusable dead space
        }
    }

    // Lookahead coupling: if this bin is the only one that fits the NEXT item too,
    // avoid consuming it in a way that blocks the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Placing here leaves a residual too small for the next item.
        // Check whether other bins could still take the next item: unknown, so use
        // mean residual as proxy for global slack.
        if mean_residual >= next_item_size as f64 {
            score += 6.0; // mild penalty; slack exists elsewhere
        } else {
            score += 15.0; // risky: little global slack for next item
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // This bin can also serve the next item: reward chaining.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it is only
    // chosen when no open bin offers a decent fit, or when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening new bins is less costly (no long tail), relax a bit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many open bins are nearly full, new bin is natural.
        if mean_residual < 20.0 {
            score -= 12.0;
        }
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 2.0 * crowding;

    // Early stream: keep bins tight to preserve flexibility later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    // Squared term penalizes large leftover space (wasted capacity),
    // but very small residuals (dead space) are also penalized via a
    // smooth "sweet spot" bump around a quarter of capacity.
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        - 30.0 * pr_norm * pr_norm * pr_norm * pr_norm;

    // Smooth dead-space penalty: residual too small to be useful.
    let dead = ((pr_norm - 0.08).exp() * (1.0 - pr_norm).max(0.0)).min(1.0);
    score += 25.0 * dead * pr_norm;

    // Stream-progress coupling: late in the stream, tighter packing matters more.
    score *= 1.0 + 0.6 * progress * pr_norm;

    // Reward last-chance bins (avoid opening a new bin when only one fits).
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead coupling: favor bins whose post-residual fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - 4.0 * slack * slack).max(0.0);
        } else {
            // Post-residual useless for next item: mild penalty.
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean (balanced packing),
    // smooth quadratic deviation.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor. Penalize the fresh bin smoothly by item fill ratio.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 0.55 * cap * (1.0 + 0.5 * (1.0 - fill)) + 20.0 * progress;
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (mod-10 classes) ---
    // Residuals in the same decimal class behave alike; reward "harmonic" residuals
    // that small future items (sizes 1..100) can still pair with.
    let pr = post_residual;
    let class = pr % 10;
    // Perfect closure: residual exactly 0 is ideal.
    if pr == 0 {
        score -= 40.0;
    }
    // Harmonic sweet spots: residuals that are multiples of 10 stay reusable.
    if class == 0 && pr > 0 {
        score -= 6.0;
    }
    // Dead-space classes: tiny non-zero residuals (1..=3) are nearly useless.
    if pr >= 1 && pr <= 3 {
        score += 12.0;
    }
    // Mid-range awkward classes (4..=7): mild penalty, they rarely fit common items.
    if (4..=7).contains(&pr) {
        score += 4.0;
    }

    // --- Integer-division thresholds on post_residual ---
    // Half-empty or better bins remain highly usable.
    if pr > bin_capacity / 2 {
        score -= 5.0;
    }
    // Quarter-empty: still decent.
    if pr > bin_capacity / 4 && pr <= bin_capacity / 2 {
        score -= 2.0;
    }

    // --- Last-chance logic: this is the only open bin that fits ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count >= 2 {
        // Competition exists; slightly discourage hoarding into crowded bins
        // unless the fit is very tight.
        if pr > 10 {
            score += 2.0 * (fitting_bins_count.min(6) as f64);
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // This bin can also host the next item: strong reward.
            score -= 8.0;
            // Extra harmony: next item fits leaving another multiple-of-10 residual.
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else if next_item_size > pr && pr >= (next_item_size / 2).max(1) {
            // Partial compatibility: mild reward.
            score -= 2.0;
        }
    }

    // --- Stream progression & global state modulation ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    // Late in the stream, tighten up: waste matters more.
    score += progress * (pr as f64) * 0.25;

    // Deviation from mean residual: prefer bins whose post state tracks the fleet mean
    // (keeps a balanced set of residuals for future items).
    let dev = (pr as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity && pr == bin_capacity - item_size && bin_residual == bin_capacity {
        // Opening a new bin: baseline neutral cost so it only wins when open-bin
        // fits are bad (their post_residual would be small/good).
        score = (bin_capacity as f64) * 0.9 + (item_size as f64) * 0.3;
        // If nothing else fits, this call is the only option anyway; keep it moderate.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        // Small items into a fresh bin are cheap; large items should prefer existing bins.
        if item_size > bin_capacity / 2 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized,
    // since nothing (items >= 1, but practically >= 10) can use them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Zero residual is perfect packing: reward strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize large post_residual less than small unusable ones but still discourage waste.
    score += (post_residual as f64) * 0.5;

    // Prefer tight fits: reward when post_residual is small relative to item size.
    if item_size > 0 {
        score += (post_residual as f64 / item_size as f64) * 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling existing.
    score += (open_bins_count as f64) * 1.5;

    // If next item can fit into the post_residual, reward this placement (lookahead).
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 25.0;
    }
    // If next item cannot fit into post_residual but post_residual > 0, mild penalty (dead space for next).
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) {
        score += 15.0;
    }

    // New-bin candidate handling: make empty bins slightly unattractive unless other bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's tight — favor it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Progression: later in stream, be more conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Reward near-perfect fits (post_residual very small).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space: residuals that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // awkward small gap
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or closely) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 55.0; // perfect chain: this bin fits next item too
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item cannot fit here; penalize proportionally to gap
            score += 8.0 * (1.0 - post_residual as f64 / (bin_capacity as f64));
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins below mean residual are "fuller";
    // prefer filling fuller bins (consolidate waste).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when good existing options exist,
    // unless the fit is genuinely poor everywhere.
    if bin_residual == bin_capacity {
        let waste_if_open = bin_capacity as f64 - item_size as f64;
        let poor_fit_everywhere = mean_residual < item_size as f64 * 0.5;
        if !poor_fit_everywhere {
            score += 25.0 + 0.4 * waste_if_open;
        } else {
            score += 5.0; // opening is cheaper than fragmenting
        }
        // Early in stream, slightly prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a slight convexity
    // penalty so we avoid leaving many bins with tiny residuals.
    let pr = post_residual as f64;
    score += 0.35 * (pr / 100.0) * (pr / 100.0) * 100.0;

    // Lookahead: if the next item fits into the post_residual, reward this bin
    // (chaining placements); otherwise penalize proportionally to how much
    // the next item misses the remaining space.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 6.0 * (1.0 - n / (pr + 1.0));
        } else {
            score += 3.0 * ((n - pr) / 100.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it instead of opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0 + 0.10 * (bin_residual as f64 - item_size as f64);
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that will be "closed out" well.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and open bins are crowded / poor fits.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let tightness = item_size as f64 / bin_capacity as f64;
        let pressure = (1.0 - crowding) * tightness;
        // Penalize opening a new bin by default; discount when pressure is high
        // (large item, low mean residual among open bins).
        score += 25.0 - 20.0 * pressure;
        // Late in the stream, opening fresh bins is less wasteful.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * t;
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins aggressively; few open bins -> be choosier.
    let open_f = open_bins_count as f64;
    score -= 2.0 * open_f.ln().max(0.0) * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * ((bin_residual as f64 - item_size as f64) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, non-linearly coupled with stream progress.
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);

    // Smooth polynomial penalty for dead space, growing with progress.
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Reward near-perfect fits with a smooth exponential bonus.
    score -= 25.0 * (-(norm_post * norm_post) * 40.0).exp();

    // Last-chance bin: strong smooth reward.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - norm_post);
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0 * norm_post;
    }

    // Mean residual coupling: penalize bins far below mean residual (fragmentation).
    let dev = (mean_residual - post) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for opening new bins as stream matures.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class index: 0 = perfect fit, 1 = tiny gap, ... penalize mid-range gaps (hardest to fill).
    let class = (pr as u32 / 10) as f64;
    score += class * class * 0.35; // quadratic penalty on dead-space class

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic coupling with lookahead: a residual that exactly (or nearly) matches
    // the next item is a great class — reward it; mismatched mid gaps get penalized.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (pr - nxt).abs();
            score -= 18.0 * (1.0 - gap / cap);
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // next item cannot use this gap: penalize proportionally to wasted class
            score += 8.0 * frac;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fits (lower post residual already does this)
        score -= 3.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins that are already relatively empty of residual (large fill ratio)
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * fill_ratio;

    // Mean residual coupling: if open bins are on average roomy, be pickier
    // (add penalty scaled by how far this bin's post residual is above the mean).
    let dev = pr - mean_residual;
    score += 0.25 * dev.max(0.0);

    // Early in the stream, tolerate opening bins less; late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * frac;

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Make it attractive only when the item is large relative to capacity or
    // no good class exists among open bins; otherwise keep it behind good fits.
    if bin_residual == bin_capacity {
        let base = pr; // == cap
        score = base + 55.0; // default: worse than any decent open-bin fit
        if item_size >= 60 {
            score -= 25.0; // big items fine to start fresh
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0; // next item won't share anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100
    // interface, but keep a conservative dead-zone threshold) are wasted capacity.
    let dead_threshold: f64 = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Penalize unusable slivers proportionally to how close to zero they are.
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; with few bins,
    // tolerate opening new capacity for better future packing.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; acceptable only when it
        // avoids creating dead space that an existing bin would suffer.
        score += 30.0 + pressure * 6.0;
        // If the next item would fit exactly in this fresh bin's residual after
        // placement, mildly encourage opening it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: small reward for reusing, scaled by pressure.
        score -= pressure * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host the next item: mild penalty for stranded space.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (concentrating waste into fewer bins).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: match post_residual against next_item_size ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            // Perfect pairing: this bin will be exactly filled by the next item.
            score -= 60.0 + 40.0 * progress;
        } else if pr >= nxt {
            // Next item still fits here; reward proportionally to how snug it is.
            let snug = 1.0 - ((pr - nxt) / bin_capacity as f64);
            score -= 25.0 * snug * (0.5 + 0.5 * progress);
        } else {
            // Next item would NOT fit: creates a stranded state unless post
            // residual is tiny (near-full bin is still good).
            if pr > 0.0 {
                let gap = nxt - pr;
                // Penalize dead space that is too small for typical items.
                score += (gap / nxt.max(1.0) as f64) * 18.0;
                if pr < 10.0 {
                    score -= 20.0; // nearly full bin is excellent anyway
                }
            }
        }
    } else {
        // Last item: just minimize leftover.
        score -= 30.0;
    }

    // ---- Relative-to-mean-residual coupling ----
    // Prefer packing into bins whose residual is below average (tighter bins),
    // keeping loose bins available for larger future items.
    let dev = mean_residual - post_residual as f64;
    score += 0.35 * dev;

    // ---- Last-chance bonus: only this bin fits the item ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral base, but discourage when a decent
        // existing fit exists; encourage when item is large (poor fits likely).
        score = (bin_capacity - item_size) as f64 + 15.0;
        if item_size >= 60 {
            score -= 20.0;
        }
        if fitting_bins_count > 0 && post_residual as f64 >= mean_residual {
            score += 25.0; // existing bins already loose; don't open more
        }
    }

    // Small global preference for filling bins tightly as stream progresses.
    score -= 0.05 * (item_size as f64) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space aggressively.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.25;
    }

    // Lookahead chaining: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here anyway; a perfect-ish fill is great.
            if post_residual <= 5 {
                score -= 12.0;
            }
        }
    }

    // New empty bin candidate: only attractive for large items or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 30.0 - progress * 10.0;
        if item_size >= 60 {
            new_bin_penalty -= 20.0;
        }
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 25.0;
        }
        if (mean_residual - item_size as f64) < 0.0 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(-40.0);
    } else {
        // Prefer bins that are already partially filled (reduce bin count pressure).
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 6.0;
    }

    // Mild global-state coupling: many open bins -> discourage fragmentation.
    if open_bins_count > 4 {
        score += (post_residual as f64) * 0.05 * (open_bins_count.min(20) as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled non-linearly.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (bins stay flexible).
    // Late in the stream: strongly penalize residual waste.
    let waste_weight = 1.0 + 3.0 * progress * progress + 2.0 * progress;
    score += 0.9 * (pr / cap) * (pr / cap) * cap * waste_weight;

    // Cubic coupling term: dead-space penalty grows super-linearly with progress.
    let norm_pr = pr / cap;
    score += cap * norm_pr.powi(3) * (0.5 + 2.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 + 6.0 * progress;
        } else {
            // Penalize creating residual that cannot fit the next item,
            // scaled by how far off it is (smooth quadratic).
            let gap = (nxt - pr) / cap;
            score += 10.0 * gap * gap * cap;
        }
    }

    // Slight preference for bins below mean residual (tighter bins first),
    // smoothly coupled with open bin count.
    let mean_norm = mean_residual / cap;
    score += 2.0 * (mean_norm - norm_pr) * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // New-bin candidate handling: empty bin gets a moderate base cost so it
    // is chosen only when no open bin offers a good fit, especially early.
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 20 defines "usable" slots.
    let res = post_residual as u32;
    let class = res % 20;
    // Penalize residuals that fall into awkward classes (dead space zones).
    let class_penalty = match class {
        0 => -6.0,               // perfectly filled bin
        1..=9 => 3.0 + class as f64 * 0.5, // small useless slivers
        10 => 0.5,               // half-class: still useful
        _ => -0.5,               // 11..19: roomy, good for mid items
    };
    score += class_penalty;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 4.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let next_class = (post_residual - next_item_size) % 20;
            if next_class == 0 {
                score -= 8.0;
            } else {
                score -= 2.0 * (next_item_size as f64 / post_residual.max(1) as f64);
            }
        } else {
            // next item cannot fit here: slight penalty proportional to wasted potential
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one with least post_residual (handled by base term).
        score += 0.2 * fitting_bins_count as f64;
    }

    // New-bin candidate detection: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; escalate as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 8.0 + 6.0 * progress;
        // Opening a new bin is acceptable if it yields a perfect-fill class
        // (post_residual in a good class) and current bins are congested.
        if class == 0 {
            new_bin_cost -= 6.0;
        } else if class >= 11 {
            new_bin_cost -= 2.0;
        }
        // If this is the only fitting option anyway, new bin cost is the fallback.
        if fitting_bins_count == 0 {
            new_bin_cost -= 4.0;
        }
        // If mean residual across open bins is large, prefer reusing them.
        new_bin_cost += (mean_residual / cap).max(0.0) * 6.0;
        score += new_bin_cost;
    }

    // Mild pressure to keep number of open bins low when they are fragmented.
    if (mean_residual / cap) < 0.15 && open_bins_count > 3 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are nearly useless for
    // future items (min size 10) -> heavy penalty; also penalize gaps that
    // cannot hold the lookahead item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small useful residual).
    score -= 0.5 * (bin_residual as f64 - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // new bins unless the fit is excellent.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if post_residual == 0 || post_residual >= 20 {
            score -= 30.0;
        }
    } else {
        score -= 0.3 * open_bins_count as f64;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is far from mean (closing outliers early).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Recognize the brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Mild bias against opening a new bin when an existing one could work.
    if is_new_bin {
        score += 6.0 + 0.05 * open_bins_count as f64;
    }

    // Tight-fit reward: relative fill of the bin by this item.
    let fill = item_size as f64 / cap;
    score -= 8.0 * fill * (1.0 - post / cap);

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize residuals that are dead space with respect to the lookahead.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 5.0 * (1.0 - nxt / cap);
        } else {
            let waste = nxt - post;
            score += 0.35 * waste.min(25.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 7.0;
    }

    // Coupling with global state: penalize creating residuals far below the
    // current mean residual (fragmentation pressure).
    score += 0.03 * (mean_residual - post).abs();

    // Dynamic time horizon: later in the stream, be slightly greedier about
    // tight fits (less room for recovery).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = post / cap;
    let norm_item = item / cap;
    let mean_res_norm = mean_residual / cap;

    // Base waste term: quadratic in normalized post-residual (dead space penalty grows superlinearly).
    let mut score = norm_post * norm_post * cap;

    // Smooth interaction: post-residual coupled with stream progress.
    // Early in the stream, keep bins flexible (mild penalty on tight fits);
    // late in the stream, aggressively prefer tight fits.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (1.5 + 3.0 * progress) * cap * 0.5;

    // Cubic coupling of item size with progress: large items late in stream
    // should prefer bins that become very tight (reward low post-residual more).
    let cube_term = norm_item * norm_item * norm_item * (1.0 - progress);
    score += cube_term * cap * 0.3;

    // Lookahead synergy: if next item fits into post-residual, reward this bin strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let synergy = (post - nxt) / cap;
            score -= (1.0 - synergy) * cap * (0.6 + 0.8 * progress);
        } else {
            // Next item won't fit here: penalize leaving a gap that is too small to be useful.
            let gap = post / cap;
            score += gap * gap * cap * 0.4;
        }
    }

    // Relative-context coupling: bin residual far below mean residual means it's an outlier;
    // smooth polynomial preference for consuming below-average residual space.
    let rel = (bin_residual as f64 / cap) - mean_res_norm;
    score -= rel * rel * cap * 0.25;
    score += rel * cap * 0.1 * (1.0 - progress);

    // Last-chance bin: if this is the only fitting bin, reward using it (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.4 + 0.6 * progress);
    }

    // New-bin candidate handling: an empty bin has norm_post = 1 - norm_item.
    // Penalize opening a new bin early-to-mid stream unless the item is huge.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let openness = 1.0 - norm_item;
        score += cap * (0.5 + 1.2 * (1.0 - progress)) * openness * openness;
        // But if no existing bin fits well, the new-bin penalty should not dominate:
        // smooth release when fitting bins are scarce.
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= cap * scarcity * (0.8 + 0.7 * progress);
    }

    // Mild penalty on proliferation of open bins, smoothed by progress.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Tiny tie-breaker proportional to post-residual for deterministic ordering.
    score += post * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes on post_residual (decades of capacity fraction 100)
    let cls = post_residual / 10;
    score += match cls {
        0 => -30.0,          // near-perfect fit
        1 => -18.0,
        2 => -8.0,
        3 => 0.0,
        4 => 4.0,
        5 => 8.0,
        6 => 12.0,
        7 => 15.0,
        8 => 18.0,
        _ => 20.0,           // barely used bin
    };

    // Lookahead coupling: reward bins that can also host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // extra reward for exact modular harmony with next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Penalize unusable dead space (residual too small for any item)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Brand-new empty bin candidate: only attractive when open-bin fits are bad
    if bin_residual == bin_capacity {
        score = 60.0 + 0.25 * item_size as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0; // new bin can host the coming pair harmonically
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Stream progression: slightly tighten preferences late in the stream
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable dead space (1..=10) — archetype core.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Mid-range gaps (11..=25) are hard to fill too; mild penalty.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }
    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize if post_residual is small but nonzero and cannot hold next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage proliferation,
    // but not so much that we accept terrible fits (dead-space term dominates).
    score += open_bins_count as f64 * 1.5;

    // Prefer filling bins that are already relatively full (small residual).
    score += bin_residual as f64 * 0.05;

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (i.e., when mean residual is large but we still want fresh space) —
    // otherwise keep it slightly worse than reusing a decent bin.
    if bin_residual == bin_capacity {
        score += 12.0 - mean_residual * 0.05;
    }

    // Slight stream-progress adaptation: later, tighten dead-space tolerance
    // by rewarding low post_residual more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (25.0 - post_residual as f64).max(0.0) * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 50.0).max(0.0);
    }

    // Penalize dead space the next item cannot use (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward using bins that are already tight (relative to mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize leaving tiny unusable residues (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: only attractive when current bin would leave large waste
    // or when open bins are few relative to stream progress.
    if bin_residual == bin_capacity {
        let waste_penalty = (item_size as f64) * 0.5;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity_bonus = if open_bins_count < 3 { 20.0 } else { 0.0 };
        score = 100.0 + waste_penalty - scarcity_bonus + 10.0 * (1.0 - progress);
        // Allow new bin if next item would not fit in the resulting residual anyway.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal wasted space after placement.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear dead-space penalty: residuals that can fit almost nothing
    // (very small) are fine; mid-sized residuals (~20-45) are the most
    // dangerous "awkward" leftovers, penalize them extra.
    let awkward = {
        let x = post / cap;
        let center = 0.30;
        let w = 0.18;
        -((x - center) * (x - center)) / (2.0 * w * w)
    };
    score += 18.0 * awkward.exp();

    // Lookahead: if the next item fits exactly or snugly into the post
    // residual, strongly reward this bin (chain placement).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = post_residual - next_item_size;
        let snug = 1.0 - (slack as f64) / cap;
        score -= 8.0 + 10.0 * snug;
    } else if next_item_size > 0 {
        // Next item cannot follow here: mild penalty, worse if the leftover
        // is large enough that we "wasted" a big bin on this item.
        let waste = post / cap;
        score += 4.0 * waste;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Competition exists: prefer bins whose residual is closest to the
        // item (best-fit among candidates), scaled by competition size.
        let tightness = 1.0 - (item_size as f64) / (bin_residual as f64).max(1.0);
        score += 6.0 * tightness;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means an
    // empty bin. Only attractive when no open bin fits, or when the item
    // is huge (near-capacity) and would strand a large residual anyway.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a bin
        } else {
            // Penalize opening a new bin when alternatives exist, but less
            // so for very large items that fragment any bin they enter.
            let hugeness = (item_size as f64) / cap;
            score += 20.0 * (1.0 - hugeness * hugeness);
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack in the system; be pickier about tight fits and less
    // eager to open new bins.
    let mr = mean_residual / cap;
    score -= 5.0 * mr * (1.0 - (post / cap));

    // Time horizon: early in the stream, be conservative (avoid stranding
    // bins); late in the stream, prioritize immediate tightness since
    // future payoff matters less.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 3.0 * (post / cap);
    score -= t * 2.0 * (post / cap);

    // Slight preference to fill bins with many prior placements implied by
    // a small residual relative to capacity (denser bins first).
    score -= 2.0 * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills mildly; late, strongly prefer small post_residual.
    let w = 0.5 + 2.0 * progress * progress;
    score -= w * (pr / cap) * (1.0 - pr / cap) * cap * 0.3;

    // Penalize large dead space quadratically as stream advances.
    score += 0.02 * pr * pr * (0.3 + progress);

    // Exact fit reward (smooth bump).
    if post_residual == 0 {
        score -= 25.0 + 15.0 * progress;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize unless post_residual would be well usable
    // relative to remaining demand and next item.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 + 10.0 * openness;
        if next_item_size > 0 {
            let n = next_item_size as f64;
            // new bin attractive if it can host next item after this placement
            let usable = if n <= pr { 1.0 } else { (cap - (n - pr)) / cap };
            score -= 20.0 * usable * (1.0 - progress);
        }
        // late in stream, prefer filling existing bins
        score += 25.0 * progress * progress;
    }

    // Next-item lookahead: reward leaving room for the next item.
    if next_item_size > 0 && bin_residual < bin_capacity {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 6.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Mild preference for bins deviating from mean residual (consolidate waste).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let mut score = pr;

    // Tight-fit reward: fraction of bin consumed by this item
    score -= 0.9 * (isz / cap) * 100.0;

    // Harmonic class of post_residual: residues divisible by common item
    // granularity (10) are reusable; odd residues are dead space.
    let gran = post_residual % 10;
    if gran != 0 {
        score += 8.0 + 0.15 * (10 - gran) as f64;
    } else if post_residual > 0 {
        score -= 6.0;
    }

    // Exact fit is gold
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: excellent, reward proportionally
            score -= 12.0 + 0.2 * (next_item_size as f64);
            // bonus if next item fills remainder nearly exactly
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize residues slightly above
            // typical item sizes (wasted space)
            score += 0.08 * (post_residual as f64 - 0.0);
            if post_residual < next_item_size as f64 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive for huge items or when
    // no decent fit exists among open bins
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin
        score += 55.0;
        // large items deserve fresh bins
        if item_size >= 60 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
        // if existing bins are fragmented, fresh bin less bad
        if mean_residual < 30.0 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Slight progression-aware tightening
    let prog = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * prog * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band (1..=12)
    // are heavily penalized, since nothing (min item 10, small items rare) fits there.
    let pr = post_residual;
    if pr > 0 && pr < 12 {
        score += (12 - pr) as f64 * 6.0; // the smaller the gap, the worse
    }
    // Perfect fit is golden.
    if pr == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that likely accommodates the lookahead item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 8.0 + 0.25 * (next_item_size as f64);
        } else if pr > 0 {
            // gap too small for next item: mild extra penalty scaled by tightness
            score += 0.15 * ((next_item_size - pr) as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins when
    // mean residual is already large enough to absorb this item.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if mean_residual >= item_size as f64 {
        score -= pressure * 2.0;
    } else {
        score += pressure * 1.5;
    }

    // New-bin candidate: reserve it for cases where this item would create
    // bad dead space in every fitting bin, or few bins fit the item.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        let mut nb = 55.0;
        // if item fills a large chunk of a fresh bin, opening is cheap
        nb -= 0.3 * (item_size as f64);
        // if many bins fit the item, opening new is less attractive
        nb += 4.0 * (fitting_bins_count as f64).min(8.0) as f64;
        // if this item would leave a large usable gap in an existing bin, prefer existing
        if pr >= 12 {
            nb += 10.0;
        }
        // late in stream: consolidate rather than open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 10.0 * progress;
        score = score.max(0.0) + nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect two-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // partial lookahead credit, decaying with mismatch
            score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // dead space unusable by next item: penalize proportionally
            score += 10.0 * (1.0 - post_residual as f64 / nxt.max(1.0)).max(0.0);
        }
    } else {
        // last item: minimize leftover
        score += 5.0;
    }

    // Penalize small unusable residuals (dead space) regardless of lookahead
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a new bin
        score += 20.0;
        // but discount it if placing here would waste most of an existing bin
        let waste = post_residual as f64 / bin_capacity as f64;
        if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) && waste < 0.2 {
            score -= 30.0; // opening fresh bin beats leaving tiny dead space
        }
        // slightly less attractive late in the stream (consolidate)
        score += 5.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Prefer packing into bins with below-average residual (tight bins stay tight)
    if !is_new_bin {
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev;
    }

    // Mild pressure to reduce open bin count when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (small post_residual) with a superlinear penalty on waste.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Dead-space penalty: leftover space too small for the smallest plausible item.
    if pr > 0.0 && pr < 12.0 {
        score += 25.0 * (12.0 - pr) / 12.0;
    }

    // Lookahead (k=2): if the next item cannot fit in the post-residual,
    // this bin's remaining space is likely dead — penalize proportionally.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 0.5 * (nxt - pr);
        } else {
            // Next item fits: reward leaving exactly-useful space.
            score -= 0.25 * (nxt / cap) * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: mild preference scaling by scarcity.
        score -= 4.0 / fitting_bins_count as f64;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large (few bins can hold it later) or the stream is early.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let new_bin_penalty = 30.0
            + 60.0 * (1.0 - fill_ratio)          // small items waste a fresh bin
            + 20.0 * progress                     // late in stream, reuse bins
            + 2.0 * open_bins_count as f64;       // avoid bin proliferation
        let new_bin_bonus = 15.0 * fill_ratio * fill_ratio
            + if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        score += new_bin_penalty - new_bin_bonus;
    }

    // Global state coupling: if mean residual across open bins is high,
    // there is slack in the system — prefer bins that consolidate space
    // (i.e., leave small post_residual relative to the mean).
    if mean_residual > 0.0 {
        score += 0.15 * (pr - mean_residual).max(-30.0).min(30.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Base: normalized post-residual, quadratically penalized (dead space grows costly)
    let mut score = (pr / cap).powi(2) * 100.0;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in stream, tight fits matter more; early, keep bins flexible.
    let tightness = (pr / cap).powi(3);
    score += tightness * (1.0 + 4.0 * progress) * 50.0;

    // Exact fit reward (smooth exponential rather than hard threshold)
    if pr == 0 {
        score -= 60.0;
    } else {
        score -= 60.0 * (-(pr as f64) / 12.0).exp();
    }

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 25.0 * (1.0 - pr / cap);
        } else {
            // wasted gap relative to next item: smooth penalty
            score += 15.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: mild penalty for leaving many half-empty bins
    score += (open_bins_count as f64).ln1p() * 2.0 * (pr / cap);

    // Mean residual coupling: prefer bins near the mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (dev / cap) * 8.0;

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_fill = mean_residual / cap;
        score = 100.0 + 50.0 * (1.0 - avg_fill) - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space classes".
    // Residue 0 (perfect fill) is best; large residues near 9 are worst.
    let r = post_residual % 10;
    score += match r {
        0 => -12.0,
        1 => 6.0,
        2 => 4.0,
        3 => 2.0,
        4 => 1.0,
        5 => 0.0,
        6 => 1.5,
        7 => 3.0,
        8 => 5.0,
        _ => 7.0,
    };

    // Harmonic compatibility: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Reward bins whose post-residual is an integer multiple of next item size
            let div = (pr / nxt).floor();
            let rem = pr - div * nxt;
            score -= 8.0 * (rem / cap);
            if pr as u32 % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot fit here; penalize wasting capacity
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Integer division thresholds on post_residual: tiny leftovers are dead space
    if post_residual <= bin_capacity / 20 {
        score -= 15.0; // near-perfect bin, strongly favor
    } else if post_residual <= bin_capacity / 8 {
        score -= 5.0;
    } else if post_residual > bin_capacity * 3 / 5 {
        score += 4.0; // leaving a big hole, mild penalty
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let tight = (mean_residual / cap).max(0.0).min(1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin base cost; discount when existing bins are mostly full or few bins fit
        let base = 20.0 + 15.0 * progress;
        score = base - 18.0 * pressure * (1.0 - tight) - 8.0 * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64));
        // If next item is large, opening fresh bin now can be good
        if next_item_size >= 50 && item_size >= 50 {
            score -= 6.0;
        }
    }

    // Favor filling bins tighter than the mean residual
    score -= 2.0 * (mean_residual - post_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are pure waste.
    // A tiny-but-nonzero post_residual is the worst outcome; zero is perfect.
    if post_residual > 0 {
        // Penalize gaps below the smallest useful size harshly, with a sharp cliff.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 2.5;
        } else {
            // Larger gaps are still usable; mild penalty proportional to waste.
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting gap,
    // this placement is part of a good plan; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; gap becomes dead space for the lookahead.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; consolidate.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual context: placing into a bin whose residual is far below mean
    // (i.e., nearly full) is good; placing into a fat bin leaves many other options.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate: the empty bin should only win when the fit is bad.
    // Give it a moderate baseline so only genuinely poor fits in open bins lose to it.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, opening fresh bins is less useful; penalize more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item can follow: reward tighter match
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 10.0; // perfect 2-chain
            }
        } else {
            // next item cannot follow; penalize proportionally to unusable gap
            score += 0.5 * gap;
        }
    }

    // Prefer bins whose residual deviates from mean residual (tight bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid opening new bin when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize creating tiny dead space (<10) that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: only attractive when open bins would leave big waste
    if bin_residual == bin_capacity {
        score += 4.0 + 0.2 * open_bins_count as f64;
    }

    // Late-stream tightening: prioritize filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * fit_ratio * (item_size as f64);

    // Penalize leaving dead space that likely cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver: nearly dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 1.5;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward for a good chain (next item fills most of remainder).
        let chain_fill = next_item_size as f64 / post_residual as f64;
        score -= 4.0 * chain_fill;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the lookahead item: penalize waste.
        score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: opening bins is costly.
        score += 20.0 + open_bins_count as f64;
        // If no existing bin fits, the new bin is the only option: soften penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, opening bins is more acceptable; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If many open bins with lots of slack, discourage yet another bin.
        if mean_residual > item_size as f64 * 2.0 {
            score += 8.0;
        }
    }

    // Mild global consolidation pressure: prefer bins with below-average residual
    // (i.e., fuller bins) to keep many medium-slack bins around.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time-horizon modulation: as stream progresses, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * fit_ratio;

    // Small tie-breaker favoring fuller bins.
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Base: prefer minimal post residual (tight fit)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes increasingly costly (superlinear)
    let t = progress;
    let dead_space_penalty = (post / cap).powi(2) * (1.0 + 3.0 * t * t) * 20.0;
    score += dead_space_penalty;

    // Cubic interaction: exact fills are rewarded more as stream progresses
    let fill_bonus = (1.0 - post / cap).powi(3) * 15.0 * (0.5 + t);
    score -= fill_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0 + 20.0 * t;
    }

    // New-bin candidate: penalize unless it enables a near-perfect fit later;
    // coupling with mean residual: if open bins are already slack, avoid new bins
    if is_new_bin {
        let slack = mean_residual / cap;
        score += 30.0 + 25.0 * slack + 10.0 * (1.0 - t);
        // reward new bin only when item is large relative to capacity
        score -= (item_size as f64 / cap).powi(2) * 20.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        let lookahead_bonus = (1.0 - diff / cap).powi(2) * 12.0;
        score -= lookahead_bonus;
    }

    // Mild penalty tied to number of open bins (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * t);

    // Small coupling with mean residual: prefer bins below mean residual
    // (i.e., already tight bins) to keep large residuals available
    score += (mean_residual - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into bands of 10.
    let class = post_residual / 10;
    score += class as f64 * 1.5; // prefer bins landing in low (tight) residual classes

    // Harmonic pairing: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect harmonic match, reserve this space
        } else if next_item_size <= post_residual {
            // partial fit: reward proportional to how well it divides the residual
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac;
        } else {
            // next item cannot use this residual; penalize large dead space
            score += (post_residual as f64) * 0.3;
        }
    }

    // Integer-division thresholds: penalize residuals that are awkward (not multiples of 10)
    let awkward = post_residual % 10;
    score += awkward as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately unattractive unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.5;
        // late in the stream, keep bins tight rather than spreading out
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Reward filling bins close to capacity
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Slight preference for bins already below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large post-residual only mildly; prefer tight fits overall.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins when pressure is high.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure penalty.
        score += 20.0 + 5.0 * pressure;
        // Opening a new bin is attractive only if it leaves a big residual
        // that could fit the next item well.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs();
            score += 0.3 * gap as f64;
        }
    } else {
        // Existing bin: reward when pressure is high.
        score -= 2.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Early stream: be conservative, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // perfect chain: item fits, next item exactly fills remainder
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // penalize leaving residue that no reasonable item (1..=100) can use well
        if post_residual > 0 && next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // compare against mean residual: prefer bins tighter than average
    score -= 0.8 * (mean_residual - post_residual as f64);

    // last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // penalize creating tiny dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // slight preference for filling bins tighter as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * post_residual as f64;

    // avoid opening new bins when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size && bin_residual - item_size < next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste fraction coupling).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly unusable
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0; // usable pocket for small items
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Global state: many open bins with high mean residual → prefer consolidation.
    if open_bins_count > 2 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * spread;
        score -= 0.5 * mean_residual / (open_bins_count as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= 12.0 * progress; // late: favor existing bins
    } else {
        score += 8.0 * (1.0 - progress); // early: mild penalty on existing bins
    }

    // New-bin candidate handling: neutral-ish baseline, penalized when the
    // item fits poorly relative to capacity or when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0; // default: prefer reusing open bins
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open new bin
        }
        if item_size >= 80 {
            score -= 35.0; // huge item: fresh bin is natural
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // fresh bin would strand space immediately
        }
    }

    // Mild penalty for very large leftover after a small item (poor packing).
    if item_size < 30 && post_residual > 70 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fits (small post_residual) matter more.
    let tightness = (1.0 - pr / cap).powi(2);
    score -= 12.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize large dead space non-linearly.
    score += 0.02 * pr * pr / cap;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New empty bin candidate: penalize mildly, less so when few bins fit
    // the item or the item is large (poor fit elsewhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 6.0 + 3.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    } else {
        // Reward bins whose residual aligns with the next item (lookahead).
        if next_item_size > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score -= 5.0 * (1.0 - gap / cap).powi(3);
        }
        // Favor bins below mean residual (relatively full bins).
        score += 0.05 * (pr as f64 - mean_residual);
    }

    // Mild penalty for spreading across too many open bins early.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let q = post_residual / (bin_capacity / 4);
    let dead_zone = post_residual % (bin_capacity / 4);
    match q {
        0 => score -= 20.0,                       // near-perfect fit
        1 => score += dead_zone as f64 * 0.5,     // awkward quarter
        2 => score -= 5.0,                        // half-full residual is reusable
        _ => score += 3.0,
    }

    // Reward leaving space exactly matching next item (harmonic lookahead)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < bin_capacity / 8 {
                score -= 10.0;
            } else {
                score += slack as f64 * 0.05;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize new empty bin unless no good open bin exists
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 && tight_fit < 0.85 {
            score += 60.0;
        } else {
            score -= 10.0;
        }
    }

    // Prefer tighter bins among open ones
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Late stream: consolidate harder
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
        score += mean_residual * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable gaps (dead space < 10 can never fit min item,
    // gaps < 20 are nearly useless given typical item sizes).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // total dead space
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: smaller relative waste is better.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, allow opening new bins more readily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0 * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): penalize mildly so we only open a new bin
    // when existing bins would create bad dead space; scale with mean residual
    // of open bins (high mean residual => existing bins are roomy, opening new
    // bin is less justified).
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.5;
    }

    // Lookahead: if next item would fit into post_residual, bonus for leaving
    // a usable gap; if next item cannot fit, slightly penalize leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = post - nxt;
        if diff == 0.0 {
            // Perfect two-item fill: this bin closes exactly after next item
            score -= 60.0;
        } else if diff > 0.0 {
            // Next item fits: mild reward scaled by tightness
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover: dead space penalty
            // Penalize more when the leftover is small and unusable
            score += 8.0 + 0.35 * (-diff);
        }
    } else {
        // Last item: prefer tightest fit only
        score += 0.0;
    }

    // Prefer bins that are already partially filled (avoid fragmenting fresh bins)
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Relative-to-mean coupling: favor bins tighter than average
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, use it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (opening fresh space is justified for big items or when no good fit exists)
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Neutral-ish base for new bin; penalize opening unless item is large
        score += 20.0 * (1.0 - item_ratio);
        // If an open bin would leave a tiny unusable gap, opening may win via lookahead terms
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual < 10 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: as stream progresses, tighten packing further
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Perfect-fit collapse: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual > 50 {
        // Large dead space is dangerous unless it can host the next item.
        score += 0.10 * (post_residual as f64 - 50.0);
    }

    // Lookahead: reward if the next item fits into the resulting residual.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0 + 0.05 * next_item_size as f64;
        } else {
            // Waste potential: residual too small for the upcoming item.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.08 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or all open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / cap; // high => open bins are full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = 0.5 * crowding + 0.3 * progress + 0.02 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // forced new bin anyway
        } else if pressure > 0.55 || item_size > 60 {
            score -= 8.0 * pressure;
        } else {
            score += 15.0; // discourage opening bins when fits exist
        }
    }

    // Mild preference for consolidating into bins below-average residual
    // (keeps tight bins tight, spreads loose bins).
    if !is_new_bin {
        score += 0.03 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer filling bins tightly (low post_residual).
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, keep some slack (mild penalty on tight fits);
    // late in the stream, demand tight fits (amplify post_residual cost).
    let tight_gain = 30.0 * (1.0 - progress) * (pr / cap) - 25.0 * progress * (pr / cap) * (pr / cap);
    score += tight_gain;

    // Non-linear reward for exact-ish fits, smoothly scaled by item size.
    let fit_ratio = it / cap;
    score -= 18.0 * fit_ratio * (1.0 - pr / cap).powi(2);

    // Penalize dead space that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - pr) / cap).max(0.0);
        score += 12.0 * unusable * (1.0 + progress);
        // Reward leaving room for the next item smoothly.
        let usable = (1.0 - ((pr - nx) / cap).abs().min(1.0)) * (pr >= nx) as i32 as f64;
        score -= 8.0 * usable;
    }

    // Last-chance bonus: smooth ramp as fitting bins become scarce.
    if fitting_bins_count <= 1 {
        score -= 15.0;
    } else {
        score -= 15.0 / (fitting_bins_count as f64).powf(1.5);
    }

    // Mild penalty for proliferating bins relative to mean residual state.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - pr / cap).abs();

    // New-bin candidate: empty bin has large post_residual, naturally penalized;
    // add extra smooth deterrent unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover decomposes into
    // plausible future item sizes (capacity fractions / integer division bands).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftover too small to ever be filled (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-class reward: residuals divisible by common item granularity (5/10/20)
    // are more reusable.
    let div10 = (post_residual % 10 == 0) as f64;
    let div5 = (post_residual % 5 == 0) as f64;
    let div20 = (post_residual % 20 == 0) as f64;
    score -= 6.0 * div10 + 3.0 * div5 + 4.0 * div20;

    // Fractional bands of capacity: leftover near half or quarter capacity is valuable.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    let band = |x: f64, t: f64, w: f64| -> f64 {
        let d = (x - t).abs();
        if d < 10.0 { w * (1.0 - d / 10.0) } else { 0.0 }
    };
    score -= band(pr, half, 8.0);
    score -= band(pr, quarter, 5.0);
    score -= band(pr, 3.0 * quarter, 5.0);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward;
    // if it cannot fit, penalize (this bin leaves dead space relative to stream).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post residual is hopeless dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0; // unless it creates dead space
        }
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // is large relative to the residual (poor fit) or stream is early.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin: keep it competitive but not dominant.
        score = cap as f64 * 0.55 - 30.0 * tight - 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        if item_size >= 70 {
            score -= 10.0; // big items: fresh bin is fine
        }
    } else {
        // Prefer tighter bins: smaller bin_residual relative to item = better fit.
        let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
        score -= 12.0 * fit_ratio;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;
    // Slight preference for bins whose residual is near the mean (balance).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,10] are nearly unusable
    // (min item size >= 1 but small gaps waste capacity), penalize heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    }
    // Medium awkward gaps also mildly penalized.
    if post_residual > 10 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 4.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual as f64 <= item_size as f64 * 0.15 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, keep score
    // higher for bins with large residual so tight bins win first.
    let open_pressure = open_bins_count as f64 * 0.8;
    score += open_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below mean (consolidate into fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // residuals everywhere are bad; empty bin gives full flexibility.
    if bin_residual == bin_capacity {
        let flexibility_bonus = 30.0 - open_bins_count as f64 * 2.0;
        score = bin_capacity as f64 - flexibility_bonus;
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 40.0; // favor opening fresh bin for large items
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: perfect next-item match is a jackpot
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.25;
        } else {
            // next item cannot fit here; leftover is pure dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: minimize residual strictly
        score += 10.0;
    }

    // Reward small post_residual residuals relative to mean residual of open bins
    score -= (mean_residual - post_residual as f64) * 0.10;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 10.0 * progress;
        if open_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // new bin could serve next item, but wasteful now
        }
        // New bin is attractive only if item barely fits nowhere (large item, tight fits)
        if item_size >= 70 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Slight penalty for very tiny unusable leftovers (< 10 can hold almost nothing)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract for small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residue too small for typical future items (1..100 unknown, assume >=10 useful).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residue won't host next item: mild penalty proportional to how close it was.
        score += 5.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in stream, be greedy about closing gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is fine when item is large (good fill) but penalize
        // opening for small items that could fit elsewhere with reasonable residue.
        score += 12.0;
        score += 0.15 * (bin_capacity - item_size) as f64; // waste of fresh capacity
        // If no open bin fits, opening is necessary: relieve the penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild global-balance term: prefer bins whose residual is below mean (fill emptier-tail bins).
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / c;

    // Base: post-residual with smooth non-linear shaping (quartic).
    let mut score = pr as f64 * (1.0 + 0.9 * fit_norm * fit_norm - 0.4 * fit_norm * fit_norm * fit_norm);

    // Stream-progress coupling: late in stream, tighter packing matters more.
    let prog_coupling = progress * (pr * pr) / (c * c);
    score += 6.0 * prog_coupling;

    // Penalize near-miss residuals that waste capacity (smooth bump around small post_residual).
    let waste = (1.0 - fit_norm).powi(3);
    score += 4.0 * waste * fit_norm;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / c);
        } else {
            score += 5.0 * (ni - pr) / c;
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (tight bins).
    score += 1.5 * (mean_residual - pr) / c;

    // Slight preference for fewer open bins pressure early on.
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else {
        // Dead-space penalty grows for residuals in unusable classes (> max next item is fine though)
        if pr < 10 {
            score += 30.0; // tiny unusable sliver
        }
    }

    // Harmonic class: modulo-10 bands of post_residual
    let band = pr % 10;
    score += (band as f64) * 0.8;

    // Next item lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
        // harmonic coupling: next item divides residual nearly evenly
        let diff = pr - next_item_size;
        if diff <= 5 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportional to waste
        score += ((next_item_size - pr) as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Many fitting bins: prefer the one with least waste anyway (post_residual term does that)
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New empty bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // A fresh bin has post_residual = C - item; good for big items
        if item_size >= 60 {
            score -= 15.0; // big items better in fresh bins
        }
        if fit_quality < 0.35 && open_bins_count > 0 {
            score += 25.0; // penalize opening bin for small items when fits exist
        }
        score += open_bins_count as f64 * 0.5; // mild consolidation pressure
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's fragmented
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    if res_frac < mean_residual / bin_capacity as f64 - 0.2 {
        score += 5.0;
    }

    // Stream progression: late in stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 60.0; // dead space too small for typical future items
    }
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Next-item lookahead: if the residual left can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0; // gap that blocks the known next item
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are open and mean residual is usable.
        score += 30.0 + pressure * 2.0;
        if mean_residual >= item_size as f64 {
            score += 40.0;
        }
    } else {
        // Slight preference for fuller bins among open ones.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / 100.0).max(0.0);

        // Perfect lookahead fit: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item fits with room to spare in this bin: mild reward.
        else if post_residual >= next_item_size {
            score -= 12.0;
        }
        // Next item won't fit: penalize creating tight dead space.
        else {
            score += 8.0;
        }
    }

    // Penalize small unusable dead space (< 10, min item size) harder than large residuals.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 25 {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative to mean residual: bins tighter than average are more valuable.
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * -1.0;

    // New empty bin candidate: prefer it only when item is huge relative to typical
    // residuals and few bins fit; otherwise keep it as fallback.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size > 70 {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Penalize large dead space quadratically once it becomes unusable
    // for typical items (worst item can be up to 80... but interface says
    // sizes up to 100, so residual >= 100 is never "dead").
    let dead_threshold = (bin_capacity as f64 * 0.35).max(20.0);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many options exist, to sharpen discrimination
        // among good fits (small post_residual still wins).
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement (creates a perfect two-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportional to waste.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing an existing bin unless the fit there is poor.
        // Give the new bin a moderate penalty that shrinks when the item
        // is large relative to capacity (big items deserve fresh space)
        // or when existing bins are nearly full on average.
        let size_frac = item_size as f64 / bin_capacity as f64;
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        let mut new_bin_penalty = 45.0
            - 25.0 * size_frac
            - 20.0 * mean_fill.clamp(0.0, 1.0);
        // Late in the stream, consolidating matters less; slightly favor
        // opening bins for clean packing.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        new_bin_penalty -= 5.0 * progress;
        // If no existing bin can even fit the item, opening is mandatory:
        // fitting_bins_count counts fitting open bins; when called for the
        // new bin this is still reported, so use it.
        if fitting_bins_count == 0 {
            new_bin_penalty = -100.0;
        }
        score += new_bin_penalty.max(-100.0);
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; reward placements that reduce fragmentation (tight fits
    // in fragmented regimes).
    if open_bins_count > 3 {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= frag * (post_residual as f64) * 0.3;
    }

    // Time horizon: early in the stream, keep bins balanced for future
    // flexibility; late in the stream, just pack tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let balance_bonus = (1.0 - progress) * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64) * 8.0;
    score -= balance_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters more (long future to reuse bins); later, relax.
    let progress_coupling = 1.0 - 0.6 * progress * progress;
    score *= progress_coupling;

    // Non-linear interaction: penalize leaving residuals that no typical item can use.
    let dead_penalty = (norm_pr * (1.0 - norm_pr)).sin().powi(2);
    score += 12.0 * dead_penalty * norm_pr;

    // Lookahead coupling: reward if next item fits into post_residual (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_margin = (pr - nxt) / cap;
        let kernel = (-fit_margin * fit_margin * 8.0).exp();
        score -= 6.0 * kernel * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_item * norm_item);
    }

    // Penalize fragmenting bins when many bins are open and mean residual is low.
    let frag = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (mean_residual / cap);
    score += 10.0 * frag * norm_pr;

    // New-bin candidate: make empty bin moderately attractive only when it avoids bad fits.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.4 * progress) + 8.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when open bins waste space badly
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 25.0
            - 15.0 * fit_quality
            - 8.0 * (fitting_bins_count == 0) as f64
            - 5.0 * ((open_bins_count as f64).ln().max(0.0)) * (mean_residual / bin_capacity as f64);
        return score;
    }

    // Harmonic class logic: classify post_residual into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals that cannot host small items (1..10) are useless
    // class 0 => perfectly closed bin (great), class 1..9 => dead space of size class
    match class {
        0 => score -= 6.0,
        1 | 2 | 3 => score -= 1.5,
        4 | 5 | 6 => score += 0.5,
        _ => score += 2.0,
    }

    // Integer-division thresholds: post_residual quarters
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 3.0; // nearly full bin: good, but slight preference ordering handled by base score
    } else if pr < quarter * 2 {
        score -= 2.0;
    } else if pr < quarter * 3 {
        score -= 3.5;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward leaving room that exactly accommodates the next item (harmonic match)
            let slack = (pr - next_item_size) % 10;
            score -= 4.0;
            if slack == 0 {
                score -= 2.5; // perfect two-item packing
            }
        } else {
            // post residual too small for next item: penalize proportionally to dead space
            score += (pr as f64) * 0.05;
            if pr < 10 {
                score -= 2.0; // tiny dead space is fine, effectively closed
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Stream progression: late in stream, prefer tightening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when open bins are loose on average, reward filling this one
    score -= 0.02 * (mean_residual - pr as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // any plausible future item (<= 20) are nearly worthless "dead space".
    if post_residual > 0 && post_residual <= 20 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual > 20 && post_residual <= 40 {
        // Moderately awkward gap: partial penalty
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here: penalize proportionally to wasted space
            score += 6.0;
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading load;
    // prefer filling existing bins over opening new ones.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate (empty bin): make it attractive only when the fit
    // is clean and open-bin pressure is low; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        // Baseline penalty so it loses against decent fits in open bins
        score += 45.0;
        // But if item fills the new bin well and few bins are open, ease it
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * fill;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large, a fresh bin may be the right host
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean
    // (i.e., it is the "odd small" bin), using it cleans up fragmentation.
    let dev = mean_residual - bin_residual as f64;
    if dev > 15.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose residual exactly matches.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but penalize leftover slack after that hypothetical placement.
            let after_next = post_residual - next_item_size;
            score -= 200.0 - after_next as f64;
        } else {
            // Next item cannot follow here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Dead-space penalty: small unusable residuals are wasteful unless item is huge.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare residual against mean residual across open bins.
    let residual_f = bin_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += mean_gap * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / residual_f.max(1.0) as f64;
    score -= fill_ratio * 50.0;

    // New-bin candidate: empty bin gets a moderate default so it is chosen only
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // Late-stream adjustment: slightly prefer consolidating into fewer bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 4.0 * (post_residual as f64 / 100.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln_1p();
        score += 18.0 + 12.0 * open_pressure * (1.0 - 0.5 * progress);
        // But allow opening when mean residual is very low (all bins nearly full).
        if mean_residual < 12.0 {
            score -= 25.0;
        }
    }

    // Mild penalty for bins far below mean residual (avoid fragmenting large gaps).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.15 * dev;
        }
    }

    // Prefer filling bins that are already heavily loaded (consolidation).
    let load_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * load_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: post_residual shaped by smooth polynomial in progress.
    // Early on, prefer tight fills (low post_residual strongly rewarded);
    // late, dead space matters even more.
    let w = 1.0 + 1.5 * progress * progress;
    let mut score = post * w;

    // Smooth quadratic coupling of post_residual with mean residual:
    // penalize bins whose leftover deviates from fleet average (fragmentation).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev;

    // Reward near-perfect fits with a smooth cubic term in normalized fill.
    let fill = 1.0 - post / cap;
    score -= 8.0 * fill * fill * fill;

    // Lookahead: if next item fits snugly into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = post - next_item_size as f64;
        score -= 4.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how much it overshoots.
        score += 2.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize so we only open a new bin when no open bin
    // fits well, with penalty easing as stream progresses / many bins open.
    if bin_residual == bin_capacity {
        let escape = 6.0 + 6.0 * (1.0 - progress);
        score += escape;
        // If no open bin can fit the item at all, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small, awkward" residue classes are penalized (dead space).
    let post = post_residual;
    let class_mod: u32 = 7;
    let awkward = post % class_mod; // residue class of leftover
    score += awkward as f64 * 1.7;

    // Integer-division thresholds: leftover that could host a mid-size item
    // is valuable; leftover too small for anything is dead space.
    if post == 0 {
        score -= 60.0; // perfect closure
    } else if post < 10 {
        score += 25.0; // unusable sliver
    } else if post <= 20 {
        score -= 12.0; // hosts small items
    } else if post <= 35 {
        score -= 20.0;
    }

    // Fraction-of-capacity harmonics on residual before placement
    let residual_frac = bin_residual as f64 / cap_f;
    if (residual_frac * 4.0).fract() < 0.05 {
        score -= 6.0; // quarter-alignment bonus
    }

    // Lookahead coupling: prefer bins whose post_residual fits next item well
    if next_item_size > 0 {
        if post >= next_item_size {
            let slack = (post - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap_f);
        } else {
            score += 10.0; // next item won't fit here
        }
        // Harmonic match: post_residual and next_item_size share residue class
        if post % class_mod == next_item_size % class_mod && post >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
        // open early if mean residual is high (fragmented state)
        score -= (mean_residual / cap_f) * 10.0;
    }

    // Late in stream: tighten packing, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // Prefer filling bins that are already relatively full
    score -= (1.0 - residual_frac) * 5.0;

    // Mild penalty for bin sprawl
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are
    // worthless; gaps below the typical item floor are nearly worthless.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // unusable sliver -> strongly penalize
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small usable leftovers).
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    } else {
        score -= 40.0; // perfect fill is excellent
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if it cannot fit, this bin's leftover becomes dead for the next step.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; a new empty bin is penalized.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins whose residual is below average (tighter bins) to keep
    // large residuals available for large future items.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: post_residual within a small window of next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap <= 10 {
            score -= (10 - gap) as f64 * 1.5;
        }
    }

    // Penalize tiny dead space (< 10) that likely can never be used.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tiny.
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual < 15.0 {
            score -= 45.0; // existing bins are nearly full; new bin is fine
        }
    }

    // Prefer bins whose residual is below mean (consolidate large spaces).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in stream: be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that can't hold typical future items.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else if pr < 20.0 {
            score += 10.0;
        }
    } else {
        score -= 8.0; // perfect fill
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 5.0 + 0.05 * ni;
        } else {
            score += 0.04 * (ni - post_residual as f64).min(40.0);
        }
    } else {
        // Last item: any bin that fits is fine, prefer exact fill.
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin, reduced late in the stream or with many bins.
        let mut new_penalty = 30.0 - 20.0 * progress;
        if open_bins_count > 8 { new_penalty -= 6.0; }
        // If mean residual across open bins is large, packing into open bins is easy.
        new_penalty += 0.15 * mean_residual.max(0.0);
        // If the item is large relative to capacity, new bin is more acceptable.
        new_penalty -= 0.1 * item_size as f64;
        score += new_penalty.max(-5.0);
    }

    // Mild preference to fill bins with lower residual (consolidate).
    score += 0.03 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: reward tight fits (small post_residual) with a non-linear convex penalty.
    let mut score = post * post / cap + 0.8 * post;

    // Smooth coupling: tight fits matter more as the stream progresses.
    let tightness = 1.0 - post / cap;
    score -= 6.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize near-full bins that leave dead space unusable by typical items,
    // but only mildly — smooth in post_residual.
    let dead = (post / cap).powi(3);
    score += 10.0 * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Penalize wasting space the next item could have used.
        score += 3.0 * (1.0 - (post_residual as f64) / (next_item_size as f64 + 1.0)).abs();
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score = cap * 0.9;
        // Cheaper to open early (bins are cheap when few are open).
        score -= 20.0 * (1.0 - progress);
        // If alternatives are plentiful and decent, make new bin unattractive.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // If the only fitting bin would leave a large dead space, prefer a new bin.
        if fitting_bins_count == 1 {
            let worst_post = (bin_residual as f64 - item_size as f64).max(0.0);
            if worst_post / cap > 0.35 {
                score -= 15.0;
            }
        }
    }

    // Mild global pressure: many open bins -> prefer consolidation (lower post wins harder).
    score += (open_bins_count as f64).sqrt() * 0.5 * (post / cap);

    // Mean-residual coupling: when mean residual is small, avoid fragmenting.
    score += 2.0 * (mean_residual / cap) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1) is never wasted, so weight absolute tightness.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Harmonic class: classify post_residual by capacity fraction bands.
    // Residuals in the "awkward middle" (roughly 30-60% of capacity) are
    // attractive landing zones for future items; very small residuals are
    // nearly dead. Penalize leaving residual in the awkward band.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let band = (pr / cap * 4.0).floor(); // 0..4 harmonic quarters
    match band as u32 {
        0 => score -= 5.0,          // nearly full: excellent closure
        1 => score -= 2.0,          // small residual, still usable
        2 => score += 8.0,          // awkward middle: half-ish residual
        _ => score += 2.0,          // mostly empty: like a new bin
    }

    // Exact power-of-two / integer-division harmonics: residual divisible
    // into common item classes (10,20,25,50) is reusable.
    if post_residual > 0 {
        let r = post_residual;
        if r % 50 == 0 || r % 25 == 0 || r % 20 == 0 || r % 10 == 0 {
            score -= 6.0;
        }
        // modulo-5 smoothness bonus
        if r % 5 == 0 {
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual too small for next item: mild penalty for stranding space
        score += 6.0;
    }

    // New-bin candidate logic: an empty bin should only win when open bins
    // fit poorly. Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open
        } else {
            // base cost of a new bin, softened if many bins are open and
            // mean residual is fragmented (high mean residual = poor fits).
            let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
            let pressure = (open_bins_count as f64).ln().max(0.0) / 3.0;
            score += 40.0 - 15.0 * fragmentation - 10.0 * pressure;
            // if lookahead item is large, fresh bin is more valuable
            if next_item_size >= bin_capacity / 2 {
                score -= 10.0;
            }
        }
    }

    // Mild stream-phase modulation: late in the stream, consolidate harder.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * phase * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the next item are semi-dead: moderate penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no open
    // bin offers a decent fit (item large relative to residual) or all fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64) > 60.0
            && item_size < bin_capacity;
        let crowded = open_bins_count as f64 > 8.0 + mean_residual / 10.0;
        if poor_fit || crowded {
            score -= 45.0;
        } else {
            // Prefer filling existing bins early in the stream.
            score += 35.0 + 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Slight preference for bins whose residual deviates from the mean the least
    // (keeps residual distribution homogeneous and usable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 40.0;

    // 2-step lookahead: strongly reward a post_residual that exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += slack * 0.6;
            if slack <= 10.0 {
                score -= 25.0; // near-perfect two-item packing
            }
        } else {
            // next item cannot follow into this bin; penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Compare against mean residual: prefer bins whose post_residual sits near/below mean
    // (keeps the pool of usable residuals homogeneous and avoids outlier dead space).
    let mean_post = mean_residual - item_size as f64;
    let deviation = (post_residual as f64 - mean_post).abs();
    score += deviation * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
        // extra reward if the fit is tight
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it attractive
    // only when no open bin offers a good fit (post_residual large relative to capacity
    // and item is large), otherwise prefer reusing open bins.
    if bin_residual == bin_capacity {
        if post_residual as f64 >= bin_capacity as f64 * 0.2 && item_size >= 50 {
            score -= 15.0; // large items justify fresh bins
        } else {
            score += 25.0; // discourage opening bins for small items / good fits exist
        }
        // early stream: allow more bins to spread load
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 10.0;
        }
    }

    // Slight preference for bins that are already fairly full (low residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mild penalty for proliferation of open bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual waste).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins fit: prefer bins with least residual anyway.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead coupling: if the next item could use the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly-ish in leftover: good.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space proportionally.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += dead * 0.25;
            }
        }
    } else {
        // Last item: purely minimize waste.
        score += post_residual as f64 * 0.5;
    }

    // Global state: when mean residual is high, prefer using fuller bins (larger residual gap).
    score += (mean_residual - post_residual as f64) * 0.08;

    // Time horizon: early in stream, be conservative about fragmenting bins;
    // late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // New-bin candidate handling: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If current item is large relative to capacity, opening fresh bin is less bad.
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
        // If many bins are open and mean residual is low, a new bin is more acceptable.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        // If next item is large and mean residual is small, new bin is attractive.
        if next_item_size > 0 && (mean_residual < next_item_size as f64) {
            score -= 10.0;
        }
    }

    // Small penalty for leaving residual in awkward dead zone (1..10 unusable range).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = (item_size, bin_residual, bin_capacity, step_index, total_items, open_bins_count, mean_residual, next_item_size, post_residual, fitting_bins_count);
