}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5 harmonic bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Class index via integer division thresholds (0..4).
    let class = (post_residual * 5) / bin_capacity; // 0..4
    let class_penalty = match class {
        0 => 0.0,          // near-perfect fill
        1 => 6.0,          // small dead space
        2 => 14.0,         // awkward mid residual
        3 => 22.0,         // poor residual
        _ => 30.0,         // nearly empty bin wasted
    };
    score += class_penalty;

    // Non-linear reward for tight fits: quadratic bonus shrinking post residual.
    score -= (cap_f - post_f) * 0.35;

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (5, 10, 20, 25) are more "usable" by future items.
    let usable = post_residual % 5 == 0 || post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0;
    if usable {
        score -= 8.0;
    } else if post_residual > 0 {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Prefer residuals that leave next_post in a good class.
            let next_class = (next_post * 5) / bin_capacity;
            let bonus = match next_class {
                0 => 25.0,
                1 => 15.0,
                2 => 8.0,
                _ => 0.0,
            };
            score -= bonus;
            // exact harmonic compatibility via modulo
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; softened late in stream or when crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 45.0 - 15.0 * progress;
        if open_bins_count == 0 {
            open_cost = -100.0; // must open
        }
        // If many bins fit the item, opening is worse; if few, cheaper.
        open_cost += (fitting_bins_count as f64) * 12.0;
        // Mean residual high => existing bins have room; opening is worse.
        open_cost += mean_residual * 0.4;
        score += open_cost;
    }

    // Mild penalty for spreading across many bins when this bin is loose.
    if open_bins_count > 3 && frac > 0.5 {
        score += 4.0;
    }

    // Progress-based tie-breaking: prefer tighter consolidation early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (post_residual near zero but still "clean").
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    score += pressure * 3.0;

    // New-bin candidate handling: only attractive if this bin is fresh AND the
    // current bin choice would leave awkward dead space, or no bins fit well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset when it avoids dead space.
        score += 20.0 + pressure * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item may pair with this one in a fresh bin.
            score -= 10.0;
        }
        // Discourage opening a new bin when a decent fit already exists.
        if fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) >= 15.0 {
            score += 15.0;
        }
    }

    // Lookahead coupling: if the next item could exactly consume this bin's
    // post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; small residual is acceptable.
        score += 2.0;
    }

    // Mild preference for filling bins below mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with little slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit here: penalize leaving awkward dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual (below-average residual = well-utilized bin).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize when many bins compete (prefer consolidating into fewest bins).
    score += 0.1 * open_bins_count as f64;

    // New-bin candidate: only attractive when item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.8 {
            score -= 20.0;
        } else {
            score += 10.0 + 20.0 * (1.0 - fill);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize small post_residual (lower score = better).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Strong reward for exact fill.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: mild penalty proportional to waste.
            score += 0.15 * post_residual as f64;
        }
        // Perfect lookahead fit is very attractive.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays over the stream as spreading becomes safer.
        let base_cost = 55.0 - 25.0 * progress;
        score = base_cost;
        // If many bins are open and mean residual is large, opening new bins is fine.
        score -= 0.3 * mean_residual;
        // But if item is large relative to capacity, opening a fresh bin is attractive.
        score -= 0.2 * item_size as f64;
        // If many bins already fit the item, discourage new bin.
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
    }

    // Slight preference to fill bins with larger residuals among equally good fits.
    score += 0.02 * bin_residual as f64;

    // Mild penalty when many bins are open, encouraging consolidation early.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // as the stream progresses, tight fits (small post_residual) become increasingly valuable.
    let pr_norm = pr / cap;
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm); // in [0,1], 1 = perfect fit
    let coupling = tightness * (0.5 + 2.0 * progress * progress);
    score -= 25.0 * coupling;

    // Penalize dead space that nothing else could use: quadratic in small residuals
    if pr > 0.0 && (next_item_size as f64) > pr {
        score += 8.0 + 0.5 * pr * pr / cap;
    }

    // Lookahead: reward leaving space exactly sized for the next item (smooth gaussian-like term)
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let fit_next = (-diff * diff / 50.0).exp();
        score -= 12.0 * fit_next;
    } else {
        // last item: strongly prefer perfect fill
        score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer it early or when open bins are already tight/fragmented
    if bin_residual == bin_capacity {
        let mean_frag = mean_residual / cap;
        let new_bin_bias = 20.0 + 60.0 * progress - 30.0 * (1.0 - mean_frag) * (1.0 - mean_frag);
        score += new_bin_bias;
        // if no existing bin fits at all, new bin is the only option anyway
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are large
    score += 0.3 * open_bins_count as f64 * pr_norm * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: items of size 10 partition
    // capacity, so residuals in the same class [k*10, (k+1)*10) behave alike.
    let r_class = post_residual / 10;
    let r_phase = post_residual % 10;

    // Reward residuals that are exact harmonic multiples (perfect packing slots).
    if r_phase == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Penalize dead space: residuals too small for the smallest possible item (1..100 range,
    // but conservative floor of 10 from classic streams).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Class-aware dead-space penalty: residual classes 1..3 (11..39) are hard to fill.
    if r_class >= 1 && r_class <= 3 && post_residual > 0 {
        score += 4.0 * (4.0 - r_class as f64);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's leftover -> penalize proportionally.
        score += 2.0 + (next_item_size - post_residual) as f64 * 0.1;
    }

    // Last-chance bonus: only one open bin fits; avoid forcing a new bin open.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // If many bins already fit the item well, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
        // Early in the stream, opening bins is fine; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If mean residual across open bins can host the item comfortably, discourage new bin.
        if mean_residual > item_size as f64 {
            score += 6.0;
        }
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter existing bins (best-fit sharpening).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight penalty for accumulating too many open bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any post_residual that is too small for the
    // smallest possible item (1..100 interface => treat gap < 10 as near-dead)
    // is unusable waste. Penalize proportionally to how "dead" it is.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Gaps that can't fit the lookahead item are also semi-dead.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 4.0;
    }

    // Reward bins whose residual gets well used (tight fits relative to capacity).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; penalize creating new bins (residual == capacity).
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // But if this bin is the last chance (only one fitting bin) and the fit
        // is decent, opening a new bin is less attractive.
        if fitting_bins_count == 1 && post_residual < 15 {
            score += 120.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin that fits: strongly prefer using it.
        score -= 60.0;
    }

    // Prefer bins with residuals below the mean (tighter bins) to leave
    // larger residuals available for future large items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, be greedier: minimize post residual harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // If lookahead fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leaves further slack: mild reward proportional to tightness.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack_after_next * 2.0;
        } else {
            // next item cannot fit here: penalize leaving dead space that blocks the next item.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 1.5;
        }
    }

    // Penalize small unusable dead space (< 10) more than larger slack.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer bins tighter than the mean residual (good fits cluster).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: keep it neutral-to-slightly-high so it is only chosen
    // when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty when many bins are open: encourage closing bins out.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize small unusable post_residual (dead space below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins would waste space badly.
    if bin_residual == bin_capacity {
        let waste_if_forced = (bin_residual - item_size) as f64;
        let mean_waste = mean_residual - item_size as f64;
        if mean_waste < waste_if_forced - 5.0 {
            // Existing bins waste less -> penalize opening a new bin.
            score += 30.0 + 0.5 * open_bins_count as f64;
        } else {
            // Existing bins would waste more -> mildly encourage a fresh bin,
            // scaled down as the stream progresses (fewer chances to amortize).
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= (20.0 - 15.0 * progress).max(2.0);
        }
    }

    // Lookahead: if next item fits into this bin's post_residual, reward placement here.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if post_residual after next item stays tight.
        let after2 = post_residual - next_item_size;
        if after2 < 10 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; mild penalty for leaving fragmented residual.
        score += 3.0;
    }

    // Prefer filling bins with larger residual (consolidate emptier bins),
    // but only when many bins are open (fragmentation pressure).
    if open_bins_count > 4 {
        score += 0.05 * (mean_residual - bin_residual as f64).abs();
        if (bin_residual as f64) > mean_residual + 10.0 {
            score -= 4.0; // use the emptier bins first
        }
    }

    // Early stream: slightly prefer keeping bins homogeneous for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 40 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let fill = 1.0 - pr / cap; // fraction of capacity used after placement

    // Base: prefer small post residual, non-linearly amplified.
    let mut score = pr * (1.0 + 0.9 * (pr / cap).powi(2));

    // Reward high fill ratio with a smooth cubic bonus (negative = favored).
    score -= 18.0 * fill * fill * fill;

    // Perfect-fit attraction: strong quadratic reward as post_residual -> 0.
    score -= 30.0 * (1.0 - pr / cap).powi(6);

    // Dead-space penalty: mid-range residuals are least useful; smooth bump via sin.
    let dead = (pr / cap - 0.5).abs();
    score -= 6.0 * (1.0 - 4.0 * dead * dead).max(0.0);

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).abs();
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (1.0 - gap / cap).max(0.0);
        // Penalize if this placement leaves exactly a sliver the next item can't use.
        score += 4.0 * (1.0 - fits_next) * (1.0 - pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && br < cap {
        score -= 25.0;
    }

    // Stream progress: early on, be picky (penalize loose fits); late, pack greedily.
    score += 12.0 * (1.0 - progress) * (pr / cap);
    score -= 8.0 * progress * fill;

    // New-bin candidate: residual == capacity. Prefer it only for large items or
    // when open bins are all nearly full (mean_residual small) or many bins exist.
    if br >= cap {
        let pressure = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = (it / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
        score = cap as f64 * 1.5
            - 20.0 * large_item
            - 15.0 * (1.0 - pressure)
            - 10.0 * openness
            + 15.0 * (1.0 - large_item) * pressure;
    }

    // Mild penalty for scattering across too many open bins relative to progress.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space in low modulo classes is more usable.
    let m = post_residual % 10;
    let class_bonus: f64 = match m {
        0 => 6.0,           // exact decade residual: very reusable
        1..=4 => 3.0,       // small usable slivers
        5..=9 => -2.0,      // awkward dead space just under a decade
    };
    score -= class_bonus;

    // Integer-division threshold: bins whose post_residual can host the next item get priority.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if post_residual is in the same decade class as next item
            if (post_residual / 10) == (next_item_size / 10) {
                score -= 4.0;
            }
        } else {
            // Penalize dead space that cannot host the lookahead item,
            // scaled by how close we were (wasted potential).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish score.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the fit here is poor
        // (large post_residual) or many bins are open with slack.
        score += 5.0;
        score -= 0.05 * (post_residual as f64);
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
        // If item is small relative to capacity, a fresh bin wastes space.
        score += 0.1 * (bin_capacity - item_size) as f64 * 0.1;
    }

    // Mean-residual coupling: prefer bins close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fit_ratio;

    // Small penalty for very large post_residual (hoarding large space for small item).
    if post_residual > 40 {
        score += 0.1 * (post_residual - 40) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: gaps that are too small to hold
    // even the minimum item size are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    // Gaps that can only hold a tiny item are nearly dead too.
    else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if next item cannot fit in the leftover gap (dead end).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating
    // into existing bins rather than spreading out.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    // Its raw post_residual (100 - item_size) is naturally large, so it
    // loses to decent fits. Only give it a modest edge when the item is
    // large (existing bins would leave a big unusable gap anyway).
    if bin_residual == bin_capacity {
        let gap_if_existing = 10.0_f64.min(1.0); // neutral placeholder scale
        let _ = gap_if_existing;
        let would_waste = (bin_capacity - item_size) as f64;
        if would_waste < 10.0 {
            // Opening fresh with a large item leaves an almost-dead gap too,
            // but at least it's a clean bin: slight reward.
            score -= 10.0;
        } else {
            // Default: opening a new bin is costly, mild penalty.
            score += 6.0;
        }
    }

    // Mean residual coupling: when open bins are already very full
    // (low mean residual), prefer squeezing into them.
    score -= mean_residual * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fill (post_residual small).
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-gap / 10.0).exp();
        // If next item fits perfectly after this placement, big bonus.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins already tighter than average
    // (consolidate), penalize using bins looser than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.4 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when many bins are open and could fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no other bin fits well, opening is fine: reduce penalty when
        // item is large relative to capacity.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
    }

    // Prefer tight fits: small residual relative to capacity is good.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / cap;
    score += 25.0 * waste_ratio * waste_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 18.0 * (next_item_size as f64 / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to stranded space.
            score += 6.0 * (1.0 - (next_item_size as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding pressure: when many bins are open, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += crowd * 4.0 * (1.0 - progress);

    // New-bin candidate handling: penalize opening a new bin, but allow it when
    // existing residuals are poor relative to the item (avoid dead-space traps).
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let item_frac = item_size as f64 / cap;
        // Base cost of a new bin, reduced when open bins are fragmented.
        score += 30.0 - 25.0 * mean_tightness - 10.0 * item_frac;
        // Early in the stream, new bins are cheaper (more future items to fill them).
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates far from mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0,1]
    let r = post / cap;

    // Smooth polynomial coupling: post_residual weighted by stream progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let progress_weight = 0.6 + 0.8 * progress * progress;

    let mut score = post * (1.0 + 0.5 * r * r) * progress_weight;

    // Non-linear interaction between post_residual and mean residual:
    // prefer bins whose post_residual is close to (below) the mean residual,
    // i.e. don't fragment bins that are already tight relative to fleet mean.
    let diff = post - mean_residual;
    score += 0.15 * diff * diff / cap;

    // Dead-space penalty: post_residual too small to fit typical future items.
    // Smooth quadratic trough around residual == next_item_size (if lookahead exists).
    if next_item_size > 0 {
        let nl = next_item_size as f64;
        let d = post - nl;
        score += 0.25 * (d * d) / (nl + 10.0);
        // Reward leaving exactly room for the next item (smooth gaussian-like dip)
        score -= 12.0 * (-(d * d) / (2.0 * (nl * 0.5 + 5.0))).exp();
    } else {
        // Last item: purely minimize waste
        score += 2.0 * r * r * cap;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 6.0 * progress;
    }

    // New-bin candidate (empty bin): penalize when open bins could fit,
    // with a smooth decay so late-stream consolidation is preferred.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 10.0 + 8.0 * (1.0 - progress) + 0.5 * open_f.sqrt();
        // But if item would leave a very flexible residual, soften the penalty
        score -= 6.0 * (-(r * r) / 0.02).exp();
    }

    // Mild reward for tight fits overall (smooth, non-linear)
    score -= 5.0 * (-(r * r) / 0.08).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by residue class mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead space penalty: tiny leftovers (1..=9) are nearly unusable
    if pr > 0 && pr < 10 {
        score += 25.0; // strongly penalize creating dead slivers
    } else if class == 0 {
        score -= 6.0; // perfectly divisible leftover is reusable
    } else if pr >= 10 && pr <= 30 {
        score -= 2.0 + (30.0 - pr as f64) * 0.1; // mid-small leftovers mildly favored
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize less if post_residual is small (bin nearly closed)
            if pr >= next_item_size as u32 {
                score += 0.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base offset so it's chosen
    // only when open bins would create bad fits
    if bin_residual == bin_capacity {
        score += 18.0;
        // early in stream, slightly prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // if next item is large, opening fresh bin is attractive
        if next_item_size >= 50 {
            score -= 5.0;
        }
    }

    // Prefer filling bins that are already relatively full (tight packing)
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= 4.0 * fill_ratio;

    // Mean residual coupling: when mean residual is high, prefer bins below mean
    // (keep tight bins for later small items)
    if (bin_residual as f64) > mean_residual {
        score += 1.5;
    } else {
        score -= 1.0;
    }

    // Many open bins: encourage closing bins out to reduce spread
    if open_bins_count > 8 && pr <= 15 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0) + 15.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (post_residual near zero but exactly zero is perfect).
    if post_residual == 0 {
        score -= 30.0;
    } else {
        // Fractional utilization of this placement.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += 3.0 * open_pressure;

    // Deviation from mean residual: prefer bins whose residual is below average
    // (concentrate filling into already-partially-used bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item could fit into this bin's post_residual,
    // reward keeping that pairing alive; otherwise penalize wasted potential.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is viable only when no
    // open bin offers a decent fit. Give the empty bin a mild handicap so it
    // only wins when existing bins are truly poor (large dead-space penalties
    // above push those bins past this baseline).
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheap and keeps options open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Extra bonus for exact match (post_residual becomes zero after next item).
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins with residual close to item needs.
    let mr = mean_residual.max(0.0);
    if (post_residual as f64) < mr {
        score += 0.3 * (mr - post_residual as f64);
    } else {
        score -= 0.15 * (post_residual as f64 - mr);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize opening a new bin when the item fits comfortably elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only for poor fits.
        score += 25.0;
        // Scale penalty down if current item is large relative to capacity.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Slight preference early in the stream to consolidate (fewer open bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover space; mild penalty.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Global residual pressure: if mean residual is low, protect this bin's space.
    score += 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: penalize opening a new bin, but allow it
    // when existing bins would leave very awkward fits and the item is large.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 10.0 * (1.0 - progress);
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 / bin_capacity as f64) * 25.0
        };
        score += base_penalty + desperation;
        // A new bin is attractive for very large items that would waste open bins.
        if item_size >= 70 && post_residual <= 30 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, slightly discounted early (waste tolerated when many items remain)
    let mut score = post * (1.0 - 0.35 * (1.0 - progress));

    // Smooth polynomial coupling: residual value depends on progress
    score += 40.0 * norm_post * norm_post * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits more as stream progresses
    score -= 25.0 * norm_item * norm_item * progress;

    // Lookahead: penalize if post-residual can't fit the next item (dead space), reward if it can
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * norm_next * (0.5 + progress);
        } else {
            score += 15.0 * norm_next * (0.4 + 0.6 * progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    let mean_norm = mean_residual / cap;
    score += 10.0 * (norm_post - mean_norm) * (norm_post - mean_norm);
    score -= 8.0 * norm_post * mean_norm * progress;

    // New-bin candidate: penalize opening a new bin, more so mid-stream when consolidation matters
    if bin_residual == bin_capacity {
        score += 18.0 + 22.0 * progress * (1.0 - progress).powf(0.5);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // "harmonic" steps (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 5.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        score -= bonus;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Next-item lookahead: reward residuals that still fit the next item
    // (keeps bins useful), penalize residuals that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it is
    // chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 30.0
            + 0.15 * mean_residual
            - (open_bins_count as f64).ln() * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big next item: fresh bin is attractive
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative anyway
        }
    }

    // Fractional capacity coupling: prefer post-residuals that are small
    // fractions of capacity.
    let frac = post_residual as f64 / cap;
    score += frac * frac * 20.0;

    // Slight stream-progress bias toward consolidating into fewer bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (fitting_bins_count.max(1) as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // likely dead space
        } else if post_residual < 30 {
            score += 8.0;
        } else {
            score -= 5.0; // large leftover remains useful
        }
    } else {
        // Perfect fit: fully closed bin, strongly rewarded.
        score -= 40.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item could exactly use the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit in leftover: mild penalty proportional to waste.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates usefully
    // from the mean (tighter-than-average bins get priority).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if item_size >= 50 {
            score += 45.0; // prefer existing bins for large items
        } else {
            score += 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward exact fill heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 50.0 * tight;
        } else {
            // Next item won't fit here: penalize leaving residual close to but below next_item_size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize small unusable residuals (dead space), but less if the item is large.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer bins with residual below mean residual (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference to fill older/denser bins when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when current fit is very poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 100.0 * (1.0 - poor_fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is best.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chained placement).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else if next_item_size > post_residual && post_residual < 10 {
            // Dead space too small for typical items: mild penalty.
            score += 6.0;
        }
        // If next item cannot fit anywhere else but fits here after this placement.
        if next_item_size <= post_residual && next_item_size > bin_residual - item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize new-bin candidate unless the item fits poorly in all open bins.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen when fit is bad.
        score += 30.0;
        // If this bin is the only fitting one, opening new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
        // Early in stream, opening bins is cheap (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
        // If many open bins already, discourage spreading.
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer bins with residual below mean (consolidate into emptier bins).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.15;

    // Mild time-horizon modulation: later in stream, favor tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += tightness * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Normalized post-residual
    let x = pr / cap;

    // Core: prefer small post-residual (tight fit), smooth polynomial coupling
    let mut score = x * (2.0 + 3.0 * x);

    // Reward tight fits more strongly as stream progresses (consolidation effect)
    score -= (1.0 - x) * (1.0 - x) * (0.5 + 2.0 * progress);

    // Penalize dead space that is too small to be useful later (smooth trough)
    // Items >= 10 typically; dead space below ~10 is unusable
    let min_useful = 10.0f64;
    if pr < min_useful {
        score += (min_useful - pr) * (min_useful - pr) * 0.05;
    } else {
        // mild smooth penalty for mid-range waste
        score += 0.1 * (x * (1.0 - x));
    }

    // Lookahead: if next item fits comfortably in the post-residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack) * (0.8 + 1.2 * progress);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += ((nx - pr) / cap) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate: penalize by default; relax when many bins fit poorly
    if is_new_bin {
        let mut penalty = 6.0 + 0.05 * open_bins_count as f64;
        // allow opening a new bin when it's the only "fitting" candidate
        if fitting_bins_count <= 1 {
            penalty -= 4.0;
        }
        // early stream: opening bins is cheaper
        penalty -= 2.0 * (1.0 - progress);
        score += penalty.max(0.0);
    }

    // Mild diversity term: prefer bins below mean residual (keeps large residuals available)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead zones"
    // (small but unusable) are penalized more than large usable gaps.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual below the smallest item size is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo-10 harmonic classes: prefer residuals that are multiples of 10
    // (classic sizes align well with capacity 100).
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.8;

    // Integer-division thresholds on post_residual: reward "half-full" style
    // sweet spots where another medium item still fits comfortably.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 6.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportional dead space.
        score += (next_item_size as f64 - pr).max(0.0) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits the item, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it mildly
    // unattractive unless the item is large (better to fill a fresh bin with
    // big items than fragment an old one) or no good alternative exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac >= 0.5 {
            score -= 8.0; // large items start fresh bins happily
        } else {
            score += 10.0 + 15.0 * (1.0 - frac); // small items prefer existing bins
        }
    }

    // Stream progression: late in the stream, consolidate; early, allow spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Coupling with mean residual: if this bin's residual is far below the mean,
    // it is already "tight" — prefer filling tight bins.
    let tightness = (mean_residual - bin_residual as f64) / cap;
    score -= tightness * 5.0;

    // Many open bins: encourage consolidation.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in unusable small gaps is heavily penalized.
    // A residual that can't fit the smallest plausible item (1..=100 range) is pure waste.
    let min_useful = 1u32;
    if post_residual < min_useful {
        score += 1000.0;
    }

    // Penalize residuals too small to fit the lookahead item (likely dead space for next item)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits strongly (waste minimization via non-linear tightness bonus)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading; prefer consolidation
    // into existing bins, making the new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportionally to open bin pressure and
        // remaining stream length; only attractive when existing fits are terrible.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 2.0 * open_bins_count as f64 + 15.0 * progress;
        // Slightly more attractive early in the stream
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bin: mild reward for keeping bin count low
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (consolidate into emptier bins, keep tight bins intact)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual still fits the next item: mild reward proportional to closeness of fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.12 * slack;
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space relative to next item size.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.25 * dead;
    }

    // Reward tight fills relative to bin capacity (small post_residual is good, but avoid 1..5 slivers).
    if post_residual > 0 && post_residual <= 5 {
        score += 10.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Compare against mean residual across open bins: prefer bins with residual near/below mean
    // (concentrate filling), penalize filling already-tight bins that others could use better.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.10 * (res - mean_residual);
    } else {
        score += 0.10 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate (residual == capacity): opening a new bin should only win when
    // existing fits are terrible. Give it a baseline penalty that shrinks as the stream matures.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 15.0 * progress;
        // If next item is large and current bin fits are poor, new bin becomes attractive.
        if next_item_size > 60 && post_residual < next_item_size {
            new_bin_score -= 10.0;
        }
        // With many open bins, spreading out is cheaper than fragmenting.
        new_bin_score += 0.5 * open_bins_count as f64;
        return new_bin_score;
    }

    // Slight preference for bins with residual close to item_size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tight fit reward: penalize large post_residual relative to capacity
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 60.0;

        // Reward small residuals that can still fit a plausible future item
        if (post_residual as f64) < mean_residual * 0.5 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Creating dead space that next item can't use: penalize if residual too small
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // If open bins have plenty of slack, penalize opening a new bin
        score += 40.0 * (1.0 - fragmentation);
        // Early in the stream, opening new bins is cheap; later it is costly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If no open bin fits well (post_residual of best would be tiny), new bin is fine
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr;

    // Smooth interaction: residual relative to mean residual across open bins.
    let mr = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    let rel = (pr - mr) / (mr + cap);
    score += 2.5 * rel * rel * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= (1.0 - norm_pr).powi(3) * (1.0 + 3.0 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Penalize when many bins fit the item (dilute priority slightly).
    if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead coupling: reward leaving space close to the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = ((pr - nxt) / cap).abs();
        score += 1.5 * gap * gap - 1.2 * (-((pr - nxt) / 8.0).abs()).exp();
    } else {
        // Last item: strongly minimize post residual.
        score += 2.0 * norm_pr;
    }

    // Mild penalty for bin proliferation early in the stream.
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit wins (post_residual already encodes this).

    // Harmonic class logic: partition post_residual into residue classes mod 10.
    // Residuals that are "harmonically compatible" with common item sizes
    // (multiples of 10) are more reusable than odd dead-space classes.
    let residue = post_residual % 10;
    if post_residual == 0 {
        // Perfect closure: strongly reward.
        score -= 40.0;
    } else {
        // Penalize dead space that is too small to hold any item (1..=9 range
        // classes), scaled by how far into the "unusable" zone we land.
        if post_residual < 10 {
            score += 25.0;
        }
        // Odd residue classes are less likely to be exactly filled later.
        if residue != 0 {
            score += 3.0 + (residue as f64) * 0.4;
        }
        // Reward residuals that match common item-size classes (10..80 multiples of 5).
        if post_residual >= 10 && post_residual % 5 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is harmonic with the stream; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot use this bin's remainder: mild penalty,
            // stronger when the remainder is tiny dead space.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 10.0; // near-perfect closure on the last fitting bin
        }
    } else if fitting_bins_count > 1 {
        // Many options: be pickier about bad fits.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // It should only win when all open fits are bad. Make the empty bin
    // moderately attractive so it beats truly awful fits (huge dead space),
    // but loses to any reasonable reuse.
    if bin_residual == bin_capacity {
        // Score the fresh bin: its post_residual equals capacity, which is
        // naturally large; anchor it to a mid-range value.
        score = (bin_capacity as f64) * 0.55;
        // Early in the stream, opening bins is cheap and good.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
        // If many bins are open with slack, discourage yet another bin.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If the mean residual is large, open bins have room already.
        score += mean_residual * 0.15;
        // But if the next item is huge, a fresh bin is flexible.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Stream-phase modulation: late in the stream, closure matters more
    // (fewer chances to fill leftover space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.05 * progress;

    // Mean-residual context: when open bins are generally slack, prefer
    // placements that reduce variance (tight fits).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any item (min size 1..~10) are pure waste.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Perfect or near-perfect fill -> strong reward.
        score -= 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // Small gap: risky, mildly penalize beyond raw residual.
        score += 12.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bonus: only one bin fits the item; using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins; favor packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (0.5 + 0.5 * progress);

    // New-bin candidate: residual == capacity. Only attractive when placement leaves
    // a large, reusable residual and existing bins are crowded or would waste space.
    if bin_residual == bin_capacity {
        let new_bin_dead = (post_residual as f64) < dead_threshold;
        if new_bin_dead {
            score += 200.0; // never open a bin that immediately becomes dead space
        } else {
            // Base penalty for opening a new bin, softened when many bins are open
            // and mean residual is low (existing bins nearly full).
            let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            score += 55.0 - 45.0 * crowding;
            // Reward if the next item could chain into this residual.
            if next_item_size > 0 && (post_residual as u32) >= next_item_size {
                score -= 15.0;
            }
        }
    } else {
        // Existing bin: reward if lookahead item also fits after placement (chaining).
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 {
            // Lookahead won't fit here; slight penalty proportional to leftover.
            score += 5.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is below average
    // (they are the "fuller" bins), pushing toward concentrating fills.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 6.0 * (mean_residual - bin_res_f) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: prefer bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        if nxt <= post {
            // Next item fits here afterwards: reward closeness to exact match.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            // Big bonus for perfect two-item packing.
            if diff < 0.5 {
                score -= 60.0;
            }
        } else {
            // Next item would NOT fit after this placement: penalize leaving
            // dead space smaller than the next item.
            score += 0.5 * (nxt - post);
        }
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.3 * (mean_residual - post_f);
    } else {
        score += 0.3 * (post_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could accept the item reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral-ish baseline; discourage unless current bin fit is terrible.
        score += 10.0;
        // Early in the stream, opening bins is cheaper (keeps flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - progress);
    } else {
        // Reward tight fits in existing bins.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fit_ratio;
    }

    // Slight preference to keep number of open bins manageable.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Strongly penalize small dead space (post_residual small but nonzero is good;
    // post_residual very small means near-perfect fit -> extra reward).
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 6.0; // near-perfect fit
        } else if post_residual < 20 {
            score -= 2.0;
        } else if post_residual < 40 {
            score += 1.5; // moderately awkward remainder
        }
    } else {
        score -= 10.0; // perfect closure
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize leaving a remainder that strands it
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // bin_capacity; make it attractive only when the item is large relative to
    // capacity or when existing bins are crowded (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Prefer new bin for large items late in stream or when open bins are tight.
        let large_item = item_size as f64 / bin_capacity as f64;
        let attraction = 20.0 * large_item + 10.0 * (1.0 - crowding) + 5.0 * progress;
        score -= attraction;
        // But never open a new bin for a tiny item when other bins exist.
        if item_size < 30 && open_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Penalize placing into a bin whose residual is much larger than the item
        // (wasting a big hole on a small item).
        let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
        score += 4.0 * waste_ratio;
    }

    // Mild pressure to consolidate: fewer open bins relative to stream length
    // favors reusing existing bins slightly.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 0.3;
    }

    // Global mean-residual coupling: when mean residual is high, prefer placements
    // that reduce variance (i.e., empty out small-residual bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: tight fit preferred (small post residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.9 * post_norm * post_norm);

    // Smooth stream-progress coupling: early on tolerate slack, late prefer tight packing.
    score += 12.0 * post_norm * (1.0 - progress) * (1.0 - progress);

    // Penalize leaving dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 * (nxt - post) / cap * (0.5 + progress);
        } else {
            // Reward reserving space for the next item (smooth, not hard).
            score -= 3.0 * (post.min(nxt * 2.0) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - item_norm);
    }

    // Mild penalty when this bin's residual is far from the mean residual (imbalance).
    score += 0.15 * (post - mean_residual).abs();

    // Discourage proliferation of open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Slight reward for larger items filling bins deeply.
    score -= 2.0 * item_norm * item_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "useful" residue classes (multiples of 10 / 25) remain reusable for the
    // common small-item sizes; odd crumbs are penalized heavily.
    let r = post_residual;
    let class_bonus = if r == 0 {
        -60.0 // perfect fill
    } else if r % 25 == 0 {
        -25.0
    } else if r % 10 == 0 {
        -15.0
    } else if r % 5 == 0 {
        -5.0
    } else {
        10.0 + (r % 5) as f64 * 4.0 // awkward crumb: penalize
    };
    score += class_bonus;

    // Tightness reward: the closer the fit relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Dead-space threshold: residuals too small for the smallest item (1..100
    // interface => treat < 12 as near-dead) are strongly penalized.
    if r > 0 && r < 12 {
        score += 35.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * (post_residual as f64);
    }

    // Lookahead: prefer bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive when open bins
    // are crowded (low mean residual) or many bins are already open and
    // fragmented; discourage gratuitous bin opening otherwise.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0
            - 60.0 * crowding
            + 20.0 * progress
            + 3.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && bin_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across many open bins: consolidation keeps
    // future choices concentrated.
    score += 0.15 * open_bins_count as f64;

    // Small nudge toward using bins with lower-than-average residual (denser
    // bins first) to keep large residuals free for large items.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to ever hold another item (or the
    // likely next item) are pure waste: penalize them heavily.
    let pr = post_residual as f64;
    let min_useful = 1.0f64;
    let next_fit = if next_item_size > 0 {
        (post_residual as u32) >= next_item_size
    } else {
        true
    };

    if post_residual > 0 && (post_residual as u32) < 10 {
        // Unusable sliver: dead space forever.
        score += 60.0 - pr; // smaller sliver => larger penalty
    } else if !next_fit && next_item_size > 0 {
        // Gap cannot hold the known next item: likely dead space.
        score += 25.0;
    }

    // --- Tight-fit reward ---
    // Very small post_residual (but still usable) is a perfect packing.
    if post_residual > 0 && (post_residual as u32) <= 5 {
        score -= 40.0;
    } else if next_fit && next_item_size > 0 && (post_residual as u32) - next_item_size <= 5 {
        // Leaves a gap that exactly accommodates the next item.
        score -= 30.0;
    }

    // --- Last-chance bin bonus ---
    // If this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // --- Open-bin pressure ---
    // Fewer open bins is better when residuals are still usable; discourage
    // spreading across many bins when the mean residual is healthy.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 * (1.0 - progress * 0.5);
    score += pressure;

    // Prefer bins whose residual is far from the mean when the mean is
    // large (consolidate big gaps), prefer near-mean bins when mean is small.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual > bin_capacity as f64 * 0.5 {
        score += dev * 0.15;
    } else {
        score -= dev * 0.10;
    }

    // --- New-bin candidate handling ---
    // An empty bin should only win when no open bin offers a decent fit.
    // Make the fresh bin moderately attractive by default but let the
    // dead-space / last-chance terms above dominate.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening new bins is more costly.
        score += progress * 10.0;
        // If many bins are open and mean residual is small, avoid new bins.
        if mean_residual < bin_capacity as f64 * 0.25 && open_bins_count > 2 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Reward perfect / near-perfect closure.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // unusable sliver
    }

    // 2-step lookahead: if the next item exactly matches the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot fit here after placement; mild penalty
            // proportional to the mismatch.
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / 50.0).min(2.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Relative to mean residual: bins with residual near the mean are
    // "typical"; prefer placing into bins below the mean residual
    // (consolidating fuller bins) when fit is decent.
    if bin_residual < bin_capacity {
        let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 4.0 * rel;
    }

    // New-bin candidate: make it unattractive by default, but allow it
    // when the item is large and no tight fit is available.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let large_item_bonus = if item_size > bin_capacity / 2 { 15.0 } else { 0.0 };
        let late_stream = (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        score += base_penalty - large_item_bonus - late_stream;
    }

    // Mild preference for filling already-open bins as stream progresses.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= (cap - post_residual as f64).max(0.0) * 0.35;

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += (nxt - post_residual as f64) * 0.6;
        } else {
            // Reward leaving exactly enough room for the next item.
            score -= 12.0 * (1.0 - ((post_residual as f64 - nxt) / cap).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 40.0;
        // If existing bins are quite full (small mean residual), a new bin is fine.
        let mean_fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 55.0 * mean_fullness;
        // Late in the stream, avoid proliferating bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * t;
        // If item is large relative to capacity, new bin is more acceptable.
        score -= 20.0 * (item_size as f64 / cap);
    } else {
        // Mild preference for filling fuller bins first.
        let fullness = 1.0 - (bin_residual as f64 / cap);
        score -= 8.0 * fullness;
        // When many bins are open, consolidate into them rather than opening more.
        score -= (open_bins_count as f64).min(20.0) * 0.3;
    }

    // Prefer bins whose residual stays close to the mean (balanced packing),
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small time-horizon modulation: early on, be greedy with tight fits;
    // later, be slightly more conservative.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * t * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: minimize wasted space, with non-linear (quadratic) waste penalty
    let mut score = pr + norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: later in the stream, waste matters more
    score *= 1.0 + 0.5 * progress * norm_pr;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate: penalize opening new bins, less so when few bins fit
    let new_bin_penalty = 25.0 + 15.0 * (1.0 - (fitting_bins_count as f64).min(6.0) / 6.0);
    score += is_new_bin * new_bin_penalty;

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            // residual too small for next item: penalize dead space
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Mean-residual context: prefer bins near the mean (smooth coupling)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Slight preference for filling larger fraction of the bin
    score -= (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with a convex (quadratic) penalty
    // so that medium waste is punished more than linearly.
    let pr = post_residual as f64;
    score = pr + 0.35 * (pr * pr) / (bin_capacity as f64);

    // Harmonic class logic: classify post_residual into modulo classes.
    // Residuals that are "usable" (0, or exactly matching a plausible next item
    // size class) are rewarded; awkward residuals are penalized.
    let pr_u = post_residual;
    if pr_u == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if pr_u <= 10 {
        // Near-perfect fit, dead space is minimal.
        score -= 25.0;
    } else {
        // Modulo-10 classes: residual divisible by 10 leaves room for a
        // smallest-class item; reward those classes.
        if pr_u % 10 == 0 {
            score -= 8.0;
        }
        // Classify by integer division thresholds on post_residual.
        let class = pr_u / 15; // harmonic bucket of width 15
        score += class as f64 * 2.5;

        // Harmonic pairing: if the next item fits exactly in the residual,
        // this is a chained perfect fit — heavily reward.
        if next_item_size > 0 && next_item_size <= pr_u {
            let chained_waste = pr_u - next_item_size;
            if chained_waste == 0 {
                score -= 40.0;
            } else if chained_waste <= 10 {
                score -= 18.0;
            } else {
                score -= (pr_u - chained_waste) as f64 * 0.15;
            }
        } else if next_item_size > 0 {
            // Next item cannot use this residual; residual becomes dead space
            // unless a future item of class <=10 arrives. Penalize.
            score += 10.0;
            // But if residual is small enough to be negligible waste anyway, soften.
            if pr_u < 20 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into open bins is genuinely poor. Give the empty bin a mild penalty so
    // decent fits beat it, but let large items with bad fits prefer it.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 22.0;
        // Large items relative to capacity benefit from a fresh bin
        // (they create big residuals elsewhere anyway).
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 18.0 * frac;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If many bins are open already, opening yet another is costly.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Crowd control: when many bins fit the item, prefer bins that keep the
    // overall residual distribution healthy (close to mean_residual).
    if fitting_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Early stream: encourage filling few bins tightly to build good structure.
    if step_index < total_items / 4 {
        score += pr * 0.1;
    }

    // Small final tie-breaker on residual for determinism.
    score += pr * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
