pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward bins whose post residual can host the next item,
    // penalize dead space smaller than the smallest possible item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * (next_item_size as f64) - 0.15 * (post_residual as f64);
        } else {
            // Dead space: smaller residual is worse if it's unusable.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 1.5 * (1.0 - progress) * (post_residual as f64);
        }
        // Bonus if after this placement the bin can take next item exactly.
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average when the fit is snug.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= 0.3 * (mean_residual - resid_f);
    } else {
        score += 0.2 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and the item would leave lots of unusable space.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        let wasteful = (post_residual as f64) > 0.5 * (bin_capacity as f64);
        if poor_fit {
            score -= 50.0;
        } else if wasteful && next_item_size > 0 && post_residual < next_item_size {
            // Opening fresh bin may be better than trapping space.
            score -= 30.0;
        } else {
            score += 120.0; // default: prefer existing bins
        }
    }

    // Mild preference for filling fuller bins overall.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty dominates for large residuals.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small dead space is nearly useless for future items (min size 10).
        score -= 20.0;
    } else if post_residual < 20 {
        score += 5.0; // moderately awkward leftover
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Penalize opening new bins when this bin fits reasonably well.
        score += 25.0;
        score -= (1.0 - fit_quality) * 20.0; // poor fits make new bin more attractive
        score += (1.0 - progress) * 10.0;    // early stream: more freedom to open bins
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let next_leftover = post_residual - next_item_size;
            if next_leftover < 10 {
                score -= 15.0; // next item leaves near-perfect fit
            } else {
                score += next_leftover as f64 * 0.15;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let spread = mean_residual - bin_residual as f64;
    score += spread * 0.3; // prefer bins with residual below average (fuller bins)

    // Prefer bins that are already partially filled (avoid fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Late in the stream, tighten up: waste becomes costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * progress * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: penalize leftover space, but with diminishing polynomial returns
    let mut score = 4.0 * norm_post - 2.0 * norm_post * norm_post;

    // Smooth coupling: tight fits matter more as the stream progresses
    score += (0.5 + progress) * norm_post * norm_post * norm_post;

    // Dead-space penalty scaled by how unusable the residual is for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - post) / cap;
        score += 1.5 * gap * (1.0 + progress);
    }

    // Perfect fit reward (smooth, via small post values)
    score -= (1.0 - norm_post).max(0.0) * 0.5;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a new bin mildly, more when open bins fit well
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 1.0 + 0.05 * open * (1.0 - progress);
        // But if mean residual is large, opening new bin is less attractive
        score += (mean_residual / cap).max(0.0) * 0.8;
    }

    // Slight preference for bins below mean residual (balance load smoothly)
    score += 0.3 * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 (dead-space classes)
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.35;

    // Integer-division thresholds: post_residual buckets by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 18.0; // tiny sliver, nearly dead space
    } else if post_residual < quarter {
        score += 6.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 4.0; // half-full is a good harmonic state
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            // harmonic class of the second-order remainder
            score += (rem2 % 10) as f64 * 0.5;
            if rem2 == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot follow in this bin: penalize proportionally
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits / large residuals
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (mean_residual - item_size as f64).abs() > 25.0;
        if poor_fit && fitting_bins_count > 1 {
            score -= 15.0 * (0.5 + progress);
        } else {
            score += 30.0; // prefer reusing open bins generally
        }
    }

    // Slight preference for tighter bins relative to the mean residual
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Congestion: many open bins -> consolidate
    score += open_bins_count as f64 * 0.6;

    // Item-size harmonic class coupling: large items prefer low post_residual
    let item_class = (item_size / 20) as f64;
    score -= item_class * (bin_capacity - post_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score += 15.0; // near-dead zone: risky unless it's a perfect fit
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // creates a gap the next item cannot use
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmentation;
    // with few open bins, tolerate spreading.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(1.0);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a bin is attractive only when the
    // item would leave a very tight fit or no good open bin exists.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64 / bin_capacity as f64) > 0.9;
        if tight {
            score -= 25.0; // big item fills a fresh bin well
        } else if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 35.0; // prefer existing bins when any fit decently
        }
    }

    // Mild preference for bins below mean residual (denser bins).
    score -= 3.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 40.0 * ((bin_residual as f64 - item_size as f64) / bin_capacity as f64).recip().min(5.0);

    // 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Penalize post_residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Penalize post_residual far from mean residual (fragmentation).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Discourage opening new bins, especially early in the stream.
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize post residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize large dead space, especially small unusable slivers.
    if post_residual < item_size {
        // dead space that cannot fit typical items is worse
        score += (item_size as f64 - post_residual as f64) * 0.15;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= 100;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized more early on (want to fill bins);
        // late in stream, allow opening when fit is poor.
        let open_penalty = 55.0 * (1.0 - 0.5 * progress);
        // If the current bin leaves a very small residual, opening may be fine.
        let poor_fit_elsewhere = (mean_residual - item_size as f64).abs() < 2.0;
        score += open_penalty - if poor_fit_elsewhere { 30.0 } else { 0.0 };
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 5.0 + open_bins_count as f64 * 0.3;
    }

    // Lookahead: favor leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // Prefer bins whose residual deviates from the mean residual in a useful way:
    // filling bins with above-average residual first balances the pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: as stream nears end, be more aggressive about filling open bins.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= horizon * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit), smoothed with a mild quadratic.
    let mut score = post + 0.35 * (post / cap) * (post / cap) * cap;

    // Reward tight fits non-linearly: coupling of post_residual with item size.
    let fit_quality = 1.0 - post / cap;
    score -= 12.0 * fit_quality * fit_quality * (item / cap);

    // Penalize dead space that likely cannot be used: interaction with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (post - nxt).max(0.0);
        score += 0.9 * (unusable / cap) * cap;
        // Bonus if this bin exactly serves the next item too.
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening new bins when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - post / cap);
    }

    // Stream-progress coupling: early on, be picky (penalize loose fits);
    // later, consolidate more aggressively into existing bins.
    let picky = (1.0 - progress) * (1.0 - progress);
    score += 10.0 * picky * (post / cap);

    // Slight preference to fill bins with larger mean residual (consolidation).
    score += 0.05 * (mean_residual - post).abs();

    // New empty bin candidate: heavily penalized unless stream is early or fit is hopeless.
    if bin_residual == bin_capacity {
        let hopeless = fitting_bins_count <= 1 && post < cap - item as f64 * 0.0; // only reached when no fit
        let early = progress < 0.15;
        let penalty = if hopeless || early { 40.0 } else { 60.0 + 30.0 * (1.0 - progress) };
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (harmonic classes of 100).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= (cap - pr) / cap * 20.0; // reward fill fraction

    // Harmonic class penalty: dead space in (0,10) is nearly unusable (min item 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Class thresholds: residuals 10..=19 risky (only tiny items fit)
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: penalize if next item cannot use post_residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= (next_item_size as f64 / cap) * 10.0;
        }
        // Modulo coupling: if post_residual % next_item_size == 0, great future packing
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: empty bin gets a base cost so it's only chosen
    // when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if item is large and would leave huge dead space anywhere, new bin is fine
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += (mean_residual / cap) * 3.0;

    // Progression: later in stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize post_residual that cannot fit the smallest possible item (1).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (2.0 + 6.0 * progress);

    // New-bin candidate: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so filling existing bins is preferred.
        score += 35.0 + 5.0 * open_bins_count as f64;
        // But if the item is large and residuals are tight, opening a new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        // Late in the stream with few fitting bins, allow a fresh bin.
        if progress > 0.7 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: next item exactly fills this bin -> strongly reward
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snugly it fits
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.35 * slack_after_next;
        } else {
            // Next item won't fit: dead space penalty scaled by wasted amount
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
            // Very small unusable remainder is worse than a large usable one
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // --- Fit quality of current placement ---
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual < 10 {
        score += 8.0; // tiny dead fragment
    }

    // --- Relative to mean residual: prefer bins with more residual (tighter packing) ---
    score -= 0.30 * (mean_residual - post_residual as f64);

    // --- Last-chance bin bonus: avoid opening a new bin when only one fits ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Only attractive if the current item nearly fills a fresh bin
        score -= (item_size as f64) * 0.55;
        // Never open a new bin when a perfect chain exists elsewhere is handled
        // by the lookahead rewards above; discourage if other bins fit fine
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // --- Slight stream-phase modulation: pack tighter early, stay flexible late ---
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (1.0 - phase) * (post_residual as f64 / bin_capacity as f64);

    // Prefer spreading across many open bins when they are numerous
    if open_bins_count > 10 {
        score += 0.05 * (open_bins_count as f64 - 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0 + (10 - post_residual) as f64 * 2.0;
    } else {
        // Penalize residuals that are too small to ever fit typical items.
        if post_residual < 25 {
            score += (25 - post_residual) as f64 * 1.5;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next == 0 {
                score -= 45.0;
            } else if leftover_after_next <= 15 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's remainder; slight penalty for
            // locking space that would have helped the next item.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; only attractive when existing
        // bins fit poorly (high mean residual fragmentation) or the item
        // is large and would leave awkward space elsewhere.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 35.0;
        score -= fragmentation * 0.4;
        score -= (open_bins_count as f64) * 1.2;
        // Late in the stream, prefer reusing open bins.
        score += progress * 12.0;
        // Large items start fresh bins more willingly.
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild preference for filling bins that are already partially used,
    // keeping the pool of open bins small.
    score -= (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + t) - pr_norm * (0.5 - 0.5 * t);
    score += 12.0 * poly;

    // Reward tight fits smoothly (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 - t);

    // Penalize when this is the last fitting bin and we would leave large dead space.
    if fitting_bins_count <= 1 {
        score += 6.0 * pr_norm * (1.0 - t) * (1.0 - t);
    }

    // Lookahead: if next item could use the post residual, reward leaving exactly that space.
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - d / bin_capacity as f64).max(0.0) * (1.0 - t);
    }

    // New-bin candidate: penalize opening a new bin smoothly, more early in the stream,
    // and less when mean residual of open bins is already high (fragmentation).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 15.0 * (1.0 - t) * (1.0 - 0.5 * frag) + 5.0 * pr_norm;
    }

    // Mild penalty for spreading across too many open bins late in stream.
    score += 0.05 * (open_bins_count as f64) * t * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (integer division thresholds) ---
    let q = post_residual / (bin_capacity / 4); // 0..=4 quarter classes
    let r = post_residual % (bin_capacity / 4);

    // Dead-space penalty: residual in the lowest quarter class is nearly unusable
    // for typical items (sizes >= 1..100, most > 25).
    if q == 0 && post_residual > 0 {
        score += 30.0; // tiny sliver -> strong penalty
    } else if q == 0 {
        score -= 60.0; // perfect fit (post_residual == 0) -> best possible
    }

    // Mid harmonic classes: reward using bins whose leftover stays usable
    match q {
        1 => score -= 12.0, // leftover 25..49: fits small items well
        2 => score -= 6.0,  // leftover 50..74: decent
        3 => score -= 2.0,  // leftover 75..99: large leftover, mild bonus
        _ => {}
    }

    // Fractional coupling: reward when item fills an exact capacity fraction
    let denom = bin_capacity as f64;
    let fill = item_size as f64 / denom;
    if (fill * 4.0).fract() < 1e-9 || (fill * 5.0).fract() < 1e-9 || (fill * 2.0).fract() < 1e-9 {
        score -= 8.0; // item is a 1/2, 1/4, or 1/5 of capacity -> harmonic placement
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0; // chainable bin
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item can't use leftover -> dead space risk
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline near mean residual
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are fragmented
        // or mean residual is small relative to item size.
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score = 100.0 - 0.5 * fragmentation - 0.3 * open_bins_count as f64;
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= denom {
            score += 5.0; // pairing opportunity in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
    }

    // Progress modulation: late in stream, tighten bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Mean-residual coupling: prefer bins below mean residual (compact bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 10 {
        // Residual that can still plausibly fit future items (>=10) is mildly rewarded.
        score -= 5.0;
    }

    // Reward using a bin whose residual tightly matches the item (low waste ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // slightly encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // If the next item could use the post residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is bigger than post residual but smaller than typical bin,
    // penalize leaving residual the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin has high base residual; make it
    // attractive only when no open bin fits well (high mean residual spread /
    // many fitting bins means poor fits exist).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 25.0;
        // If this bin is the only fitting option, opening a new bin is competitive.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Large current item relative to capacity makes a fresh bin more appealing.
        score += 0.2 * item_size as f64;
        // Discourage opening bins early in the stream.
        score += 30.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward proportional to closeness of post_residual to next_item_size
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)) * (diff / (bin_capacity as f64)).exp();
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving a residual that is too small for the next item
        // (dead space: next item can't use it and nothing else likely will).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize post_residual (already the base).
    }

    // Penalize creating tiny unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins with above-average residual
    // (pack into emptier bins, keep tight bins for tight fits).
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= 0.3 * (res_f - mean_residual);
    } else {
        score += 0.3 * (mean_residual - res_f);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only allow
    // it when no open bin fits, or when the current bin's residual after
    // placement would be badly fragmented relative to the lookahead.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        // If other bins fit the item, opening a new bin should rarely win.
        let open_alt_penalty = if fitting_bins_count > 0 { 80.0 } else { 0.0 };
        // With lookahead, a new bin guarantees perfect fit for next item if
        // item_size + next_item_size <= capacity; slightly soften penalty then.
        let lookahead_soften = if next_item_size > 0
            && item_size + next_item_size <= bin_capacity
            && next_item_size >= post_residual
        {
            10.0
        } else {
            0.0
        };
        score += base_penalty + open_alt_penalty - lookahead_soften;
    }

    // Mild stream-progression term: later in the stream, be slightly more
    // conservative about spreading across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress;

    // Slight preference for filling bins tighter overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny useless sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin when
    // decent fits exist, but allow it when all open bins would leave bad waste.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, decaying as stream progresses
        // (late in stream, consolidating matters more).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress);

        // If the item would fit poorly in every open bin (large waste elsewhere),
        // opening a fresh bin becomes attractive: reduce the penalty.
        let would_waste_elsewhere = fitting_bins_count > 0
            && (mean_residual - item_size as f64).abs() < 5.0;
        if would_waste_elsewhere {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative at all
        }
    }

    // Lookahead coupling: if the next item would exactly consume this bin's
    // post_residual, reward heavily; if next item cannot use the leftover, penalize.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 10.0;
        } else if next_item_size > post_residual {
            // leftover can't serve next item; mildly penalize large leftovers
            score += 0.05 * (post_residual as f64);
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins to avoid fragmentation.
    if open_bins_count > 3 && mean_residual > 30.0 && !is_new_bin {
        score -= 5.0;
    }

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: mildly prefer tight fits. Late: strongly prefer
    // minimizing post_residual (dead space) since future correction is limited.
    let w = 0.5 + 2.0 * progress * progress;
    let tight = (pr / cap) * (pr / cap); // quadratic normalized dead space
    score += w * 30.0 * tight;

    // Cubic interaction: dead space penalized more when it cannot fit the next item.
    let next_fits = if next_item_size > 0 && (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
    let prn = pr / cap;
    score += next_fits * (-8.0 * prn - 4.0 * prn * prn);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Penalize bins far from the mean residual (smooth quadratic divergence),
    // encouraging residual homogeneity across open bins.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + open_bins_count as f64);

    // Mild penalty for opening new bins late in the stream, scaled by fill.
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if new_bin {
        score += 5.0 + 10.0 * progress * (1.0 - prn);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: multiples of small units are
    // "usable" residues; odd fragments create dead space.
    let cap_frac = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class A: post_residual divisible by 5 or 10 -> highly reusable residue.
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Class B: integer-division thresholds on post_residual.
    let tier = post_residual / 10; // 0..=10
    score += tier as f64 * 1.5;

    // Perfect fit is king.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Harmonic penalty: slack mod 10 classes.
            score += (slack % 10) as f64 * 0.8;
            if slack <= 10 {
                score -= 5.0; // near-exact follow-up fit
            }
        } else {
            // Next item cannot follow into this bin: mild penalty,
            // worse if this bin is the last chance for the current item.
            score += 4.0;
        }
    }

    // Last-chance bonus: only one bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless
    // they are all bad fits; scale with stream progression and crowding.
    if bin_residual == bin_capacity {
        score += 25.0
            + (open_bins_count as f64).sqrt() * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // But if mean residual is small (bins nearly full), a new bin is fine.
        score -= (cap_frac - mean_residual) * 0.15;
    }

    // Dead-space penalty for tiny unusable residues (1..10) that no item
    // (min size 1) reliably consumes; keep harmonic flavor via mod classes.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.2;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into fuller bins (low post_residual already does this).
    score += (mean_residual - post_f).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 - tightness.min(1.0)) * 20.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: penalize fitting into already-open bins mildly,
    // encouraging consolidation; but reward it when few bins remain.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by post_residual dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: only prefer a fresh bin when current fit is poor
    // and residual would become dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        if post_residual < 10 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin if an open bin is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item fills the leftover space.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill_ratio;
        } else {
            // Next item won't fit here: penalize large dead space.
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are generally preferred...
        score += 60.0;
        // ...but if this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            // Keep last-chance open bin preferable unless it's a terrible fit.
            if post_residual as f64 > 0.6 * bin_capacity as f64 {
                score -= 70.0;
            }
        }
        // Late in the stream, avoid spawning bins with big residual.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference for compact bins as the stream grows.
    score += 0.05 * (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Perfect or near-perfect fill gets a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many alternatives: mild penalty to encourage spreading via other bins if fit is loose.
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate: penalize opening a new bin, but less when the item is large
    // or the current bin's residual would leave awkward dead space.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 60.0;
        // Large items are fine in fresh bins.
        new_bin_penalty -= (item_size as f64 / 10.0) * 2.0;
        // If no existing bin fits well (post_residual large relative to residual), reduce penalty.
        if post_residual as f64 > 0.45 * bin_capacity as f64 {
            new_bin_penalty -= 30.0;
        }
        // Late in the stream, avoid opening new bins more aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 20.0 * progress;
        // Many open bins already: discourage adding more unless item is big.
        if open_bins_count > 5 {
            new_bin_penalty += 2.0 * ((open_bins_count - 5) as f64).min(10.0);
        }
        score += new_bin_penalty;
    }

    // Lookahead: if the next item would fit in the post-residual, reward leaving it here.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains nicely: reward, stronger when residual nearly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize wasting the gap.
            score += 5.0;
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean (tighter bins),
    // encouraging consolidation toward fuller bins.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 4.0 * (bin_res_f - mean_residual) / bin_capacity as f64;
    }

    // Slight preference for bins with larger residual when item is small (keep big gaps for big items).
    if item_size < 30 && bin_res_f > 60.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap; // 0 = perfect fit
    let mut score = post;

    // Base: quadratic reward for tight fits (waste grows superlinearly)
    score += 60.0 * fit_ratio * fit_ratio;

    // Smooth coupling of waste with stream progress: late in the stream,
    // dead space is more costly (fewer chances to fill it).
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Lookahead: if the next item could use this post-residual, reward heavily (smooth kernel)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).abs();
        let kernel = (-gap / 20.0).exp();
        score -= 25.0 * kernel * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.3);
    } else {
        // Many options: penalize leaving large residual relative to mean residual
        score += 8.0 * ((post - mean_residual) / cap).abs();
    }

    // Reward using open bins (avoid bin proliferation), smoothly decaying with openness
    score -= (open_bins_count as f64).ln().max(0.0) * 5.0 * (1.0 - fit_ratio);

    // New-bin candidate handling: empty bin should only win when the fit is
    // either very tight or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_ratio = item / cap;
        // Penalize opening a new bin unless item is big or fit would be near-perfect
        let penalty = 30.0 * (1.0 - item_ratio * item_ratio) + 15.0 * fit_ratio;
        score += penalty;
        // Late in stream, opening fresh bins is slightly more acceptable
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero waste.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class reward: post_residual in low residue classes mod 10
    // (e.g. 0..9) pairs better with future item sizes drawn in decades.
    let residue_class = (post_residual % 10) as f64;
    score -= (10.0 - residue_class) * 0.4;

    // Dead-space penalty: if the lookahead item cannot fit in the leftover,
    // this placement likely strands space. Penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += post_residual as f64 * 0.6;
        // Extra penalty if the stranded residue is in an awkward band
        // (too small for the smallest plausible item, i.e. < 10).
        if post_residual < 10 {
            score += 15.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving exactly enough room for the next item (chained fit).
        score -= 8.0;
    }

    // Last-chance logic: if this is the only bin that fits, using it avoids
    // opening a new bin; reward moderately unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a bin is costly; penalize so it only wins when open-bin
        // fits are clearly bad (large post_residual with dead space).
        score += 30.0;
        // But if no open bin fits at all, the new bin is the only choice:
        // soften the penalty so it still gets selected.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If the fresh bin would leave a tight, reusable residual
        // (small post_residual after placing a large item), reduce penalty.
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // Mild pressure against proliferating many open bins with high mean
    // residual: encourage consolidation when mean residual is already large.
    score += mean_residual * 0.05;

    // Late-stream tightening: as the stream progresses, prefer tighter fits
    // to avoid ending with many partially filled bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are effectively wasted -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fit, ideal
    } else if post_residual < 10 {
        // unusable sliver: penalize far beyond its face value
        score += (10 - post_residual) as f64 * 12.0;
    } else {
        // usable gap: mild quadratic penalty to prefer tighter fits
        score += (post_residual as f64) * (post_residual as f64) / 400.0;
    }

    // Reward exact / near-exact packing relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few are open, slightly tolerate new-bin usage.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.8 * (0.5 + progress);

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would NOT fit here but would fit elsewhere, mild penalty
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual
    // (i.e., fuller bins) to consolidate packing.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: only attractive when existing bins are tight
    // or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score = 60.0 + 40.0 * pressure - 20.0 * fill_ratio;
        // Late in the stream, opening new bins is cheaper than dead space
        score -= 30.0 * progress;
        if fitting_bins_count == 1 {
            score += 120.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: post_residual can host next item comfortably.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Cannot host next item: penalize proportionally to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 8.0 + shortfall * 0.5;
    }

    // Zero residual is excellent (bin fully closed).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        // Tiny dead space that nothing (min size 1..100 range) reliably uses:
        // mildly penalize, but keep it better than mid-range waste.
        score += 5.0;
    }

    // Compare against the fleet: a bin much tighter than the mean is a good target.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: expensive to open unless current fit is bad
    // or the stream is early and we want to build a diverse pool.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        if poor_fit || open_bins_count == 0 {
            score -= 150.0;
        } else {
            score += 250.0 - 100.0 * progress;
        }
    }

    // Slight preference for tighter original residual (denser bins first).
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

