    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item can still use the post-residual,
    // reward leaving a useful gap; otherwise penalize dead space.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
