    // Global state coupling: prefer bins whose residual is below the mean
    // (tighter bins get filled first, keeping large gaps open).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Slight preference for filling bins with fewer open bins active
    // (consolidation pressure early, relaxation late in the stream).
    score -= 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // Prefer tight fits: reward small post-residual non-linearly.
    score -= 12.0 / (1.0 + post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
