    // fit exists (high post_residual in all bins) or early when mean residual is low.
    if bin_residual == bin_capacity {
        let mean_tight = (mean_residual / cap).clamp(0.0, 1.0);
        let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 3.0)).sqrt();
        score += 12.0 * (1.0 - mean_tight) * (1.0 - progress) * (1.0 - open_pressure);
        // Late in the stream, discourage new bins unless residuals are truly bad.
        score += 8.0 * mean_tight * progress;
    }

    // Mild global pressure: prefer filling already-open bins when many are open.
    if bin_residual != bin_capacity {
        score -= 1.5 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Smooth progress coupling: as the stream advances, slightly tighten
    // preference for minimal post_residual (non-linear interaction).
    score *= 1.0 + 0.5 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect lookahead fit: next item exactly fills this bin afterwards.
    if !is_new_bin && next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Next item fits into the resulting residual comfortably.
    if !is_new_bin && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Harmonic classes: residuals divisible by common item granularities
    // (10, 20, 25, 50) remain usable by many future item sizes.
    if post_residual > 0 {
        let r = post_residual;
        if r % 50 == 0 { score -= 8.0; }
        else if r % 25 == 0 { score -= 6.0; }
        else if r % 20 == 0 { score -= 5.0; }
        else if r % 10 == 0 { score -= 4.0; }
        // Dead-space penalty: tiny odd residuals (1..=5) are hard to fill.
        if r <= 5 { score += 10.0; }
        else if r < 10 { score += 4.0; }
    } else {
        // Perfect closure of a bin is ideal.
        score -= 20.0;
    }

    // New-bin candidate: opening a bin is only attractive when the item is
    // large relative to capacity (yielding a small, well-shaped residual)
    // or when many bins are open and residual fragmentation is high.
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Harmonic bonus: residual after placement divisible by 10 is reusable.
        let harmonic = if post_residual % 10 == 0 { 6.0 } else { 0.0 };
        score += 18.0 - 20.0 * fill_ratio - harmonic;
        // Late in the stream, avoid spawning bins for poor fits.
        score += 10.0 * progress;
        // If only this new bin "fits", it is forced anyway; neutralize penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (tighter-than-average bins get priority to be closed out).
    if !is_new_bin {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (< 10, min item size)
    // are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Penalize very large leftover gaps that few future items can use.
    if post_residual > 60 {
        score += 0.15 * (post_residual as f64 - 60.0);
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly reward this placement (sets up a perfect follow-up).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        } else {
            score -= 5.0 * (1.0 - slack as f64 / 100.0);
        }
    }
    // If next item cannot fit in post_residual, mild penalty (dead end for lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits,
    // strongly discourage opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open,
    // but the empty-bin candidate has residual == capacity and gets this
    // penalty too, so it only wins when fits elsewhere are very bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64 * 0.1;
    }

    // Slight preference for bins below mean residual (balancing load)
    // so that large-residual bins stay available for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5;
    }

    // Late-stream urgency: near the end, close out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is only attractive when no open bin fits,
        // or when the only fitting bin is a "last chance" with a bad fit.
        if fitting_bins_count == 0 {
            // Must open a bin: neutral, slight reward for small wasted capacity.
            score -= 50.0;
        } else {
            // Discourage new bin when existing bins fit; penalty grows with
            // how many alternatives exist and how tight the stream is.
            score += 120.0 + 30.0 * (fitting_bins_count as f64) + 40.0 * progress;
        }
        return score;
    }

    // --- 2-step lookahead matching on open bins ---
    let pr = post_residual as f64;
    let ni = next_item_size as f64;

    if next_item_size > 0 {
        if (pr - ni).abs() < 0.5 {
            // Perfect match: next item exactly fills this bin.
            score -= 80.0;
        } else if pr > ni {
            // Next item can also fit here; mild reward, tighter is better.
            score -= 0.3 * (pr - ni);
        } else {
            // Dead space relative to the next item: penalize proportionally,
            // but small leftovers (<10) are nearly unusable anyway.
            let dead = ni - pr;
            let dead_penalty = if pr < 10.0 { dead * 1.5 } else { dead * 0.8 };
            score += dead_penalty;
        }
    } else {
        // Last item: minimize leftover directly.
        score += 0.5 * pr;
    }

    // Coupling with mean residual: prefer bins that are tighter than average
    // (concentrate packing), penalize bins looser than the mean.
    score += 0.4 * (pr - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mild pressure to fill existing bins as the stream progresses.
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space that likely cannot host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when existing
    // bins fit reasonably well. Make the empty bin unattractive unless the item
    // is large relative to typical residuals or no real bin is close.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = open_bins_count as f64;
        // A new bin is fine for big items or when residuals are tight.
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let tight_state = mean_residual < item_size as f64 * 1.2;
        let base = 120.0
            - if big_item { 70.0 } else { 0.0 }
            - if tight_state { 50.0 } else { 0.0 }
            - 15.0 * progress;
        // Slight scaling with number of open bins: many open bins -> avoid new ones.
        score += base + 2.0 * open_pressure;
    }

    // Lookahead coupling: if the next item would fit exactly in the post residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let nfit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * nfit;
        } else {
            // Next item won't fit here; leaving large residual is less useful.
            score += 8.0;
        }
    }

    // Mild preference for bins with below-average residual (conserves roomy bins).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Small early-stream exploration: spread items early, tighten later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * fit_ratio * fit_ratio);

    // Tight-fit reward: smooth coupling of item size and residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness * tightness;

    // Stream-progress coupling: later in stream, penalize wasted space more
    score += 6.0 * progress * fit_ratio * (1.0 - progress);

    // Last-chance bonus: only bin that fits -> strong reward, smoothly scaled
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 20.0 * last_chance * (1.0 - fit_ratio);

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (pr - next_item_size as f64) / cap;
    }

    // Crowd penalty: many open bins with high mean residual -> discourage fragmentation
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0) * (1.0 - fit_ratio);

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
        // but if current item is huge and no good fit exists, soften
        score -= 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align with
    // typical item granularity (items 10..80), making them reusable.
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 60.0 * (pr / cap);
    } else if harmonic == 5 {
        score -= 25.0 * (pr / cap);
    } else {
        // Odd/awkward residues penalized proportionally to how unusable they are.
        score += 15.0 * (harmonic as f64 / 10.0);
    }

    // Integer-division thresholds: can the next item also fit in the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead reward: keep bins that can serve the next item too.
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= post_residual + 5 {
        // Near-miss: slight penalty, bin nearly reusable.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        score += 90.0 + 0.3 * open_bins_count as f64;
        // If item is large relative to capacity, opening fresh is less costly.
        if item_size as f64 > 0.7 * cap {
            score -= 60.0;
        }
        // If residuals across bins are fragmented, a fresh bin is more attractive.
        if mean_residual < 0.25 * cap && open_bins_count > 2 {
            score -= 50.0;
        }
    }

    // Prefer filling bins with small residuals first (tight fit preference).
    score -= 0.4 * (cap - bin_residual as f64);

    // Stream progression: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the next item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Prefer bins whose residual is close to the mean (balanced packing).
    score -= 0.5 * (bin_residual as f64 - mean_residual).abs().min(30.0);

    // New-bin candidate handling: only attractive when the item fits poorly everywhere
    // (tight fit is better than any new bin, so bias new bins upward).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (item_size as f64);
        if fitting_bins_count > 0 && item_size >= 60 {
            // Large items in a tight spot may justify a fresh bin.
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Bonus if next item fits exactly into the post-residual bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit anywhere else after this placement, prefer keeping space.
        let next_fits_now = post_residual >= next_item_size;
        if !next_fits_now {
            score += 10.0;
        }
    }

    // Penalize post_residual that is small but unusable (dead space) relative to min item size.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Penalize wasting a large residual bin on a small item when mean residual is high.
    if (post_residual as f64) > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0;
        // If other bins fit and any have decent match, new bin is less attractive.
        score += base_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Reserve fresh bin for pairing current + next item.
            score -= 45.0;
        }
    }

    // Slight preference to fill bins tighter as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
