pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Non-linear coupling with stream progress: later in the stream,
    // waste becomes more costly (bins opened now persist to the end).
    score *= 1.0 + 0.8 * progress * progress;

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= 12.0 * (1.0 - diff / cap).max(0.0);
        // If next item cannot fit anywhere after this placement, mild penalty.
        if pr < nxt && pr < mean_residual * 0.5 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty when
    // the item is large (a fresh bin gives a clean large residual) and few bins fit.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let mut new_bin_penalty = 30.0;
        new_bin_penalty -= 20.0 * item_frac * item_frac;
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 18.0;
        }
        // Early in the stream, opening bins is cheaper (future items can use them).
        new_bin_penalty *= 1.0 - 0.35 * progress;
        score += new_bin_penalty.max(0.0);
    }

    // Slight preference for bins whose residual deviates from the mean in a
    // usable way: bins with small residual are naturally favored via pr already,
    // but add smooth coupling to avoid fragmenting many half-empty bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: mod-10 buckets. Small dead space in
    // "harmonically usable" classes (10..=30) is less harmful than odd gaps.
    let pr = post_residual;
    let harm_class = pr % 10;
    if pr > 0 {
        match harm_class {
            0 => score -= 8.0,        // round residual: highly reusable
            5 => score -= 5.0,        // half-class: decent reuse
            1 | 9 => score += 6.0,    // awkward slivers
            2 | 8 => score += 3.0,
            _ => {}
        }
    }

    // Integer-division thresholds: dead space below the minimum item size is pure waste
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Next-item lookahead: reward residuals that can host the lookahead item exactly
    if next_item_size > 0 {
        if pr >= next_item_size {
            // how well does the leftover pair with the next item
            let pair_left = pr - next_item_size;
            if pair_left == 0 {
                score -= 120.0;
            } else if pair_left < 10 {
                score -= 15.0;
            } else {
                score -= 10.0 * (pair_left as f64 / 100.0);
            }
        } else {
            // leftover cannot host next item: penalize proportionally
            score += 0.5 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer tighter bins when many are open (reduce fragmentation)
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // New-bin candidate: make it attractive only when the fit here is bad
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio < 0.35 {
        score -= 30.0; // encourage fresh bin for very loose fits
    } else {
        score += 20.0; // discourage wasting a new bin on good fits
    }

    // Early stream: be slightly conservative about bin count
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // Mean-residual coupling: if this bin is far below mean residual, it is a good target
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space: penalize proportionally if it's unlikely to fit typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect or near-perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but make the new-bin candidate (untouched full residual) less attractive
    // unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins below the mean residual (tighter bins get filled first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 120.0;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item also fits here: excellent chaining, big reward.
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit: penalize wasted residual proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Penalize leaving dead space relative to mean residual (worse than average).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.6;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Late in the stream: prefer tighter packing, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base = 15.0 + progress * 25.0;
        // If next item is large and current fit is poor, new bin becomes attractive.
        let poor_fit = (post_residual as f64 - item_size as f64).max(0.0);
        score += base - poor_fit * 0.4;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, especially when it becomes unusable.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < 25 {
        score -= 10.0 * (1.0 - post_residual as f64 / 25.0);
    } else {
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            if waste < 10 {
                score -= 20.0;
            } else {
                score -= 8.0 * (1.0 - waste as f64 / post_residual.max(1) as f64);
            }
        } else {
            // Next item cannot use leftover: leftover likely dead space.
            score += 5.0 + (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 45.0;
        score -= 10.0 * pressure.min(3.0);
        if fit_ratio < 0.35 && fitting_bins_count > 0 {
            score += 20.0; // don't open new bin when decent fits exist
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // fresh bin can pair consecutive items
        }
    }

    // Time horizon: later in the stream, be more conservative (prefer existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 12.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins with residual close to the item to keep mean residual balanced.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Stream-progress coupling: waste becomes more costly late in the stream
    let progress_coupling = post * progress * (1.0 - progress) * 0.9 + post * progress * 0.5;
    score += progress_coupling;

    // Interaction: normalized post-residual squared against progress (non-linear)
    score += 30.0 * norm_post * norm_post * progress;

    // Reward tight fits more strongly as stream advances
    let tightness = (item_size as f64) / cap;
    score -= 12.0 * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count.min(10) as f64 - 2.0).sqrt();
    }

    // Lookahead coupling: leave room for the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            // post-residual close to next item size is valuable
            let fit_quality = 1.0 - (gap / cap).abs().sqrt();
            score -= 8.0 * fit_quality * (0.4 + 0.6 * progress);
        } else {
            // penalize blocking the next item
            score += 6.0 + (-gap / cap) * 15.0;
        }
    }

    // Mean-residual deviation: penalize bins far from the fleet mean (smooth)
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev * cap * 0.01;

    // New-bin candidate handling: penalize opening a fresh bin smoothly,
    // unless current post-residual is truly bad (near-full waste).
    if bin_residual == bin_capacity {
        let waste_now = post / cap; // == 1.0 for empty bin
        let _ = waste_now;
        let alternative_badness = norm_post; // post of this bin relative to cap
        // For the empty-bin call, post == cap so norm_post == 1:
        // apply a smooth penalty that decays if open bins are all poor fits.
        let crowding = open_bins_count as f64;
        score += 18.0 + 2.0 * crowding.sqrt() + 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive
        score -= 0.05 * (next_item_size as f64);
        let _ = alternative_badness;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "wasted" get penalized
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect / near-perfect fits get strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Harmonic thresholds: residual in [1..=10] is nearly dead space -> penalize mildly,
    // but if next item can use it, reward instead.
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fit: reward proportional to tightness of the pair
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 - slack_after_next as f64 * 0.5;
    } else if post_residual < 10 {
        // dead space class (unusable for typical items)
        score += 15.0;
    }

    // Modulo-10 harmonic classes: leftover divisible by 10 aligns with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 10 != 0 {
        score += (post_residual % 10) as f64 * 0.6;
    }

    // Large leftover fraction is fine (bin stays flexible), tiny-but-nonzero is bad
    let frac = pr / cap;
    if frac > 0.5 {
        score -= 8.0;
    } else if frac < 0.1 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so we only open when no good fit exists
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.1;
        // late in the stream, closing out bins is more valuable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins that are already relatively full
    score -= (1.0 - bin_residual as f64 / cap) * 10.0;

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Small tie-break coupling with item size (bigger items prefer emptier bins)
    score += (item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward gap" band: residual barely above the minimum item size is
    // likely to become dead space later.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer consolidating into
    // existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (creates a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit into post_residual but could fit a fresh bin,
    // slightly penalize leaving a large-but-unusable residual.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: it is only attractive when no open bin
    // offers a decent fit (large residual waste) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But if existing bins would leave big dead space, new bin wins.
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 45.0;
        }
        if open_bins_count > 6 {
            score += 10.0;
        }
    }

    // Slight stream-position coupling: late in the stream, be more
    // conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Reward close lookahead match (next item nearly fills the leftover)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (20.0 / (1.0 + gap * 0.15)).min(20.0);
    }
    // Penalize leaving dead space the next item can't use
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Relative-to-mean coupling: prefer bins with below-average residual
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // New-bin candidate handling: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // An existing bin fits; new bin should only win for poor fits elsewhere
            score += 40.0 + 60.0 * (1.0 - fill_ratio);
        } else {
            // No existing bin fits: opening new bin is fine, slight reward for large items
            score -= 10.0 * fill_ratio;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use -> penalize proportionally.
            score += 0.5 * post_residual as f64;
        }
        // Exact chain fit: post_residual equals next item size exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are mostly full.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64)
        } else {
            0.0
        };
        // Penalize opening a new bin; relax penalty as existing bins fill up.
        score += 45.0 * (1.0 - crowding);
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative: must open
        }
    } else {
        // Prefer reusing bins that are already fairly full (best-fit bias).
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // Time horizon: early in the stream, be more conservative about opening
    // bins (many items remain); later, allow more slack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference for bins close to the mean residual (keeps bin set balanced).
    score += 0.1 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).powi(2) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, prefer tighter packing (larger fills, smaller post residual)
    let progress_coupling = 60.0 * (1.0 - progress) * norm_pr * norm_pr
        - 40.0 * progress * norm_item * (1.0 - norm_item);
    score += progress_coupling;

    // Dead-space penalty: quadratic in unusable residual relative to smallest possible item (1)
    // but smoothed: penalize residuals that cannot fit next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 30.0 * (1.0 - pr / cap) * (1.0 - progress);
    }

    // Reward perfect fit smoothly
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Compare against mean residual: bins far below mean residual are "tighter" — favor them
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: make it slightly unattractive unless residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = mean_residual / cap;
        score += 5.0 + 20.0 * (1.0 - tightness) * (0.5 + 0.5 * progress);
    }

    // Lookahead synergy: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (norm_next / (norm_pr + 1e-6)).min(1.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Harmonic class of post_residual: residual mod small classes
    // Residuals that are multiples of 10 are "harmonic" — more reusable
    let pr = post_residual;
    let harmonic10 = (pr % 10 == 0) as f64;
    let harmonic5 = (pr % 5 == 0) as f64;
    score -= 6.0 * harmonic10 + 3.0 * harmonic5;

    // Penalize dead space: tiny unusable residuals (1..=3)
    if pr > 0 && pr <= 3 {
        score += 15.0;
    }

    // Integer-division threshold: post_residual bucketed by capacity fraction
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 8.0; // leaves room for large future items
    } else if pr >= quarter {
        score -= 3.0;
    } else if pr > 0 {
        score += 4.0; // awkward mid-small residual
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chains nicely
            // Harmonic match: next item exactly fills residual
            if next_item_size == pr {
                score -= 10.0; // perfect closure
            }
            // modulo coupling between next item and residual class
            if pr % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    } else {
        // Last item: prefer filling residual as fully as possible
        score -= 5.0 * fit_ratio;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are
    // badly fragmented (low mean residual utilization) or item is huge
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Penalize new bins generally
        score += 25.0 + 10.0 * (1.0 - pressure);
        // But relax penalty when open bins are fragmented and item is large
        if open_bins_count > 0 && fragmentation < 0.25 && pressure > 0.6 {
            score -= 18.0;
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference to consolidate: fewer open bins favored
    score -= 0.5 * (fitting_bins_count as f64).ln().max(0.0);

    // Small noise-free tie-break by step (deterministic drift)
    score += 0.01 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item can use are pure waste.
    // Treat residual <= 10 (min item size) as fully consumed; residual in
    // (0,10) is dead space -> heavy penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // unusable dead space
    } else {
        // Usable gap: mild reward scaled by tightness
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - tightness);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so we only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If next item is large and current item is small, opening fresh is less bad
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
        // Late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 20.0; // near-perfect two-item chain
        } else {
            score -= 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, favor consolidation
    // (penalize spreading into bins far above mean residual).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
        score += 0.5 * open_bins_count as f64;
    }

    // Small reward for filling large items into large-residual bins
    score -= 0.1 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if post_residual == next_item_size {
            // Perfect 2-step packing: huge reward.
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space that cannot fit next item: penalize, worse when small.
            let dead = pr;
            let dead_frac = dead / bin_capacity as f64;
            score += 60.0 * (1.0 - dead_frac) * (1.0 - dead_frac);
            // Extra penalty if item barely fails to fit next item.
            if gap <= 10.0 {
                score += 25.0;
            }
        }
    } else {
        // Last item: just minimize residual (score already = post_residual).
    }

    // Penalize leaving residuals too small to ever be useful (below min item size 1... use small threshold).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 5.0 {
        score += 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin when the item fits
    // reasonably well in an existing bin.
    if bin_residual == bin_capacity {
        // New bin: residual after placement = capacity - item_size.
        // Prefer new bin only if it yields a perfect 2-step match and existing bins don't.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 120.0;
        } else {
            // Base penalty so new bins are only chosen when open bins score worse.
            score += 70.0;
            // Less penalty late in the stream / many open bins already.
            score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
        }
    } else {
        // Existing bin: reward tight fits relative to mean residual.
        let tightness = (bin_residual as f64 - item_size as f64).max(0.0);
        if mean_residual > 0.0 && tightness < mean_residual * 0.5 {
            score -= 15.0;
        }
        // Reward filling bins nearly completely.
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.8 {
            score -= 20.0 * fill;
        }
    }

    // Mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere or the lookahead item benefits from a fresh large residual.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 {
            // Fresh bin can host both current and next item.
            if item_size + next_item_size <= bin_capacity {
                score -= 45.0;
            }
        }
        // Early in the stream, opening bins is cheaper (more items to come).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: reward residual that can still fit the next item (flexibility),
    // penalize residuals that are too small for typical future items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Dead space that can't fit the next item: penalize proportionally.
            score += (post_residual as f64) * 0.3;
        }
    } else {
        // Last item: any placement is fine; prefer tightest.
        score -= 5.0;
    }

    // Prefer bins with below-mean residual (consolidate emptiness).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.15;

    // Mild penalty for tiny unusable post_residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap; // in [0,1]

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr as f64;
    score += 40.0 * norm_post * norm_post;          // penalize large dead space super-linearly
    score -= 25.0 * norm_post * (1.0 - norm_post);  // reward mid-range utilization smoothness

    // Stream-progress coupling: late in stream, squeeze harder into existing bins
    let squeeze = 30.0 * progress * (1.0 - progress) + 60.0 * progress * progress;
    score += squeeze * (1.0 - norm_post);

    // Last-chance bin: strongly favor when it is the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 45.0 + 25.0 * progress;
    }

    // Lookahead: if next item could use the post-residual, reward leaving that space
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr as f64 {
            score -= 15.0 * (ns / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - (cap - ns).abs() / cap) * progress;
        }
    }

    // Mean-residual coupling: if this bin is far from mean residual, mild penalty
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    if bin_residual == bin_capacity {
        score += 35.0 + 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, with non-linear shaping.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction of post residual

    // Harmonic class of the post residual (integer division thresholds).
    // Classes: 0 (perfect), <=10, <=20, <=30, <=50, >50 dead-space classes.
    let class_penalty: f64 = if post_residual == 0 {
        -12.0
    } else if post_residual <= 10 {
        -6.0
    } else if post_residual <= 20 {
        0.0
    } else if post_residual <= 30 {
        4.0
    } else if post_residual <= 50 {
        10.0
    } else {
        18.0
    };
    score += class_penalty;

    // Quadratic dead-space growth for large unusable residuals.
    score += 0.35 * frac * frac * cap * 0.1;

    // Modulo arithmetic: residuals in [1..=9] are "harmonic slivers" —
    // only useful for tiny future items; penalize mildly unless perfect.
    if post_residual >= 1 && post_residual <= 9 {
        score += 5.0;
    }
    // Multiples of 10 in residual pair well with 10..80 item grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains where the next item also fits here.
            let slack_after_next = post_residual - next_item_size;
            let chain_bonus: f64 = if slack_after_next == 0 {
                -10.0
            } else if slack_after_next <= 10 {
                -5.0
            } else {
                -1.5
            };
            score += chain_bonus;
        } else {
            // Next item won't fit here; penalize proportional to overshoot class.
            let over = (next_item_size - post_residual) as f64;
            score += if over <= 10.0 { 3.0 } else if over <= 25.0 { 6.0 } else { 9.0 };
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // Crowd control: with many open bins, prefer consolidating into
    // already-tight bins rather than spreading.
    if open_bins_count > 3 {
        let tightness = 1.0 - (bin_residual as f64) / cap;
        score -= 2.5 * tightness;
    }

    // Mean-residual anchoring: bins below mean residual are already
    // "used up"; prefer them slightly.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0 * ((res_f - mean_residual) / cap);
    }

    // Stream progression: early on, be pickier about dead space;
    // late in the stream, just close bins out aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate handling: bin_residual == bin_capacity (empty bin).
    if bin_residual == bin_capacity {
        // Default mild cost for opening a new bin.
        score = cap * 0.55 + 8.0;
        // Open a new bin when the current item is large and would leave
        // an awkward residual in any existing bin, or when this is the
        // last chance but the fit is terrible.
        let awkward = post_residual > 30 && post_residual < 50;
        if fitting_bins_count >= 1 && awkward {
            score -= 20.0; // prefer fresh bin over creating dead space
        }
        if next_item_size > 0 && next_item_size >= 60 && post_residual < next_item_size {
            score -= 6.0; // big item coming; keep fresh capacity
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps that few future items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 8.0 * (1.0 - tightness.min(1.0));
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += pressure * 2.0;
    } else {
        score -= pressure * 0.15;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    }
    // If next item would be blocked by the resulting gap, slight penalty.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 3.0;
    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual exactly matches next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap);
    }

    // Penalize dead space that is too small for the smallest plausible item (1..100 range)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates unusable space relative to lookahead
    }
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny dead space is worthless
    }

    // Relative-to-mean coupling: bins with residual far above mean are worth filling
    score -= 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 30.0 + 40.0 * (1.0 - poor_fit) - 10.0 * progress;
        // A fresh bin wastes nothing now, but discourage unless existing fits are bad
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tight-fit bonus: reward placements leaving small-but-usable residual
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual), superlinear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are wasted
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 3.0; // next item can't use this leftover
        }
        // If next item is large, prefer filling bins with current item.
        if next_item_size >= item_size && post_residual >= next_item_size {
            score -= 4.0;
        }
    } else {
        // Last item: maximize fill, any residual is pure waste.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax
    // the penalty when open bins are fragmented (high mean residual spread)
    // or many bins already exist.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        // If current item leaves large residual in any open bin, new bin is fine.
        // Fragmentation proxy: mean residual far from item needs.
        let spread = (mean_residual - post_residual as f64).abs();
        if mean_residual < item_size as f64 {
            new_bin_penalty -= 8.0; // open bins can barely fit anything
        }
        if spread > 20.0 {
            new_bin_penalty -= 4.0;
        }
        // Late in stream, opening fresh bins is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty -= 6.0 * progress;
        // Many open bins: prefer consolidating into one of them.
        new_bin_penalty += (open_bins_count as f64).sqrt() * 1.5;
        score += new_bin_penalty;
    }

    // Mild preference for filling fuller bins among equals.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 2.0 * fill;

    // Prefer minimizing total open bins early on.
    if bin_residual != bin_capacity {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth polynomial interaction: penalize large residuals early, small residuals late
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Tight fit reward, amplified as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 8.0 * (ns / cap);
        } else {
            score += 6.0 * (1.0 - pr / ns.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr) / cap;

    // New-bin candidate: prefer it only when residuals are very tight late in stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches 0
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 35 {
        score -= 12.0;
    }

    // Dead-space penalty: post_residual too small for any plausible future item
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 15.0;
    }

    // Harmonic classes: bucket post_residual into capacity fractions via integer division.
    // Residuals in the class [50,74] (half-full class) are valuable; heavily penalize
    // residuals just above small-item thresholds where nothing pairs well.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let class = post_residual / 25;
    score -= match class {
        0 => 18.0,           // [0,24]: near-full bin, great placement
        1 => 10.0,           // [25,49]: quarter class
        2 => 4.0,            // [50,74]: half class, mild preference
        _ => 0.0,            // large residual: baseline
    };
    let _ = (half, quarter);

    // Modulo coupling with next_item_size: if the next item fits exactly in the
    // post_residual, strongly favor this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 10 {
            score -= 20.0;
        } else {
            score -= (10.0f64).min(slack as f64 * 0.3);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual can't host next item: penalize proportional to wasted lookahead fit
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.15;
    }

    // Last-chance logic: if this is the only fitting bin, force usage to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Cheaper to open new bin early in stream (more future to amortize)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is wasteful
        score += fitting_bins_count as f64 * 6.0;
        // If next item is large and current item is small, fresh bin preserves structure
        if next_item_size > 60 && item_size <= 30 {
            score -= 25.0;
        }
    }

    // Congestion pressure: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than spreading.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln() * 2.0;
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    // Slight recency tiebreak: keep scores distinct across bins via residual modulo classes
    score -= (post_residual % 7) as f64 * 0.4;
    score -= (post_residual % 13) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Near-full placements are excellent: reward tight fits.
    if post_residual <= 10 {
        score -= 30.0;
    }

    // Dead-space pressure relative to capacity: penalize leaving large unusable chunks
    // when post_residual cannot hold even a mid-sized future item.
    let dead_threshold = bin_capacity as f64 * 0.35;
    if post_residual as f64 > dead_threshold {
        score += 0.0; // large residual is still usable, keep base
    } else if post_residual as f64 > 10.0 {
        // moderately small residual: mild penalty scaled by how unusable it is
        let unusability = 1.0 - (post_residual as f64 - 10.0) / (dead_threshold - 10.0);
        score += 15.0 * unusability;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        // next item cannot use this gap; penalize if gap is small
        if post_residual < 25 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: penalize bins that keep many bins open with scattered residuals.
    let open_pressure = open_bins_count as f64 * 0.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // penalize it unless the current bin's post_residual would be tiny dead space.
        score += 35.0;
        if fitting_bins_count == 1 {
            // still allow opening if the existing fit is terrible (large post_residual waste)
            score += 10.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mean residual alignment: prefer bins whose residual is below average
    // (i.e., more filled bins) to consolidate packing.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain fit: post_residual exactly equals next item size.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as i64 - next_item_size as i64 >= 0 {
            // Next item still fits in this bin after placement: mild reward scaled by tightness.
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item cannot fit: penalize proportionally to wasted chain opportunity.
            score += 10.0 + diff * 0.2;
        }
    }

    // Penalize post_residual far above mean residual (creating outlier dead space).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits (small post_residual) with a super-linear bonus.
    let pr = post_residual as f64;
    score -= 40.0 * (1.0 - pr / bin_capacity as f64).powi(6);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it enables a perfect 2-step chain.
    if bin_residual == bin_capacity {
        if next_item_size > 0
            && item_size as f64 + next_item_size as f64 <= bin_capacity as f64
        {
            score -= 8.0; // fresh bin can host the current + next item chain
        } else {
            score += 18.0; // discourage opening new bins without lookahead justification
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residual, with quadratic decay.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact/near-exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot follow here; mildly penalize leaving awkward gap.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when current open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win by default.
        score += 20.0;
        // If item leaves a large residual in this bin, opening is more acceptable.
        score -= 0.2 * post_residual as f64;
        // If many bins compete and mean residual is high, new bin is less needed.
        score += 2.0 * open_bins_count as f64;
        score += 0.3 * mean_residual;
        // Late in stream: prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Favor filling already-open bins, especially those below mean residual (emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild preference to balance across bins: penalize bins far above mean residual.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff * diff;

    // Early stream: encourage creating well-structured bins (leave room for medium items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter packing (small post_residual) is rewarded more.
    let tightness = 1.0 - (pr / cap);
    let progress_gain = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score -= tightness * tightness * (2.0 + 3.0 * progress_gain) * 10.0;

    // Penalize leaving residual too small to be useful (dead space), smoothly.
    let dead_zone = ((pr / cap) * 2.0 - 0.2).tanh();
    score += dead_zone.abs() * 5.0 * (1.0 - progress);

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize residual that almost-but-not-quite fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // New-bin candidate handling: empty bin gets a base penalty so that
    // decent fits into open bins are preferred; relax late in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Slight penalty when many bins are open and mean residual is high
        // (fragmentation pressure): prefer bins below the mean residual.
        score += ((pr - mean_residual) / cap).tanh() * 3.0;
    }

    // Mild preference for filling larger items into tighter bins overall.
    score -= (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into 8 bands.
    let band = (post_residual * 8 / bin_capacity) as i64; // 0..=7
    let class_penalty: [f64; 8] = [0.0, 60.0, 40.0, 25.0, 15.0, 8.0, 3.0, 0.0];
    score += class_penalty[band.min(7) as usize];

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.15;
    }

    // Harmonic compatibility: does next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item chains perfectly: strong reward, especially if it fills exactly
        score -= 20.0;
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        }
    } else if next_item_size > post_residual {
        // dead space risk: penalize proportionally to wasted fraction
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste;
    }

    // Harmonic class matching between item and residual (modulo logic on capacity fractions)
    let item_class = (item_size * 8 / bin_capacity) as i64;
    let resid_class = (bin_residual * 8 / bin_capacity) as i64;
    if item_class == resid_class {
        score -= 10.0; // same harmonic band: good fill
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: encourage consolidation by penalizing lightly-filled bins.
    if open_bins_count > 4 {
        let gap = (mean_residual - post_residual as f64).abs();
        score += gap * 0.3;
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if post_residual == bin_capacity {
            // base cost of opening a bin; offset if stream is early or bins are scarce
            let progress = step_index as f64 / total_items.max(1) as f64;
            score = bin_capacity as f64 + progress * 30.0 - (fitting_bins_count == 0) as i32 as f64 * 80.0;
            if next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count == 0 {
                score -= 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..=100 range, but typically >= 10) are wasted space.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Unusable sliver: heavy penalty scaled by how close to the threshold.
        score += (dead_threshold - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 25.0;
    }

    // Reward tight fits: ratio of item to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // would leave a large, awkward gap in every existing bin. Empty-bin call
    // has bin_residual == bin_capacity; make it attractive only for large
    // items or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of already open bins.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // If mean residual of open bins is large, opening a new bin wastes
        // existing capacity; penalize more.
        score += mean_residual * 0.3;
        // Lookahead: if next item is small, a fresh bin is fine (it can host
        // many future items); soften penalty.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
        // Late in the stream, avoid opening bins that will go underused.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.9 {
            score += 20.0 * progress;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure; reward.
        score -= 5.0;
        // Bonus for keeping residuals aligned with likely next item sizes:
        // if post_residual can host the next item, this is a good pairing.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize leaving residuals just below the next item's size
        // (near-miss dead space).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // General open-bin pressure: fewer bins preferred; slight reward for
    // consolidating into existing bins when many are open.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover can host the next item: reward closeness of the match.
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover too small for the lookahead item: penalize dead space,
        // scaled by how close it came to fitting.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.8;
    }

    // Reward tightening relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New empty bin candidate: penalize so it is chosen only when
    // no open bin fits or all fits are terrible.
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64).sqrt() * 20.0;
    }

    // Late in the stream, prefer packing tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (next_item_size as f64) / (post_residual as f64);
        score -= 25.0 * next_tight;
    }
    // Penalize leaving a residual too small for any plausible next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }
    // Many fitting bins: mild penalty to preserve flexibility for tighter candidates.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Penalize bins whose residual deviates far above the mean residual (keeps bin states balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New empty bin candidate: discourage unless item is large or no real alternative exists.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 45.0 - 30.0 * large_item;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with a chain of big items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, but with diminishing returns for tiny residuals.
    let mut score = pr.powf(1.35);

    // Smooth non-linear coupling of post residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = (-norm_pr * std::f64::consts::PI).exp();
    score -= 40.0 * progress * tightness * norm_pr;

    // Penalize residuals that cannot fit the lookahead item (smooth logistic gate).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = 1.0 / (1.0 + (-(pr - nxt + 0.5) * 0.25).exp());
        score -= 25.0 * (1.0 - fits_next) * (0.5 + progress);
    }

    // Reward using a bin when it is the only fitting bin (avoid opening new bins).
    if fitting_bins_count <= 1 {
        score -= 60.0;
    }

    // Mild penalty proportional to how far this bin's residual deviates from mean residual,
    // scaled by open bin count (encourage balanced packing early, greedy late).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 15.0 * dev * (1.0 - progress) / (1.0 + open_bins_count as f64);

    // Smooth new-bin preference: strongly discourage opening a new bin when
    // progress is high or many bins already fit the item.
    if bin_residual == bin_capacity {
        let open_pressure = 1.0 / (1.0 + (-(open_bins_count as f64 - 3.0) * 0.5).exp());
        score += 30.0 + 50.0 * progress + 20.0 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in a
    // "clean" residue class (multiples of 10) are more reusable.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0;
    } else if class <= 2 || class >= 8 {
        score += 4.0; // awkward sliver leftovers
    }

    // Integer-division thresholds on post residual: large usable chunks
    // (>= half capacity) are valuable; tiny chunks are dead space.
    if post_residual >= bin_capacity / 2 {
        score -= 8.0;
    } else if post_residual < bin_capacity / 5 {
        score += 10.0;
    }

    // Lookahead coupling: reward bins whose post residual can host the
    // next item exactly or nearly exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 6.0; // next item won't fit here
        }
        // Harmonic pairing: item + next_item summing to a capacity fraction
        if item_size + next_item_size == bin_capacity {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: make it mildly unattractive unless it beats a
    // really bad fit (huge post_residual waste or tiny leftover).
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) + 20.0
            - (next_item_size as f64) * 0.1
            - (open_bins_count as f64) * 0.5;
    }

    // Progression: as the stream advances, tighten packing (penalize waste more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.3 * progress;

    // Mean residual context: if open bins are generally roomy, prefer
    // spreading into this bin less aggressively.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small for the
    // smallest plausible future item (min item = 1, but "useful" threshold
    // calibrated around small item sizes). Gaps in (0, threshold) are dead.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // If next item fits exactly in post_residual, big reward (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }
    // Penalize if post_residual cannot hold the (small) next item: dead for lookahead.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins; mildly
    // favor filling existing bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Mean-residual coupling: when mean residual is large, prefer bins
    // that absorb a lot (reduce mean); when small, avoid wasting big gaps.
    if mean_residual > (bin_capacity as f64) * 0.5 && item_size as f64 > mean_residual * 0.6 {
        score -= 6.0;
    }

    // New-bin candidate: residual == capacity. Make it moderately attractive
    // only when the item is large relative to capacity or fits nowhere well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 20.0;
        // Large items justify a fresh bin (avoid fragmenting).
        if item_size > 60 {
            score -= 18.0;
        }
        // Late in the stream, opening bins is less costly (fewer future regrets).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Small early-stream nudge: keep bins balanced early by preferring
    // higher post_residual slightly when few bins exist.
    if open_bins_count <= 2 {
        score += post_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Leftover that can still host the next item is somewhat valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64) * 0.05;
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.25;
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual means we compacted this bin more than typical -> reward.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): should only win when the fit is bad
    // elsewhere. Give it a mild penalty so tight fits in open bins win,
    // but not so large that a terrible fit is forced.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If the item fits poorly in an empty bin anyway (tiny item), that's fine.
        if item_size >= bin_capacity / 2 {
            score -= 4.0;
        }
    }

    // Prefer filling bins that are already mostly full (small residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: small unusable leftovers are wasteful, but less so late in the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64));
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing bins.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when the item is large and residual usage elsewhere is high.
    if is_new_bin {
        let size_frac = item_size as f64 / bin_capacity as f64;
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 35.0 * (1.0 - size_frac) * (1.0 + mean_tightness);
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        score -= 10.0 * progress;
    }

    // Mild preference for bins with residual close to the item (perfect match seeking).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    let mut score = post;

    // Smooth non-linear coupling: waste grows super-linearly with post_residual,
    // amplified as the stream progresses.
    let progress_amp = 1.0 + 3.0 * progress * progress;
    score += progress_amp * 2.0 * post_norm * post_norm * cap;

    // Penalize dead space relative to mean residual (smooth quadratic).
    let dev = post_norm - mean_residual / cap;
    score += 1.5 * dev * dev * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= 4.0 * (1.0 - post_norm) * fit_ratio * cap * 0.5;

    // Lookahead: penalize if post_residual cannot hold the next item (smooth gate).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - post).max(0.0) / cap;
        score += 2.0 * gap * gap * cap;
        // Bonus when post_residual nicely accommodates the next item.
        let cover = if nx > 0.0 { (post / nx).min(1.0) } else { 0.0 };
        score -= 1.0 * cover * cover;
    }

    // Last-chance bin: strongly favor using it (smooth exponential reward).
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + fit_ratio);
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * (open_bins_count as f64).powf(1.2);

    // New-bin candidate: make it moderately attractive only for large items /
    // when post_residual would be tiny relative to capacity anyway.
    if bin_residual == bin_capacity {
        score -= 2.0 * fit_ratio;
        score += 3.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, 25, 50, 75, 100) are more reusable; reward them.
    let cap = bin_capacity as f64;
    let quarter = (cap / 4.0) as u32;
    let post = post_residual;
    let post_mod = post % quarter.max(1);
    let harmonic_distance = post_mod.min(quarter.max(1) - post_mod) as f64;
    score += 0.9 * harmonic_distance; // penalize off-class residuals

    // Exact harmonic class bonus (dead space zero is perfect)
    if post == 0 {
        score -= 30.0;
    } else if post % quarter == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= post {
        score -= 6.0;
        // Extra reward if next item lands on a harmonic boundary too
        if (post - next_item_size) % quarter == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post && post > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted class
        score += 0.35 * post as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 14.0 + 10.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 6.0 * (fitting_bins_count as f64).sqrt();
        }
        // Large items relative to capacity justify a fresh bin more
        let big_item = item_size as f64 > 0.6 * cap;
        if big_item {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    }

    // Tight-fit reward: small relative slack is good
    let slack_ratio = post as f64 / cap;
    score += 4.0 * slack_ratio * slack_ratio;

    // Spread pressure: when many bins are open, prefer filling the emptiest-tight
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Modulo threshold on item size: items in upper harmonic half pair better
    // with bins whose residual is in the complementary half
    let item_class = item_size % quarter.max(1);
    let resid_class = bin_residual % quarter.max(1);
    if item_class + resid_class <= quarter.max(1) {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to be useful are heavily penalized.
    // A residual is "dead" if it cannot fit even a mid-size item (assume ~10% capacity threshold).
    let dead_threshold = bin_capacity as f64 * 0.12;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if (post_residual as f64) < dead_threshold {
            score -= 10.0; // near-perfect fit on last chance
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so its post_residual
    // is large; add pressure so it only wins when fits are truly bad.
    score += open_bins_count as f64 * 2.0;

    // Mean residual coupling: if open bins are already quite empty, penalize
    // leaving this bin with a large residual relative to the mean.
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post_residual is smaller than next item but nonzero (wasted potential).
    else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Prefer tight fits generally: reward small post_residual relative to item size.
    score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 8.0;

    // Late in the stream, consolidate: extra penalty for new-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: small post_residual (tight fit) is good.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight_fit;

    // 2-step lookahead: reward bins where the NEXT item also fits in the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can follow: strong reward, scaled by how snugly it fits.
            let next_tight = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 20.0 * next_tight;
            // Bonus if next item fills bin almost completely after both placements.
            if post_residual - next_item_size <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize wasting a big residual on one item.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than the average open bin.
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave awkward dead space
    // and the next item is large relative to the post residual.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 && post_residual <= 10 {
            score -= 10.0; // perfect item fit in fresh bin, keep chain going
        } else {
            score += 18.0; // discourage opening new bins when open bins fit fine
        }
        // Early in stream, more open bins are acceptable; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Penalize leaving residuals that are hard to reuse (small odd gaps) for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Relative waste component: penalize proportionally unusable leftover space.
    score += (post / cap) * 35.0;

    // Strongly prefer near-perfect fits (tiny post_residual).
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual > 40 {
        // Large dead space is risky unless the bin is fresh.
        score += 12.0 * (post / cap);
    }

    // New-bin candidate: mild penalty so we only open new bins when fits are bad;
    // penalty grows over time (late stream => consolidate more).
    if is_new_bin {
        score += 10.0 + 15.0 * progress;
        // Opening a new bin is more acceptable if it leaves room for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0;
        }
    }

    // Global state: many open bins => favor filling existing ones (consolidation pressure).
    score += open_bins_count as f64 * 0.4;

    // High mean residual across bins => slack is abundant, be pickier about bad fits.
    score += mean_residual * 0.06;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nxt = next_item_size as f64;

    // Core: strongly reward small post_residual (quadratic dead-space penalty)
    let mut score = post * (1.0 + 0.02 * post / cap) + 0.0035 * post * post / cap;

    // Smooth polynomial coupling of fit quality with stream progress:
    // later in the stream, tighter fits matter more (dead space is less recoverable)
    let fit_quality = 1.0 - (post / cap);
    score -= 6.0 * fit_quality * fit_quality * (0.5 + progress);

    // Reward using bins with larger residual (consume slack where it exists)
    score -= 0.012 * resid * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits exactly in post_residual, big bonus (smooth)
    if nxt > 0.0 && post > 0.0 {
        let gap = (post - nxt).abs();
        score -= 5.0 * (1.0 - gap / cap).powi(3);
    } else if nxt == 0.0 {
        // last item: fully closing a bin is ideal
        score -= 8.0 * (1.0 - post / cap).powi(2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 4.0 * (1.0 - post / cap);
    } else if fitting_bins_count > 1 {
        // mild competition penalty so the best-fitting bin wins among many
        score += 0.35 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin should score worse than decent fits,
    // but better than terrible fits (large post_residual on open bins)
    let is_new = bin_residual == bin_capacity && item > 0.0;
    if is_new {
        // baseline cost of opening a bin; decreases as stream progresses / many bins open
        score = cap * (0.85 - 0.15 * progress) + 0.5 * (open_bins_count as f64).sqrt();
        // if next item is huge, a fresh bin is more attractive
        score -= 0.15 * nxt.min(cap);
    }

    // Mean-residual coupling: when open bins are slack-rich, prefer consuming them
    score -= 0.02 * mean_residual * (1.0 - fit_quality);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: values divisible by common item
    // sizes (10, 20, 25, 50) are reusable "harmonic" dead space.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr == 0 {
        harmonic_bonus -= 60.0; // perfect closure
    } else {
        if pr % 10 == 0 { harmonic_bonus -= 8.0; }
        if pr % 20 == 0 { harmonic_bonus -= 4.0; }
        if pr % 25 == 0 { harmonic_bonus -= 4.0; }
        if pr % 50 == 0 { harmonic_bonus -= 6.0; }
        // Small unusable residues are penalized super-linearly.
        if pr < 10 {
            harmonic_bonus += (10 - pr) as f64 * 6.0;
        } else if pr < 20 {
            harmonic_bonus += (20 - pr) as f64 * 1.5;
        }
        // Integer-division threshold: residue classes that match the
        // lookahead item keep the bin useful for the next step.
        if next_item_size > 0 && next_item_size <= pr {
            let diff = pr - next_item_size;
            harmonic_bonus -= 12.0;
            if diff % 10 == 0 { harmonic_bonus -= 5.0; }
            if diff == 0 { harmonic_bonus -= 15.0; }
        } else if next_item_size > pr && next_item_size > 0 {
            harmonic_bonus += 5.0; // bin likely dead after this placement
        }
    }
    score += harmonic_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (tight bins, low mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        score += 18.0 - 22.0 * pressure - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    // Prefer filling bins that are already more depleted (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // gaps 1..9 are near-unusable (min item ~10)
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // only fits tiny items, mildly wasteful
    }

    // Reward using tight residual space: the fuller the bin relative to residual, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += 0.9 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly prefer placing here over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post-residual exactly, big bonus.
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual && post_residual > 0 {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 15.0; // dead space that even the next item can't use
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) early,
    // but late in the stream consolidate into larger residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - bin_residual as f64) * (0.15 - 0.25 * progress);

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, all residuals small) or stream is early and item is big.
    if bin_residual == bin_capacity {
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        let poor_fit_everywhere = fitting_bins_count == 0
            || (avg_open_residual < item_size as f64 + 5.0);
        if poor_fit_everywhere {
            score -= 40.0; // open a fresh bin rather than butcher a fit
        } else {
            score += 55.0 + 1.5 * open_bins_count as f64; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: minimize wasted space non-linearly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let look_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - look_gap / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills the remainder.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that nothing useful can use.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: pure tight fit.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins that are already well-used
    // (below mean residual) to consolidate space.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin, especially early in the stream or when
    // decent alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * (1.0 - progress);
        if post_residual as f64 > mean_residual + 20.0 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Perfect chaining: post_residual exactly fits next item.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Wasted chain potential relative to mean residual.
            score += 4.0 * (1.0 - (post_residual as f64) / (mean_residual.max(1.0) + post_residual as f64));
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (open_bins_count as f64).ln().max(0.0);
        score = bin_capacity as f64 + 15.0 + 10.0 * congestion - 10.0 * progress;

        // If no existing bin fits well, opening a new bin becomes competitive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Lookahead synergy: fresh bin can host both current and next item.
        if next_item_size > 0 && 2 * item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidate fuller bins).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Time-horizon coupling: later in stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit), smooth polynomial in post/cap.
    let x = post / cap; // normalized post-residual in [0,1]
    let mut score = x * (2.0 - x); // concave penalty: small residuals rewarded strongly

    // Non-linear coupling: tight fits matter more as the stream progresses.
    score -= (1.0 - x * x) * (0.35 + 0.65 * progress);

    // Penalize dead space that is too small to be useful later (below min item size),
    // smoothly via a quadratic bump around the unusable region.
    let unusable = ((10.0 - post).max(0.0)) / 10.0;
    score += unusable * unusable * 6.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead coupling: reward leaving post-residual that still fits the next item;
    // penalize if post_residual is nonzero but too small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt && post >= 10.0 {
            score -= 2.5 * (1.0 - (post - nxt) / cap);
        } else if post > 0.0 && post < nxt {
            score += 1.5 + 2.0 * progress;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins fit poorly (large post_residuals)
        // or when fragmentation is high. Smooth gate on item size and mean residual.
        let big_item = item / cap;
        score += 4.0
            - 6.0 * big_item * big_item
            - 2.0 * (mean_residual / cap).max(0.0).min(1.0)
            - 3.0 * progress;
    }

    // Mild penalty for proliferating many open bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 measure dead space quality
    let r = post_residual % 10;
    score -= match r {
        0 => 12.0, // perfectly harmonic residual (e.g. 0,10,...): excellent
        5 => 6.0,  // half-class: decent
        _ => {
            // penalize awkward residues, worse for small r (thin slivers)
            let thin = if r < 5 { r } else { 10 - r };
            (thin as f64) * 1.5
        }
    };

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Harmonic pairing: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_r = next_item_size % 10;
        let post_class = post_residual / 10;
        let next_class = next_item_size / 10;
        if post_residual % next_item_size == 0 {
            score -= 15.0; // exact integer-division fit
        } else if next_r == 0 || next_r == 5 {
            score -= 8.0; // harmonic next item fits
        }
        // coupling of capacity-fraction classes
        let frac = (post_residual as f64) / (bin_capacity as f64);
        if frac >= 0.5 && next_class >= 2 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use: penalize
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64; // = capacity - item
        if fit_quality <= 20 {
            // item is big; opening a fresh bin is reasonable
            score -= 10.0;
        } else {
            // small item: strongly discourage wasting a new bin
            score += 30.0 + (fit_quality - 20.0) * 0.5;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // many open bins: discourage opening more
        score += (open_bins_count as f64) * 1.2;
    } else {
        // favor tighter existing bins slightly via mean-residual contrast
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: mild baseline preference unless open-bin fits are good.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized by open-bin pressure; slightly worse than a perfect fit.
        return 5.0 + 0.6 * open_bins_count as f64;
    }

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A gap is "dead" if no plausible future item (1..=100) can use it well.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny sliver: pure dead space — heavily penalize.
            score += 60.0;
        } else if post_residual < 25 {
            // Small gap: only usable by small items; penalize proportionally.
            score += 25.0 + (25 - post_residual) as f64 * 1.5;
        } else if post_residual < 50 {
            // Medium gap: mildly risky.
            score += 8.0;
        }
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead synergy: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack <= 10 {
            score -= 12.0;
        }
    }
    // Penalize if next item won't fit here (bin becomes dead for the near future).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin count pressure: discourage proliferation of bins with poor residuals.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual deviates below the mean (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late-stream tightening: dead space matters more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * if post_residual < 25 { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but reward exact/near-exact fits extra.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chaining keeps slack small; penalize growing slack.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            if slack <= 10.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: this bin becomes dead space after placement.
            let dead = post_residual as f64;
            score += 0.35 * dead;
        }
    }

    // Compare against mean residual: placing into a bin with residual far below mean
    // (small residual bin) is good; big-residual bins should be saved for big items.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.25 * (mean_residual - resid);
    } else {
        score += 0.15 * (resid - mean_residual);
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty to encourage spreading across bins? No: prefer consolidation,
        // but among multiple fitting bins prefer the tightest (handled by post_residual).
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if current bin would leave large dead space and next item is big,
        // opening fresh may be better.
        if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid opening bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty on very loose fits regardless (dead space creation).
    if post_residual > 30 {
        score += 0.2 * (post_residual - 30) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize creating tiny unusable slivers
        if post_residual < 10 {
            score += 25.0;
        } else {
            score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // If next item exactly fills post_residual, big reward
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin unless it's
    // genuinely attractive (large item, no good alternatives).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() + 1.0 };
        // Base cost of a new bin
        score += 70.0;
        // Cheaper to open a bin early in the stream or when many bins are open anyway
        score -= 25.0 * progress;
        score -= 5.0 * open_bins_count as f64;
        // Large items benefit from a fresh bin
        score -= 0.4 * item_size as f64;
        // If alternatives exist, discourage new bin proportionally
        score += 15.0 * pressure;
        // If the next item is large and this item leaves a good residual, fresh bin is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins relative to global mean residual
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Slight noise-free diversity term: avoid over-focusing on one bin
    if bin_residual > item_size * 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, larger residual space is fine; late in the stream, dead space is more costly.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * norm_pr * norm_pr * progress;
    score += 30.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tight = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 25.0 * tight * (0.5 + 0.5 * progress);

    // Penalize when post_residual is small but nonzero and can't fit the lookahead item,
    // weighted by how close the next item is to the leftover space.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (norm_next - norm_pr).abs();
        let waste = 1.0 - gap;
        score += 10.0 * waste * norm_pr * (1.0 - norm_item);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * norm_pr;
    }

    // Mild penalty relative to mean residual: avoid leaving this bin far below average fill.
    score += 0.5 * (mean_residual - pr).abs() * (0.3 + 0.7 * progress);

    // New-bin candidate: empty bin has full residual; penalize opening new bins,
    // more so early when open bins still have room to consolidate.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strong bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Exact fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: bins whose residual falls into "good" modular classes
    // (multiples of 10, 25, 50) remain usable for common item sizes.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // Dead-space penalty for awkward residuals (just above small item sizes).
        if pr < 10 {
            score += 25.0; // unusable dead space under min item size
        } else if pr < 20 {
            score += 8.0;
        }
    }

    // Next-item coupling: if the lookahead item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Extra reward if it fills nearly exactly.
        let gap = pr - next_item_size;
        if gap <= 10 { score -= 8.0; }
    } else if next_item_size > pr {
        // Post residual can't host next item: mild penalty scaled by waste.
        score += 4.0 + (next_item_size as f64 - pr as f64) * 0.1;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins win normally.
        score += 40.0;
        // But if the item is huge relative to mean residual (poor fits everywhere),
        // opening a fresh bin becomes attractive.
        let frac = item_size as f64 / cap;
        if frac > 0.6 {
            score -= 25.0 * frac;
        }
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early stream: fresh bins are cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 10.0;
        }
    }

    // Mild pressure against bin proliferation.
    score += 0.5 * open_bins_count as f64;

    // Small progress-based tie-break.
    score += 0.01 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling a bin deeply (small post_residual relative to capacity).
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 30.0 + 2.5 * open_bins_count as f64 + 20.0 * progress;
        // Allow a new bin if the next item would benefit from fresh space.
        if next_item_size > 0 && next_item_size > post_residual + 10 && open_bins_count > 0 {
            score -= 10.0;
        }
    } else {
        // Mild penalty for using bins when many are open (encourage consolidation).
        score += 0.4 * open_bins_count as f64 * (1.0 - fill_ratio);
        // Favor bins whose residual is close to the mean (keep residuals uniform).
        score += 0.15 * ((bin_residual as f64 - mean_residual).abs());
        // Lookahead: if next item fits the resulting gap, reward this placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual exactly (or nearly) matches
    // the next item's size, so the next item can seal this bin.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual as u32 == next_item_size {
            score -= 45.0; // perfect chaining: bin closed after next item
        } else if diff <= 10.0 {
            score -= 25.0 - 2.0 * diff;
        } else {
            // penalize dead space that the next item cannot use
            if post_residual < next_item_size as f64 {
                score += 0.3 * (next_item_size as f64 - post_residual as f64);
            }
        }
    } else {
        // last item: minimize waste directly
        score += 5.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates below the mean
    // (consolidating space into fewer bins).
    score += 0.15 * (mean_residual - bin_residual as f64).abs().copysign(bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current item is large and would
    // leave open bins with unusable slivers.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = (post_residual as f64) * (1.0 - progress);
        score = 100.0 - 0.5 * item_size as f64 - 0.2 * waste_elsewhere;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also chain the next item
        }
        if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the sole fitting bin
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Penalize small dead space that can't hold typical items.
    if post_residual < 10 {
        score -= 6.0; // perfect closure bonus
    } else if post_residual < 20 {
        score += 4.0; // awkward dead zone
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tight = tightness; // 1.0 for empty bin
        // Penalize new bin more when many bins are open and mean residual is large.
        score += 18.0 + 0.35 * open_bins_count as f64 + 0.2 * mean_residual;
        // Late in the stream, discourage opening bins unless truly necessary.
        score += 15.0 * progress;
        // If the next item is large and this bin would stay near-empty, slight discount.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < mean_residual {
            score -= 5.0;
        }
        let _ = mean_tight;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 7.0;
        } else if post_residual > 0 {
            score += 3.0; // leaves unusable sliver for the known next item
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins elsewhere).
    score += 0.05 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual.
    let mut score = pr * (1.0 + 0.02 * (pr / cap) * (pr / cap));

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (pack tightly).
    let progress_coupling = pr * pr / cap * (0.5 + progress);
    score += 0.15 * progress_coupling;

    // Reward bins whose residual after placement matches the lookahead item
    // (smooth Gaussian-like coupling instead of hard equality).
    if nxt > 0.0 {
        let d = (pr - nxt) / cap;
        score -= 12.0 * (-40.0 * d * d).exp();
    } else {
        // Last item: strongly prefer zero post residual.
        score -= 10.0 * (-(pr / cap) * (pr / cap) * 4.0).exp();
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize bins far below/above mean residual (encourage residual balance),
    // with smooth quadratic term modulated by progress.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap * (1.0 - progress);

    // New-bin candidate: penalize so it's only chosen when all open bins fit badly.
    if bin_residual == bin_capacity {
        // The worse the best alternative would be (large item, few fitting bins),
        // the less we penalize opening a new bin.
        let desperation = (fitting_bins_count == 0) as i32 as f64 * 10.0
            + (item / cap) * 4.0
            + progress * 2.0;
        score = 60.0 + pr * 0.1 - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtraction)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class of post_residual modulo 10:
    // dead space classes (1..=9 mod 10) that can't fit typical small items get penalized
    let residue_class = post_residual % 10;
    if post_residual > 0 {
        match residue_class {
            0 => score -= 6.0,          // round residual, most reusable
            1 | 2 | 3 => score += 4.0,  // sliver dead space
            4 | 5 | 6 => score += 1.0,
            _ => score += 2.5,
        }
    }

    // Dead-space detection: residual too small for the lookahead item but nonzero
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
        // extra penalty if the wasted space is in an awkward class
        if post_residual < 10 {
            score += 5.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // reward leaving room for the known next item
        score -= 4.0;
        if post_residual == next_item_size {
            score -= 10.0; // chains into a perfect fit next step
        }
    }

    // Last-chance bin: only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: opening a new bin should only win when it
    // produces a much better harmonic class than any open bin
    if bin_residual == bin_capacity {
        score += 18.0;
        // if the item is large, the new bin's post residual is small and useful
        if item_size >= 70 {
            score -= 10.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Prefer bins tighter than the mean residual (better-packed bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // the smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // Semi-dead zone: only items of size <= post_residual can ever use it.
        score += 8.0 + (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin count pressure: mildly discourage accumulating too many bins,
    // but this applies equally to all candidates so it mostly shapes the
    // dead-space tradeoff late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 1.5 * progress) * 0.05;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the fresh bin mildly unattractive so it
    // wins only when open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening a bin for a big item with a matching
        // lookahead can be worthwhile (pairing two large items).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor)
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual and post_residual is dead space anyway, slight penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mean-residual coupling: when mean residual across bins is high, prefer
    // consolidating into fuller bins (larger post_residual penalty).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
