pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item also fits in the post-residual, reward this bin.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 14.0;
        // Extra reward if next item nearly fills the bin after placement.
        let post2 = post_residual - next_item_size;
        if post2 < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Dead space that the next item can't use: penalize proportionally.
        let waste = (post_residual as f64) / cap;
        score += 8.0 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Late in the stream, avoid opening new bins more strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If mean residual is large, open bins are underused; discourage new bin.
        if mean_residual > (item_size as f64) * 1.2 {
            score += 12.0;
        }
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for very large residual bins being "wasted" on small items.
    if (item_size as u32) < 20 && bin_residual > 60 && bin_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let res = bin_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Polynomial coupling of waste ratio with stream progress: late in the
    // stream, dead space becomes progressively more costly.
    let waste_ratio = post / cap;
    let progress_coupling = (waste_ratio * waste_ratio) * (0.5 + 2.5 * progress * progress);
    score += 30.0 * progress_coupling;

    // Reward filling a bin almost exactly (smooth bump near zero post residual).
    score -= 15.0 * (-post / (0.25 * cap)).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // With multiple options, penalize wasting space in a tight bin less
        // if it keeps many bins viable.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = post - next_item_size as f64;
        score -= 10.0 * (1.0 - slack / cap).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover gap.
        score += 3.0 * (post / cap);
    }

    // New-bin candidate handling: empty bin starts with a penalty so we only
    // open a new bin when the item is large relative to capacity or fits badly
    // everywhere.
    let is_new_bin = (bin_residual as u64) == (bin_capacity as u64);
    if is_new_bin {
        let big_item = item / cap; // 0..1
        // Opening a bin is good for large items or late in the stream.
        score += 40.0 - 45.0 * big_item - 20.0 * progress;
        // If no open bin can fit, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Slight preference for reusing existing bins.
        score -= 2.0;
        // Penalize placing into bins whose residual is far from the item
        // (creates awkward leftovers), scaled by mean residual context.
        let fit_gap = (res - item) / cap;
        score += 5.0 * fit_gap * fit_gap;
        // Balance usage across bins: prefer bins near the mean residual.
        let dev = (res - mean_residual) / cap;
        score += 4.0 * dev * dev;
    }

    // Mild global pressure: more open bins -> encourage consolidation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    let mut score = post * 0.02;

    // Harmonic class of post_residual: modulo classes of 10 (capacity fractions).
    // Residuals that are exact multiples of 10 are "harmonic" and more reusable.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= harmonic * 3.0;

    // Integer-division thresholds: post_residual bucket determines dead-space risk.
    let bucket = post_residual / 10; // 0..=10
    // Penalize tiny dead space (<10) that can never be used (min item size 1..100 unknown, but small slivers attract few items)
    if post_residual < 10 {
        score += 6.0;
    }
    // Sweet-spot buckets: residuals in [20,40] or [50,70] are highly reusable.
    if bucket >= 2 && bucket <= 4 { score -= 2.5; }
    if bucket >= 5 && bucket <= 7 { score -= 1.5; }

    // Lookahead coupling: reward if next item fits the post residual (harmonic chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Exact chaining: post_residual == next_item_size is perfect.
            if post_residual == next_item_size {
                score -= 8.0;
            } else {
                score -= 3.0 * (nxt / post.max(1.0));
            }
        } else {
            // Next item won't fit here; penalize proportionally to leftover waste.
            score += 1.0 + (post / cap) * 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it
    // moderately attractive only when no open bin fits well, and when open bins
    // are mostly full (low mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let fill_pressure = 1.0 - (mean_residual / cap);
        score = cap * 0.02; // baseline post_residual of empty bin
        score -= fill_pressure * 4.0;
        score += open_bins_count as f64 * 0.05; // slight resistance to bin proliferation
        // If stream is near the end, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 3.0;
    }

    // Mild penalty when item barely fits a nearly-full bin but leaves a bad class.
    let frac = item / cap;
    if frac > 0.8 && post_residual > 0 {
        score -= 1.0; // reward placing big items, freeing small residual classes
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    // A residual that is too small to host even the minimum item size is pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable dead space penalty
    } else if post_residual < 20 {
        score += 25.0; // barely usable gap
    }

    // Perfect-fit reward: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Prefer bins tighter than the mean residual (near-full bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // would leave an unusable gap or fits perfectly.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        if post_residual == 0 {
            score -= 100.0;
        }
        if post_residual < 10 {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits snugly.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post - next;
        score -= 25.0 - slack * 0.8;
    }
    // Next item cannot use leftover: dead space risk.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += (next - post) * 0.35;
    }

    // Penalize unusable small dead space (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Tight fit reward relative to mean residual.
    let tightness = 1.0 - (post / cap);
    score -= tightness * 12.0;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (mean_residual - post) * 0.25;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or all open bins would leave bad residue.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / cap) > 0.7;
        let poor_fits = fitting_bins_count == 0;
        if !(big_item || poor_fits) {
            score += 55.0;
        } else {
            score += 8.0;
        }
    }

    // Slight late-stream pressure to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize leaving dead space that likely can't be used later.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small unusable-ish gap is fine (item nearly fills bin)
    } else if post_residual >= 10 && post_residual < item_size.min(40) {
        // gap smaller than a plausible future item => wasted space
        score += 0.35 * (post_residual as f64);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this bin strongly.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 * (next_item_size as f64) / (bin_capacity as f64);
        // extra reward if next item fits snugly too
        let next_left = post_residual as f64 - next_item_size as f64;
        if next_left < 10.0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        // post residual can't host next item: mild penalty scaled by gap
        score += 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // when several bins fit, prefer the one whose use preserves flexibility
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Time horizon: early in stream, be more willing to open new bins (exploration);
    // late in stream, consolidate to avoid many mostly-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress; // late: slight global preference for existing bins

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when: few bins fit the item,
        // the item is large, or open bins are already quite full on average.
        let avg_fullness = 1.0 - mean_residual / (bin_capacity as f64).max(1.0);
        let pressure = (avg_fullness - 0.5).max(0.0); // 0 when bins half-empty
        let large_item_bonus = (item_size as f64 / 100.0) * 6.0;
        let scarcity = if fitting_bins_count <= 1 { 14.0 } else { 0.0 };
        let openness = (1.0 - progress) * 2.0; // early stream: cheaper to open
        score += 18.0 - large_item_bonus - 10.0 * pressure - scarcity - openness;
        // never make new bin too attractive when a decent fit exists
        if post_residual == 0 {
            score += 30.0; // perfect fit in an existing bin always wins
        }
    }

    // Mild penalty on bins far below mean residual (keep bins balanced, avoid
    // fragmenting many half-empty bins when one is nearly full).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += 0.08 * diff;
    }

    // Slight penalty proportional to open bin count: encourage closing out bins.
    score += 0.02 * (open_bins_count as f64).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, punish dead space more.
    let w = 1.0 + 1.5 * progress * progress;
    score *= w;

    // Non-linear reward for small normalized residual (tight packing)
    score -= 30.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize residuals that are too small to ever fit a future item
    // (dead space): quadratic penalty once post_residual < 10.
    if post < 10.0 && post > 0.0 {
        score += 20.0 * (10.0 - post) / 10.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a bin while others fit
        score += 35.0;
        // If this bin is the only fitting option (no open bin fits),
        // fitting_bins_count counts only open bins that fit, so ==0 means new bin required
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in stream with large next item, opening fresh bin can help
        let next_fits_now = (next_item_size as f64) <= post;
        if !next_fits_now && next_item_size > 0 {
            score += 15.0 * (1.0 - progress);
        }
        // Fewer open bins => slightly cheaper to open
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Reward bins whose residual stays useful for the lookahead item
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0;
        }
        // Prefer bins below mean residual (keeps residual distribution balanced)
        score += 0.15 * (post - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: group residuals into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals too small to accept the smallest plausible item.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Modulo-class logic on post_residual relative to capacity fractions (C/8 bands).
    let band = post_residual % 25; // C/4 harmonic class
    let band_bonus = match band {
        0 => 25.0,           // perfectly quarter-aligned residual
        1..=5 => 10.0,       // near-aligned
        _ => 0.0,
    };
    score -= band_bonus;

    // Integer division threshold: residual / item_size quotient rewards tight fits.
    let quotient = if item_size > 0 { post_residual / item_size } else { 0 };
    if quotient >= 1 {
        score -= 8.0 + 2.0 * quotient as f64;
    }

    // Lookahead coupling: does the residual left behind admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.1;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - pr) * 0.15; // wasted sliver vs next item
        }
        // Harmonic pair: item + next_item sums near capacity fractions
        let pair = item_size + next_item_size;
        if pair == bin_capacity {
            score -= 20.0;
        } else if bin_residual >= pair {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: prefer only when open bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 + 40.0 * pressure - 10.0 * progress;
        if open_bins_count == 0 {
            score = -100.0; // must open first bin
        }
    }

    // Mild preference to balance residual usage across open bins.
    score -= 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": post-residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < next_item_size as f64 * 1.0 && post_residual > 0 {
        // Gap unusable by the lookahead item: strong dead-space penalty.
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward leaving enough room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual - next_item_size <= 5 {
            score -= 6.0; // chain fit: both items pack this bin tightly
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins mildly.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: empty bin should only win if it enables a tight
    // future pairing or no open bin is decent; otherwise penalize it.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size - next_item_size) <= 5 {
            score -= 35.0; // perfect two-item chain in a fresh bin
        }
        if open_bins_count == 0 || fitting_bins_count == 0 {
            score -= 30.0; // no alternative exists
        }
    }

    // Slight preference for tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (item perfectly fills the bin).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left after hypothetically hosting the next item: small slack is better.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 - (slack_after_next as f64).min(40.0);
            // Bonus if the next item then exactly finishes the bin.
            if slack_after_next == 0 {
                score -= 60.0;
            }
        } else {
            // Post-residual cannot host next item: penalize proportionally to how
            // close it is to being useful (near-miss dead space is worst).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Penalize small-but-nonzero dead space relative to mean residual across bins.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable slivers are bad
    }
    // Compare against the average residual: prefer bins that tighten the distribution.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: make it attractive only when the current fit is poor
    // (large post_residual) or when many bins are already open.
    if bin_residual == bin_capacity {
        // Base penalty so empty bins are chosen only when justified.
        score += 45.0;
        // Attractive when the item leaves a huge residual in any existing bin anyway
        // (i.e. poor fits everywhere) — the empty-bin call has post_residual == C - item.
        score -= (item_size as f64) * 0.1;
        // More open bins -> slightly prefer reusing them over adding new ones.
        score += (open_bins_count as f64) * 2.0;
        // Late in the stream, keep consolidation: discourage new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly for small residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately expensive,
    // cheaper only when few bins fit the item or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 35.0 - 15.0 * progress - 12.0 * scarcity;
        // If next item is large and this bin would be near-perfect for both, allow opening.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins aggressively rather than fragmenting space.
    if open_bins_count > 0 {
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 6.0 * mean_tight * (open_bins_count as f64).sqrt();
    }

    // Prefer placing into bins that are already partially filled (avoid bin proliferation).
    score += 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fit reward: strongly favor bins left with little space.
    score -= (1.0 - pr / cap).powi(3) * 30.0;

    // Dead-space penalty: residual too small for the lookahead item is likely wasted.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && pr < nx {
            let waste = (nx - pr) / cap;
            score += waste * 25.0 * (0.5 + 0.5 * progress);
        }
        // Reward residuals that exactly accommodate the next item (chain packing).
        if nx > 0.0 && (pr - nx).abs() < 0.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * (1.0 - progress);
    }

    // Penalize very small but nonzero leftovers less as stream progresses
    // (late-stage tight packing is more valuable).
    if pr > 0.0 && pr < 10.0 {
        score -= 6.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean residual
    // (fill the emptiest-feeling bins relatively harder when mean is high).
    score += (mean_residual - pr) * 0.15;

    // Mild penalty for opening new bins when many are open and progress is early.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residues that other items
    //     commonly fit into are good; prime/awkward residues are dead space. ---
    let pr = post_residual as i64;
    if pr > 0 {
        // Residue classes modulo small harmonics of capacity.
        let mod10 = pr % 10;
        let mod20 = pr % 20;
        let mod25 = pr % 25;
        let mod50 = pr % 50;

        // Exact harmonic closures (0 mod 10/20/25/50) are ideal residuals:
        // many future item sizes can land in them.
        if pr % 50 == 0 { score -= 22.0; }
        else if pr % 25 == 0 { score -= 16.0; }
        else if pr % 20 == 0 { score -= 14.0; }
        else if pr % 10 == 0 { score -= 9.0; }

        // Penalize awkward residues (prime-ish, near-miss classes).
        if mod10 != 0 && mod10 <= 3 { score += 8.0; }          // tiny unusable slivers
        if mod20 >= 17 { score += 5.0; }                        // near-closure but not
        if mod25 >= 22 { score += 5.0; }
        if mod50 >= 47 { score += 4.0; }

        // Integer-division thresholds: how many "typical" small items still fit.
        let fits_10 = pr / 10;
        let fits_20 = pr / 20;
        let fits_40 = pr / 40;
        let usable_depth = (fits_10 + 2 * fits_20 + 3 * fits_40) as f64;
        score -= 0.9 * usable_depth;

        // Dead-space cliff: residual too small for any plausible item.
        if pr < 10 { score += 30.0; }
        else if pr < 20 { score += 12.0; }
    } else if pr == 0 {
        // Perfect fill — best possible outcome.
        score -= 45.0;
    }

    // --- Lookahead coupling: does this placement leave room for next_item_size? ---
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let n = next_item_size as i64;
        if pr >= n {
            // Harmonic match between post_residual and next item.
            if pr % n == 0 {
                score -= 18.0;                       // next item closes this bin exactly
            } else if (pr - n) % 10 == 0 || (pr - n) % 20 == 0 {
                score -= 10.0;                       // leaves a harmonic residue after next
            } else {
                score -= 4.0;                        // at least it fits
            }
        } else {
            // Next item won't fit here: residual becomes stranded unless small.
            if pr > 0 && pr < 20 { score += 14.0; }
            else if pr >= 20 { score += 3.0; }       // still reusable by later items
        }
    }

    // --- Last-chance bonus: only this bin fits the item; avoid opening a new bin. ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- New-bin candidate handling: bin_residual == bin_capacity means empty bin. ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Base cost of a fresh bin: high, unless item is large relative to capacity
        // and current bins are congested.
        let congestion = if open_bins_count > 0 {
            mean_residual / (bin_capacity as f64)
        } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;

        // Large items with poor fits elsewhere justify a new bin.
        if item_frac > 0.6 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
        // If open bins are nearly full on average, a new bin is fine.
        if congestion < 0.25 && open_bins_count > 0 {
            score -= 12.0;
        }
        // Otherwise keep the fresh-bin option expensive.
        score += 10.0 + 8.0 * (1.0 - item_frac);
    }

    // --- Stream progression: early on, prefer tight fits to build good bins;
    //     late in the stream, prioritize closing bins (reduce open count). ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        // Late stage: strongly reward near-perfect fills.
        if pr <= 5 { score -= 15.0; }
        score -= 6.0 * progress;
    } else {
        // Early stage: keep residuals flexible (mid-range residuals are valuable).
        let mid = 1.0 - ((pr as f64 - 50.0) / 50.0).abs().min(1.0);
        score -= 3.0 * mid;
    }

    // --- Tie-break: prefer bins that reduce fragmentation pressure ---
    //     (bins whose residual is far below the mean are close to closure).
    if open_bins_count > 0 {
        let diff = bin_residual as f64 - mean_residual;
        if diff < 0.0 { score -= 0.05 * (-diff); } else { score += 0.03 * diff; }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are wasted. Penalize gaps in the "dead zone".
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward tight fit relative to what was available.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 18.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: dead space penalty.
        score += 8.0;
    }

    // New-bin candidate: score it by its post residual, with a mild bias so
    // that we only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If mean residual of open bins is small (all bins nearly full),
        // opening a fresh bin is attractive.
        if mean_residual < 25.0 {
            score -= 15.0;
        }
    }

    // Mild time progression: later in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but unusable residual).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 1.5;
        }
    }

    // New-bin candidate handling: make empty bin attractive only when existing
    // fits are poor or fragmentation is high.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Base cost of opening a new bin.
        score += 8.0;
        // More attractive if mean residual is fragmented (many small residuals).
        let frag = mean_residual / bin_capacity as f64;
        if frag < 0.35 {
            score -= 6.0 * (0.35 - frag);
        }
        // Attractive late in stream when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual != bin_capacity {
        score -= 2.0 * open_pressure.min(3.0);
    }

    // Time horizon: early stream favors flexibility (keep residuals balanced),
    // late stream favors filling bins as tightly as possible.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * t * fit_ratio;
    score += 2.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    // Slight nudge toward bins with residual close to mean (balance preservation).
    score += 0.02 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: tight fit preferred (low post residual).
    let mut score = pr;

    // Non-linear coupling: post residual normalized and squared interaction with progress.
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses.
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Next-item lookahead: if next item fits exactly in post residual, reward.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - diff / cap).max(0.0);
        // Penalize leaving residual just below next item (dead space trap).
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 5.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // New bin candidate handling.
    if is_new_bin {
        // Prefer opening a new bin when current bin would leave tiny dead space
        // or when no bin fits (fitting_bins_count counts open bins only).
        let dead = pr / cap;
        score += 30.0; // default cost of opening a new bin
        score -= 35.0 * dead * dead; // reward if residual after placement is large (versatile)
        // Early stream: new bins are cheaper to open (exploration).
        score -= 15.0 * (1.0 - progress);
        // If many bins fit the item elsewhere, opening new bin is wasteful.
        score += 4.0 * fitting_bins_count as f64;
    } else {
        // Mild diversity term: prefer bins with residual near mean to balance.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference (tight packing).
    score -= 25.0 * (item_size as f64 / bin_capacity as f64);

    // Harmonic class of post_residual: integer division into capacity fractions.
    // Residuals in [0,10) are near-perfect fits -> strong reward.
    if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 18.0;
    } else if post_residual < 35 {
        score -= 6.0;
    } else if post_residual < 50 {
        score += 8.0;
    } else {
        score += 20.0; // large dead space penalty
    }

    // Modulo arithmetic on post_residual: penalize residuals that are
    // "awkward" classes (not multiples of 5 or 10, hard to fill later).
    let awkward = (post_residual % 10 != 0) as f64 * 4.0
        + (post_residual % 5 != 0) as f64 * 3.0;
    score += awkward;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // Harmonic class of the leftover after the lookahead item.
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 && post2 > 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Only prefer opening a new bin when open bins have poor fits (high mean residual)
    // and the item is large.
    if bin_residual == bin_capacity {
        // Neutral starting point; discourage unless existing bins are fragmented.
        score += 30.0;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual > 45.0 && item_size > 50 {
            score -= 45.0; // open fresh bin when open bins are half-empty and item big
        }
        if post_residual < 15 {
            score -= 25.0; // large item nearly filling a fresh bin
        }
        let _ = fragmentation;
    }

    // Stream progression: early in the stream, be slightly more willing to
    // spread items (more future items to fill bins); later, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker against bin proliferation.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 150.0; // perfect fit: zero waste
    }

    // Penalize gaps that cannot fit the lookahead item but could be avoided.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }
    // Reward a residual that exactly accommodates the next item (chain planning).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac * fill_frac;

    // Open-bin pressure: discourage spreading across too many bins early,
    // but relax near end of stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual coupling: prefer bins already below average residual
    // (concentrate waste in few bins rather than spreading it).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin is attractive only when no open bin
    // offers a decent fit. Make the empty bin costly unless item is large.
    if bin_residual == bin_capacity {
        score += 55.0 - 0.4 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: strongly reward when post_residual exactly matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if gap < 1e-6 {
            score -= 50.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual as f64 >= nxt {
            // next item fits: reward proportionally to how snug the chain is
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item will NOT fit here: penalize leftover dead space
            score += 8.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // leaving less than average residual -> good consolidation
        score -= 0.5 * (-dev);
    } else {
        score += 0.3 * dev;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so new bins are used only when existing bins are poor.
        score += 20.0;
        // If the item would leave a very large residual in any bin (bad fit overall),
        // a fresh bin with a big residual is preferable.
        if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
            score -= 25.0;
        }
        // Fewer open bins relative to stream progress -> cheaper to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late-stream tie-breaker: prefer bins with the largest residual consumed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual nonlinearly.
    if bin_residual < bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 6.0 * fit_ratio * fit_ratio;

        // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item cannot use this leftover space -> mild penalty
            score += 2.0 * (post_residual as f64 / 100.0);
        }
    }

    // Global state coupling: many open bins with large mean residual -> encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
        score -= 3.0 * mean_residual / 100.0 * (0.5 + progress);
    }

    // New-bin candidate handling: an empty bin gets a time-varying bias.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays late in the stream when
        // leftover open bins would otherwise strand capacity.
        let open_cost = 10.0 - 6.0 * progress;
        // If few bins fit the item, opening fresh is more acceptable.
        let scarcity = if fitting_bins_count <= 1 { 4.0 } else { 0.0 };
        // If mean residual across open bins is small, new bin is attractive.
        let mean_adj = (mean_residual / bin_capacity as f64) * 8.0;
        score += open_cost + scarcity - mean_adj;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let resid_frac = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // residual waste matters more as the stream matures.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let mut score = pr * (0.6 + 0.8 * progress_poly);

    // Non-linear penalty for leaving awkward residuals (dead space),
    // strongest for small-but-nonzero leftovers that few items can use.
    let dead = resid_frac * (1.0 - resid_frac); // peaks mid-range
    score += 18.0 * dead * (1.0 - progress_poly);

    // Reward tight fits (low post residual) with a saturating bonus.
    score -= 12.0 * (-pr / (0.25 * cap)).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress_poly;
    }

    // Lookahead: bonus if the post residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 10.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        // penalty proportional to how badly next item misses this residual
        let miss = (next_item_size as f64 - pr) / cap;
        score += 8.0 * miss * miss;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current fit is poor or the stream is young (future items benefit).
    if bin_residual == bin_capacity {
        let poor_fit = 1.0 - (item_size as f64 / cap);
        let openness = (1.0 - progress_poly).max(0.15);
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score = 30.0 + 45.0 * poor_fit - 35.0 * openness + 4.0 * crowd;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 8.0 * openness;
        }
    }

    // Mild tie-breaker: prefer bins below mean residual (consolidating waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: how well the leftover can host future items
    // Classes by residue modulo 10 (item sizes are multiples/small granularity)
    let post = post_residual;
    let post_mod = post % 10;
    if post == 0 {
        score -= 50.0; // exact capacity fraction, ideal state
    } else if post_mod == 0 {
        score -= 20.0; // decade-aligned leftover: likely reusable
    } else if post < 10 {
        score += 40.0; // dead space below min item size
    } else {
        // penalize awkward remainders proportionally
        let awkward = (post_mod as f64) / 10.0;
        score += 8.0 * awkward;
    }

    // Lookahead: does post_residual fit the next item?
    if next_item_size > 0 && post >= next_item_size {
        score -= 15.0 + 0.2 * (next_item_size as f64);
    } else if next_item_size > 0 && post > 0 && post < next_item_size {
        score += 12.0; // stranded leftover vs lookahead
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / cap;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative
        } else {
            // penalize new bin when item is small relative to capacity
            score += 40.0 * (1.0 - pressure);
        }
        // early stream: allow more bins; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild bonus for tight fits (small post_residual relative to capacity)
    score -= 0.3 * (1.0 - (post as f64) / cap);

    // Spread bins when too many open bins relative to mean residual
    if mean_residual > 0.0 && (post as f64) > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (1..=10) are nearly useless.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Medium gaps (11..=25) are moderately risky.
    if post_residual > 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Mild reward if next item still fits after this placement.
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize if this placement kills the chance for the next item.
        score += 10.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // keeping loose bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.6;

    // New-bin candidate handling: only attractive when no open bin offers a good fit
    // (i.e., current bin would leave a bad gap or the fit is poor).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 - 20.0;
        // If current placement would be a tight fit, strongly prefer the open bin.
        if post_residual <= 10 {
            score += 70.0;
        }
        // If many bins are already open, opening another is relatively cheaper.
        score -= open_bins_count as f64 * 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item exactly -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space: post_residual smaller than next item but too small to be reused later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Waste created relative to lookahead item.
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Residual still usable for the next item: reward closeness of match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + slack);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current residuals are all poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // If no open bin fits well (this bin is last chance anyway), soften penalty.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: favor filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Exact fit bonus: strong reward for zero waste.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward leaving a residual that could still host future items:
    // usable slivers (>= small item) are fine; tiny dead space is penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // Dead space penalty, worse early when many future items remain.
            score += (1.0 - progress) * (10.0 - pr) * 4.0;
        } else {
            // Usable residual is mildly attractive, scaled by future demand.
            score -= (1.0 - progress) * 2.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chain fit — reward heavily. If next item is blocked by the
    // resulting residual while other bins exist, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt && (post_residual as f64) - nxt < 10.0 {
            score -= 60.0;
        } else if (post_residual as f64) < nxt && (post_residual as f64) < 10.0 && fitting_bins_count > 1 {
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + 40.0 * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // into open bins is poor. Penalize the fresh bin, more so when many
    // open bins already exist and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 250.0 + open_bins_count as f64 * 5.0;
        // But late in the stream, opening a bin for a good future chain
        // (item + next item both fit) becomes cheaper.
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap {
            score -= 90.0 * progress;
        }
    }

    // Global fragmentation pressure: when mean residual is high relative
    // to capacity, favor filling existing bins harder.
    let frag = mean_residual / cap;
    score *= 1.0 + 0.5 * frag;

    // Tie-break noise-free smoothness: prefer bins with residual close to
    // item_size (best-fit shaping) via quadratic coupling.
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += gap * gap * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress) - 0.5 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits with smooth polynomial term
    let fit = 1.0 - norm_pr;
    score -= 0.6 * fit * fit * fit;

    // Penalize near-full bins late in stream only if next item doesn't fit
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let next_fits = pr >= ni;
        if !next_fits {
            let urgency = 0.3 + 0.7 * progress;
            score += urgency * (ni - pr) / cap * 10.0;
        } else {
            // reward bins that can also fit the next item (chained fit)
            let chain = 1.0 - (pr - ni) / cap;
            score -= 0.4 * chain * chain * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64).ln() * norm_pr;

    // Smooth coupling with mean residual: prefer bins below mean residual (tighter)
    let mr = mean_residual / cap;
    score += 0.3 * (norm_pr - mr) * (1.0 - progress);

    // New-bin candidate baseline: keep it slightly unattractive unless post_residual is huge
    if bin_residual == bin_capacity {
        score += 1.5 - 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose residual falls into
    // "dead" classes (small but not tiny) are heavily penalized.
    let pr = post_residual;
    let class = pr / 10; // integer division: harmonic class 0..=10
    match class {
        0 => score -= 30.0,               // near-perfect fit, almost no waste
        1 => score -= 12.0,               // good fit
        2 => score += 6.0,                // awkward small residual
        3 => score += 10.0,
        4 => score += 12.0,
        _ => {}                            // large residuals are fine (reusable)
    }

    // Modulo coupling: residuals that are multiples of common item sizes pair well.
    if pr >= 10 && pr <= 80 {
        let nxt = next_item_size;
        if nxt > 0 && nxt <= pr {
            // next item fits exactly-ish into this residual -> reward
            let slack = pr - nxt;
            if slack == 0 { score -= 25.0; }
            else if slack <= 5 { score -= 15.0; }
            else if slack <= 10 { score -= 5.0; }
        } else if nxt > 0 && nxt > pr {
            // residual too small for lookahead: dead space penalty
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive if the item is huge relative
    // to capacity (few open bins could ever absorb it well) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin; shrinks for very large items.
        let mut nb = 22.0 - 16.0 * fill_frac;
        // Early in stream: opening bins is cheaper (more future use of them).
        nb -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual -> avoid another bin.
        nb += (open_bins_count as f64) * 0.4 + mean_residual * 0.08;
        score += nb;
    } else {
        // Prefer fuller bins: reward low residual relative to mean.
        score -= (mean_residual - bin_residual as f64) * 0.25;
        // Slight preference for bins that stay compact.
        score += (bin_residual as f64 / cap) * 3.0;
    }

    // Small harmonic tie-break on item size classes (odd/even structure).
    score += ((item_size % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Dead space that cannot fit even the smallest plausible item is worse.
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        } else if dead < 20.0 {
            score += 15.0 * (20.0 - dead) / 10.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 25.0 * (1.0 - post_residual as f64 / item_size as f64).max(0.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for consuming a scarce large residual when alternatives exist.
        score += 0.05 * open_bins_count as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the gap: penalize leaving it.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: residual == capacity. Penalize opening a new bin
    // unless the item is large or existing bins are nearly full.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // New bin is attractive only for big items or when open bins are mostly full.
        score += 25.0 - 30.0 * fill_ratio - 25.0 * mean_fullness;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            // Room for lookahead item in fresh bin: soften penalty.
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space)
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space the next item cannot use
            score += 10.0 + 0.3 * post_residual as f64;
        }
    }

    // Penalize residuals far from mean residual (waste relative to fleet average)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last fitting bin: strong incentive to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current item is large and would leave
    // a well-shaped residual elsewhere
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared dead-space penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to lookahead item
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding: many open bins -> prefer consolidation onto low-residual bins
    if open_bins_count > 2 {
        let rel = post_residual as f64 / bin_capacity as f64;
        score -= (open_bins_count as f64).ln() * (1.0 - rel) * 6.0;
    }

    // Global residual alignment: prefer bins below mean residual (tighter than average)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).recip()
        } else {
            1.0
        };
        // Opening a new bin is good for large items / when few alternatives
        score = 60.0 + 40.0 * frac - 70.0 * pressure - 20.0 * frac * pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can host next item too
            score -= 10.0;
        }
        // late in stream, avoid opening new bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0 * (1.0 - frac);
    }

    // Mild time-horizon modulation: early stream -> be picky about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 0.9 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping
    let mut score = post
        + 40.0 * post_norm * post_norm          // penalize large leftover space quadratically
        - 15.0 * post_norm * (1.0 - post_norm); // mild reward for mid-range fits

    // Stream progress coupling: early on, keep bins flexible; late, pack tightly
    score += 20.0 * progress * post_norm * post_norm;
    score -= 10.0 * (1.0 - progress) * (1.0 - post_norm);

    // Last-chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 25.0 * (1.0 - post_norm);
    }

    // Lookahead: reward if next item fits into post_residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (nxt / cap));
        } else {
            score += 8.0 * (nxt / cap) * (1.0 - post_norm);
        }
    }

    // Mean residual coupling: penalize bins deviating from mean (fragmentation control)
    score += 0.05 * (post - mean_residual).abs();

    // New empty bin candidate: penalize so it's chosen only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness reward: strongly prefer small post_residual.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 50.0;

    // Harmonic classes on post_residual: bins whose residual falls into
    // "usable" residue classes (multiples of small divisors) are more
    // likely to be fillable by future items, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = |r: u32| -> f64 {
            if r % 10 == 0 { -6.0 } else if r % 5 == 0 { -3.0 }
            else if r % 3 == 0 { -1.5 } else { 0.0 }
        };
        score += class_bonus(pr);
        // Very small dead space (< 10) is nearly unusable: penalize.
        if pr < 10 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in the post_residual,
    // this is a perfect harmonic pair — big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Next item fits but leaves a new residual; evaluate its class.
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 8.0; } else if nr % 5 == 0 { score -= 4.0; }
            if nr < 10 { score += 6.0; }
        }
        // Next item cannot fit here regardless: mild penalty for wasting
        // a tight bin that a later item might need.
        if next_item_size > pr && pr < 10 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to
    // avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when the
    // item fits poorly in every open bin (many fitting bins with bad
    // fits) or stream is early.
    if bin_residual == bin_capacity {
        // Neutral baseline; make it slightly unattractive unless the
        // item would leave a "nice" residual class (aligned residual).
        if item_size % 10 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        // As stream progresses, prefer filling existing bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are worse than moderate ones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (near-zero post residual is a perfect pack).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits the post residual, this placement chains well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bins pressure: penalize opening a new bin when open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But allow a new bin if existing bins would create dead space anyway.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    }

    // Slight late-stream tightening: be greedier as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post-residual: good lookahead, reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.15 * slack;
    }

    // Next item does NOT fit into post-residual: dead space penalty, worse if post_residual is small.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 - 2.0 * dead; // tiny unusable slivers are costly
        } else {
            score += 5.0 + 0.05 * dead;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins: penalize wasting a well-filled bin on a loose fit.
    if fitting_bins_count > 1 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    // Reward bins already tighter than the mean (compact packing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in the stream, prefer closing bins tightly (small post_residual extra weight).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate: only attractive when current bin fit is terrible.
    if bin_residual == bin_capacity {
        let badness = if next_item_size > 0 && post_residual < next_item_size { 30.0 } else { 0.0 };
        score = 55.0 + badness - (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - post_residual as f64).abs() < 0.5 {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 0.05 * (ni - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when the current item leaves
    // a large post_residual in every open bin (poor fits everywhere).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0 + 0.3 * open_bins_count as f64;
        // If few bins fit the item and mean residual is small, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual across open bins is already large, reuse them instead.
        if mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Mild preference to fill bins with larger residual when many bins are open.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 + 0.8 * progress) + 1.6 * norm_post * (1.0 - progress);

    let mut score = post * (1.0 + 0.5 * norm_post) + poly * cap * 0.25;

    // Reward tight fits smoothly (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: only one fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 10.0 * miss * miss;
        }
    }

    // Penalize divergence from mean residual (keeps bin pool homogeneous).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild penalty for many open bins relative to stream progress.
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: prefer opening early, avoid late waste.
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - progress) - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets. Residuals that are
    // multiples of 10 are "harmonic" (perfect fits for the 10..80 item grid),
    // so reward them; off-grid residuals carry dead-space risk.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0;
    } else if class <= 3 {
        score += 4.0; // tiny slivers are nearly dead space
    } else {
        score += 1.5;
    }

    // Integer-division thresholds: large post_residual chunks are valuable.
    let big_chunk = post_residual / 20; // 0..=5
    score -= 3.0 * big_chunk as f64;

    // Lookahead: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_slack = post_residual - next_item_size;
            if next_slack % 10 == 0 {
                score -= 8.0; // perfect pair placement
            } else if next_slack <= 5 {
                score += 2.0; // next item fills bin but leaves sliver
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty if we
            // strand a large residual that nothing later can use well
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // penalize opening new bins; reduce penalty when fragmentation is
        // high (mean residual small => open bins are tight) or item is huge
        let mut new_bin_penalty = 14.0;
        if item_size >= 60 {
            new_bin_penalty -= 4.0;
        }
        if fragmentation < 0.15 && open_bins_count > 0 {
            new_bin_penalty -= 6.0; // open bins nearly full, fresh bin ok
        }
        if progress > 0.9 {
            new_bin_penalty -= 2.0; // end of stream, waste matters less
        }
        score += new_bin_penalty;
    }

    // Prefer bins tighter than the mean (concentrate filling).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // Mild preference to keep number of open bins from exploding.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: subtract for very small post_residual (good packing).
    if post_residual == 0 {
        score -= 60.0; // perfect fill is ideal
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Strict dead space avoidance: penalize gaps too small for the next item
    // (or for the minimum item size), since they are likely unusable.
    let min_item = if next_item_size > 0 { next_item_size.min(1) } else { 1 };
    let threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < threshold {
        score += 30.0 + 0.5 * (threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny gap = dead space regardless of lookahead
    }

    // If the gap cannot hold the next item, this placement creates stranded space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        // Gap that can exactly host the next item is valuable.
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: with many open bins, discourage wasting capacity;
    // with few open bins, allow looser fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Deviation from mean residual: prefer bins whose residual is far above mean
    // (i.e., near-empty bins) only when item is small; prefer near-mean bins otherwise.
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    if item_size <= 30 {
        score -= 0.05 * dev;
    } else {
        score += 0.05 * dev;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when no open bin
    // offers a decent fit (post_residual would be large/dead) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_possible = if next_item_size > 0 { 0.0 } else { 0.0 };
        let _ = best_possible;
        // Base cost of opening a new bin.
        let mut new_bin_score = 55.0 + pressure * 5.0;
        // Early stream: opening bins is cheap to build a portfolio.
        new_bin_score -= (1.0 - progress) * 20.0;
        // If this bin would be the only fitting bin, opening new bin is wasteful.
        if fitting_bins_count == 1 {
            new_bin_score += 40.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            new_bin_score -= 15.0;
        }
        score = score.max(new_bin_score.min(score)) ; // keep score sane
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (low dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score += leftover * 0.6; // still fine, penalize leftover mildly
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }

        // Bonus if placing item here makes a perfect pair (item + next fills bin).
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 {
            score -= 30.0; // big items: fresh bin is fine
        } else {
            score += 20.0; // small items: prefer stuffing open bins
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 15.0; // anticipate pairing two large items in fresh bins
        }
    }

    // Slight preference for filling more-opened bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement blocks next item from using this bin
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is bad elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening a new bin, more when many bins open or item is small.
        score += 30.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 25.0; // large items justify fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Global pressure: if mean residual is low, conserve space (penalize waste).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Mild time-horizon modulation: early stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: penalize leftover space, with a non-linear (quadratic) dead-space term.
    let mut score = post * (1.0 + norm_post * norm_post);

    // Stream-progress coupling: early on, prefer tighter fills more aggressively.
    let prog_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5;
    score *= prog_coupling;

    // Cubic interaction between progress and normalized post-residual:
    // late in the stream, small residuals matter less (bins are nearly done).
    score -= 8.0 * progress * progress * progress * norm_post;

    // Reward filling a bin almost completely (smooth sigmoid-like bonus).
    let fill_ratio = 1.0 - norm_post;
    score -= 12.0 * fill_ratio * fill_ratio * fill_ratio;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size as f64 <= post {
        let gap = (post - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Penalize bins whose residual deviates from the mean (keep residuals homogeneous).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + norm_post);

    // New-bin candidate: neutral-ish baseline, penalized slightly more when many bins are open
    // and progress is low (encourage using existing bins early).
    if bin_residual == bin_capacity {
        score = cap * (1.0 + norm_post * norm_post) + 5.0 + 3.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let pr = post_residual;
    let class = (pr % 10) as f64;

    // Reward small post_residual (best fit), extra reward for near-perfect fits
    score -= 6.0 * (1.0 - pr as f64 / cap);

    if pr == 0 {
        score -= 50.0; // perfect fill
    } else if pr <= 5 {
        score -= 20.0;
    } else if pr < 10 {
        score -= 8.0;
    }

    // Dead-space penalty: post_residual that no typical item can use.
    // Items 1..100 unknown; treat residuals < 10 as dead, and residuals in
    // awkward classes (e.g. 11..19) as semi-dead.
    if pr > 0 && pr < 10 {
        score += 15.0 + class;
    }
    if pr >= 11 && pr <= 19 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: only bin that fits item -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // cheaper to open a bin early in the stream when many bins already open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if few fitting bins and item is large, opening new bin is reasonable
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // large items fill new bins well
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Slight preference to fill bins with low residual relative to mean (balance avoidance)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Modulo coupling: reward when item_size class matches residual class (tight packing)
    if (item_size % 10) == (bin_residual % 10) && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps that few items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Moderate penalty for medium gaps that only tiny items can use.
    else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the gap: penalize creating dead space.
        score += post_residual as f64 * 1.5;
    }

    // New-bin candidate calibration: empty bin gets baseline tied to mean residual;
    // prefer opening a new bin only when all open bins have small residuals.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 120.0; // never open new bin when it's the only fitting one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: post_residual can hold next item with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in the residual: penalize dead space proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += 0.35 * dead;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64).min(40.0);
    } else {
        score += 0.3 * ((post_residual as f64) - mean_residual).min(40.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect lookahead pair
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && item_size + next_item_size == bin_capacity;
        if perfect {
            score -= 55.0;
        } else {
            score += 15.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Slight progression term: early in stream, be more conservative about waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    let tight_bonus = 20.0 * (-post_residual as f64 / 10.0).exp();
    score -= tight_bonus;

    // Penalize leaving residuals that no typical item can use (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // unusable sliver
    }

    // Penalize putting a small item into a large-residual bin (waste of big space).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * waste * waste;

    // Reward using a bin that is already mostly full (consolidation).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bin: strongly favor filling it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many alternatives: slight penalty to keep flexible bins available.
        score += (fitting_bins_count as f64).min(6.0);
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 5.0; // next item still fits here
        } else {
            // next item won't fit: leaving large post_residual is wasteful
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: maximize final fill, ignore future flexibility.
        score -= 10.0 * fill_ratio;
    }

    // Time horizon: early in the stream, prefer keeping bins flexible;
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * fill_ratio;

    // Global state: many open bins -> encourage consolidation into existing bins,
    // making new-bin candidate less attractive.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.0 * pressure.min(10.0);

    // Mean residual coupling: when mean residual is high, avoid adding to fragmentation.
    score += 3.0 * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64;

    // New-bin candidate handling: empty bin gets a moderate default penalty so it's
    // chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer tight fits via smooth polynomial in post_residual
    let mut score = post + 30.0 * post_norm * post_norm;

    // Stream-progress coupling: later in the stream, penalize loose residuals more strongly
    score += 25.0 * progress * post_norm * post_norm;

    // Non-linear coupling of item size with progress: big items late -> reward tight packing
    score -= 20.0 * item_norm * item_norm * (1.0 - progress);

    // Penalize opening a new bin (empty bin candidate) more as stream progresses
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    // Last-chance bin: strong reward so we don't waste it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - (next_item_size as f64 / post.max(1.0)).min(1.0));
    }

    // Mean residual interaction: placing into a bin far from mean residual is mildly penalized
    score += 0.1 * ((post - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor() as i64; // 0..10 harmonic band

    // Reward tight fits (low band = little waste), with non-linear emphasis
    score -= match class {
        0 => 30.0,
        1 => 18.0,
        2 => 10.0,
        3 => 5.0,
        _ => 0.0,
    };

    // Modulo coupling: post_residual divisible by common small sizes is reusable
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr >= 10 && pr <= 30 { score += 8.0; } // tiny slivers are dead space
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // exact harmonic match bonus
            if post_residual == next_item_size { score -= 10.0; }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        // but if item is large and few bins fit it, new bin is okay
        if fitting_bins_count == 0 || item_size as f64 > cap * 0.6 {
            score -= 15.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer fuller bins overall
    score -= (cap - mean_residual).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Moderate gaps (10..=20) are risky but usable for small items.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (exact or near-exact fill).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave an even tighter fit, extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }

    // Open-bin pressure: mildly prefer filling existing bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit lookahead: strongly reward bins whose post_residual exactly
    // matches the next item, or into which the next item will fit.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 45.0; // exact 2-step match: seal the bin perfectly
        } else if post_residual >= next_item_size {
            score -= 12.0; // next item still fits after this placement
        }
        // Penalize leaving a residual just below the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless it is the
    // only option or the fit is very poor elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 120.0; // no open bin fits: must open new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin guarantees lookahead fit
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic horizon effects
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: strongly prefer bins where post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving awkward small-but-unusable gaps (dead space zone).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny gap is nearly dead
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // moderately awkward
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow in this bin: mild penalty if it creates isolation
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (item_size as f64 / bin_residual as f64);
    }

    // Penalize dumping small items into large residuals early on (waste of space),
    // but relax this late in the stream when consolidation matters more.
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 8.0 * waste_ratio * (1.0 - 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; using it for a small item fragments capacity.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.max(0.0) * (1.0 - progress);

    // Prefer filling nearly-full bins completely (harvest them before opening new).
    if bin_residual <= 20 && post_residual == 0 {
        score -= 25.0; // perfect closure
    } else if bin_residual <= 20 {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but encourage opening a
    // fresh bin when no open bin fits well (post_residual small relative to item)
    // or when open bins would be left with bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with number of open bins and progress.
        score += 20.0 + 2.0 * (open_bins_count as f64).sqrt() + 15.0 * progress;
        // But if the item is large relative to capacity, a fresh bin is attractive
        // because few bins can host it anyway.
        score -= 12.0 * (item_size as f64 / bin_capacity as f64);
        // If the next item is also large, opening fresh helps pack both.
        if next_item_size >= 50 {
            score -= 8.0;
        }
        // Late in stream, avoid opening bins unless truly necessary.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Small global pressure: when many bins are open, favor using existing ones.
    score += 0.15 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64 * 0.0
        + (fitting_bins_count as f64).ln().max(0.0) * -1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: quadratic dead-space penalty, normalized
    let mut score = (pr * pr) / cap;

    // Smooth cubic coupling of dead space with stream progress:
    // late in the stream, dead space matters more (less time to fill it)
    let late = progress * progress * progress;
    score += 40.0 * late * (pr / cap);

    // Tight-fit reward: near-zero post residual strongly favored
    let tight = 1.0 - (pr / cap).min(1.0);
    score -= 15.0 * tight * tight;

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack);
    } else if next_item_size > 0 {
        // post residual can't fit next item: penalize proportionally
        score += 6.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + late);
    }

    // Slight preference to keep bins balanced vs mean residual (smooth coupling)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: baseline score so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 20.0 * late + (fitting_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: dead-space classes are residues that
    // cannot host typical items. Penalize residues in "useless" bands.
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // integer division threshold classes
        match class {
            0 => score += 25.0,          // 1..9 : almost dead space
            1 => score += 8.0,           // 10..19: only tiny items fit
            2 => score -= 2.0,           // 20..29: usable
            3 => score -= 5.0,           // 30..39: good
            4 => score -= 6.0,           // 40..49
            5 => score -= 4.0,           // 50..59
            6 | 7 => score -= 3.0,       // 60..79
            _ => score -= 1.0,           // large residual: keep loose
        }
    } else {
        score -= 40.0; // perfect fill: strongly favored
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0; // chain placement possible
            // harmonic match: next item divides nicely into leftover
            let k = pr / next_item_size.max(1);
            if k >= 2 { score -= 4.0; }
        } else {
            score += 10.0; // next item won't fit here: dead-end risk
            // extra penalty if this bin was the only fitting option
            if fitting_bins_count == 1 { score += 6.0; }
        }
    }

    // Last-chance bonus: only this open bin can host the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin wastes residual capacity
    // proportional to current item size unless the item is large.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score = 0.5 * cap - frac * cap * 0.9; // large items justify new bins
        if frac > 0.7 { score -= 20.0; }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // many open bins with slack: discourage another bin
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += (mean_residual - 30.0) * 0.3;
        }
    }

    // Mild preference to use bins below mean residual (tighter bins first)
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that can't fit the next item are toxic.
    let gap_usable = post_residual >= next_item_size && next_item_size > 0;
    if !gap_usable {
        // Dead space penalty, amplified when gap is tiny but nonzero.
        if post_residual > 0 {
            score += 25.0 + (15.0 - (post_residual.min(15)) as f64);
        }
    } else {
        // Reward keeping room for the lookahead item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - slack * 0.15;
    }

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins, but
    // encourage closing out bins that are nearly full.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.5));
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit = fill_ratio > 0.6 && post_residual >= next_item_size;
        if decent_fit {
            score += 60.0; // refuse to open a new bin on good fits
        } else {
            score -= 5.0; // allow opening when open bins fit poorly
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space that is too small to be useful later.
        if post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        } else {
            score -= 10.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).min(1.0);
        }
    }

    // Aggressive 2-step lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: chain placement possible.
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0;
            if slack == 0.0 {
                score -= 20.0; // perfect 2-item chain
            }
        } else {
            // Next item won't fit here; penalize more if the leftover is small.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.3 * gap.min(50.0);
        }
    }

    // Relative to mean residual: prefer using bins with more residual than average
    // (consume the "wasted" bins first), avoid draining below-average bins.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.25 * (res - mean_residual).min(60.0);
    } else {
        score += 0.20 * (mean_residual - res).min(60.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = bin_capacity as f64 * 0.55; // ~55
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is larger, a fresh bin has good future flexibility.
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        } else if fitting_bins_count == 1 {
            // Only one open bin fits; opening new is usually worse.
            score += 30.0;
        } else {
            score += 15.0;
        }
    }

    // Slight stream-progression pressure: later in the stream, waste matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest future item is waste.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // This bin becomes closed after placement; mild penalty if it closes with large waste.
            if post_residual < 10 {
                score -= 5.0; // clean close is good
            } else {
                score += 0.05 * post_residual as f64;
            }
        } else {
            // next item also fits here: good chaining
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual > bin_capacity / 2 {
            score += 10.0; // wasteful use of the only fitting bin; consider new bin
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0; // default penalty: prefer existing bins
        if fitting_bins_count == 1 {
            score -= 20.0; // existing fit is poor, opening fresh is reasonable
        }
        if post_residual > bin_capacity / 2 && fitting_bins_count >= 1 {
            score -= 15.0; // big item, poor fits elsewhere
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Time-horizon coupling: early in stream, be conservative with bins; later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins with high mean residual -> favor filling laggard bins.
    if open_bins_count > 1 {
        let gap = mean_residual - bin_residual as f64;
        score += 0.08 * gap;
    }

    // Slight preference for bins with residual just above item (best-fit character).
    score += 0.02 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling: tight fits (small post_residual) are rewarded more
    // as the stream progresses, since late-stage packing benefits from
    // conserving well-shaped residual space.
    let tightness = 1.0 - (post_residual as f64 / cap);
    let tight_reward = tightness * tightness * (1.0 + 60.0 * progress);
    score -= tight_reward;

    // Penalize awkward residuals: mid-range dead space (neither tight nor
    // spacious) becomes less useful over time. Smooth cubic in normalized
    // post_residual, scaled by progress.
    let pr = post_residual as f64 / cap;
    let dead = 4.0 * pr * (1.0 - pr); // peaks at pr = 0.5
    score += dead * dead * (10.0 + 40.0 * progress);

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this bin strongly; if next item cannot fit anywhere else and
    // this bin's post_residual can host it, extra reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let fit_quality = 1.0 - ((post_residual as f64 - nx) / cap);
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            // post_residual too small for next item: penalize proportional
            // to how close it is to being "just barely unusable"
            let miss = (nx - post_residual as f64) / cap;
            score += 8.0 * (1.0 - miss) * (1.0 - miss);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == cap - item.
    // Slightly penalize opening a new bin unless current residuals are poor
    // (high mean residual means open bins are already full-ish).
    if bin_residual == bin_capacity {
        let scarcity = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 * (1.0 - scarcity);
        // Early in the stream, opening bins is cheaper; late, avoid it.
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins; encourages
    // consolidation when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small unusable gaps (below min item size) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect closure is excellent
    } else if post_residual < 20 {
        score += 25.0; // small dead zone is bad
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Classes near multiples of capacity fractions are more reusable.
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus = match class {
        0 => -12.0,                    // round residuals pair easily
        1 | 9 => 6.0,                  // awkward off-by-one gaps
        2 | 8 => 3.0,
        5 => -6.0,                     // half-class residuals versatile
        3 | 4 | 6 | 7 => 0.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual relative to typical item scale.
    let half_bucket = (pr / 25) as f64; // 0..4 buckets
    score -= 4.0 * half_bucket;

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins early; allow later when bins are crowded.
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.05);
        score += 45.0 + 30.0 * (1.0 - progress) - crowd.min(20.0);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Lookahead: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item won't fit here; mildly penalize leaving awkward gap
            score += 6.0;
        }
    }

    // Prefer filling bins when many are open (bin consolidation).
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count.min(20) as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mean-residual coupling: when mean residual is high, prefer bins below mean
    // (drain the laggards); when low, any reasonable fit works.
    if bin_residual != bin_capacity {
        let dev = mean_residual - post_residual as f64;
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: gaps too small for any item (min size 1)
    // but especially gaps smaller than the next item (wasted for lookahead).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver, effectively dead
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Perfect fill: reward heavily
        score -= 100.0;
    }

    // Reward tight fits (small waste relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so it gets no
    // tightness reward and no last-chance reward, naturally deprioritized.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But if the mean residual is very low (all bins nearly full),
        // a new bin becomes more attractive.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 40.0;
        }
    }

    // Slight preference for bins with residual close to item size (best fit)
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.3;

    // Late in the stream, consolidate: favor bins that will be closed out soon
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else {
            score += gap * 0.55; // penalize mismatch with lookahead
        }
        // Reward leaving room for the next item (post >= next).
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space smaller than next item is likely unusable
            score += (post_residual as f64).min(next_item_size as f64) * 0.9;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 15.0;
    }

    // Penalize large residual relative to mean residual (keeps big bins for big items).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Avoid fragmenting nearly-full bins: small post-residuals are good.
    if post_residual < 10 && post_residual > 0 {
        score -= 10.0;
    }

    // Slight penalty for opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Exact pairing bonus: item + next fill the bin nicely.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity of open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced when open bins fit poorly.
        score += 22.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Fresh bin can host the pair perfectly; encourage opening.
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    }

    // Global state coupling: when mean residual is high, prefer bins above mean
    // (consolidate), i.e., penalize bins below mean residual slightly.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
        // Mild preference for already-open bins over opening new ones.
        score -= 2.0;
    }

    // Slight time-decay on post_residual weight: early on, keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, mildly non-linear (quadratic waste pressure)
    let mut score = post * (1.0 + 0.35 * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream => penalize large residuals more strongly (waste consolidation)
    let progress_coupling = 1.0 + 0.8 * progress * progress * norm_post * (1.0 - norm_post);
    score += post * progress_coupling;

    // Reward tight fits via cubic smooth term on normalized fill
    let fill = 1.0 - norm_post;
    score -= 12.0 * fill * fill * fill;

    // Lookahead: if next item fits in post_residual, reward (smooth quadratic bonus)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - post) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post * norm_post);
    }

    // New-bin candidate handling: penalize opening a fresh bin unless residuals are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let mean_tightness = 1.0 - (mean_residual / cap);
        // Opening is penalized by progress and by mean residual availability
        score += 20.0 + 25.0 * progress + 10.0 * mean_tightness - 2.0 * crowd.sqrt();
    }

    // Mean residual coupling: prefer bins deviating from mean residual when mean is small
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: rewards residuals that sit in
    // "reusable" classes (small remainders or exact multiples of common item sizes).
    let post_i = post_residual;
    if post_i > 0 {
        let class = post_i % 10;
        // Residuals near multiples of 10 are more likely to be reused.
        let harmony = (class as f64 / 10.0) * 8.0;
        score += harmony;
        // Exact tiny dead space is great (near-full bin).
        if post_i <= 5 {
            score -= 12.0;
        }
        // Integer division threshold: residuals that can still hold a
        // mid-sized item (>= 10) are more valuable than sub-10 slivers.
        if post_i / 10 == 0 {
            score -= 6.0; // sliver but harmless, slight bonus
        } else if post_i / 10 >= 4 {
            score += 4.0; // large leftover: mild penalty for wasted capacity
        }
    } else {
        // Perfect fill.
        score -= 25.0;
    }

    // Tightness reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap_f;
    score -= 10.0 * fill;

    // Lookahead coupling: penalize if next item cannot fit in post-residual.
    if next_item_size > 0 {
        if post_i >= next_item_size {
            // Bonus scaled by how well next item fits the leftover.
            let slack = (post_i - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap_f);
            // Harmonic bonus if next item exactly fills post-residual.
            if post_i == next_item_size {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            score += 6.0 + 0.15 * ((next_item_size - post_i) as f64);
        }
    } else {
        // Last item: prefer tightest fit anywhere.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are genuinely poor fits. Penalize opening a new bin normally.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If many bins already fit the item, opening a new one is bad.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, opening new bins wastes capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If mean residual across open bins is large, we should use them.
        score += 0.2 * mean_residual;
    } else if bin_residual == bin_capacity {
        // Very first bin: neutral.
        score -= 5.0;
    }

    // Mild penalty when many bins compete: prefer concentrating load.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (< 10) are nearly unusable
    // for future items (sizes >= 1, practically >= 10 in classic streams), so
    // punish them hard; a perfect fill is rewarded.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score += (10.0 - pr) * 8.0; // dead space penalty
    } else {
        // prefer leaving a gap that can still host a plausible item
        score -= 5.0;
    }

    // Reward using an existing bin vs. opening a new one (new bin has
    // bin_residual == bin_capacity, so post_residual is large; add explicit
    // pressure so we only open when existing fits are truly poor).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 12.0;
        // last-chance bin: strongly prefer using it before it goes to waste
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: dead space is locked in
        score += 6.0;
    }

    // Mild open-bin pressure: consolidate when too many bins are open.
    score += 0.3 * open_bins_count as f64;

    // Slight preference for tighter-than-average fits.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post-placement residual (perfect chain match).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect match: next item exactly fills remaining space -> big reward.
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a new residual; reward proportional
            // to how tight the chain fit is.
            let chain_residual = post - nxt;
            score -= 30.0 - chain_residual * 0.4;
        } else {
            // Next item won't fit here: penalize mildly, more so if we
            // squander nearly all the residual on dead space.
            let waste = post;
            score += waste * 0.25;
        }

        // Coupling with mean residual: bins with residual far below mean
        // are "nearly full" -> placing here is good (consolidation).
        let post_f = post_residual as f64;
        if post_f < mean_residual {
            score -= (mean_residual - post_f) * 0.3;
        } else {
            score += (post_f - mean_residual) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize tiny dead space that no small item (min size 1) could ever
    // pair well with, but reward residual exactly matching common sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when current residuals are large
    // (open bins are mostly empty) or late in the stream with no better fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 - 20.0 * progress;
        // If mean residual is small (bins nearly full), a new bin is fine.
        score -= (100.0 - mean_residual).min(100.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with a mild non-linear boost.
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    score -= 8.0 * tightness;

    // Penalize leaving dead space that no typical item (<= 80) could fill usefully.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver = wasted capacity
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 3.0; // still usable by small items
    } else if post_residual > 80 {
        score += 6.0; // large leftover, but only if item was small
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0; // bin becomes useless for lookahead item
        }
    }

    // New-bin candidate handling: opening a bin is penalized, but less when
    // current fit is bad or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 45.0;
        // Encourage new bins late in stream when fragmentation is high.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 10.0 * progress;
        // If mean residual is small (bins nearly full), a new bin is reasonable.
        new_bin_score -= 0.15 * mean_residual;
        // If few bins fit the item, new bin is more acceptable.
        new_bin_score -= 8.0 * (fitting_bins_count as f64);
        // Large items prefer fresh bins.
        new_bin_score -= 0.2 * (item_size as f64);
        score = score.max(new_bin_score);
    }

    // Mild preference to fill bins that are already relatively full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    // Slight penalty for accumulating too many open bins early.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_frac = pr / cap;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear reward for tight fit: quadratic coupling of fill ratio with stream progress
    score -= (1.0 - pr_frac).powi(2) * (40.0 + 80.0 * progress);

    // Cubic dead-space penalty for very small post residuals that are unusable
    if pr > 0 {
        score += (pr_frac * (1.0 - pr_frac)).powi(3) * 60.0;
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 25.0 * (1.0 - slack / cap).powi(2);
    } else if next_item_size > 0 {
        // penalize when next item cannot follow into this bin
        score += 12.0 * (1.0 - pr_frac);
    }

    // Last-chance bin: strong smooth bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 50.0 * progress;
    }

    // Mean-residual interaction: penalize bins far from the mean (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 20.0;

    // New-bin candidate: make it moderately attractive early, less so late
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 40.0 * (1.0 - progress) - 20.0 * (1.0 - fit_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10
    let class = (post_residual % 10) as f64;
    // Small residues (1..=4) are near-perfect fits; big residues (5..9) are awkward
    if post_residual > 0 {
        if class <= 4.0 {
            score -= 6.0 * (4.0 - class) / 4.0; // reward near-zero leftovers
        } else {
            score += 2.0 * (class - 4.0) / 5.0; // penalize awkward leftovers
        }
    } else {
        score -= 12.0; // perfect fill
    }

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic threshold classes on next_item_size
        let nclass = next_item_size % 10;
        let bonus = if next_item_size >= 50 { 8.0 } else if nclass == 0 { 6.0 } else { 4.0 };
        score -= bonus;
        // Extra reward if leftover after the lookahead item lands in a good class
        let post2 = post_residual - next_item_size;
        if post2 % 10 <= 4 || post2 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the lookahead cannot use
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is expensive
    if is_new_bin {
        // Base penalty grows with how many bins fit the item
        let crowding = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).min(6.0) };
        score += 15.0 + 4.0 * crowding;
        // Late in the stream, prefer consolidating into existing bins
        score += 8.0 * progress;
        // If mean residual is large, existing bins have room: penalize new bin more
        score += (mean_residual / 10.0).min(10.0);
        // Exception: a huge item (>= 80% of capacity) with poor fits justifies a fresh bin
        if item_size * 5 >= bin_capacity * 4 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Exception: next item won't fit anywhere useful (large lookahead) -> new bin ok
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0;
        }
    } else {
        // Prefer tighter existing bins: normalize residual against mean residual
        score += (post_residual as f64 - mean_residual) * 0.3;
        // Slight preference for bins with lower index-like load (denser packing early)
        score += 0.05 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // minimum item are pure waste — penalize them heavily.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Soft-dead-space: gaps that only fit very small items are risky.
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins; when few are open, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive if the item would leave
    // a large, reusable gap in existing bins, or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with how many bins fit the item.
        score += 12.0;
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space
        if post_residual < 10 {
            score += 60.0 - 6.0 * post_residual as f64;
        }
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0) * 0.5;
        } else {
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 55.0;
        // opening new bin is attractive if lookahead fits well there too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if post_residual == 0 {
            score -= 1000.0; // exact fill of a fresh bin (item == capacity)
        }
    }

    // Early stream: be slightly conservative, keep bins mergeable
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more than linearly.
    if post_residual > 0 {
        score -= 12.0 / post_residual as f64;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Fill ratio coupling: bins that end up mostly full are attractive.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 / (1.0 + slack);
    }
    // If next item would leave near-zero waste after this placement, extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 5 {
        score -= 5.0;
    }
    // Penalize creating dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.05 * post_residual as f64;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the current item is large
    // relative to remaining space in typical bins, or many bins already open.
    if bin_residual == bin_capacity {
        let avg_open_util = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = item_size as f64 / bin_capacity as f64;
        // Open a new bin when existing bins are crowded or item is large.
        score += 18.0 - 20.0 * avg_open_util - 10.0 * pressure;
        // Late in the stream, avoid proliferating bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // If item fits poorly everywhere (large item), new bin is good.
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild preference for bins with residual close to the item (best-fit flavor),
    // scaled by how many alternatives exist.
    let diff = (bin_residual - item_size) as f64;
    score += 0.02 * diff * (fitting_bins_count as f64).sqrt();

    // Slight penalty on bins with much larger residual than mean (save them
    // for future large items), unless near stream end.
    if bin_residual as f64 > mean_residual + 20.0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 4.0;
    }

    // Tie-break: prefer using older/more open bins to consolidate? Prefer fewer
    // open bins by nudging toward any existing bin vs new.
    if bin_residual != bin_capacity {
        score -= 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let base = pr / cap;

    // Smooth non-linear coupling: post-residual shaped by stream progress
    let mut score = pr as f64;
    score += 40.0 * base * base * (0.5 + progress);
    score -= 25.0 * (1.0 - base) * (1.0 - base) * (1.0 - progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr as f64 - mean_residual) / cap;
    score += 30.0 * dead * dead;

    // Lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 20.0 * fit_next * (nx / cap) * (1.0 - base);
        score += 15.0 * (1.0 - fit_next) * (1.0 - progress);
    }

    // Last-chance bonus (smooth in fitting count)
    if fitting_bins_count <= 1 {
        score -= 45.0 * (1.0 - base);
    }

    // Mild pressure against opening many bins late
    score += (open_bins_count as f64).ln() * (1.0 + progress) * 3.0;

    // New-bin candidate: keep it attractive only when fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - (item_size as f64) / cap) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: fill bins tightly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - frac) * 40.0;

    // Harmonic class of post_residual: dead space that no item (1..=100) can
    // use well is penalized. Small post_residuals are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr > 80 {
        score += 30.0; // nearly empty bin left behind is wasteful
    }

    // Modulo arithmetic on residual classes (harmonic classes of C=100).
    // Residuals congruent to awkward remainders (e.g. 1 mod 10) are hard to fill.
    let awkward = pr % 10;
    if pr > 0 && awkward != 0 && awkward < 5 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + item_size as f64 * 0.3;
    }

    // New-bin candidate handling: prefer an empty new bin only when current fit is bad.
    if bin_residual == bin_capacity {
        // New bin baseline: neutral score scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * (1.0 - progress);
        // If item is large relative to capacity, new bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 15.0;
        }
    }

    // Spread-awareness: when many bins are open with high mean residual,
    // prefer consolidating into fuller bins (high residual bins get penalized).
    if mean_residual > 30.0 && bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Early stream: be slightly conservative, keep bins flexible.
    if step_index < total_items / 10 && post_residual < 15 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (dead-space avoidance archetype)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: prefer filling existing bins when many are open
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 10.0 * open_pressure;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New bin candidate: penalize unless it enables a much better future fit
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
            20.0
        } else {
            0.0
        };
        score += 35.0 - lookahead_bonus;
    }

    // Lookahead: reward bins that can also fit the next item after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward when post_residual exactly matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 40.0; // perfect chain fit
        } else if post_residual as u32 >= next_item_size {
            score -= 12.0 / (1.0 + diff / 20.0); // graded reward for feasibility
        } else {
            // next item cannot fit here; penalize dead space proportionally
            score += (nxt - post_residual as f64) * 0.35;
        }
    }

    // Penalize small unusable residuals (dead space)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless
    // current bin residual is a poor fit (large post_residual dead space).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; becomes attractive only when existing bins are bad
        score = 60.0 + (bin_capacity as f64 - item_size as f64) * 0.1;
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) >= item_size {
            score -= 15.0; // fresh bin can also host the lookahead item
        }
    }

    // Late-stream bias: consolidate more aggressively as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
        score -= 10.0 + 8.0 * chain_quality;
    } else if next_item_size > 0 {
        // Slight penalty if post-residual becomes unusable for the lookahead item.
        score += 3.0 * (next_item_size as f64 / 100.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when residuals are large (fragmentation control).
    if bin_residual != bin_capacity {
        score += 0.05 * open_bins_count as f64;
        // Prefer bins below mean residual (pack into emptier-tail bins) mildly.
        score += 0.10 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: keep it competitive only when fits are poor.
        score = bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

        // If no open bin can fit, opening is necessary: make it cheap.
        if fitting_bins_count == 0 {
            score -= 40.0 + 20.0 * progress;
        } else {
            // Open a new bin when existing fits are wasteful (large post-residual elsewhere)
            // and the item is large relative to capacity.
            let waste_elsewhere = mean_residual.max(0.0);
            let large_item = item_size as f64 / bin_capacity as f64;
            let next_also_large = next_item_size as f64 / bin_capacity as f64;
            score -= 12.0 * large_item
                   + 6.0 * (waste_elsewhere / bin_capacity as f64).min(1.0)
                   + 8.0 * next_also_large * (1.0 - progress);
            // Late in the stream, discourage opening new bins more strongly.
            score += 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with non-linear tightening as stream progresses.
    let mut score = post_norm * (1.0 + 1.5 * progress * progress);

    // Smooth penalty for awkward dead space (mid-range residuals are least useful).
    let awkward = 4.0 * post_norm * (1.0 - post_norm);
    score += awkward * (0.6 + 0.4 * progress);

    // Reward tight fits with a smooth cubic coupling.
    let fit_tightness = 1.0 - post_norm;
    score -= 2.0 * fit_tightness * fit_tightness * fit_tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: reward if next item fits smoothly into post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 1.2 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 0.5 * ((nxt - post) / cap) * (1.0 - progress);
        }
    }

    // Mild spread penalty: discourage straying far from mean residual.
    score += 0.15 * ((post - mean_residual) / cap).abs();

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the stream is early (preserving space for later).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (mean_residual / cap);
        score += 2.0 + 6.0 * crowd - 2.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets
    let class = post_residual % 10;
    // Residuals in "dead" classes (1..9 small remainders) are less useful
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }
    if class == 0 {
        score -= 15.0; // perfectly divisible residual is reusable
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Next item lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 180.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        let left_after_next = post_residual - next_item_size;
        if left_after_next % 10 == 0 {
            score -= 40.0;
        }
        score += left_after_next as f64 * 0.3;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin
    if bin_residual == bin_capacity {
        score += 150.0;
        // Opening a new bin is better if no open bin gives a good fit
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fit_ratio > 0.85 {
            score -= 100.0; // large item: fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 150.0;
        }
    }

    // Prefer filling bins that are already relatively full
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 30.0;

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * used_frac;

    // Slight pull toward mean residual to keep balance
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 150.0; // perfect fit reward
    }

    // Reward tight fits relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Pressure from number of open bins: discourage spreading when many bins open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size && next_item_size <= post_residual {
        score -= 30.0;
    }
    // Penalize leaving a gap just under the next item size (near-miss dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // New bin candidate handling: keep it neutral-ish unless fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Late-stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-chain match gets a strong reward.
        score -= 18.0 * (-diff / 6.0).exp();
        // Also reward leaving space usable by typical future items (>=10).
        if post_residual >= 10 {
            score -= 3.0;
        } else if post_residual > 0 {
            // Dead space penalty: small unusable slivers.
            score += 6.0;
        }
    } else {
        // Last item: just minimize waste.
        score = post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already "tight"; placing there is valuable (Best-Fit-like).
    let r = bin_residual as f64;
    let rel = r - mean_residual;
    score += 0.15 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // But penalize very loose fits even so.
        if post_residual > 40 {
            score += 12.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large relative to capacity or the fit in existing bins is poor.
    if bin_residual == bin_capacity {
        // Neutral baseline: cost of consuming a fresh bin.
        score = bin_capacity as f64 * 0.9;
        // Prefer new bin for big items (they leave little dead space anyway).
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * frac * frac;
        // If next item chains well with this one in a fresh bin, encourage.
        if next_item_size > 0 {
            let chain = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs();
            score -= 10.0 * (-(chain as f64) / 8.0).exp();
        }
        // Late in the stream, avoid opening new bins (fewer future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If many bins are open and one fits, discourage new bin.
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Mild penalty for spreading across many open bins when this bin is loose.
    if open_bins_count > 4 && post_residual > 50 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual), non-linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 10.0;
    } else if post_residual > 60 {
        score += 18.0; // large dead space is wasteful
    }

    // Lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.15 * slack; // prefer chains that still stay tight
        } else {
            // Next item won't chain here; penalize proportionally to wasted potential.
            score += 8.0 + 0.1 * (next_item_size as f64);
        }
    } else {
        // Last item in stream: prioritize filling residual as much as possible.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 2.5 * (open_bins_count as f64).ln().max(0.0);

    // Relative residual context: bins with residual far above the mean are
    // good targets (they have room), bins far below mean are nearly full.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.08 * dev;

    // Late in the stream: be greedier about filling bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // New-bin candidate: opening a new bin is only attractive when no existing
    // bin offers a decent fit. Make the empty bin moderately unattractive by
    // default; it wins only when all open-bin scores are worse.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, new bins are cheaper (plenty of future items to fill them).
        score -= 30.0 * (1.0 - progress);
        // If many bins are open, discourage spreading further.
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 20.0 * poly;

    // Tight fits are good: reward small post_residual non-linearly
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead: penalize leaving space that next item cannot use
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let waste = (pr - ns) / cap;
            score -= 10.0 * (1.0 - waste) * progress;
        } else {
            let gap = (ns - pr) / cap;
            score += 12.0 * gap * (0.5 + 0.5 * progress);
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New empty bin candidate: penalize mildly unless current residual is unusable
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / cap;
        score += 30.0 - 25.0 * tight * progress;
        if fitting_bins_count > 0 {
            score += 15.0 * (1.0 - mean_residual / cap);
        }
    }

    // Mean residual coupling: prefer bins deviating from mean in the right direction
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress) - 3.0 * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with non-linear emphasis.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Harmonic class: post_residual buckets via integer division.
    let class = post_residual / 20; // 0..=5 classes
    score -= 3.0 * (5 - class) as f64;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // extra reward if next item then fits almost perfectly
        let npr = post_residual - next_item_size;
        if npr <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item would need another bin; mild penalty for chaining badly
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // the item is large or current bins are too full/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // opening new bin is attractive when open bins have small mean residual
        score = 100.0
            - 30.0 * fragmentation
            - 20.0 * progress
            - (item_size as f64) * 0.3;
        // if many bins can fit the item elsewhere, opening is wasteful
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // large item with no good home: opening is fine
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are nearly unusable.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Penalize gaps that are too small for the smallest plausible item (1..100 range).
        // A gap < ~10 is dead space; a gap that cannot fit the lookahead item is risky.
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap);
        } else {
            // Mild preference for smaller usable gaps (tight fit).
            score += 0.15 * gap;
        }
        // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size as f64 - gap);
        }
        // Reward gaps that exactly fit the next item (perfect chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Perfect fill: heavily reward.
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
        // Extra reward if the fit is tight (post_residual small).
        if post_residual <= 15 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new bins.
    // The new-bin candidate has bin_residual == bin_capacity; give it a penalty
    // that grows with the number of open bins.
    if bin_residual == bin_capacity {
        score += 55.0 + 8.0 * open_bins_count as f64;
        // Exception: if the item is huge relative to mean residual space, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Slight early-stream preference to consolidate into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // Reward bins whose residual is far below the mean (they are being filled well).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit wins.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward exact / near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // Next item fits here after this placement: strong reward scaled by closeness.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 {
                score -= 15.0; // perfect chain fit
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid leaving space far above average (waste).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.08 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 25.0                       // default penalty for opening a new bin
                 - 22.0 * pressure          // reward when it also chains with next item
                 + (open_bins_count as f64).min(10.0) * 0.5; // slight extra reluctance as bins accumulate
    }

    // Late in the stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very small unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: quadratic bonus for very small leftover space.
    let tight = post / cap;
    score -= 12.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Penalize creating awkward dead space: residual too small for typical
    // future items (below a "usefulness threshold" of ~10% capacity).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 18.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64 / 10.0));
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - snug / cap);
    } else if next_item_size > 0 {
        // Penalize leaving a residual just barely too small for next item.
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; prefer spreading load.
        score += 1.5 * ((fitting_bins_count - 1) as f64).sqrt();
    }

    // Time horizon: early in the stream, be conservative (favor filling
    // existing bins); late, allow more freedom to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress);

    // Global state: penalize selecting bins when mean residual is already
    // high (fragmentation risk); reward when mean residual is low.
    let mean_tight = 1.0 - (mean_residual / cap).min(1.0);
    score += 5.0 * mean_tight - 3.0 * (1.0 - mean_tight);

    // New-bin candidate: make it expensive by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no existing bin fits well (large post_residual elsewhere)
        // and stream is late, soften the penalty.
        let desperation = (post_residual as f64 / cap) * (10.0 * progress);
        score -= desperation;
        // If next item is large, opening a fresh bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Slight preference for bins with more residual used already (larger fill).
    score -= 2.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Base: penalize wasted residual, softened by progress (late stream -> tighter packing matters)
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear coupling: quadratic residual term favors filling bins nearly full
    let pr_norm = pr / cap;
    score += 30.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward near-perfect fits: smooth bump when post_residual is small
    let tightness = (-pr / 8.0).exp();
    score -= 12.0 * tightness * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (-gap / 10.0).exp();
        } else {
            score += 3.0 * (-gap.abs() / 15.0).exp();
        }
    }

    // New-bin candidate: penalize opening new bins early, less so when open bins are congested
    if is_new_bin {
        let congestion = mean_residual / cap;
        score += 20.0 * (1.0 - progress) - 15.0 * congestion * progress;
    }

    // Mild penalty for spreading across many bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod small primes
    let r = post_residual as i64;
    let mod3 = r % 3;
    let mod5 = r % 5;
    let mod10 = r % 10;

    // Reward residuals that fall into "usable" harmonic classes (small leftovers
    // divisible by common item sizes are more likely to be filled later).
    if r > 0 {
        if mod10 == 0 { score -= 12.0; }
        else if mod5 == 0 { score -= 6.0; }
        else if mod3 == 0 { score -= 3.0; }
        // Odd tiny residues are dead space
        if r < 10 && r % 2 == 1 { score += 15.0; }
    } else {
        // Perfect fill is ideal
        score -= 40.0;
    }

    // Tight fit reward: quadratic coupling of item size to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * frac;
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current
    // residuals are fragmented or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalty for new bin, reduced when open bins are fragmented
        score = 100.0 + 20.0 * (1.0 - fragmentation) + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 15.0; // big item followed by big item: keep existing bins
        }
    }

    // Mild preference for fuller bins overall (residual below mean)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small but potentially usable gap: mild penalty unless it fits the lookahead item.
        if next_item_size == 0 || post_residual < next_item_size {
            score += 18.0;
        } else {
            score -= 12.0; // gap is exactly useful for the next item
        }
    }

    // Reward tight fits (waste minimization).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or stream is early.
        score += 30.0 + 2.5 * open_bins_count as f64 + 20.0 * (1.0 - progress);
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 1.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Prefer bins below mean residual (balancing residuals across bins).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small dead space (unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize if next item cannot fit in post_residual but bin is otherwise tight.
        if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when open bins exist that fit reasonably.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it only wins for very poor fits.
        score += 35.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 2.5 * tightness * tightness;

    // Reward exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: leftover space too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 45.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Prefer bins with residual below mean (more filled bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more heavily as stream progresses
        // unless item is large and no good fit exists.
        let mut new_bin_penalty = 25.0 + 40.0 * progress;
        if item_size > 60 && fitting_bins_count <= 1 {
            new_bin_penalty *= 0.4;
        }
        if next_item_size > 0 && next_item_size >= item_size && fitting_bins_count == 0 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    } else {
        // Open bins get a mild bonus late in the stream to consolidate.
        score -= 5.0 * progress;
    }

    // Slight penalty for many open bins: encourage packing into existing bins.
    score += 0.15 * open_bins_count as f64;

    score
}
